/* ----- sample conversion ----- */
#define SOX_UNSIGNED_8BIT_TO_SAMPLE(d) ((sox_sample_t)(((uint32_t)(uint8_t)(d) ^ 0x80) << 24))
#define SOX_SIGNED_8BIT_TO_SAMPLE(d) ((sox_sample_t)((uint32_t)(uint8_t)(d) << 24))
#define SOX_UNSIGNED_16BIT_TO_SAMPLE(d) ((sox_sample_t)(((uint32_t)(uint16_t)(d) ^ 0x8000) << 16))
