#define SOX_UNSIGNED_24BIT_TO_SAMPLE(d) ((sox_sample_t)((((uint32_t)(d) & 0xffffff) ^ 0x800000) << 8))
#define SOX_SIGNED_24BIT_TO_SAMPLE(d) ((sox_sample_t)((uint32_t)(d) << 8))
#define SOX_UNSIGNED_32BIT_TO_SAMPLE(d) ((sox_sample_t)((uint32_t)(d) ^ 0x80000000u))
#define SOX_SIGNED_32BIT_TO_SAMPLE(d) ((sox_sample_t)(d))

static inline sox_sample_t sox_float64_to_sample(double d, size_t *clips)
{
  double t = d * (SOX_SAMPLE_MAX + 1.0);
  if (t < 0) {
    if (t <= SOX_SAMPLE_MIN - 0.5) { ++*clips; return SOX_SAMPLE_MIN; }
    return (sox_sample_t)(t - 0.5);
  }
  if (t >= SOX_SAMPLE_MAX + 0.5) {
    if (t > SOX_SAMPLE_MAX + 1.0) ++*clips;
    return SOX_SAMPLE_MAX;
  }
  return (sox_sample_t)(t + 0.5);
}
#define SOX_FLOAT_64BIT_TO_SAMPLE(d,clips) sox_float64_to_sample((d), &(clips))
#define SOX_FLOAT_32BIT_TO_SAMPLE(d,clips) sox_float64_to_sample((double)(d), &(clips))

static inline int32_t sox_sample_to_bits(sox_sample_t d, int bits, size_t *clips)
{
  int shift = 32 - bits;
  if (bits == 32) return d;
  if (d > SOX_SAMPLE_MAX - (1 << (shift - 1))) { ++*clips; return (int32_t)SOX_INT_MAX(bits); }
  return (int32_t)(((uint32_t)d + (1u << (shift - 1))) ) >> shift;
}
/* Note: for negative d, (d + half) >> shift done arithmetically */
static inline int32_t sox_sample_to_signed(sox_sample_t d, int bits, size_t *clips)
{
  int shift;
  if (bits >= 32) return d;
  shift = 32 - bits;
  if (d > SOX_SAMPLE_MAX - (1 << (shift - 1))) { ++*clips; return (int32_t)SOX_INT_MAX(bits); }
  return (int32_t)(d + (1 << (shift - 1))) >> shift;
}
#define SOX_SAMPLE_TO_SIGNED_8BIT(d,clips) ((int8_t)sox_sample_to_signed((d),8,&(clips)))
#define SOX_SAMPLE_TO_UNSIGNED_8BIT(d,clips) ((uint8_t)(sox_sample_to_signed((d),8,&(clips)) ^ 0x80))
#define SOX_SAMPLE_TO_SIGNED_16BIT(d,clips) ((int16_t)sox_sample_to_signed((d),16,&(clips)))
#define SOX_SAMPLE_TO_UNSIGNED_16BIT(d,clips) ((uint16_t)(sox_sample_to_signed((d),16,&(clips)) ^ 0x8000))
#define SOX_SAMPLE_TO_SIGNED_24BIT(d,clips) (sox_sample_to_signed((d),24,&(clips)))
#define SOX_SAMPLE_TO_UNSIGNED_24BIT(d,clips) ((uint32_t)(sox_sample_to_signed((d),24,&(clips)) ^ 0x800000) & 0xffffff)
#define SOX_SAMPLE_TO_SIGNED_32BIT(d,clips) ((int32_t)(d))
#define SOX_SAMPLE_TO_UNSIGNED_32BIT(d,clips) ((uint32_t)(d) ^ 0x80000000u)
#define SOX_SAMPLE_TO_FLOAT_32BIT(d,clips) ((float)((d) * (1.0 / (SOX_SAMPLE_MAX + 1.0))))
#define SOX_SAMPLE_TO_FLOAT_64BIT(d,clips) ((d) * (1.0 / (SOX_SAMPLE_MAX + 1.0)))

#define SOX_ROUND_CLIP_COUNT(d, clips) \
  ((d) < 0? (d) <= SOX_SAMPLE_MIN - 0.5? ++(clips), SOX_SAMPLE_MIN: (sox_sample_t)((d) - 0.5) \
          : (d) >= SOX_SAMPLE_MAX + 0.5? ++(clips), SOX_SAMPLE_MAX: (sox_sample_t)((d) + 0.5))
#define SOX_INTEGER_CLIP_COUNT(bits,i,clips) ( \
  (i) >(1 << ((bits)-1))- 1? ++(clips),(1 << ((bits)-1))- 1 : \
  (i) <-1 << ((bits)-1)    ? ++(clips),-1 << ((bits)-1) : (i))
#define SOX_SAMPLE_CLIP_COUNT(samp, clips) \
  do { if (samp > SOX_SAMPLE_MAX) { samp = SOX_SAMPLE_MAX; clips++; } \
       else if (samp < SOX_SAMPLE_MIN) { samp = SOX_SAMPLE_MIN; clips++; } } while (0)

