/* ----- note/frequency parsing ----- */
int lsx_parse_note(char const *text, char **end_ptr)
{
  int result = INT_MAX;

  if (*text >= 'A' && *text <= 'G') {
    result = (int)(5 / 3. * (*text++ - 'A') + 9.5) % 12 - 9;
    if (*text == 'b') { --result; ++text; }
    else if (*text == '#') { ++result; ++text; }
    if (isdigit((unsigned char)*text))
      result += 12 * (*text++ - '4');
  }
  *end_ptr = (char *)text;
  return result;
}

double lsx_parse_frequency_k(char const *text, char **end_ptr, int key)
{
  double result;

  if (*text == '%') {
    result = strtod(text + 1, end_ptr);
    if (*end_ptr == text + 1)
      return -1;
    return 440 * pow(2., result / 12);
  }
  if (*text >= 'A' && *text <= 'G') {
    int note = lsx_parse_note(text, end_ptr);
    return key == INT_MAX ? 440 * pow(2., note / 12.) : 0; /* just intonation handled by synth */
  }
  result = strtod(text, end_ptr);
  if (end_ptr) {
    if (*end_ptr == text)
      return -1;
    if (**end_ptr == 'k') {
      result *= 1000;
      ++*end_ptr;
    }
  }
  return result < 0 ? -1 : result;
}

