/* ----- getopt ----- */
void lsx_getopt_init(int argc, char * const *argv, const char *shortopts, const lsx_option_t *longopts, lsx_getopt_flags_t flags, int first, lsx_getopt_t *state)
{
  state->argc = argc;
  state->argv = argv;
  state->shortopts = (shortopts[0] == '+' || shortopts[0] == '-') ? shortopts + 1 : shortopts;
  state->longopts = longopts;
  state->flags = flags;
  state->curpos = NULL;
  state->ind = first;
  state->opt = '?';
  state->arg = NULL;
  state->lngind = -1;
}

static void getopt_warn(lsx_getopt_t *state, const char *fmt, ...)
{
  va_list ap;
  if (!(state->flags & lsx_getopt_flag_opterr)) return;
  va_start(ap, fmt);
  {
    const char *save = sox_globals.subsystem;
    sox_globals.subsystem = "getopt";
    output_message(2, fmt, ap);
    sox_globals.subsystem = save;
  }
  va_end(ap);
}

int lsx_getopt(lsx_getopt_t *state)
{
  int oerr;
  state->arg = NULL;
  state->lngind = -1;
  oerr = 0 != (state->flags & lsx_getopt_flag_opterr);
  if (!state->curpos || !*state->curpos) {
    const char *current;
    state->curpos = NULL;
    if (state->ind >= state->argc) return -1;
    current = state->argv[state->ind];
    if (current[0] != '-' || current[1] == 0) return -1; /* non-option */
    if (current[1] == '-' && current[2] == 0) { state->ind++; return -1; }
    if (current[1] == '-' || (state->flags & lsx_getopt_flag_longonly)) {
      /* long option */
      const char *name = current + (current[1] == '-' ? 2 : 1);
      size_t namelen = strcspn(name, "=");
      const char *eq = name[namelen] == '=' ? name + namelen + 1 : NULL;
      int i, match = -1, nmatches = 0;
      if (state->longopts) {
        for (i = 0; state->longopts[i].name; i++) {
          if (!strncmp(state->longopts[i].name, name, namelen)) {
            if (strlen(state->longopts[i].name) == namelen) { match = i; nmatches = 1; break; }
            if (match < 0) match = i;
            nmatches++;
          }
        }
      }
      if (nmatches > 1) {
        if (oerr) {
          getopt_warn(state, "parameter `%s' is ambiguous:", current);
          for (i = 0; state->longopts[i].name; i++)
            if (!strncmp(state->longopts[i].name, name, namelen))
              getopt_warn(state, "parameter `%s' could be `--%s'", current, state->longopts[i].name);
        }
        state->ind++;
        return '?';
      }
      if (match >= 0) {
        const lsx_option_t *o = &state->longopts[match];
        state->ind++;
        state->lngind = match;
        if (o->has_arg == lsx_option_arg_none) {
          if (eq) {
            getopt_warn(state, "`%s' did not expect an argument from `%s'", o->name, current);
            return '?';
          }
        } else if (o->has_arg == lsx_option_arg_required) {
          if (eq) state->arg = eq;
          else if (state->ind < state->argc) state->arg = state->argv[state->ind++];
          else {
            getopt_warn(state, "`%s' requires an argument from `%s'", o->name, current);
            return '?';
          }
        } else {
          if (eq) state->arg = eq;
        }
        if (o->flag) { *o->flag = o->val; return 0; }
        return o->val;
      }
      if (current[1] == '-' || !(state->flags & lsx_getopt_flag_longonly)) {
        getopt_warn(state, "parameter not recognized from `%s'", current);
        state->ind++;
        return '?';
      }
    }
    state->curpos = current + 1;
  }
  {
    char ch = *state->curpos++;
    const char *spec = ch == ':' ? NULL : strchr(state->shortopts, ch);
    state->opt = ch;
    if (!spec) {
      getopt_warn(state, "option `%c' not recognized", ch);
      if (!*state->curpos) { state->ind++; state->curpos = NULL; }
      return '?';
    }
    if (spec[1] == ':') {
      if (spec[2] == ':') { /* optional */
        if (*state->curpos) { state->arg = state->curpos; }
        state->ind++;
        state->curpos = NULL;
      } else {
        if (*state->curpos) { state->arg = state->curpos; state->ind++; state->curpos = NULL; }
        else if (state->ind + 1 < state->argc) { state->arg = state->argv[state->ind + 1]; state->ind += 2; state->curpos = NULL; }
        else {
          getopt_warn(state, "option `%c' requires an argument", ch);
          state->ind++; state->curpos = NULL;
          return '?';
        }
      }
    } else {
      if (!*state->curpos) { state->ind++; state->curpos = NULL; }
    }
    return ch;
  }
}

