/* ----- comments ----- */
size_t sox_num_comments(sox_comments_t comments) { return comments.n; }

void sox_append_comment(sox_comments_t *comments, char const *comment)
{
  comments->list = lsx_realloc(comments->list, (comments->n + 2) * sizeof(char *));
  comments->list[comments->n++] = lsx_strdup(comment);
  comments->list[comments->n] = NULL;
}

void sox_append_comments(sox_comments_t *comments, char const *comment)
{
  char *end;
  if (comment) {
    while ((end = strchr(comment, '\n'))) {
      size_t len = end - comment;
      char *c = lsx_malloc((len + 1) * sizeof(*c));
      strncpy(c, comment, len);
      c[len] = '\0';
      sox_append_comment(comments, c);
      comment += len + 1;
      free(c);
    }
    if (*comment)
      sox_append_comment(comments, comment);
  }
}

void sox_copy_comments(sox_comments_t *dst, const sox_comments_t *src)
{
  size_t i;
  for (i = 0; i < src->n; i++) sox_append_comment(dst, src->list[i]);
}

void sox_delete_comments(sox_comments_t *comments)
{
  size_t i;
  for (i = 0; i < comments->n; i++) free(comments->list[i]);
  free(comments->list);
  comments->list = NULL; comments->n = 0;
}

char const *sox_find_comment(sox_comments_t comments, char const *id)
{
  size_t len = strlen(id);
  size_t i;
  for (i = 0; i < comments.n; i++)
    if (!strncasecmp(comments.list[i], id, len) && comments.list[i][len] == '=')
      return comments.list[i] + len + 1;
  return NULL;
}

/* ----- registry ----- */
const sox_format_handler_t *sox_find_format(char const *name0, sox_bool no_dev)
{
  size_t f, n;
  if (name0) {
    char *name = lsx_strdup(name0);
    char *pos = strchr(name, ';');
    if (pos) *pos = '\0';
    for (f = 0; sox_format_fns[f].fn; ++f) {
      const sox_format_handler_t *handler = sox_format_fns[f].fn();
      if (!(no_dev && (handler->flags & SOX_FILE_DEVICE)))
        for (n = 0; handler->names[n]; ++n)
          if (!lsx_strcasecmp(handler->names[n], name)) {
            free(name);
            return handler;
          }
    }
    free(name);
  }
  return NULL;
}

const char *sox_strerror(int sox_errno)
{
  static char const * const errors[] = {
    "Invalid Audio Header",
    "Unsupported data format",
    "Can't allocate memory",
    "Operation not permitted",
    "Operation not supported",
    "Invalid argument",
  };
  if (sox_errno < SOX_EHDR)
    return strerror(sox_errno);
  sox_errno -= SOX_EHDR;
  if (sox_errno < 0 || (size_t)sox_errno >= array_length(errors))
    return "Unknown error";
  return errors[sox_errno];
}

void lsx_fail_errno(sox_format_t *ft, int sox_errno, const char *fmt, ...)
{
  va_list args;
  ft->sox_errno = sox_errno;
  va_start(args, fmt);
  vsnprintf(ft->sox_errstr, sizeof(ft->sox_errstr), fmt, args);
  va_end(args);
  ft->sox_errstr[255] = '\0';
}

/* ----- low level I/O ----- */
size_t lsx_readbuf(sox_format_t *ft, void *buf, size_t len)
{
  size_t ret = fread(buf, 1, len, ft->fp);
  if (ret != len && ferror(ft->fp))
    lsx_fail_errno(ft, errno, "lsx_readbuf");
  ft->tell_off += ret;
  return ret;
}

int lsx_skipbytes(sox_format_t *ft, size_t n)
{
  unsigned char trash;
  while (n--)
    if (lsx_readb(ft, &trash) == SOX_EOF)
      return SOX_EOF;
  return SOX_SUCCESS;
}

int lsx_padbytes(sox_format_t *ft, size_t n)
{
  while (n--)
    if (lsx_writeb(ft, '\0') == SOX_EOF)
      return SOX_EOF;
  return SOX_SUCCESS;
}

size_t lsx_writebuf(sox_format_t *ft, void const *buf, size_t len)
{
  size_t ret = fwrite(buf, 1, len, ft->fp);
  if (ret != len) {
    lsx_fail_errno(ft, errno, "error writing output file");
    clearerr(ft->fp);
  }
  ft->tell_off += ret;
  return ret;
}

uint64_t lsx_filelength(sox_format_t *ft)
{
  struct stat st;
  int ret = ft->fp ? fstat(fileno(ft->fp), &st) : -1;
  return (!ret && (st.st_mode & S_IFREG)) ? (uint64_t)st.st_size : 0;
}

int lsx_error(sox_format_t *ft) { return ferror(ft->fp); }
void lsx_rewind(sox_format_t *ft) { rewind(ft->fp); ft->tell_off = 0; }
void lsx_clearerr(sox_format_t *ft) { clearerr(ft->fp); ft->sox_errno = 0; }
int lsx_eof(sox_format_t *ft) { return feof(ft->fp); }
uint64_t lsx_tell(sox_format_t *ft) { return ft->seekable ? (uint64_t)ftello(ft->fp) : ft->tell_off; }

int lsx_seeki(sox_format_t *ft, int64_t offset, int whence)
{
  if (ft->seekable == 0) {
    if (whence == SEEK_CUR) {
      while (offset > 0 && !feof(ft->fp)) {
        getc(ft->fp);
        offset--;
        ++ft->tell_off;
      }
      if (offset)
        lsx_fail_errno(ft, SOX_EOF, "offset past EOF");
      else
        ft->sox_errno = SOX_SUCCESS;
    } else
      lsx_fail_errno(ft, SOX_EPERM, "file not seekable");
  } else {
    if (fseeko(ft->fp, (off_t)offset, whence) == -1)
      lsx_fail_errno(ft, errno, "%s", strerror(errno));
    else
      ft->sox_errno = SOX_SUCCESS;
  }
  return ft->sox_errno;
}

int lsx_readchars(sox_format_t *ft, char *chars, size_t len)
{
  size_t ret = lsx_readbuf(ft, chars, len);
  if (ret == len)
    return SOX_SUCCESS;
  if (!ferror(ft->fp))
    lsx_fail_errno(ft, SOX_EOF, "premature EOF");
  return SOX_EOF;
}

int lsx_reads(sox_format_t *ft, char *c, size_t len)
{
  char *sc;
  char in;
  sc = c;
  do {
    if (lsx_readbuf(ft, &in, (size_t)1) != 1) {
      *sc = 0;
      return (SOX_EOF);
    }
    if (in == 0 || in == '\n')
      break;
    *sc = in;
    sc++;
  } while (sc - c < (ptrdiff_t)len);
  *sc = 0;
  return (SOX_SUCCESS);
}

int lsx_writes(sox_format_t *ft, char const *c)
{
  size_t len = strlen(c);
  if (lsx_writebuf(ft, c, len) != len) return SOX_EOF;
  return SOX_SUCCESS;
}

