uint16_t lsx_swapw(uint16_t uw) { return ((uw >> 8) | (uw << 8)) & 0xffff; }
uint32_t lsx_swapdw(uint32_t udw) { return (udw >> 24) | ((udw >> 8) & 0xff00) | ((udw << 8) & 0xff0000) | (udw << 24); }
static uint64_t swapqw(uint64_t v) { return ((uint64_t)lsx_swapdw((uint32_t)v) << 32) | lsx_swapdw((uint32_t)(v >> 32)); }

/* file data is "little-endian unless reverse_bytes" (machine is little endian) */
int lsx_readb(sox_format_t *ft, uint8_t *ub)
{
  if (lsx_readbuf(ft, ub, 1) != 1) {
    if (!ferror(ft->fp)) lsx_fail_errno(ft, errno, "premature EOF");
    return SOX_EOF;
  }
  if (ft->encoding.reverse_bits) *ub = lsx_cswap[*ub];
  if (ft->encoding.reverse_nibbles) *ub = ((*ub & 15) << 4) | (*ub >> 4);
  return SOX_SUCCESS;
}
int lsx_readsb(sox_format_t *ft, int8_t *sb) { uint8_t u; int r = lsx_readb(ft, &u); *sb = (int8_t)u; return r; }
int lsx_readw(sox_format_t *ft, uint16_t *uw)
{
  uint8_t b[2];
  if (lsx_readbuf(ft, b, 2) != 2) { lsx_fail_errno(ft, errno, "premature EOF"); return SOX_EOF; }
  *uw = b[0] | (b[1] << 8);
  if (ft->encoding.reverse_bytes) *uw = lsx_swapw(*uw);
  return SOX_SUCCESS;
}
int lsx_readsw(sox_format_t *ft, int16_t *sw) { uint16_t u; int r = lsx_readw(ft, &u); *sw = (int16_t)u; return r; }
int lsx_read3(sox_format_t *ft, uint32_t *u3)
{
  uint8_t b[3];
  if (lsx_readbuf(ft, b, 3) != 3) { lsx_fail_errno(ft, errno, "premature EOF"); return SOX_EOF; }
  if (ft->encoding.reverse_bytes) *u3 = b[2] | (b[1] << 8) | ((uint32_t)b[0] << 16);
  else *u3 = b[0] | (b[1] << 8) | ((uint32_t)b[2] << 16);
  return SOX_SUCCESS;
}
int lsx_readdw(sox_format_t *ft, uint32_t *udw)
{
  uint8_t b[4];
  if (lsx_readbuf(ft, b, 4) != 4) { lsx_fail_errno(ft, errno, "premature EOF"); return SOX_EOF; }
  *udw = b[0] | (b[1] << 8) | ((uint32_t)b[2] << 16) | ((uint32_t)b[3] << 24);
  if (ft->encoding.reverse_bytes) *udw = lsx_swapdw(*udw);
  return SOX_SUCCESS;
}
int lsx_readsdw(sox_format_t *ft, int32_t *sdw) { uint32_t u; int r = lsx_readdw(ft, &u); *sdw = (int32_t)u; return r; }
int lsx_readqw(sox_format_t *ft, uint64_t *uqw)
{
