  uint32_t u; float r;
  if (lsx_readdw(ft, &u)) return SOX_EOF;
  memcpy(&r, &u, 4); *f = r;
  return SOX_SUCCESS;
}
int lsx_readdf(sox_format_t *ft, double *d)
{
  uint64_t u; double r;
  if (lsx_readqw(ft, &u)) return SOX_EOF;
  memcpy(&r, &u, 8); *d = r;
  return SOX_SUCCESS;
}

int lsx_writeb(sox_format_t *ft, unsigned ub)
{
  uint8_t b = (uint8_t)ub;
  if (ft->encoding.reverse_nibbles) b = ((b & 15) << 4) | (b >> 4);
  if (ft->encoding.reverse_bits) b = lsx_cswap[b];
  return lsx_writebuf(ft, &b, 1) == 1 ? SOX_SUCCESS : SOX_EOF;
}
int lsx_writesb(sox_format_t *ft, signed sb) { return lsx_writeb(ft, (unsigned)sb & 0xff); }
int lsx_writew(sox_format_t *ft, unsigned uw)
{
  uint8_t b[2];
  uint16_t v = (uint16_t)uw;
  if (ft->encoding.reverse_bytes) v = lsx_swapw(v);
  b[0] = v & 0xff; b[1] = v >> 8;
  return lsx_writebuf(ft, b, 2) == 2 ? SOX_SUCCESS : SOX_EOF;
}
int lsx_writesw(sox_format_t *ft, signed sw) { return lsx_writew(ft, (unsigned)sw & 0xffff); }
int lsx_write3(sox_format_t *ft, unsigned u3)
{
  uint8_t b[3];
  if (ft->encoding.reverse_bytes) { b[0] = (u3 >> 16) & 0xff; b[1] = (u3 >> 8) & 0xff; b[2] = u3 & 0xff; }
  else { b[0] = u3 & 0xff; b[1] = (u3 >> 8) & 0xff; b[2] = (u3 >> 16) & 0xff; }
  return lsx_writebuf(ft, b, 3) == 3 ? SOX_SUCCESS : SOX_EOF;
}
int lsx_writedw(sox_format_t *ft, unsigned udw)
{
  uint8_t b[4];
  uint32_t v = udw;
  if (ft->encoding.reverse_bytes) v = lsx_swapdw(v);
  b[0] = v & 0xff; b[1] = (v >> 8) & 0xff; b[2] = (v >> 16) & 0xff; b[3] = v >> 24;
  return lsx_writebuf(ft, b, 4) == 4 ? SOX_SUCCESS : SOX_EOF;
}
int lsx_writesdw(sox_format_t *ft, signed sdw) { return lsx_writedw(ft, (unsigned)sdw); }
int lsx_writeqw(sox_format_t *ft, uint64_t uqw)
{
  uint8_t b[8]; int i;
  if (ft->encoding.reverse_bytes) uqw = swapqw(uqw);
  for (i = 0; i < 8; i++) b[i] = (uqw >> (8 * i)) & 0xff;
  return lsx_writebuf(ft, b, 8) == 8 ? SOX_SUCCESS : SOX_EOF;
}
int lsx_writef(sox_format_t *ft, double f)
{
  float t = (float)f; uint32_t u;
  memcpy(&u, &t, 4);
  return lsx_writedw(ft, u);
}
int lsx_writedf(sox_format_t *ft, double d)
{
  uint64_t u;
  memcpy(&u, &d, 8);
  return lsx_writeqw(ft, u);
}

/* ----- raw sample I/O ----- */
extern const int16_t lsx_ulaw2linear16[256];
extern const int16_t lsx_alaw2linear16[256];
uint8_t lsx_14linear2ulaw(int16_t pcm_val);
uint8_t lsx_13linear2alaw(int16_t pcm_val);

static size_t raw_bytes_per_sample(sox_format_t *ft)
{
  switch (ft->encoding.encoding) {
    case SOX_ENCODING_ULAW: case SOX_ENCODING_ALAW: return 1;
    default: return (ft->encoding.bits_per_sample + 7) / 8;
  }
}

size_t lsx_rawread(sox_format_t *ft, sox_sample_t *buf, size_t nsamp)
{
  size_t size = raw_bytes_per_sample(ft);
  size_t i, n, done = 0;
  uint8_t tmp[8192];
  size_t chunk = sizeof(tmp) / size;
  sox_encoding_t enc = ft->encoding.encoding;
  unsigned bits = ft->encoding.bits_per_sample;
  int rb = ft->encoding.reverse_bytes == SOX_OPTION_YES || ft->encoding.reverse_bytes == 1;

  if (size == 0) return 0;
  while (done < nsamp) {
    size_t want = min(chunk, nsamp - done);
    size_t got = lsx_readbuf(ft, tmp, want * size);
    n = got / size;
    for (i = 0; i < n; i++) {
      uint8_t *p = tmp + i * size;
      sox_sample_t s = 0;
      if (size == 1) {
        uint8_t b = p[0];
        if (ft->encoding.reverse_bits) b = lsx_cswap[b];
        if (ft->encoding.reverse_nibbles) b = ((b & 15) << 4) | (b >> 4);
        switch (enc) {
          case SOX_ENCODING_UNSIGNED: s = SOX_UNSIGNED_8BIT_TO_SAMPLE(b); break;
          case SOX_ENCODING_ULAW: s = SOX_SIGNED_16BIT_TO_SAMPLE(lsx_ulaw2linear16[b]); break;
          case SOX_ENCODING_ALAW: s = SOX_SIGNED_16BIT_TO_SAMPLE(lsx_alaw2linear16[b]); break;
          default: s = SOX_SIGNED_8BIT_TO_SAMPLE(b); break;
        }
      } else if (size == 2) {
        uint16_t v = rb ? (p[0] << 8 | p[1]) : (p[0] | p[1] << 8);
        s = enc == SOX_ENCODING_UNSIGNED ? SOX_UNSIGNED_16BIT_TO_SAMPLE(v) : SOX_SIGNED_16BIT_TO_SAMPLE(v);
      } else if (size == 3) {
        uint32_t v = rb ? ((uint32_t)p[0] << 16 | p[1] << 8 | p[2]) : (p[0] | p[1] << 8 | (uint32_t)p[2] << 16);
        s = enc == SOX_ENCODING_UNSIGNED ? SOX_UNSIGNED_24BIT_TO_SAMPLE(v) : SOX_SIGNED_24BIT_TO_SAMPLE(v);
      } else if (size == 4) {
        uint32_t v = rb ? ((uint32_t)p[0] << 24 | (uint32_t)p[1] << 16 | p[2] << 8 | p[3]) : (p[0] | p[1] << 8 | (uint32_t)p[2] << 16 | (uint32_t)p[3] << 24);
        if (enc == SOX_ENCODING_FLOAT) {
          float f; memcpy(&f, &v, 4);
          s = SOX_FLOAT_32BIT_TO_SAMPLE(f, ft->clips);
        } else if (enc == SOX_ENCODING_UNSIGNED) s = SOX_UNSIGNED_32BIT_TO_SAMPLE(v);
        else s = (sox_sample_t)v;
      } else if (size == 8) {
        uint64_t v = 0; int k;
        if (rb) for (k = 0; k < 8; k++) v = (v << 8) | p[k];
        else for (k = 7; k >= 0; k--) v = (v << 8) | p[k];
        { double d; memcpy(&d, &v, 8); s = SOX_FLOAT_64BIT_TO_SAMPLE(d, ft->clips); }
      }
      buf[done + i] = s;
    }
    done += n;
    if (got < want * size) break;
  }
  (void)bits;
  return done;
}

size_t lsx_rawwrite(sox_format_t *ft, const sox_sample_t *buf, size_t nsamp)
{
  size_t size = raw_bytes_per_sample(ft);
  size_t i, done = 0;
  uint8_t tmp[8192];
  size_t chunk = sizeof(tmp) / size;
  sox_encoding_t enc = ft->encoding.encoding;
  int rb = ft->encoding.reverse_bytes == SOX_OPTION_YES || ft->encoding.reverse_bytes == 1;

  if (size == 0) return 0;
  while (done < nsamp) {
    size_t n = min(chunk, nsamp - done);
    for (i = 0; i < n; i++) {
      uint8_t *p = tmp + i * size;
      sox_sample_t s = buf[done + i];
      if (size == 1) {
        uint8_t b;
        switch (enc) {
          case SOX_ENCODING_UNSIGNED: b = SOX_SAMPLE_TO_UNSIGNED_8BIT(s, ft->clips); break;
          case SOX_ENCODING_ULAW: b = lsx_14linear2ulaw((int16_t)(SOX_SAMPLE_TO_SIGNED_16BIT(s, ft->clips) >> 2)); break;
          case SOX_ENCODING_ALAW: b = lsx_13linear2alaw((int16_t)(SOX_SAMPLE_TO_SIGNED_16BIT(s, ft->clips) >> 3)); break;
          default: b = (uint8_t)SOX_SAMPLE_TO_SIGNED_8BIT(s, ft->clips); break;
        }
        if (ft->encoding.reverse_nibbles) b = ((b & 15) << 4) | (b >> 4);
        if (ft->encoding.reverse_bits) b = lsx_cswap[b];
        p[0] = b;
      } else if (size == 2) {
        uint16_t v = enc == SOX_ENCODING_UNSIGNED ? SOX_SAMPLE_TO_UNSIGNED_16BIT(s, ft->clips) : (uint16_t)SOX_SAMPLE_TO_SIGNED_16BIT(s, ft->clips);
        if (rb) { p[0] = v >> 8; p[1] = v & 0xff; } else { p[0] = v & 0xff; p[1] = v >> 8; }
      } else if (size == 3) {
        uint32_t v = enc == SOX_ENCODING_UNSIGNED ? SOX_SAMPLE_TO_UNSIGNED_24BIT(s, ft->clips) : (uint32_t)SOX_SAMPLE_TO_SIGNED_24BIT(s, ft->clips);
        if (rb) { p[0] = (v >> 16) & 0xff; p[1] = (v >> 8) & 0xff; p[2] = v & 0xff; }
        else { p[0] = v & 0xff; p[1] = (v >> 8) & 0xff; p[2] = (v >> 16) & 0xff; }
      } else if (size == 4) {
        uint32_t v;
        if (enc == SOX_ENCODING_FLOAT) { float f = SOX_SAMPLE_TO_FLOAT_32BIT(s, ft->clips); memcpy(&v, &f, 4); }
        else if (enc == SOX_ENCODING_UNSIGNED) v = SOX_SAMPLE_TO_UNSIGNED_32BIT(s, ft->clips);
        else v = (uint32_t)s;
        if (rb) { p[0] = v >> 24; p[1] = (v >> 16) & 0xff; p[2] = (v >> 8) & 0xff; p[3] = v & 0xff; }
        else { p[0] = v & 0xff; p[1] = (v >> 8) & 0xff; p[2] = (v >> 16) & 0xff; p[3] = v >> 24; }
      } else if (size == 8) {
        double d = SOX_SAMPLE_TO_FLOAT_64BIT(s, ft->clips);
        uint64_t v; int k;
        memcpy(&v, &d, 8);
        if (rb) for (k = 0; k < 8; k++) p[k] = (v >> (8 * (7 - k))) & 0xff;
        else for (k = 0; k < 8; k++) p[k] = (v >> (8 * k)) & 0xff;
      }
    }
    if (lsx_writebuf(ft, tmp, n * size) != n * size) {
      return done;
    }
    done += n;
  }
  return done;
}

int lsx_rawseek(sox_format_t *ft, uint64_t offset)
{
  size_t size = raw_bytes_per_sample(ft);
  uint64_t new_offset = offset * size;
  size_t channel_block = size * ft->signal.channels;
  uint64_t alignment = new_offset % channel_block;
  if (alignment != 0) new_offset += (channel_block - alignment);
  new_offset += ft->data_start;
  return lsx_seeki(ft, (int64_t)new_offset, SEEK_SET);
}

int lsx_check_read_params(sox_format_t *ft, unsigned channels, sox_rate_t rate, sox_encoding_t encoding, unsigned bits_per_sample, uint64_t num_samples, sox_bool check_length)
{
  ft->signal.length = ft->signal.length == SOX_IGNORE_LENGTH ? SOX_UNSPEC : num_samples;

  if (ft->seekable)
    ft->data_start = lsx_tell(ft);

  if (channels && ft->signal.channels && ft->signal.channels != channels)
    lsx_warn("`%s': overriding number of channels", ft->filename);
  else ft->signal.channels = channels;

  if (rate && ft->signal.rate && ft->signal.rate != rate)
    lsx_warn("`%s': overriding sample rate", ft->filename);
  else ft->signal.rate = rate;

  if (encoding && ft->encoding.encoding && ft->encoding.encoding != encoding)
    lsx_warn("`%s': overriding encoding type", ft->filename);
  else ft->encoding.encoding = encoding;

  if (bits_per_sample && ft->encoding.bits_per_sample && ft->encoding.bits_per_sample != bits_per_sample)
    lsx_warn("`%s': overriding encoding size", ft->filename);
  ft->encoding.bits_per_sample = bits_per_sample;

  if (check_length && ft->encoding.bits_per_sample && lsx_filelength(ft)) {
    uint64_t calculated_length = ((lsx_filelength(ft) - ft->data_start) * 8) / ft->encoding.bits_per_sample;
    if (!ft->signal.length)
      ft->signal.length = calculated_length;
    else if (num_samples != calculated_length)
      lsx_warn("`%s': file header gives the total number of samples as %llu but file length indicates the number is in fact %llu", ft->filename, (unsigned long long)num_samples, (unsigned long long)calculated_length);
  }

  if (sox_precision(ft->encoding.encoding, ft->encoding.bits_per_sample))
    return SOX_SUCCESS;
  lsx_fail_errno(ft, EINVAL, "invalid format for this file type");
  return SOX_EOF;
}

/* ----- open read/write ----- */
static sox_bool is_url(const char *text)
{
  return !(strncasecmp(text, "http:", 5) && strncasecmp(text, "https:", 6) && strncasecmp(text, "ftp:", 4));
}

#define AUTO_DETECT_SIZE 256
static const char *auto_detect_format(sox_format_t *ft, char const *ext)
{
  char data[AUTO_DETECT_SIZE];
  size_t len = lsx_readbuf(ft, data, ft->seekable ? sizeof(data) : 128);
  static const char prc_header[] = "\x37\x00\x00\x10\x6d\x00\x00\x10\x7e\x00\x00\x10";
  #define CHECK(type, p2, l2, d2, p1, l1, d1) if (len >= p1 + l1 && \
      !memcmp(data + p1, d1, (size_t)l1) && !memcmp(data + p2, d2, (size_t)l2)) return #type;
  CHECK(voc, 0, 0, "", 0, 20, "Creative Voice File\x1a")
  CHECK(smp, 0, 0, "", 0, 17, "SOUND SAMPLE DATA")
  CHECK(wve, 0, 0, "", 0, 15, "ALawSoundFile**")
  CHECK(gsrt, 0, 0, "", 16, 9, "ring.bin")
  CHECK(amr-wb, 0, 0, "", 0, 9, "#!AMR-WB\n")
  CHECK(prc, 0, 0, "", 0, 12, prc_header)
  CHECK(sph, 0, 0, "", 0, 7, "NIST_1A")
  CHECK(amr-nb, 0, 0, "", 0, 6, "#!AMR\n")
  CHECK(txw, 0, 0, "", 0, 6, "LM8953")
  CHECK(sndt, 0, 0, "", 0, 6, "SOUND\x1a")
  CHECK(vorbis, 0, 4, "OggS", 29, 6, "vorbis")
  CHECK(opus, 0, 4, "OggS", 28, 8, "OpusHead")
  CHECK(speex, 0, 4, "OggS", 28, 6, "Speex")
  CHECK(hcom, 65, 4, "FSSD", 128, 4, "HCOM")
  CHECK(wav, 0, 4, "RIFF", 8, 4, "WAVE")
  CHECK(wav, 0, 4, "RIFX", 8, 4, "WAVE")
  CHECK(wav, 0, 4, "RF64", 8, 4, "WAVE")
  CHECK(aiff, 0, 4, "FORM", 8, 4, "AIFF")
  CHECK(aifc, 0, 4, "FORM", 8, 4, "AIFC")
  CHECK(8svx, 0, 4, "FORM", 8, 4, "8SVX")
  CHECK(maud, 0, 4, "FORM", 8, 4, "MAUD")
  CHECK(xa, 0, 0, "", 0, 4, "XA\0\0")
  CHECK(xa, 0, 0, "", 0, 4, "XAI\0")
  CHECK(xa, 0, 0, "", 0, 4, "XAJ\0")
  CHECK(au, 0, 0, "", 0, 4, ".snd")
  CHECK(au, 0, 0, "", 0, 4, "dns.")
  CHECK(au, 0, 0, "", 0, 4, "\0ds.")
  CHECK(au, 0, 0, "", 0, 4, ".sd\0")
  CHECK(flac, 0, 0, "", 0, 4, "fLaC")
  CHECK(avr, 0, 0, "", 0, 4, "2BIT")
  CHECK(caf, 0, 0, "", 0, 4, "caff")
  CHECK(wv, 0, 0, "", 0, 4, "wvpk")
  CHECK(paf, 0, 0, "", 0, 4, " paf")
  CHECK(sf, 0, 0, "", 0, 4, "\144\243\001\0")
  CHECK(sf, 0, 0, "", 0, 4, "\0\001\243\144")
  CHECK(sf, 0, 0, "", 0, 4, "\144\243\002\0")
  CHECK(sf, 0, 0, "", 0, 4, "\0\002\243\144")
  CHECK(sf, 0, 0, "", 0, 4, "\144\243\003\0")
  CHECK(sf, 0, 0, "", 0, 4, "\0\003\243\144")
  CHECK(sf, 0, 0, "", 0, 4, "\144\243\004\0")
  CHECK(sox, 0, 0, "", 0, 4, ".SoX")
  CHECK(sox, 0, 0, "", 0, 4, "XoS.")
  if (ext && !strcasecmp(ext, "snd"))
    CHECK(sndr, 7, 1, "", 0, 2, "\0")
  #undef CHECK
  return NULL;
}

static void set_endiannesses(sox_format_t *ft)
{
  /* machine is little endian */
  if (ft->encoding.opposite_endian)
    ft->encoding.reverse_bytes = (ft->handler.flags & SOX_FILE_ENDIAN) ?
      !(ft->handler.flags & SOX_FILE_ENDBIG) != 0 : sox_true;
  else if (ft->encoding.reverse_bytes == SOX_OPTION_DEFAULT)
    ft->encoding.reverse_bytes = (ft->handler.flags & SOX_FILE_ENDIAN) ?
      !(ft->handler.flags & SOX_FILE_ENDBIG) == 0 : sox_false;
  else if (ft->handler.flags & SOX_FILE_ENDIAN) {
    if (ft->encoding.reverse_bytes == (sox_option_t)(!(ft->handler.flags & SOX_FILE_ENDBIG) != 0))
      lsx_report("`%s': overriding file-type byte-order", ft->filename);
  } else if (ft->encoding.reverse_bytes == SOX_OPTION_YES)
    lsx_report("`%s': overriding machine byte-order", ft->filename);

  if (ft->encoding.reverse_bits == SOX_OPTION_DEFAULT)
    ft->encoding.reverse_bits = !!(ft->handler.flags & SOX_FILE_BIT_REV);
  else if (ft->encoding.reverse_bits == !(ft->handler.flags & SOX_FILE_BIT_REV))
    lsx_report("`%s': overriding file-type bit-order", ft->filename);

  if (ft->encoding.reverse_nibbles == SOX_OPTION_DEFAULT)
    ft->encoding.reverse_nibbles = !!(ft->handler.flags & SOX_FILE_NIB_REV);
  else if (ft->encoding.reverse_nibbles == !(ft->handler.flags & SOX_FILE_NIB_REV))
    lsx_report("`%s': overriding file-type nibble-order", ft->filename);
}

static sox_bool is_seekable(sox_format_t const *ft)
{
  struct stat st;
  if (!ft->fp) return sox_false;
  fstat(fileno(ft->fp), &st);
  return ((st.st_mode & S_IFMT) == S_IFREG);
}

static FILE *xfopen(char const *identifier, char const *mode, int *io_type)
{
  *io_type = 0;
  if (*identifier == '|') {
    FILE *f = popen(identifier + 1, *mode == 'r' ? "r" : "w");
    *io_type = 1;
    return f;
  }
  return fopen(identifier, mode);
}

sox_format_t *sox_open_read(const char *path, const sox_signalinfo_t *signal, const sox_encodinginfo_t *encoding, const char *filetype)
{
  sox_format_t *ft = lsx_calloc(1, sizeof(*ft));
  const sox_format_handler_t *handler;
  char const *const io_types[] = {"file", "pipe", "file URL"};
  char const *type = "";
  int io_type = 0;
  const char *save_sub = sox_globals.subsystem;

  lsx_set_subsystem("formats");
  if (filetype) {
    if (!(handler = sox_find_format(filetype, sox_false))) {
      lsx_fail("no handler for given file type `%s'", filetype);
      goto error;
    }
    ft->handler = *handler;
  }

  if (!(ft->handler.flags & SOX_FILE_NOSTDIO)) {
    if (!strcmp(path, "-")) {
      if (sox_globals.stdin_in_use_by) {
        lsx_fail("`-' (stdin) already in use by `%s'", sox_globals.stdin_in_use_by);
        goto error;
      }
      sox_globals.stdin_in_use_by = "audio input";
      ft->fp = stdin;
      ft->is_stdio = 1;
    } else {
      ft->fp = xfopen(path, "rb", &io_type);
      type = io_types[io_type];
      if (ft->fp == NULL) {
        lsx_fail("can't open input %s `%s': %s", type, path, strerror(errno));
        goto error;
      }
    }
    ft->seekable = is_seekable(ft);
  }

  if (!filetype) {
    if (ft->seekable || 1) {
      const char *ext = lsx_find_file_extension(path);
      filetype = auto_detect_format(ft, ext);
      if (ft->seekable) lsx_rewind(ft);
      else {
        /* pipe: cannot rewind; reopen not possible. We buffered via ungetc? */
      }
    }
    if (filetype) {
      lsx_report("detected file format type `%s'", filetype);
      if (!(handler = sox_find_format(filetype, sox_false))) {
        lsx_fail("no handler for detected file type `%s'", filetype);
        goto error;
      }
    } else {
      if (io_type == 1) {
        lsx_fail("type-detection for pipes is not supported");
        goto error;
      }
      if (!(filetype = lsx_find_file_extension(path))) {
        lsx_fail("can't determine type of %s `%s'", type, path);
        goto error;
      }
      if (!(handler = sox_find_format(filetype, sox_true))) {
        lsx_fail("no handler for file extension `%s'", filetype);
        goto error;
      }
    }
    ft->handler = *handler;
  }
  if (!ft->handler.startread && !ft->handler.read) {
    lsx_fail("file type `%s' isn't readable", filetype);
    goto error;
  }

  ft->mode = 'r';
  ft->filetype = lsx_strdup(filetype);
  ft->filename = lsx_strdup(path);
  if (signal)
    ft->signal = *signal;

  if (encoding)
    ft->encoding = *encoding;
  else sox_init_encodinginfo(&ft->encoding);
  set_endiannesses(ft);

  if ((ft->handler.flags & SOX_FILE_DEVICE) && !(ft->handler.flags & SOX_FILE_PHONY))
    lsx_set_dft_length(0);

  ft->priv = lsx_calloc(1, ft->handler.priv_size);
  /* Read and write starters can change their formats. */
  if (ft->handler.startread) {
    const char *sub = ft->handler.names[0];
    lsx_set_subsystem(NULL);
    {
      extern const char *lsx_format_subsystem(const sox_format_handler_t *);
      lsx_set_subsystem(lsx_format_subsystem(&ft->handler));
    }
    (void)sub;
    if ((*ft->handler.startread)(ft) != SOX_SUCCESS) {
      lsx_set_subsystem("formats");
      lsx_fail("can't open input %s `%s': %s", type, ft->filename, ft->sox_errstr);
      goto error;
    }
    lsx_set_subsystem("formats");
  }

  /* Fill in some defaults: */
  if (sox_precision(ft->encoding.encoding, ft->encoding.bits_per_sample))
    ft->signal.precision = sox_precision(ft->encoding.encoding, ft->encoding.bits_per_sample);
  /* Check that the settings are valid: */
  {
    char const *s = NULL;
    if (ft->signal.rate <= 0) s = "sample rate zero or negative";
    else if (!ft->signal.precision) s = "data encoding or sample size was not specified";
    else if (!ft->signal.channels) s = "channel count zero";
    if (s) {
      lsx_fail("bad input format for %s `%s': %s", type, ft->filename, s);
      goto error;
    }
  }
  lsx_set_subsystem(save_sub);
  return ft;

error:
  if (ft->fp && ft->fp != stdin) fclose(ft->fp);
  free(ft->priv);
  free(ft->filename);
  free(ft->filetype);
  free(ft);
  lsx_set_subsystem(save_sub);
  return NULL;
}

static sox_bool set_output_format(sox_format_t *ft)
{
  sox_encoding_t e = SOX_ENCODING_UNKNOWN;
  unsigned i, s;
  unsigned const *encodings = ft->handler.write_formats;
#define enc_arg(T) (T)encodings[i++]

  if (ft->handler.write_rates) {
    if (!ft->signal.rate)
      ft->signal.rate = ft->handler.write_rates[0];
    else {
      sox_rate_t r;
      i = 0;
      while ((r = ft->handler.write_rates[i++])) {
        if (r == ft->signal.rate)
          break;
      }
      if (r != ft->signal.rate) {
        sox_rate_t given = ft->signal.rate, mx = 0;
        ft->signal.rate = HUGE_VAL;
        i = 0;
        while ((r = ft->handler.write_rates[i++])) {
          if (r > given && r < ft->signal.rate)
            ft->signal.rate = r;
          else mx = max(r, mx);
        }
        if (ft->signal.rate == HUGE_VAL)
          ft->signal.rate = mx;
        lsx_warn("%s can't encode at %gHz; using %gHz", ft->handler.names[0], given, ft->signal.rate);
      }
    }
  } else if (!ft->signal.rate)
    ft->signal.rate = SOX_DEFAULT_RATE;

  if (ft->handler.flags & SOX_FILE_CHANS) {
    if (ft->signal.channels == 1 && !(ft->handler.flags & SOX_FILE_MONO)) {
      ft->signal.channels = (ft->handler.flags & SOX_FILE_STEREO) ? 2 : 4;
      lsx_warn("%s can't encode mono; setting channels to %u", ft->handler.names[0], ft->signal.channels);
    } else if (ft->signal.channels == 2 && !(ft->handler.flags & SOX_FILE_STEREO)) {
      ft->signal.channels = (ft->handler.flags & SOX_FILE_QUAD) ? 4 : 1;
      lsx_warn("%s can't encode stereo; setting channels to %u", ft->handler.names[0], ft->signal.channels);
    } else if (ft->signal.channels == 4 && !(ft->handler.flags & SOX_FILE_QUAD)) {
      ft->signal.channels = (ft->handler.flags & SOX_FILE_STEREO) ? 2 : 1;
      lsx_warn("%s can't encode quad; setting channels to %u", ft->handler.names[0], ft->signal.channels);
    }
  } else ft->signal.channels = max(ft->signal.channels, 1);

  if (!encodings)
    return sox_true;
  /* If an encoding has been given, check if it supported by this handler */
  if (ft->encoding.encoding) {
    i = 0;
    while ((e = enc_arg(sox_encoding_t)))
      if (e == ft->encoding.encoding)
        break;
      else while (enc_arg(unsigned));
    if (e != ft->encoding.encoding) {
      lsx_warn("%s can't encode %s", ft->handler.names[0], sox_encodings_info[ft->encoding.encoding].desc);
      ft->encoding.encoding = 0;
    } else {
      unsigned max_p = 0;
      unsigned max_p_s = 0;
      unsigned given_size = 0;
      sox_bool found = sox_false;
      if (ft->encoding.bits_per_sample)
        given_size = ft->encoding.bits_per_sample;
      ft->encoding.bits_per_sample = 65;
      while ((s = enc_arg(unsigned))) {
        if (s == given_size)
          found = sox_true;
        if (sox_precision(e, s) >= ft->signal.precision) {
          if (s < ft->encoding.bits_per_sample)
            ft->encoding.bits_per_sample = s;
        } else if (sox_precision(e, s) > max_p) {
          max_p = sox_precision(e, s);
          max_p_s = s;
        }
      }
      if (ft->encoding.bits_per_sample == 65)
        ft->encoding.bits_per_sample = max_p_s;
      if (given_size) {
        if (found)
          ft->encoding.bits_per_sample = given_size;
        else lsx_warn("%s can't encode %s to %u-bit", ft->handler.names[0], sox_encodings_info[ft->encoding.encoding].desc, given_size);
      }
    }
  }

  /* If a size has been given, check if it supported by this handler */
  if (!ft->encoding.encoding && ft->encoding.bits_per_sample) {
    i = 0;
    s = 0;
    while (s != ft->encoding.bits_per_sample && (e = enc_arg(sox_encoding_t)))
      while ((s = enc_arg(unsigned)) && s != ft->encoding.bits_per_sample);
    if (s != ft->encoding.bits_per_sample) {
      lsx_warn("%s can't encode to %u-bit", ft->handler.names[0], ft->encoding.bits_per_sample);
      ft->encoding.bits_per_sample = 0;
    } else ft->encoding.encoding = e;
  }

  /* Find the smallest lossless encoding with precision >= signal.precision */
  if (!ft->encoding.encoding) {
    ft->encoding.bits_per_sample = 65;
    i = 0;
    while ((e = enc_arg(sox_encoding_t)))
      while ((s = enc_arg(unsigned)))
        if (!(sox_encodings_info[e].flags & (SOX_LOSSY1 | SOX_LOSSY2)) &&
            sox_precision(e, s) >= ft->signal.precision && s < ft->encoding.bits_per_sample) {
          ft->encoding.encoding = e;
          ft->encoding.bits_per_sample = s;
        }
  }

  /* Find the smallest lossy encoding with precision >= signal precision,
   * or, if none such, the highest precision encoding */
  if (!ft->encoding.encoding) {
    unsigned max_p = 0;
    sox_encoding_t max_p_e = 0;
    unsigned max_p_s = 0;
    i = 0;
    while ((e = enc_arg(sox_encoding_t)))
      do {
        s = enc_arg(unsigned);
        if (sox_precision(e, s) >= ft->signal.precision) {
          if (s < ft->encoding.bits_per_sample) {
            ft->encoding.encoding = e;
            ft->encoding.bits_per_sample = s;
          }
        } else if (sox_precision(e, s) > max_p) {
          max_p = sox_precision(e, s);
          max_p_e = e;
          max_p_s = s;
        }
      } while (s);
    if (!ft->encoding.encoding) {
      ft->encoding.encoding = max_p_e;
      ft->encoding.bits_per_sample = max_p_s;
    }
  }
  ft->signal.precision = min(ft->signal.precision, sox_precision(ft->encoding.encoding, ft->encoding.bits_per_sample));
#undef enc_arg
  return ft->encoding.encoding != 0;
}

sox_format_t *sox_open_write(const char *path, const sox_signalinfo_t *signal, const sox_encodinginfo_t *encoding, const char *filetype, const sox_comments_t *comments, sox_bool (*overwrite_permitted)(const char *filename))
{
  sox_bool no_filetype_given = filetype == NULL;
  sox_format_t *ft = lsx_calloc(1, sizeof(*ft));
  const sox_format_handler_t *handler;
  const char *save_sub = sox_globals.subsystem;

  lsx_set_subsystem("formats");
  if (!path || !signal) {
    lsx_fail("must specify file name and signal parameters to write file");
    goto error;
  }

  if (filetype) {
    if (!(handler = sox_find_format(filetype, sox_false))) {
      lsx_fail("no handler for given file type `%s'", filetype);
      goto error;
    }
    ft->handler = *handler;
  } else {
    const char *extension = lsx_find_file_extension(path);
    if (!extension || !strcmp(path, "-")) {
      lsx_fail("can't determine type of `%s'", path);
      goto error;
    }
    if (!(handler = sox_find_format(extension, sox_true))) {
      lsx_fail("no handler for file extension `%s'", extension);
      goto error;
    }
    ft->handler = *handler;
    filetype = extension;
  }
  if (!ft->handler.startwrite && !ft->handler.write) {
    lsx_fail("file type `%s' isn't writeable", filetype);
    goto error;
  }

  if (!(ft->handler.flags & SOX_FILE_NOSTDIO)) {
    if (!strcmp(path, "-")) {
      if (sox_globals.stdout_in_use_by) {
        lsx_fail("`-' (stdout) already in use by `%s'", sox_globals.stdout_in_use_by);
        goto error;
      }
      sox_globals.stdout_in_use_by = "audio output";
      ft->fp = stdout;
      ft->is_stdio = 1;
    } else {
      struct stat st;
      if (!stat(path, &st) && (st.st_mode & S_IFMT) == S_IFREG &&
          (overwrite_permitted && !overwrite_permitted(path))) {
        lsx_fail("permission to overwrite `%s' denied", path);
        goto error;
      }
      ft->fp = fopen(path, "w+b");
      if (ft->fp == NULL) {
        lsx_fail("can't open output file `%s': %s", path, strerror(errno));
        goto error;
      }
    }
    ft->seekable = is_seekable(ft);
  }

  ft->filetype = lsx_strdup(filetype);
  ft->filename = lsx_strdup(path);
  ft->mode = 'w';
  ft->signal = *signal;

  if (encoding)
    ft->encoding = *encoding;
  else sox_init_encodinginfo(&ft->encoding);
  set_endiannesses(ft);

  if (comments != NULL)
    sox_copy_comments(&ft->comments, comments);

  ft->priv = lsx_calloc(1, ft->handler.priv_size);
  if (!set_output_format(ft)) {
    lsx_fail("can't open output file `%s': %s", path, "this handler does not support this data size");
    goto error;
  }
  (void)no_filetype_given;

  if (ft->handler.startwrite) {
    extern const char *lsx_format_subsystem(const sox_format_handler_t *);
    int r;
    lsx_set_subsystem(lsx_format_subsystem(&ft->handler));
    r = ft->handler.startwrite(ft);
    lsx_set_subsystem("formats");
    if (r != SOX_SUCCESS) {
      lsx_fail("can't open output file `%s': %s", ft->filename, ft->sox_errstr);
      goto error;
    }
  }
  lsx_set_subsystem(save_sub);
  return ft;

error:
  if (ft->fp && ft->fp != stdout) fclose(ft->fp);
  free(ft->priv);
  free(ft->filename);
  free(ft->filetype);
  free(ft);
  lsx_set_subsystem(save_sub);
  return NULL;
}

size_t sox_read(sox_format_t *ft, sox_sample_t *buf, size_t len)
{
  size_t actual;
  extern const char *lsx_format_subsystem(const sox_format_handler_t *);
  const char *save = sox_globals.subsystem;
  if (ft->signal.length != SOX_UNSPEC)
    len = min(len, ft->signal.length - ft->olength);
  lsx_set_subsystem(lsx_format_subsystem(&ft->handler));
  actual = ft->handler.read ? (*ft->handler.read)(ft, buf, len) : 0;
  lsx_set_subsystem(save);
  actual = actual > len ? 0 : actual;
  ft->olength += actual;
  return actual;
}

size_t sox_write(sox_format_t *ft, const sox_sample_t *buf, size_t len)
{
  size_t actual;
  extern const char *lsx_format_subsystem(const sox_format_handler_t *);
  const char *save = sox_globals.subsystem;
  lsx_set_subsystem(lsx_format_subsystem(&ft->handler));
  actual = ft->handler.write ? (*ft->handler.write)(ft, buf, len) : 0;
  lsx_set_subsystem(save);
  ft->olength += actual;
  return actual;
}

int sox_close(sox_format_t *ft)
{
  int result = SOX_SUCCESS;
  extern const char *lsx_format_subsystem(const sox_format_handler_t *);
  const char *save = sox_globals.subsystem;
  lsx_set_subsystem(lsx_format_subsystem(&ft->handler));
  if (ft->mode == 'r')
    result = ft->handler.stopread ? (*ft->handler.stopread)(ft) : SOX_SUCCESS;
  else {
    if (ft->handler.flags & SOX_FILE_REWIND) {
      if (ft->olength != ft->signal.length && ft->seekable) {
        result = lsx_seeki(ft, 0, 0);
        if (result == SOX_SUCCESS)
          result = ft->handler.stopwrite ? (*ft->handler.stopwrite)(ft)
             : ft->handler.startwrite ? (*ft->handler.startwrite)(ft) : SOX_SUCCESS;
      }
    } else result = ft->handler.stopwrite ? (*ft->handler.stopwrite)(ft) : SOX_SUCCESS;
  }
  lsx_set_subsystem(save);
  if (ft->fp) {
    if (ft->fp == stdin || ft->fp == stdout) fflush(ft->fp);
    else fclose(ft->fp);
  }
  free(ft->filename);
  free(ft->filetype);
  sox_delete_comments(&ft->comments);
  free(ft->priv);
  free(ft);
  return result;
}

int sox_seek(sox_format_t *ft, uint64_t offset, int whence)
{
  if (whence != 0) return SOX_EOF;
  if (!(ft->seekable && ft->handler.seek)) return SOX_EOF;
  {
    int r = (*ft->handler.seek)(ft, offset);
    if (r == SOX_SUCCESS) ft->olength = offset;
    return r;
  }
}
