static int findChunk(sox_format_t *ft, const char *Label, uint32_t *len)
{
  char magic[5];
  for (;;) {
    if (lsx_reads(ft, magic, (size_t)4) == SOX_EOF) {
      lsx_fail_errno(ft, SOX_EHDR, "WAVE file has missing %s chunk", Label);
      return SOX_EOF;
    }
    if (lsx_readdw(ft, len) == SOX_EOF) {
      lsx_fail_errno(ft, SOX_EHDR, "WAVE file %s chunk is too short", magic);
      return SOX_EOF;
    }
    lsx_debug("Found chunk '%s', size %u", magic, *len);
    if (strncmp(Label, magic, (size_t)4) == 0)
      break;
    /* skip to next chunk */
    if (*len == 0 || lsx_seeki(ft, (int64_t)*len + (*len & 1), SEEK_CUR) != SOX_SUCCESS) {
      if (*len == 0) continue;
      lsx_fail_errno(ft, SOX_EHDR, "WAV chunk appears to have invalid size %d.", *len);
      return SOX_EOF;
    }
  }
  return SOX_SUCCESS;
}

/* lsx_reads reads up to newline; we need exact 4 bytes */
static int read4(sox_format_t *ft, char *buf)
{
  if (lsx_readbuf(ft, buf, 4) != 4) return SOX_EOF;
  buf[4] = 0;
  return SOX_SUCCESS;
}

static int findChunk4(sox_format_t *ft, const char *Label, uint32_t *len)
{
  char magic[5];
  for (;;) {
    if (read4(ft, magic) == SOX_EOF) {
      lsx_fail_errno(ft, SOX_EHDR, "WAVE file has missing %s chunk", Label);
      return SOX_EOF;
    }
    if (lsx_readdw(ft, len) == SOX_EOF) {
      lsx_fail_errno(ft, SOX_EHDR, "WAVE file %s chunk is too short", magic);
      return SOX_EOF;
    }
    lsx_debug("Found chunk '%s', size %u", magic, *len);
    if (strncmp(Label, magic, (size_t)4) == 0)
      break;
    if (lsx_seeki(ft, (int64_t)*len + (*len & 1), SEEK_CUR) != SOX_SUCCESS) {
      lsx_fail_errno(ft, SOX_EHDR, "WAV chunk appears to have invalid size %d.", *len);
      return SOX_EOF;
    }
  }
  return SOX_SUCCESS;
}

static int startread(sox_format_t *ft)
{
  priv_t *wav = (priv_t *)ft->priv;
  char magic[5];
  uint32_t dwRiffLength;
  unsigned short wChannels;
  uint32_t dwSampleRate;
  uint32_t dwAvgBytesPerSec;
  uint16_t wBitsPerSample;
  uint32_t len;
  int bytesPerBlock = 0;
  int bytespersample;
  uint16_t wExtSize = 0;
  sox_encoding_t encoding = SOX_ENCODING_UNKNOWN;
  (void)findChunk;

  ft->sox_errno = SOX_SUCCESS;
  wav->ignoreSize = ft->signal.length == SOX_IGNORE_LENGTH;

  if (read4(ft, magic) == SOX_EOF || (strncmp("RIFF", magic, 4) && strncmp("RIFX", magic, 4) && strncmp("RF64", magic, 4))) {
    lsx_fail_errno(ft, SOX_EHDR, "WAVE: RIFF header not found");
    return SOX_EOF;
  }

  /* RIFX is a Big-endian RIFF */
  if (strncmp("RIFX", magic, 4) == 0) {
    lsx_debug("Found RIFX header");
    ft->encoding.reverse_bytes = SOX_OPTION_YES;
  } else ft->encoding.reverse_bytes = SOX_OPTION_NO;
  wav->isRF64 = !strncmp("RF64", magic, 4);

  lsx_readdw(ft, &dwRiffLength);

  if (read4(ft, magic) == SOX_EOF || strncmp("WAVE", magic, 4)) {
    lsx_fail_errno(ft, SOX_EHDR, "WAVE header not found");
    return SOX_EOF;
  }

  if (wav->isRF64) {
    if (findChunk4(ft, "ds64", &len) == SOX_EOF) {
      return SOX_EOF;
    }
    lsx_seeki(ft, (int64_t)len, SEEK_CUR);
  }

  /* Now look for the format chunk */
  if (findChunk4(ft, "fmt ", &len) == SOX_EOF) {
    return SOX_EOF;
  }
  wav->formatTag = 0;
  if (len < 16) {
    lsx_fail_errno(ft, SOX_EHDR, "WAVE file fmt chunk is too short");
    return SOX_EOF;
  }

  lsx_readw(ft, &wav->formatTag);
  lsx_readw(ft, &wChannels);
  lsx_readdw(ft, &dwSampleRate);
  lsx_readdw(ft, &dwAvgBytesPerSec);
  lsx_readw(ft, &wav->blockAlign);
  lsx_readw(ft, &wBitsPerSample);
  len -= 16;

  if (wav->formatTag == WAVE_FORMAT_EXTENSIBLE) {
    uint16_t numberOfValidBits;
    uint32_t speakerPositionMask;
    uint16_t subFormatTag;
    uint8_t dummyByte;
    int i;

    if (len < 2) {
      lsx_fail_errno(ft, SOX_EHDR, "WAVE file fmt chunk is too short");
      return SOX_EOF;
    }
    lsx_readw(ft, &wExtSize);
    len -= 2;
    if (wExtSize < 22) {
      lsx_fail_errno(ft, SOX_EHDR, "WAVE file fmt chunk is too short");
      return SOX_EOF;
    }
    lsx_readw(ft, &numberOfValidBits);
    lsx_readdw(ft, &speakerPositionMask);
    lsx_readw(ft, &subFormatTag);
    for (i = 0; i < 14; ++i) lsx_readb(ft, &dummyByte);
    len -= 22;
    if (numberOfValidBits > wBitsPerSample) {
      lsx_fail_errno(ft, SOX_EHDR, "WAVE file fmt with padded samples is not supported yet");
      return SOX_EOF;
    }
    wav->formatTag = subFormatTag;
    lsx_report("EXTENSIBLE");
  }

  switch (wav->formatTag) {
    case WAVE_FORMAT_UNKNOWN:
      lsx_fail_errno(ft, SOX_EHDR, "WAVE file is in unsupported Microsoft Official Unknown format.");
      return SOX_EOF;
    case WAVE_FORMAT_PCM:
      if (wBitsPerSample == 8)
        encoding = SOX_ENCODING_UNSIGNED;
      else
        encoding = SOX_ENCODING_SIGN2;
      break;
    case WAVE_FORMAT_IMA_ADPCM:
      if (wBitsPerSample != 4) {
        lsx_fail_errno(ft, SOX_EOF, "Can only handle 4-bit IMA ADPCM in wav files");
        return SOX_EOF;
      }
      encoding = SOX_ENCODING_IMA_ADPCM;
      break;
    case WAVE_FORMAT_ADPCM:
      if (wBitsPerSample != 4) {
        lsx_fail_errno(ft, SOX_EOF, "Can only handle 4-bit MS ADPCM in wav files");
        return SOX_EOF;
      }
      encoding = SOX_ENCODING_MS_ADPCM;
      break;
    case WAVE_FORMAT_IEEE_FLOAT:
      if (wBitsPerSample == 32 || wBitsPerSample == 64)
        encoding = SOX_ENCODING_FLOAT;
      else {
        lsx_fail_errno(ft, SOX_EFMT, "Unsupported floating point format");
        return SOX_EOF;
      }
      break;
    case WAVE_FORMAT_ALAW:
      encoding = SOX_ENCODING_ALAW;
      break;
    case WAVE_FORMAT_MULAW:
      encoding = SOX_ENCODING_ULAW;
      break;
    default:
      lsx_fail_errno(ft, SOX_EHDR, "WAV file has unsupported format type 0x%x (%s)", wav->formatTag, wav_format_str(wav->formatTag));
      return SOX_EOF;
  }

  if (ft->encoding.encoding && ft->encoding.encoding != encoding)
    lsx_report("User options overriding encoding read in .wav header");
  else ft->encoding.encoding = encoding;

  if (ft->signal.channels == 0 || ft->signal.channels == wChannels)
    ft->signal.channels = wChannels;
  else
    lsx_report("User options overriding channels read in .wav header");

  if (ft->signal.channels == 0) {
    lsx_fail_errno(ft, SOX_EHDR, "Channel count is zero");
    return SOX_EOF;
  }

  if (ft->signal.rate == 0 || ft->signal.rate == dwSampleRate)
    ft->signal.rate = dwSampleRate;
  else
    lsx_report("User options overriding rate read in .wav header");

  wav->lsx_ms_adpcm_i_coefs = NULL;
  wav->packet = NULL;
  wav->samples = NULL;

  /* non-PCM formats except alaw and mulaw formats have extended fmt chunk. */
  if (wav->formatTag != WAVE_FORMAT_PCM &&
      wav->formatTag != WAVE_FORMAT_ALAW &&
      wav->formatTag != WAVE_FORMAT_MULAW) {
    if (len >= 2) {
      lsx_readw(ft, &wExtSize);
      len -= 2;
    } else {
      lsx_warn("wave header missing extended part of fmt chunk");
    }
  }

  if (wExtSize > len) {
    lsx_fail_errno(ft, SOX_EOF, "wave header error: wExtSize inconsistent with wFmtLen");
    return SOX_EOF;
  }

  switch (wav->formatTag) {
    case WAVE_FORMAT_ADPCM:
      if (wExtSize < 4) {
        lsx_fail_errno(ft, SOX_EOF, "format[%s]: expects wExtSize >= %d", wav_format_str(wav->formatTag), 4);
        return SOX_EOF;
      }
      if (wBitsPerSample != 4) {
        lsx_fail_errno(ft, SOX_EOF, "Can only handle 4-bit MS ADPCM in wav files");
        return SOX_EOF;
      }
      lsx_readw(ft, &wav->samplesPerBlock);
      bytesPerBlock = lsx_ms_adpcm_bytes_per_block(ft->signal.channels, wav->samplesPerBlock);
      if (bytesPerBlock > wav->blockAlign) {
        lsx_fail_errno(ft, SOX_EOF, "format[%s]: samplesPerBlock(%d) incompatible with blockAlign(%d)", wav_format_str(wav->formatTag), wav->samplesPerBlock, wav->blockAlign);
        return SOX_EOF;
      }
      lsx_readw(ft, &wav->nCoefs);
      if (wav->nCoefs < 7 || wav->nCoefs > 0x100) {
        lsx_fail_errno(ft, SOX_EOF, "ADPCM file nCoefs (%.4hx) makes no sense", wav->nCoefs);
        return SOX_EOF;
      }
      wav->packet = lsx_malloc(wav->blockAlign);
      len -= 4;
      if (wExtSize < 4 + 4 * wav->nCoefs) {
        lsx_fail_errno(ft, SOX_EOF, "wave header error: wExtSize(%d) too small for nCoefs(%d)", wExtSize, wav->nCoefs);
        return SOX_EOF;
      }
      wav->samples = lsx_malloc(wChannels * wav->samplesPerBlock * sizeof(short));
      wav->lsx_ms_adpcm_i_coefs = lsx_malloc(wav->nCoefs * 2 * sizeof(short));
      {
        int i, errct = 0;
        for (i = 0; len >= 2 && i < 2 * wav->nCoefs; i++) {
          int16_t c;
          lsx_readsw(ft, &c);
          wav->lsx_ms_adpcm_i_coefs[i] = c;
          len -= 2;
          if (i < 14) errct += (wav->lsx_ms_adpcm_i_coefs[i] != lsx_ms_adpcm_i_coef[i / 2][i % 2]);
        }
        if (errct) lsx_warn("base lsx_ms_adpcm_i_coefs differ in %d/14 positions", errct);
      }
      bytespersample = 2;
      break;

    case WAVE_FORMAT_IMA_ADPCM:
      if (wExtSize < 2) {
        lsx_fail_errno(ft, SOX_EOF, "format[%s]: expects wExtSize >= %d", wav_format_str(wav->formatTag), 2);
        return SOX_EOF;
      }
      if (wBitsPerSample != 4) {
        lsx_fail_errno(ft, SOX_EOF, "Can only handle 4-bit IMA ADPCM in wav files");
        return SOX_EOF;
      }
      lsx_readw(ft, &wav->samplesPerBlock);
      bytesPerBlock = lsx_ima_bytes_per_block(ft->signal.channels, wav->samplesPerBlock);
      if (bytesPerBlock > wav->blockAlign || wav->samplesPerBlock % 8 != 1) {
        lsx_fail_errno(ft, SOX_EOF, "format[%s]: samplesPerBlock(%d) incompatible with blockAlign(%d)", wav_format_str(wav->formatTag), wav->samplesPerBlock, wav->blockAlign);
        return SOX_EOF;
      }
      wav->packet = lsx_malloc(wav->blockAlign);
      len -= 2;
      wav->samples = lsx_malloc(wChannels * wav->samplesPerBlock * sizeof(short));
      bytespersample = 2;
      break;

    case WAVE_FORMAT_IEEE_FLOAT:
    case WAVE_FORMAT_PCM:
    case WAVE_FORMAT_ALAW:
    case WAVE_FORMAT_MULAW:
    default:
      bytespersample = (wBitsPerSample + 7) / 8;
      break;
  }

  /* User options take precedence */
  if (!ft->encoding.bits_per_sample || ft->encoding.bits_per_sample == wBitsPerSample)
    ft->encoding.bits_per_sample = wBitsPerSample;
  else
    lsx_warn("User options overriding size read in .wav header");

  /* Skip anything left over from fmt chunk */
  lsx_seeki(ft, (int64_t)len, SEEK_CUR);

  /* for non-PCM formats, there's a 'fact' chunk before the 'data' chunk */
  /* Now look for the wave data chunk */
  if (findChunk4(ft, "data", &len) == SOX_EOF) {
    lsx_fail_errno(ft, SOX_EOF, "Could not find data chunk.");
    return SOX_EOF;
  }
  wav->dataStart = lsx_tell(ft);

  /* Data starts here */
  if (len == UINT32_MAX || len == 0x7ffff000u) {
    lsx_warn("WAV data length is magic value or UINT32_MAX, ignoring");
    wav->ignoreSize = 1;
  }
  if (wav->ignoreSize) {
    len = 0;
    if (ft->seekable) {
      uint64_t flen = lsx_filelength(ft);
      if (flen > wav->dataStart) {
        uint64_t l = flen - wav->dataStart;
        len = l > UINT32_MAX ? UINT32_MAX : (uint32_t)l;
      }
    }
  }
  wav->dataLength = len;

  switch (wav->formatTag) {
    case WAVE_FORMAT_ADPCM:
      wav->numSamples = lsx_ms_adpcm_samples_in(wav->dataLength, ft->signal.channels, wav->blockAlign, wav->samplesPerBlock);
      wav->blockSamplesRemaining = 0;
      break;
    case WAVE_FORMAT_IMA_ADPCM:
      wav->numSamples = lsx_ima_samples_in(wav->dataLength, ft->signal.channels, wav->blockAlign, wav->samplesPerBlock);
      wav->blockSamplesRemaining = 0;
      lsx_ima_init_table();
      break;
    default:
      wav->numSamples = bytespersample && ft->signal.channels ? wav->dataLength / bytespersample / ft->signal.channels : 0;
      break;
  }
  if (wav->ignoreSize && !ft->seekable) wav->numSamples = 0;
  ft->signal.length = (wav->ignoreSize && !ft->seekable) ? SOX_UNSPEC : wav->numSamples * ft->signal.channels;
  if (wav->ignoreSize && ft->seekable) ft->signal.length = wav->numSamples * ft->signal.channels;
  if (wav->ignoreSize && !ft->seekable) ft->signal.length = SOX_UNSPEC;

  lsx_debug("Reading Wave file: %s format, %d channel%s, %d samp/sec",
      wav_format_str(wav->formatTag), ft->signal.channels,
      wChannels == 1 ? "" : "s", dwSampleRate);
  lsx_debug("        %d byte/sec, %d block align, %d bits/samp, %u data bytes",
      dwAvgBytesPerSec, wav->blockAlign, wBitsPerSample, (unsigned)wav->dataLength);

  if (wav->formatTag == WAVE_FORMAT_ADPCM || wav->formatTag == WAVE_FORMAT_IMA_ADPCM)
    lsx_debug("        %d Samps/block, %d bytes/block", wav->samplesPerBlock, bytesPerBlock);

  if (ft->seekable) ft->data_start = wav->dataStart;
  return SOX_SUCCESS;
}

/* Read an ADPCM block; returns samples per channel decoded */
static unsigned short ImaAdpcmReadBlock(sox_format_t *ft)
{
  priv_t *wav = (priv_t *)ft->priv;
  size_t bytesRead;
  int samplesThisBlock;

  bytesRead = lsx_readbuf(ft, wav->packet, (size_t)wav->blockAlign);
  samplesThisBlock = wav->samplesPerBlock;
  if (bytesRead < wav->blockAlign) {
    samplesThisBlock = lsx_ima_samples_in((size_t)0, (size_t)ft->signal.channels, bytesRead, (size_t)0);
    if (samplesThisBlock == 0 || samplesThisBlock > wav->samplesPerBlock) {
      lsx_warn("Premature EOF on .wav input file");
      return 0;
    }
  }
  wav->samplePtr = wav->samples;
  lsx_ima_block_expand_i(ft->signal.channels, wav->packet, wav->samples, samplesThisBlock);
  return samplesThisBlock;
}

static unsigned short AdpcmReadBlock(sox_format_t *ft)
{
  priv_t *wav = (priv_t *)ft->priv;
  size_t bytesRead;
  int samplesThisBlock;
  const char *errmsg;

  bytesRead = lsx_readbuf(ft, wav->packet, (size_t)wav->blockAlign);
  samplesThisBlock = wav->samplesPerBlock;
  if (bytesRead < wav->blockAlign) {
    samplesThisBlock = lsx_ms_adpcm_samples_in((size_t)0, (size_t)ft->signal.channels, bytesRead, (size_t)0);
    if (samplesThisBlock == 0 || samplesThisBlock > wav->samplesPerBlock) {
      lsx_warn("Premature EOF on .wav input file");
      return 0;
    }
  }
  errmsg = lsx_ms_adpcm_block_expand_i(ft->signal.channels, wav->nCoefs, wav->lsx_ms_adpcm_i_coefs, wav->packet, wav->samples, samplesThisBlock);
  if (errmsg)
    lsx_warn("%s", errmsg);
  return samplesThisBlock;
}

static size_t read_samples(sox_format_t *ft, sox_sample_t *buf, size_t len)
{
  priv_t *wav = (priv_t *)ft->priv;
  size_t done;

  ft->sox_errno = SOX_SUCCESS;

  /* If file is in ADPCM encoding then read in multiple blocks else */
  /* read as much as possible and return quickly. */
  switch (ft->encoding.encoding) {
    case SOX_ENCODING_IMA_ADPCM:
    case SOX_ENCODING_MS_ADPCM:
      if (!wav->ignoreSize && len > (wav->numSamples * ft->signal.channels))
        len = (wav->numSamples * ft->signal.channels);
      done = 0;
      while (done < len) {
        short *p, *top;
        size_t ct;
        if (wav->blockSamplesRemaining == 0) {
          if (ft->encoding.encoding == SOX_ENCODING_IMA_ADPCM)
            wav->blockSamplesRemaining = ImaAdpcmReadBlock(ft);
          else
            wav->blockSamplesRemaining = AdpcmReadBlock(ft);
          if (wav->blockSamplesRemaining == 0) {
            /* Don't try to read any more samples */
            wav->numSamples = 0;
            return done;
          }
          wav->samplePtr = wav->samples;
        }
        ct = len - done;
        if (ct > (wav->blockSamplesRemaining * ft->signal.channels))
          ct = (wav->blockSamplesRemaining * ft->signal.channels);
        done += ct;
        wav->blockSamplesRemaining -= (ct / ft->signal.channels);
        p = wav->samplePtr;
        top = p + ct;
        while (p < top)
          *buf++ = SOX_SIGNED_16BIT_TO_SAMPLE(*p++);
        wav->samplePtr = p;
      }
      if (!wav->ignoreSize)
        wav->numSamples -= (done / ft->signal.channels);
      break;

    default:
      if (!wav->ignoreSize && len > wav->numSamples * ft->signal.channels)
        len = (wav->numSamples * ft->signal.channels);
      done = lsx_rawread(ft, buf, len);
      if (done == 0 && wav->numSamples != 0 && !wav->ignoreSize)
        lsx_warn("Premature EOF on .wav input file");
      if (!wav->ignoreSize)
        wav->numSamples -= (done / ft->signal.channels);
      break;
  }
  return done;
}

static int stopread(sox_format_t *ft)
{
  priv_t *wav = (priv_t *)ft->priv;
  ft->sox_errno = SOX_SUCCESS;
  free(wav->packet);
  free(wav->samples);
  free(wav->lsx_ms_adpcm_i_coefs);
  return SOX_SUCCESS;
}

static int wavwritehdr(sox_format_t *ft, int second_header);

static int startwrite(sox_format_t *ft)
{
  priv_t *wav = (priv_t *)ft->priv;
  int rc;

  ft->sox_errno = SOX_SUCCESS;

  if (ft->encoding.encoding != SOX_ENCODING_MS_ADPCM &&
      ft->encoding.encoding != SOX_ENCODING_IMA_ADPCM &&
      ft->encoding.encoding != SOX_ENCODING_GSM) {
    rc = 0;
  }

  wav->numSamples = 0;
  wav->dataLength = 0;
  if (!ft->signal.length && !ft->seekable)
    lsx_warn("Length in output .wav header will be wrong since can't seek to fix it");

  rc = wavwritehdr(ft, 0);
  if (rc != 0)
    return rc;

  wav->packet = NULL;
  wav->samples = NULL;
  wav->lsx_ms_adpcm_i_coefs = NULL;
  switch (wav->formatTag) {
    size_t ch, sbsize;
    case WAVE_FORMAT_IMA_ADPCM:
      lsx_ima_init_table();
      /* intentional case fallthru! */
    case WAVE_FORMAT_ADPCM:
      /* #channels already range-checked for overflow in wavwritehdr() */
      for (ch = 0; ch < ft->signal.channels; ch++)
        wav->state[ch] = 0;
      sbsize = ft->signal.channels * wav->samplesPerBlock;
      wav->packet = lsx_malloc((size_t)wav->blockAlign);
      wav->samples = lsx_malloc(sbsize * sizeof(short));
      wav->sampleTop = wav->samples + sbsize;
      wav->samplePtr = wav->samples;
      break;
    default:
      break;
  }
  return SOX_SUCCESS;
}

static void wavwritehdr_write(sox_format_t *ft, const char *s) { lsx_writebuf(ft, s, 4); }

static int wavwritehdr(sox_format_t *ft, int second_header)
{
  priv_t *wav = (priv_t *)ft->priv;

  /* variables written to wav file header */
  /* RIFF header */
  uint32_t dwRiffLength_ = 0;
  /* fmt chunk */
  uint16_t wFmtSize = 16;
  uint16_t wFormatTag = 0;
  uint16_t wChannels;
  uint32_t dwSamplesPerSecond;
  uint32_t dwAvgBytesPerSec = 0;
  uint16_t wBlockAlign = 0;
  uint16_t wBitsPerSample = 0;
  /* fmt chunk extension (not PCM) */
  uint16_t wExtSize = 0;
  uint16_t wSamplesPerBlock = 0;
  uint32_t dwFactSize = 0;
  uint32_t dwDataLength = 0;
  uint32_t dwSamplesWritten = 0;
  uint16_t wValidBitsPerSample = 0;
  uint32_t dwChannelMask = 0;
  int isExtensible = 0;
  uint64_t dwSamplesWritten64 = 0;

  dwSamplesPerSecond = (uint32_t)(ft->signal.rate);
  wChannels = ft->signal.channels;
  wBitsPerSample = ft->encoding.bits_per_sample;
  wSamplesPerBlock = 1; /* common default for PCM data */

  switch (ft->encoding.encoding) {
    case SOX_ENCODING_UNSIGNED:
    case SOX_ENCODING_SIGN2:
      wFormatTag = WAVE_FORMAT_PCM;
      wBlockAlign = (uint16_t)(wChannels * ((wBitsPerSample + 7) / 8));
      break;
    case SOX_ENCODING_FLOAT:
      wFormatTag = WAVE_FORMAT_IEEE_FLOAT;
      wBlockAlign = (uint16_t)(wChannels * ((wBitsPerSample + 7) / 8));
      break;
    case SOX_ENCODING_ALAW:
      wFormatTag = WAVE_FORMAT_ALAW;
      wBlockAlign = wChannels;
      break;
    case SOX_ENCODING_ULAW:
      wFormatTag = WAVE_FORMAT_MULAW;
      wBlockAlign = wChannels;
      break;
    case SOX_ENCODING_IMA_ADPCM:
      if (wChannels > 16) {
        lsx_fail_errno(ft, SOX_EOF, "Channels(%d) must be <= 16", wChannels);
        return SOX_EOF;
      }
      wFormatTag = WAVE_FORMAT_IMA_ADPCM;
      wBlockAlign = (uint16_t)(wChannels * 256); /* reasonable default */
      wBitsPerSample = 4;
      wExtSize = 2;
      wSamplesPerBlock = lsx_ima_samples_in((size_t)0, (size_t)wChannels, (size_t)wBlockAlign, (size_t)0);
      break;
    case SOX_ENCODING_MS_ADPCM:
      if (wChannels > 16) {
        lsx_fail_errno(ft, SOX_EOF, "Channels(%d) must be <= 16", wChannels);
        return SOX_EOF;
      }
      wFormatTag = WAVE_FORMAT_ADPCM;
      wBlockAlign = ft->signal.rate / 11008;
      wBlockAlign = max(wBlockAlign, 1);
      wBlockAlign = (uint16_t)(wChannels * 256 * wBlockAlign);
      {
        /* round down to power of 2 multiple */
        unsigned k = (unsigned)(ft->signal.rate / 11025);
        unsigned m = 1;
        while (m * 2 <= k) m *= 2;
        wBlockAlign = (uint16_t)(wChannels * 256 * m);
      }
      wBitsPerSample = 4;
      wExtSize = 4 + 4 * 7; /* Ext fmt data length */
      wSamplesPerBlock = lsx_ms_adpcm_samples_in((size_t)0, (size_t)wChannels, (size_t)wBlockAlign, (size_t)0);
      break;
    default:
      break;
  }
  wav->formatTag = wFormatTag;
  wav->blockAlign = wBlockAlign;
  wav->samplesPerBlock = wSamplesPerBlock;

  /* When creating header, use length hint given by input file.  If no
   * hint then write default value.  Also, use default value even
   * on header update if more then 32-bit length needs to be written.
   */
  dwSamplesWritten64 = second_header ? wav->numSamples : ft->signal.length / max(wChannels, 1);
  dwSamplesWritten = (uint32_t)dwSamplesWritten64;

  if (wFormatTag == WAVE_FORMAT_ADPCM || wFormatTag == WAVE_FORMAT_IMA_ADPCM) {
    uint64_t blocks = (dwSamplesWritten64 + wSamplesPerBlock - 1) / wSamplesPerBlock;
    dwDataLength = (uint32_t)(blocks * wBlockAlign);
    if (second_header) dwDataLength = (uint32_t)wav->dataLength;
  } else {
    dwDataLength = (uint32_t)(dwSamplesWritten64 * wBlockAlign);
    if (second_header) dwDataLength = (uint32_t)wav->dataLength;
  }

  if (wFormatTag == WAVE_FORMAT_PCM && (wBitsPerSample > 16 || wChannels > 2)
      && strcmp(ft->filetype, "wavpcm")) {
    isExtensible = 1;
    wFmtSize += 2 + 22;
  } else if (wFormatTag != WAVE_FORMAT_PCM)
    wFmtSize += 2 + wExtSize;

  dwAvgBytesPerSec = (double)wBlockAlign * ft->signal.rate / (double)wSamplesPerBlock + 0.5;

  /* figured out header info, so write it */

  /* If user specified opposite swap than we think, assume they are
   * asking to write a RIFX file.
   */
  if (ft->encoding.reverse_bytes) {
    if (!second_header)
      lsx_report("Requested to swap bytes so writing RIFX header");
    wavwritehdr_write(ft, "RIFX");
  } else
    wavwritehdr_write(ft, "RIFF");

  if (wFormatTag != WAVE_FORMAT_PCM || isExtensible)
    dwFactSize = 12;
  dwRiffLength_ = 4 + 8 + wFmtSize + dwFactSize + 8 + dwDataLength + (dwDataLength & 1);
  if (!second_header && !ft->signal.length) {
    dwRiffLength_ = 4 + 8 + wFmtSize + dwFactSize + 8;
  }
  lsx_writedw(ft, dwRiffLength_);
  wavwritehdr_write(ft, "WAVE");
  wavwritehdr_write(ft, "fmt ");
  lsx_writedw(ft, wFmtSize);
  lsx_writew(ft, isExtensible ? WAVE_FORMAT_EXTENSIBLE : wFormatTag);
  lsx_writew(ft, wChannels);
  lsx_writedw(ft, dwSamplesPerSecond);
  lsx_writedw(ft, dwAvgBytesPerSec);
  lsx_writew(ft, wBlockAlign);
  lsx_writew(ft, wBitsPerSample); /* end info common to all fmts */

  if (isExtensible) {
    uint32_t dwChannelMask_ = 0;
    static const char guid[14] = "\x00\x00\x00\x00\x10\x00\x80\x00\x00\xAA\x00\x38\x9B\x71";
    lsx_writew(ft, 22);
    lsx_writew(ft, wBitsPerSample); /* No padding in container */
    if (wChannels == 1) dwChannelMask_ = 0x4;
    else if (wChannels == 2) dwChannelMask_ = 0x3;
    else if (wChannels == 4) dwChannelMask_ = 0x33;
    else if (wChannels == 6) dwChannelMask_ = 0x3F;
    else if (wChannels == 8) dwChannelMask_ = 0x63F;
    lsx_writedw(ft, dwChannelMask_);
    lsx_writew(ft, wFormatTag);
    lsx_writebuf(ft, guid, (size_t)14);
    (void)wValidBitsPerSample; (void)dwChannelMask;
  } else
    /* if not PCM, we need to write out wExtSize even if wExtSize=0 */
    if (wFormatTag != WAVE_FORMAT_PCM)
      lsx_writew(ft, wExtSize);

  switch (wFormatTag) {
    int i, j;
    case WAVE_FORMAT_IMA_ADPCM:
      lsx_writew(ft, wSamplesPerBlock);
      break;
    case WAVE_FORMAT_ADPCM:
      lsx_writew(ft, wSamplesPerBlock);
      lsx_writew(ft, 7); /* nCoefs */
      for (i = 0; i < 7; i++)
        for (j = 0; j < 2; j++)
          lsx_writew(ft, (uint16_t)lsx_ms_adpcm_i_coef[i][j]);
      break;
    default:
      break;
  }

  /* if not PCM, write the 'fact' chunk */
  if (isExtensible || wFormatTag != WAVE_FORMAT_PCM) {
    wavwritehdr_write(ft, "fact");
    lsx_writedw(ft, 4);
    lsx_writedw(ft, dwSamplesWritten);
  }

  wavwritehdr_write(ft, "data");
  if (!second_header && !ft->signal.length)
    lsx_writedw(ft, 0xffffffffu);
  else
    lsx_writedw(ft, dwDataLength);

  if (!second_header) {
    lsx_debug("Writing Wave file: %s format, %d channel%s, %d samp/sec",
        wav_format_str(wFormatTag), wChannels, wChannels == 1 ? "" : "s", dwSamplesPerSecond);
    lsx_debug("        %d byte/sec, %d block align, %d bits/samp",
        dwAvgBytesPerSec, wBlockAlign, wBitsPerSample);
  } else {
    lsx_debug("Finished writing Wave file, %u data bytes %lu samples",
        dwDataLength, (unsigned long)wav->numSamples);
  }
  return SOX_SUCCESS;
}

static size_t write_samples(sox_format_t *ft, const sox_sample_t *buf, size_t len)
{
  priv_t *wav = (priv_t *)ft->priv;
  ptrdiff_t total_len = len;

  ft->sox_errno = SOX_SUCCESS;

  switch (wav->formatTag) {
    case WAVE_FORMAT_IMA_ADPCM:
    case WAVE_FORMAT_ADPCM:
      while (len > 0) {
        short *p = wav->samplePtr;
        short *top = wav->sampleTop;
        if (top > p + len) top = p + len;
        len -= top - p; /* update residual len */
        while (p < top)
          *p++ = (*buf++ + 0x8000) >> 16 > 32767 ? 32767 : (short)(((int64_t)(*(buf - 1)) + 0x8000) >> 16);
        wav->samplePtr = p;
        if (p == wav->sampleTop)
          lsx_wav_adpcm_write_block(ft);
      }
      return total_len - len;

    default:
      len = lsx_rawwrite(ft, buf, len);
      wav->numSamples += (len / ft->signal.channels);
      wav->dataLength += len * ((ft->encoding.bits_per_sample + 7) / 8);
      return len;
  }
}

static int stopwrite(sox_format_t *ft)
{
  priv_t *wav = (priv_t *)ft->priv;

  ft->sox_errno = SOX_SUCCESS;

  /* Call this to flush out any remaining data. */
  switch (wav->formatTag) {
    case WAVE_FORMAT_IMA_ADPCM:
    case WAVE_FORMAT_ADPCM:
      lsx_wav_adpcm_write_block(ft);
      break;
    default:
      break;
  }

  /* Add a pad byte if the number of data bytes is odd.
     See wavwritehdr() above for the calculation. */
  if (wav->dataLength & 1)
    lsx_writeb(ft, 0);

  free(wav->packet);
  free(wav->samples);
  free(wav->lsx_ms_adpcm_i_coefs);

  /* All samples are already written out. */
  /* If file header needs fixing up, for example it needs the */
  /* the number of samples in a field, seek back and write them here. */
  if (!ft->seekable)
    return SOX_SUCCESS;

  if (lsx_seeki(ft, (int64_t)0, SEEK_SET) != 0) {
    lsx_fail_errno(ft, SOX_EOF, "Can't rewind output file to rewrite .wav header.");
    return SOX_EOF;
  }

  return (wavwritehdr(ft, 1));
}

static int seek(sox_format_t *ft, uint64_t offset)
{
  priv_t *wav = (priv_t *)ft->priv;

  if (ft->encoding.bits_per_sample & 7)
    lsx_fail_errno(ft, SOX_ENOTSUP, "seeking not supported with this encoding");
  else if (wav->formatTag == WAVE_FORMAT_IMA_ADPCM || wav->formatTag == WAVE_FORMAT_ADPCM)
    lsx_fail_errno(ft, SOX_ENOTSUP, "ADPCM not supported");
  else {
    uint64_t new_offset = offset;
    uint64_t alignment = new_offset % ft->signal.channels;
    if (alignment != 0)
      new_offset += (ft->signal.channels - alignment);
    {
      uint64_t byte_offset = new_offset * (ft->encoding.bits_per_sample >> 3) + wav->dataStart;
      ft->sox_errno = lsx_seeki(ft, (int64_t)byte_offset, SEEK_SET);
    }
    if (ft->sox_errno == SOX_SUCCESS)
      wav->numSamples = (ft->signal.length / ft->signal.channels) - (new_offset / ft->signal.channels);
  }
  return ft->sox_errno;
}

/* ADPCM block writer shared */
void lsx_wav_adpcm_write_block(sox_format_t *ft)
{
  priv_t *wav = (priv_t *)ft->priv;
  short *p = wav->samplePtr;
  size_t ct = p - wav->samples;
  if (ct >= ft->signal.channels) {
    /* zero-fill samples if needed to complete block */
    for (p = wav->samplePtr; p < wav->sampleTop; p++) *p = 0;
    /* compress the samples to wav->packet */
    if (wav->formatTag == WAVE_FORMAT_ADPCM)
      lsx_ms_adpcm_block_mash_i((unsigned)ft->signal.channels, wav->samples, wav->samplesPerBlock, wav->state, wav->packet, wav->blockAlign);
    else
      lsx_ima_block_mash_i((unsigned)ft->signal.channels, wav->samples, wav->samplesPerBlock, wav->state, wav->packet, 9);
    /* write the compressed packet */
    if (lsx_writebuf(ft, wav->packet, (size_t)wav->blockAlign) != wav->blockAlign) {
      lsx_fail_errno(ft, SOX_EOF, "write error");
      return;
    }
    /* update lengths and samplePtr */
    wav->dataLength += wav->blockAlign;
    wav->numSamples += ct / ft->signal.channels;
    wav->samplePtr = wav->samples;
  }
}

const sox_format_handler_t *lsx_wav_format_fn(void)
{
  static char const * const names[] = {"wav", "wavpcm", "amb", NULL};
  static unsigned const write_encodings[] = {
    SOX_ENCODING_SIGN2, 16, 24, 32, 0,
    SOX_ENCODING_UNSIGNED, 8, 0,
    SOX_ENCODING_ULAW, 8, 0,
    SOX_ENCODING_ALAW, 8, 0,
    SOX_ENCODING_MS_ADPCM, 4, 0,
    SOX_ENCODING_IMA_ADPCM, 4, 0,
    SOX_ENCODING_FLOAT, 32, 64, 0,
    0};
  static sox_format_handler_t const handler = {
    "Microsoft audio format", names, SOX_FILE_LIT_END,
    startread, read_samples, stopread,
    startwrite, write_samples, stopwrite,
    seek, write_encodings, NULL, sizeof(priv_t)
  };
  return &handler;
}
