/* IMA and MS ADPCM codecs (WAV), and OKI/IMA raw ADPCM */
#include "adpcm.h"

/* ---------------- MS ADPCM ---------------- */
static const int stepAdjustTable[] = {
  230, 230, 230, 230, 307, 409, 512, 614,
  768, 614, 512, 409, 307, 230, 230, 230
};

const short lsx_ms_adpcm_i_coef[7][2] = {
  { 256,   0}, { 512, -256}, {   0,   0}, { 192,  64},
  { 240,   0}, { 460, -208}, { 392, -232}
};

typedef struct { int step; short coef[2]; } MsState_t;

static inline int AdpcmDecode(int c, MsState_t *state, int sample1, int sample2)
{
  int vlin, sample, step;
  step = state->step;
  {
    int nstep = (stepAdjustTable[c] * step) >> 8;
    state->step = (nstep < 16) ? 16 : nstep;
  }
  vlin = ((sample1 * state->coef[0]) + (sample2 * state->coef[1])) >> 8;
  c -= (c & 0x08) << 1;
  sample = (c * step) + vlin;
  if (sample > 0x7fff) sample = 0x7fff;
  else if (sample < -0x8000) sample = -0x8000;
  return sample;
}

const char *lsx_ms_adpcm_block_expand_i(unsigned chans, int nCoef, const short *coef, const unsigned char *ibuff, short *obuff, int n)
{
  const unsigned char *ip;
  unsigned ch;
  const char *errmsg = NULL;
  MsState_t state[16];

  ip = ibuff;
  for (ch = 0; ch < chans; ch++) {
    unsigned char bpred = *ip++;
    if (bpred >= nCoef) {
      errmsg = "MSADPCM bpred >= nCoef, arbitrarily using 0\n";
      bpred = 0;
    }
    state[ch].coef[0] = coef[(int)bpred * 2 + 0];
    state[ch].coef[1] = coef[(int)bpred * 2 + 1];
  }
  for (ch = 0; ch < chans; ch++) {
    state[ch].step = (short)(ip[0] | (ip[1] << 8));
    ip += 2;
  }
  /* sample1's directly into obuff */
  for (ch = 0; ch < chans; ch++) {
    obuff[chans + ch] = (short)(ip[0] | (ip[1] << 8));
    ip += 2;
  }
  /* sample2's directly into obuff */
  for (ch = 0; ch < chans; ch++) {
    obuff[ch] = (short)(ip[0] | (ip[1] << 8));
    ip += 2;
  }
  {
    unsigned ch2;
    unsigned char b;
    short *op, *top, *tmp;

    op = obuff + 2 * chans;
    top = obuff + n * chans;
    ch2 = 0;
    while (op < top) {
      b = *ip++;
      tmp = op;
      *op++ = AdpcmDecode(b >> 4, state + ch2, tmp[-(int)chans], tmp[-(int)(2 * chans)]);
      if (++ch2 == chans) ch2 = 0;
      tmp = op;
      *op++ = AdpcmDecode(b & 0x0f, state + ch2, tmp[-(int)chans], tmp[-(int)(2 * chans)]);
      if (++ch2 == chans) ch2 = 0;
    }
  }
  return errmsg;
}

static int AdpcmMashS(unsigned ch, unsigned chans, short v[2], const short iCoef[2], const short *ibuff, int n, int *iostep, unsigned char *obuff)
{
  const short *ip, *itop;
  unsigned char *op;
  int ox = 0;
  int d, v0, v1, step;
  double d2;

  ip = ibuff + ch;
  itop = ibuff + n * chans;
  v0 = v[0];
  v1 = v[1];
  d = *ip - v1; ip += chans;
  d2 = d * d;
  d = *ip - v0; ip += chans;
  d2 += d * d;

  step = *iostep;

  op = obuff;
  if (op) {
    op += chans;
    op += 2 * ch;
    op[0] = step; op[1] = step >> 8;
    op += 2 * chans;
    op[0] = v0; op[1] = v0 >> 8;
    op += 2 * chans;
    op[0] = v1; op[1] = v1 >> 8;
    op = obuff + 7 * chans;
    ox = 4 * ch;
  }
  for (; ip < itop; ip += chans) {
    int vlin, d3, dp, c;
    vlin = (v0 * iCoef[0] + v1 * iCoef[1]) >> 8;
    d3 = *ip - vlin;
    dp = d3 + (step << 3) + (step >> 1);
    c = 0;
    if (dp > 0) {
      c = dp / step;
      if (c > 15) c = 15;
    }
    c -= 8;
    dp = c * step;
    c &= 0x0f;

    v1 = v0;
    v0 = vlin + dp;
    if (v0 < -0x8000) v0 = -0x8000;
    else if (v0 > 0x7fff) v0 = 0x7fff;

    d3 = *ip - v0;
    d2 += d3 * d3;

    if (op) {
      op[ox >> 3] |= (ox & 4) ? c : (c << 4);
      ox += 4 * chans;
    }
    step = (stepAdjustTable[c] * step) >> 8;
    if (step < 16) step = 16;
  }
  d2 /= n;
  *iostep = step;
  return (int)sqrt(d2);
}

static void AdpcmMashChannel(unsigned ch, unsigned chans, const short *ip, int n, int *st, unsigned char *obuff)
{
  short v[2];
  int n0, s0, s1, ss, smin;
  int dmin, k, kmin;

  n0 = n / 2; if (n0 > 32) n0 = 32;
  if (*st < 16) *st = 16;
  v[1] = ip[ch];
  v[0] = ip[ch + chans];

  dmin = 0; kmin = 0; smin = 0;
  for (k = 0; k < 7; k++) {
    int d0, d1;
    ss = s0 = *st;
    d0 = AdpcmMashS(ch, chans, v, lsx_ms_adpcm_i_coef[k], ip, n, &ss, NULL);

    s1 = s0;
    AdpcmMashS(ch, chans, v, lsx_ms_adpcm_i_coef[k], ip, n0, &s1, NULL);
    ss = s1 = (3 * s0 + s1) / 4;
    d1 = AdpcmMashS(ch, chans, v, lsx_ms_adpcm_i_coef[k], ip, n, &ss, NULL);
    if (!k || d0 < dmin || d1 < dmin) {
      kmin = k;
      if (d0 <= d1) {
        dmin = d0;
        smin = s0;
      } else {
        dmin = d1;
        smin = s1;
      }
    }
  }
  *st = smin;
  AdpcmMashS(ch, chans, v, lsx_ms_adpcm_i_coef[kmin], ip, n, st, obuff);
  obuff[ch] = kmin;
}

void lsx_ms_adpcm_block_mash_i(unsigned chans, const short *ip, int n, int *st, unsigned char *obuff, int blockAlign)
{
  unsigned ch;
  unsigned char *p;
  for (p = obuff + 7 * chans; p < obuff + blockAlign; p++) *p = 0;
  for (ch = 0; ch < chans; ch++)
