void lsx_ima_init_table(void)
{
  int i, j, k;
  for (i = 0; i <= ISSTMAX; i++) {
    for (j = 0; j < 8; j++) {
      k = i + imaStateAdjust(j);
      if (k < 0) k = 0;
      else if (k > ISSTMAX) k = ISSTMAX;
      imaStateAdjustTable[i][j] = k;
    }
  }
}

static void ImaExpandS(unsigned ch, unsigned chans, const unsigned char *ibuff, short *obuff, int n, unsigned o_inc)
{
  const unsigned char *ip;
  int i_inc;
  short *op;
  int i, val, state;

  ip = ibuff + 4 * ch;
  i_inc = 4 * (chans - 1);
  val = (short)(ip[0] + (ip[1] << 8));
  state = ip[2];
  if (state > ISSTMAX) {
    lsx_warn("IMA_ADPCM block ch%d initial-state (%d) out of range", ch, state);
    state = 0;
  }
  ip += 4 + i_inc;

  op = obuff;
  *op = val;
  op += o_inc;

  for (i = 1; i < n; i++) {
    int step, dp, c, cm;

    if (i & 1) {
      cm = *ip & 0x0f;
    } else {
      cm = (*ip++) >> 4;
      if ((i & 7) == 0)
        ip += i_inc;
