  } else {
    mask = 0x55;
    pcm_val = -pcm_val - 1;
  }
  seg = search(pcm_val, seg_aend, 8);
  if (seg >= 8)
    return (uint8_t)(0x7F ^ mask);
  else {
    aval = (uint8_t)seg << SEG_SHIFT;
    if (seg < 2)
