{"command":"cat > /workspace/src/effects.c <<'EOF'
/* Effects chain */
#include "sox.h"

#define EFF_TABLE_STEP 8

static int default_function(sox_effect_t *effp) { (void)effp; return SOX_SUCCESS; }
static int default_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  (void)effp; (void)ibuf; (void)obuf; *isamp = 0; *osamp = 0;
  return SOX_SUCCESS;
}
static int default_drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{
  (void)effp; (void)obuf; *osamp = 0;
  return SOX_EOF;
}
static int default_getopts(sox_effect_t *effp, int argc, char **argv)
{
  (void)argv;
  return --argc ? lsx_usage(effp) : SOX_SUCCESS;
}

sox_effect_t *sox_create_effect(const sox_effect_handler_t *eh)
{
  sox_effect_t *effp = lsx_calloc(1, sizeof(*effp));
  effp->obuf = NULL;
  effp->handler = *eh;
  if (!effp->handler.getopts) effp->handler.getopts = default_getopts;
  if (!effp->handler.start) effp->handler.start = default_function;
  if (!effp->handler.flow) effp->handler.flow = lsx_flow_copy;
  if (!effp->handler.drain) effp->handler.drain = default_drain;
  if (!effp->handler.stop) effp->handler.stop = default_function;
  if (!effp->handler.kill) effp->handler.kill = default_function;
  effp->priv = lsx_calloc(1, effp->handler.priv_size);
  (void)default_flow;
  return effp;
}

int sox_effect_options(sox_effect_t *effp, int argc, char * const argv[])
{
  int result;
  const char *save = sox_globals.subsystem;
  char **argv2 = lsx_malloc((argc + 2) * sizeof(*argv2));
  argv2[0] = (char *)effp->handler.name;
  memcpy(argv2 + 1, argv, argc * sizeof(*argv2));
  argv2[argc + 1] = NULL;
  lsx_set_subsystem(effp->handler.name);
  result = effp->handler.getopts(effp, argc + 1, argv2);
  lsx_set_subsystem(save);
  free(argv2);
  return result;
}

sox_effects_chain_t *sox_create_effects_chain(const sox_encodinginfo_t *in_enc, const sox_encodinginfo_t *out_enc)
{
  sox_effects_chain_t *result = lsx_calloc(1, sizeof(sox_effects_chain_t));
  result->in_enc = in_enc;
  result->out_enc = out_enc;
  return result;
}

void sox_delete_effects_chain(sox_effects_chain_t *ecp)
{
  if (ecp && ecp->length)
    sox_delete_effects(ecp);
  if (ecp) {
    free(ecp->effects);
    free(ecp);
  }
}

static void *memdup(const void *p, size_t n)
{
  void *r = lsx_malloc(n ? n : 1);
  if (n) memcpy(r, p, n);
  return r;
}

int sox_add_effect(sox_effects_chain_t *chain, sox_effect_t *effp, sox_signalinfo_t *in, const sox_signalinfo_t *out)
{
  int ret, (*start)(sox_effect_t *effp) = effp->handler.start;
  size_t f;
  sox_effect_t eff0;
  const char *save = sox_globals.subsystem;

  effp->in_signal = *in;
  effp->out_signal = *out;
  effp->in_encoding = chain->in_enc;
  effp->out_encoding = chain->out_enc;
  if (!(effp->handler.flags & SOX_EFF_CHAN))
    effp->out_signal.channels = in->channels;
  if (!(effp->handler.flags & SOX_EFF_RATE))
    effp->out_signal.rate = in->rate;
  if (!(effp->handler.flags & SOX_EFF_PREC))
    effp->out_signal.precision = (effp->handler.flags & SOX_EFF_MODIFY) ? in->precision : SOX_SAMPLE_PRECISION;
  if (!(effp->handler.flags & SOX_EFF_GAIN))
    effp->out_signal.mult = in->mult;

  effp->flows = (effp->handler.flags & SOX_EFF_MCHAN) ? 1 : effp->in_signal.channels;
  effp->clips = 0;
  effp->imin = 0;
  eff0 = *effp;
  eff0.priv = memdup(eff0.priv, eff0.handler.priv_size);
  eff0.in_signal.mult = NULL;
  lsx_set_subsystem(effp->handler.name);
  ret = start(effp);
  if (ret == SOX_EFF_NULL) {
    lsx_report("has no effect in this configuration");
    free(eff0.priv);
    effp->handler.kill(effp);
    effp->in_signal.mult = NULL;
    lsx_set_subsystem(save);
    return SOX_SUCCESS;
  }
  if (ret != SOX_SUCCESS) {
    free(eff0.priv);
    lsx_set_subsystem(save);
    return SOX_EOF;
  }
  if (in->mult)
    lsx_debug("mult=%g", *in->mult);

  if (!(effp->handler.flags & SOX_EFF_LENGTH)) {
    effp->out_signal.length = in->length;
    if (effp->out_signal.length != SOX_UNKNOWN_LEN) {
      if (effp->handler.flags & SOX_EFF_CHAN)
        effp->out_signal.length = effp->out_signal.length / in->channels * effp->out_signal.channels;
      if (effp->handler.flags & SOX_EFF_RATE)
        effp->out_signal.length = effp->out_signal.length / in->rate * effp->out_signal.rate + .5;
    }
  }

  *in = effp->out_signal;

  if (chain->length == chain->table_size) {
    chain->table_size += EFF_TABLE_STEP;
    chain->effects = lsx_realloc(chain->effects, chain->table_size * sizeof(*chain->effects));
  }

  chain->effects[chain->length] = lsx_calloc(effp->flows, sizeof(chain->effects[chain->length][0]));
  chain->effects[chain->length][0] = *effp;

  for (f = 1; f < effp->flows; ++f) {
    chain->effects[chain->length][f] = eff0;
    chain->effects[chain->length][f].flow = f;
    chain->effects[chain->length][f].priv = memdup(eff0.priv, eff0.handler.priv_size);
    if (start(&chain->effects[chain->length][f]) != SOX_SUCCESS) {
      free(eff0.priv);
      lsx_set_subsystem(save);
      return SOX_EOF;
    }
  }

  ++chain->length;
  free(eff0.priv);
  lsx_set_subsystem(save);
  return SOX_SUCCESS;
}

static int flow_effect(sox_effects_chain_t *chain, size_t n)
{
  sox_effect_t *effp1 = &chain->effects[n - 1][0];
  sox_effect_t *effp = &chain->effects[n][0];
  int effstatus = SOX_SUCCESS;
  size_t i, f;
  const sox_sample_t *ibuf;
  size_t idone = effp1->oend - effp1->obeg;
  size_t obeg = sox_globals.bufsiz - effp->oend;

  lsx_set_subsystem(effp->handler.name);
  if (effp->flows == 1) {
    effstatus = effp->handler.flow(effp, &effp1->obuf[effp1->obeg], &effp->obuf[effp->oend], &idone, &obeg);
    if (obeg % effp->out_signal.channels != 0) {
      lsx_fail("multi-channel effect flowed asymmetrically!");
      effstatus = SOX_EOF;
    }
  } else {
    sox_sample_t *obuf = &effp->obuf[effp->oend];
    size_t idone_last = 0, odone_last = 0;
    ibuf = &effp1->obuf[effp1->obeg];
    for (i = 0; i < idone; i += effp->flows)
      for (f = 0; f < effp->flows; ++f)
        chain->ibufc[f][i / effp->flows] = *ibuf++;

    for (f = 0; f < effp->flows; ++f) {
      size_t idonec = idone / effp->flows;
      size_t odonec = obeg / effp->flows;
      int eff_status_c = effp->handler.flow(&chain->effects[n][f], chain->ibufc[f], chain->obufc[f], &idonec, &odonec);
      if (f && (idonec != idone_last || odonec != odone_last)) {
        lsx_fail("flowed asymmetrically!");
        effstatus = SOX_EOF;
      }
      idone_last = idonec;
      odone_last = odonec;
      if (eff_status_c != SOX_SUCCESS)
        effstatus = SOX_EOF;
    }

    for (i = 0; i < odone_last; ++i)
      for (f = 0; f < effp->flows; ++f)
        *obuf++ = chain->obufc[f][i];

    idone = effp->flows * idone_last;
    obeg = effp->flows * odone_last;
  }
  effp1->obeg += idone;
  if (effp1->obeg == effp1->oend)
    effp1->obeg = effp1->oend = 0;
  else if (effp1->oend - effp1->obeg < effp->imin) {
    memmove(effp1->obuf, &effp1->obuf[effp1->obeg], (effp1->oend - effp1->obeg) * sizeof(*effp1->obuf));
    effp1->oend -= effp1->obeg;
    effp1->obeg = 0;
  }

  effp->oend += obeg;

  return effstatus == SOX_SUCCESS ? SOX_SUCCESS : SOX_EOF;
}

static int drain_effect(sox_effects_chain_t *chain, size_t n)
{
  sox_effect_t *effp = &chain->effects[n][0];
  int effstatus = SOX_SUCCESS;
  size_t i, f;
  size_t obeg = sox_globals.bufsiz - effp->oend;

  lsx_set_subsystem(effp->handler.name);
  if (effp->flows == 1) {
    effstatus = effp->handler.drain(effp, &effp->obuf[effp->oend], &obeg);
    if (obeg % effp->out_signal.channels != 0) {
      lsx_fail("multi-channel effect drained asymmetrically!");
      effstatus = SOX_EOF;
    }
  } else {
    sox_sample_t *obuf = &effp->obuf[effp->oend];
    size_t odone_last = 0;

    for (f = 0; f < effp->flows; ++f) {
      size_t odonec = obeg / effp->flows;
      int eff_status_c = effp->handler.drain(&chain->effects[n][f], chain->obufc[f], &odonec);
      if (f && (odonec != odone_last)) {
        lsx_fail("drained asymmetrically!");
        effstatus = SOX_EOF;
      }
      odone_last = odonec;

      if (eff_status_c != SOX_SUCCESS)
        effstatus = SOX_EOF;
    }

    for (i = 0; i < odone_last; ++i)
      for (f = 0; f < effp->flows; ++f)
        *obuf++ = chain->obufc[f][i];
    obeg = f * odone_last;
  }
  if (!obeg)
    effstatus = SOX_EOF;

  effp->oend += obeg;

  return effstatus == SOX_SUCCESS ? SOX_SUCCESS : SOX_EOF;
}

int sox_flow_effects(sox_effects_chain_t *chain, int (*callback)(sox_bool all_done, void *client_data), void *client_data)
{
  int flow_status = SOX_SUCCESS;
  size_t e, source_e = 0;
  size_t max_flows = 0;
  sox_bool draining = sox_true;
  const char *save = sox_globals.subsystem;

  for (e = 0; e < chain->length; ++e) {
    chain->effects[e][0].obuf = lsx_realloc(chain->effects[e][0].obuf, sox_globals.bufsiz * sizeof(chain->effects[e][0].obuf[0]));
    chain->effects[e][0].obeg = chain->effects[e][0].oend = 0;
    max_flows = max(max_flows, chain->effects[e][0].flows);
  }
  if (max_flows > 1) {
    chain->ibufc = lsx_calloc(max_flows, sizeof(*chain->ibufc));
    chain->obufc = lsx_calloc(max_flows, sizeof(*chain->obufc));
    for (e = 0; e < max_flows; ++e) {
      chain->ibufc[e] = lsx_calloc(sox_globals.bufsiz / 2, sizeof(chain->ibufc[e][0]));
      chain->obufc[e] = lsx_calloc(sox_globals.bufsiz / 2, sizeof(chain->obufc[e][0]));
    }
  }

  e = chain->length - 1;
  while (source_e < chain->length) {
#define have_imin (e > 0 && e < chain->length && chain->effects[e - 1][0].oend - chain->effects[e - 1][0].obeg >= chain->effects[e][0].imin)
    size_t osize = chain->effects[e][0].oend - chain->effects[e][0].obeg;
    if (e == source_e && (draining || !have_imin)) {
      if (drain_effect(chain, e) == SOX_EOF) {
        ++source_e;
        draining = sox_false;
      }
    } else if (have_imin && flow_effect(chain, e) == SOX_EOF) {
      flow_status = SOX_EOF;
      if (e == chain->length - 1)
        break;
      source_e = e;
      draining = sox_true;
    }
    if (e < chain->length - 1 && chain->effects[e][0].oend - chain->effects[e][0].obeg > osize)
      ++e;
    else if (e == source_e)
      draining = sox_true;
    else if (e < source_e)
      e = source_e;
    else
      --e;

    if (callback && callback(source_e == chain->length, client_data) != SOX_SUCCESS) {
      flow_status = SOX_EOF;
      break;
    }
  }

  if (max_flows > 1) {
    for (e = 0; e < max_flows; ++e) {
      free(chain->ibufc[e]);
      free(chain->obufc[e]);
    }
    free(chain->obufc);
    free(chain->ibufc);
  }
  for (e = 0; e < chain->length; ++e) {
    free(chain->effects[e][0].obuf);
    chain->effects[e][0].obuf = NULL;
  }
  lsx_set_subsystem(save);
  return flow_status;
}

size_t sox_stop_effect(sox_effect_t *effp)
{
  size_t f, clips = 0;
  const char *save = sox_globals.subsystem;
  lsx_set_subsystem(effp->handler.name);
  for (f = 0; f < effp->flows; ++f) {
    effp[f].handler.stop(&effp[f]);
    clips += effp[f].clips;
  }
  lsx_set_subsystem(save);
  return clips;
}

uint64_t sox_effects_clips(sox_effects_chain_t *chain)
{
  unsigned i, f;
  uint64_t clips = 0;
  for (i = 1; i < chain->length - 1; ++i)
    for (f = 0; f < chain->effects[i][0].flows; ++f)
      clips += chain->effects[i][f].clips;
  return clips;
}

void sox_delete_effect(sox_effect_t *effp)
{
  uint64_t clips;
  unsigned f;
  const char *save = sox_globals.subsystem;

  if ((clips = sox_stop_effect(effp)) != 0) {
    lsx_set_subsystem(effp->handler.name);
    lsx_warn("%s clipped %llu samples; decrease volume?", effp->handler.name, (unsigned long long)clips);
  }
  lsx_set_subsystem(effp->handler.name);
  if (effp->obuf)
    free(effp->obuf);
  for (f = 0; f < effp->flows; ++f) {
    effp[f].handler.kill(&effp[f]);
    free(effp[f].priv);
  }
  free(effp);
  lsx_set_subsystem(save);
}

void sox_delete_effect_last(sox_effects_chain_t *chain)
{
  if (chain->length > 0) {
    chain->length--;
    sox_delete_effect(chain->effects[chain->length]);
    chain->effects[chain->length] = NULL;
  }
}

void sox_delete_effects(sox_effects_chain_t *chain)
{
  size_t e;
  for (e = 0; e < chain->length; ++e) {
    sox_delete_effect(chain->effects[e]);
    chain->effects[e] = NULL;
  }
  chain->length = 0;
}

int lsx_effect_set_imin(sox_effect_t *effp, size_t imin)
{
  if (imin > sox_globals.bufsiz / effp->flows) {
    lsx_fail("sox_globals.bufsiz < %lu", (unsigned long)(imin * effp->flows));
    return SOX_EOF;
  }
  effp->imin = imin;
  return SOX_SUCCESS;
}

const sox_effect_handler_t *sox_find_effect(char const *name)
{
  int e;
  for (e = 0; sox_effect_fns[e]; ++e) {
    const sox_effect_handler_t *eh = sox_effect_fns[e]();
