static void init_file(file_t *f)
{
  memset(f, 0, sizeof(*f));
  sox_init_encodinginfo(&f->encoding);
  f->volume = HUGE_VAL;
  f->replay_gain = HUGE_VAL;
}

static file_t *new_file(void)
{
  file_t *f = lsx_calloc(sizeof(*f), 1);
  init_file(f);
  return f;
}

static char *read_comment_file(char const *const filename)
{
  sox_bool result = sox_false;
  FILE *file = fopen(filename, "rt");
  size_t text_length = 100;
  char *text = lsx_malloc(text_length + 1);
  size_t i = 0;
  int c;

  if (file == NULL) {
    lsx_fail("Cannot open comment file `%s'", filename);
    exit(1);
  }
  do {
    c = getc(file);
    if (c == EOF) break;
    if (i == text_length) text = lsx_realloc(text, (text_length <<= 1) + 1);
    text[i++] = c;
  } while (1);
  if (ferror(file)) {
    lsx_fail("Error reading comment file `%s'", filename);
    exit(1);
  }
  fclose(file);
  text[i] = '\0';
  (void)result;
  return text;
}

static char const *device_name(char const *const type)
{
  char *name = NULL, *from_env = getenv("AUDIODEV");
  if (!type) return NULL;
  if (!strcmp(type, "sunau")) name = "/dev/audio";
  else if (!strcmp(type, "oss") || !strcmp(type, "ossdsp")) name = "/dev/dsp";
  else if (!strcmp(type, "alsa") || !strcmp(type, "ao") || !strcmp(type, "sndio") ||
           !strcmp(type, "coreaudio") || !strcmp(type, "pulseaudio") || !strcmp(type, "waveaudio"))
    name = "default";
  return name ? from_env ? from_env : name : NULL;
}

