static int enum_option(char const *arg, int option_index, lsx_enum_item const *items, const lsx_option_t *long_options)
{
  lsx_enum_item const *p = lsx_find_enum_text(arg, items, 0);
  if (p == NULL) {
    size_t len = 1;
    char *set = lsx_malloc(len);
    *set = 0;
    for (p = items; p->name; ++p) {
      set = lsx_realloc(set, len += 2 + strlen(p->name));
      strcat(set, ", ");
      strcat(set, p->name);
    }
    lsx_fail("--%s: `%s' is not one of: %s.", long_options[option_index].name, arg, set + 2);
    free(set);
    exit(1);
  }
  return p->value;
}

