static int opt_index(int val)
{
  int i;
  for (i = 0; long_options[i].name; ++i)
    if (long_options[i].val == val)
      return i;
  return -1;
}

static sox_bool parse_gopts_and_fopts(file_t *f, lsx_getopt_t *optstate)
{
  const char *save = sox_globals.subsystem;
  while (sox_true) {
    int c;
    int i;
    char dummy;

    switch (c = lsx_getopt(optstate)) {
      case -1:
        return sox_false;

      case 0:
        switch (optstate->lngind) {
          case 0:  /* add-comment */
            sox_append_comment(&f->comments, optstate->arg);
            break;
          case 1: /* buffer */
#define SOX_BUFMIN 16
            if (sscanf(optstate->arg, "%i %c", &i, &dummy) != 1 || i <= SOX_BUFMIN) {
              lsx_fail("Buffer size `%s' must be > %d", optstate->arg, SOX_BUFMIN);
              exit(1);
            }
            sox_globals.bufsiz = i;
            break;
          case 2:
            combine_method = enum_option(optstate->arg, optstate->lngind, combine_methods, long_options);
            break;
          case 3:
            sox_append_comments(&f->comments, read_comment_file(optstate->arg));
            break;
          case 4:
            sox_append_comments(&f->comments, optstate->arg);
            break;
          case 5:
            if (f->encoding.reverse_bytes != SOX_OPTION_DEFAULT || f->encoding.opposite_endian)
              usage("only one endian option per file is allowed");
            switch (enum_option(optstate->arg, optstate->lngind, endian_options, long_options)) {
              case ENDIAN_little: f->encoding.reverse_bytes = SOX_OPTION_NO; break;
              case ENDIAN_big: f->encoding.reverse_bytes = SOX_OPTION_YES; break;
              case ENDIAN_swap: f->encoding.opposite_endian = sox_true; break;
            }
            break;
          case 6:
            if (sscanf(optstate->arg, "%i %c", &i, &dummy) != 1 || i <= SOX_BUFMIN) {
              lsx_fail("Buffer size `%s' must be > %d", optstate->arg, SOX_BUFMIN);
              exit(1);
            }
            sox_globals.input_bufsiz = i;
            break;
          case 7:
            interactive = sox_true;
            break;
          case 8:
            usage_effect(optstate->arg);
            break;
          case 9:
            usage_format(optstate->arg);
            break;
          case 10:
            f->no_glob = sox_true;
            break;
          case 11:
            sox_effects_globals.plot = enum_option(optstate->arg, optstate->lngind, plot_methods, long_options);
            break;
          case 12:
            replay_gain_mode_e = enum_option(optstate->arg, optstate->lngind, rg_modes, long_options);
            break;
          case 13:
            display_SoX_version(stdout);
            exit(0);
            break;
          case 14:
            /* output */
            break;
          case 15:
            effects_filename = lsx_strdup(optstate->arg);
            break;
          case 16:
            sox_globals.tmp_path = lsx_strdup(optstate->arg);
            break;
          case 17:
            sox_globals.use_threads = sox_false;
            break;
          case 18:
            f->signal.length = SOX_IGNORE_LENGTH;
            break;
          case 19:
            do_guarded_norm = is_guarded = sox_true;
            norm_level = optstate->arg ? lsx_strdup(optstate->arg) : NULL;
            if (!norm_level) {
              /* The original crashes here */
              raise(SIGSEGV);
            }
            break;
          case 20:
            /* magic */
            break;
          case 21:
            play_rate_arg = lsx_strdup(optstate->arg);
            break;
          case 22:
            no_clobber = sox_false;
            break;
          case 23:
            no_clobber = sox_true;
            break;
          case 24:
            sox_globals.use_threads = sox_true;
            break;
          case 25:
            if (sscanf(optstate->arg, "%i %c", &i, &dummy) != 1 || i < 8 || i > 16) {
              lsx_fail("Minimum DFT size `%s' must be >= 8 and <= 16", optstate->arg);
              exit(1);
            }
            sox_globals.log2_dft_min_size = i;
            break;
        }
        break;

      case 'm': combine_method = sox_mix; break;
      case 'M': combine_method = sox_merge; break;
      case 'T': combine_method = sox_multiply; break;

      case 'R': sox_globals.repeatable = sox_true; break;

      case 'd':
      case 'n':
      case 'p':
        optstate->ind = optstate->ind;
        return sox_true + c;

      case 'h':
        usage(NULL);
        break;

      case '?':
        usage("invalid option");
        break;

      case 't':
        f->filetype = lsx_strdup(optstate->arg);
        if (f->filetype[0] == '.')
          f->filetype++;
        break;

      case 'r': {
        char k = 0;
        size_t n = sscanf(optstate->arg, "%lf %c %c", &f->signal.rate, &k, &dummy);
        if (n < 1 || f->signal.rate <= 0 || (n > 1 && k != 'k')) {
          lsx_fail("Rate value `%s' is not a positive number", optstate->arg);
          exit(1);
        }
        f->signal.rate *= k == 'k' ? 1000. : 1.;
        break;
      }

      case 'v':
        if (sscanf(optstate->arg, "%lf %c", &f->volume, &dummy) != 1) {
          lsx_fail("Volume value `%s' is not a number", optstate->arg);
          exit(1);
        }
        uservolume = sox_true;
        if (f->volume < 0.0)
          lsx_report("Volume adjustment is negative; this will result in a phase change");
        break;

      case 'c':
        if (sscanf(optstate->arg, "%d %c", &i, &dummy) != 1 || i <= 0) {
          lsx_fail("Channels value `%s' is not a positive integer", optstate->arg);
          exit(1);
        }
        f->signal.channels = i;
        break;

      case 'C':
        if (sscanf(optstate->arg, "%lf %c", &f->encoding.compression, &dummy) != 1) {
          lsx_fail("Compression value `%s' is not a number", optstate->arg);
          exit(1);
        }
        break;

      case 'b':
        if (sscanf(optstate->arg, "%d %c", &i, &dummy) != 1 || i <= 0) {
          lsx_fail("Bits value `%s' is not a positive integer", optstate->arg);
          exit(1);
        }
        f->encoding.bits_per_sample = i;
        break;

      case 'e':
        switch (enum_option(optstate->arg, opt_index('e'), encodings, long_options)) {
          case encoding_signed_integer: f->encoding.encoding = SOX_ENCODING_SIGN2; break;
          case encoding_unsigned_integer: f->encoding.encoding = SOX_ENCODING_UNSIGNED; break;
          case encoding_floating_point: f->encoding.encoding = SOX_ENCODING_FLOAT; break;
          case encoding_ms_adpcm: f->encoding.encoding = SOX_ENCODING_MS_ADPCM; break;
          case encoding_ima_adpcm: f->encoding.encoding = SOX_ENCODING_IMA_ADPCM; break;
          case encoding_oki_adpcm: f->encoding.encoding = SOX_ENCODING_OKI_ADPCM; break;
          case encoding_gsm_full_rate: f->encoding.encoding = SOX_ENCODING_GSM; break;
          case encoding_u_law: f->encoding.encoding = SOX_ENCODING_ULAW;
            if (f->encoding.bits_per_sample == 0) f->encoding.bits_per_sample = 8;
            break;
          case encoding_a_law: f->encoding.encoding = SOX_ENCODING_ALAW;
            if (f->encoding.bits_per_sample == 0) f->encoding.bits_per_sample = 8;
            break;
        }
        break;

      case 'L': case 'B': case 'x':
        if (f->encoding.reverse_bytes != SOX_OPTION_DEFAULT || f->encoding.opposite_endian)
          usage("only one endian option per file is allowed");
        switch (c) {
          case 'L': f->encoding.reverse_bytes = SOX_OPTION_NO; break;
          case 'B': f->encoding.reverse_bytes = SOX_OPTION_YES; break;
          case 'x': f->encoding.opposite_endian = sox_true; break;
        }
        break;
      case 'X': f->encoding.reverse_bits = SOX_OPTION_YES; break;
      case 'N': f->encoding.reverse_nibbles = SOX_OPTION_YES; break;

      case 'S': show_progress = sox_true; show_progress_set = sox_true; break;
      case 'q': show_progress = sox_false; show_progress_set = sox_true; break;
      case 'D': no_dither = sox_true; break;

      case 'V':
        if (optstate->arg == NULL)
          ++sox_globals.verbosity;
        else {
          if (sscanf(optstate->arg, "%i %c", &i, &dummy) != 1 || i < 0) {
            sox_globals.verbosity = 2;
            lsx_fail("Verbosity value `%s' is not a non-negative integer", optstate->arg);
            exit(1);
          }
          sox_globals.verbosity = i;
        }
        break;

      case 'G':
        is_guarded = sox_true;
        break;

      default:
        usage("invalid option");
        break;
    }
  }
  (void)save;
}

/* parse effect arguments into user_effargs */
static void parse_effects(int argc, char **argv, int optind)
{
  for (eff_chain_count = 0; optind < argc; ++eff_chain_count) {
    for (; optind < argc && strcmp(argv[optind], ":"); ++optind) {
      size_t eff_offset = nuser_effects[eff_chain_count];
      user_eff_t *eff;
      int newline_mode = 0;
      (void)newline_mode;

      user_effargs[eff_chain_count] = lsx_realloc(user_effargs[eff_chain_count], (eff_offset + 1) * sizeof(user_eff_t));
      eff = &user_effargs[eff_chain_count][eff_offset];
      eff->name = argv[optind++];
      eff->argc = 0;
      eff->argv = NULL;
      if (!sox_find_effect(eff->name)) {
        lsx_fail("Effect `%s' does not exist!", eff->name);
        exit(1);
      }
      while (optind < argc && !sox_find_effect(argv[optind]) && strcmp(argv[optind], ":")) {
        eff->argv = lsx_realloc(eff->argv, (eff->argc + 1) * sizeof(char *));
        eff->argv[eff->argc++] = argv[optind++];
      }
      --optind;
      nuser_effects[eff_chain_count]++;
      if (nuser_effects[eff_chain_count] > 1000) break;
    }
    if (optind < argc && !strcmp(argv[optind], ":")) {
      ++optind;
      init_eff_chains_next:
      user_effargs = lsx_realloc(user_effargs, (eff_chain_count + 2) * sizeof(*user_effargs));
      nuser_effects = lsx_realloc(nuser_effects, (eff_chain_count + 2) * sizeof(*nuser_effects));
      user_effargs[eff_chain_count + 1] = NULL;
      nuser_effects[eff_chain_count + 1] = 0;
      if (0) goto init_eff_chains_next;
      if (optind >= argc) { ++eff_chain_count; break; }
      continue;
    }
  }
}

/* effects file */
static void read_user_effects(char const *filename)
{
  FILE *file = fopen(filename, "r");
  const size_t buffer_size_step = 1024;
  size_t buffer_size = buffer_size_step;
  char *s = lsx_malloc(buffer_size);
  size_t pos = 0;
  int argc;
  char **argv;
  sox_bool last_was_colon = sox_false;

  if (eff_chain_count > 0) {
    eff_chain_count = 0;
    free(user_effargs);
    free(nuser_effects);
    user_effargs = NULL; nuser_effects = NULL;
    init_eff_chains();
  }

  if (file == NULL) {
    lsx_fail("Cannot open effects file `%s': %s", filename, strerror(errno));
    exit(1);
  }

  lsx_report("Reading effects from file `%s'", filename);

  while (fgets(s + pos, (int)(buffer_size - pos), file)) {
    size_t len = strlen(s + pos);
    if (len && s[pos + len - 1] == '\n')
      s[pos + len - 1] = '\0', pos = 0;
    else if (len + 1 != buffer_size - pos) {
      pos = 0;
    } else {
      buffer_size += buffer_size_step;
      s = lsx_realloc(s, buffer_size);
      pos += len;
      continue;
    }
    /* tokenize */
    {
      char *p = s;
      argc = 0;
      argv = NULL;
      while (*p) {
        char *start, *out;
        while (*p && isspace((unsigned char)*p)) ++p;
        if (!*p || *p == '#') break;
        start = out = p;
        while (*p && !isspace((unsigned char)*p)) {
          if (*p == '"' || *p == '\'') {
            char q = *p++;
            while (*p && *p != q) *out++ = *p++;
            if (*p) ++p;
          } else *out++ = *p++;
        }
        if (*p) ++p;
        *out = '\0';
        argv = lsx_realloc(argv, (argc + 1) * sizeof(*argv));
        argv[argc++] = lsx_strdup(start);
      }
      if (argc == 0) { free(argv); continue; }
      last_was_colon = sox_false;
      {
        int i = 0;
        while (i < argc) {
          if (!strcmp(argv[i], ":")) {
            ++eff_chain_count;
            init_eff_chains();
            last_was_colon = sox_true;
            ++i;
            continue;
          }
          {
            size_t off = nuser_effects[eff_chain_count];
            user_eff_t *eff;
            user_effargs[eff_chain_count] = lsx_realloc(user_effargs[eff_chain_count], (off + 1) * sizeof(user_eff_t));
            eff = &user_effargs[eff_chain_count][off];
            eff->name = argv[i++];
            eff->argc = 0; eff->argv = NULL;
            if (!sox_find_effect(eff->name)) {
              lsx_fail("Effect `%s' does not exist!", eff->name);
              exit(1);
            }
            while (i < argc && !sox_find_effect(argv[i]) && strcmp(argv[i], ":")) {
              eff->argv = lsx_realloc(eff->argv, (eff->argc + 1) * sizeof(char *));
              eff->argv[eff->argc++] = argv[i++];
            }
            nuser_effects[eff_chain_count]++;
            last_was_colon = sox_false;
          }
        }
      }
      /* each line is a chain */
      ++eff_chain_count;
      init_eff_chains();
    }
  }
  if (ferror(file)) {
    lsx_fail("error reading effects file `%s': %s", filename, strerror(errno));
    exit(1);
  }
  fclose(file);
  free(s);
  if (eff_chain_count > 0 && nuser_effects[eff_chain_count] == 0 && !last_was_colon) {
    /* drop trailing empty chain */
  } else
    ++eff_chain_count;
  if (eff_chain_count == 0) eff_chain_count = 1;
}

/* ----- effects creation ----- */
static sox_bool is_experimental_warned = sox_false;

static void create_user_effects(void)
{
  size_t i;
  sox_effect_t *effp;
  size_t num_effects = nuser_effects[current_eff_chain];

  if (num_effects > user_efftab_size) {
    user_efftab = lsx_realloc(user_efftab, num_effects * sizeof(*user_efftab));
    user_efftab_size = num_effects;
  }

  for (i = 0; i < num_effects; i++) {
    user_eff_t *ue = &user_effargs[current_eff_chain][i];
    effp = sox_create_effect(sox_find_effect(ue->name));

    if (effp->handler.flags & SOX_EFF_DEPRECATED) {
      lsx_set_subsystem(NULL);
      lsx_warn("effect `%s' is deprecated; see sox(1) for an alternative", effp->handler.name);
    } else if (effp->handler.flags & SOX_EFF_ALPHA) {
      lsx_set_subsystem(NULL);
      lsx_warn("effect `%s' is experimental/incomplete", effp->handler.name);
    } else if (effp->handler.flags & SOX_EFF_INTERNAL) {
      lsx_set_subsystem(NULL);
      lsx_fail("`%s' is a libSoX-only effect", effp->handler.name);
      exit(1);
    }

    if (sox_effect_options(effp, ue->argc, ue->argv) == SOX_EOF)
      exit(1);

    user_efftab[i] = effp;
  }
  (void)is_experimental_warned;
}

static void auto_effect(sox_effects_chain_t *chain, char const *name, int argc, char *argv[], sox_signalinfo_t *signal, int *guard)
{
  sox_effect_t *effp;

  effp = sox_create_effect(sox_find_effect(name));
  if (sox_effect_options(effp, argc, argv) == SOX_EOF)
    exit(1);
  if (sox_add_effect(chain, effp, signal, &ofile->ft->signal) != SOX_SUCCESS)
    exit(2);
  free(effp);
  (void)guard;
}

/* ----- input combiner ----- */
typedef struct {
  sox_sample_t **ibuf;
  size_t *ilen;
} input_combiner_t;

static size_t sox_read_wide(sox_format_t *ft, sox_sample_t *buf, size_t max)
{
  size_t len = max / combiner_signal.channels;
  len = sox_read(ft, buf, len * ft->signal.channels) / ft->signal.channels;
  if (!len && ft->sox_errno) {
    lsx_set_subsystem(NULL);
    lsx_fail("`%s' %s: %s", ft->filename, ft->sox_errstr, sox_strerror(ft->sox_errno));
  }
  return len;
}

static void balance_input(sox_sample_t *buf, size_t ws, file_t *f)
{
  size_t s = ws * f->ft->signal.channels;
  if (f->volume != 1) while (s--) {
    double d = f->volume * *buf;
    size_t c = 0;
    *buf++ = SOX_ROUND_CLIP_COUNT(d, c);
    f->volume_clips += c;
  }
}

static int combiner_start(sox_effect_t *effp)
{
  input_combiner_t *z = (input_combiner_t *)effp->priv;
  uint64_t ws;
  size_t i;

  if (combine_method <= sox_concatenate)
    progress_to_next_input_file_dummy: ;
  else {
    ws = 0;
    z->ibuf = lsx_malloc(input_count * sizeof(*z->ibuf));
    for (i = 0; i < input_count; i++) {
      z->ibuf[i] = lsx_malloc(sox_globals.bufsiz * sizeof(sox_sample_t));
      if (files[i]->ft->signal.length > ws * files[i]->ft->signal.channels) ws = files[i]->ft->signal.length / files[i]->ft->signal.channels;
    }
    z->ilen = lsx_malloc(input_count * sizeof(*z->ilen));
  }
  return SOX_SUCCESS;
}

static sox_bool can_segue(size_t i)
{
  return files[i]->ft->signal.channels == files[i - 1]->ft->signal.channels &&
         files[i]->ft->signal.rate == files[i - 1]->ft->signal.rate;
}

static int combiner_drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{
  input_combiner_t *z = (input_combiner_t *)effp->priv;
  size_t ws, s, i;
  size_t olen = 0;

  if (combine_method <= sox_concatenate) while (sox_true) {
    if (!user_abort)
      olen = sox_read_wide(files[current_input]->ft, obuf, *osamp);
    if (olen == 0) {
      if (++current_input < input_count) {
        if (combine_method == sox_sequence && !can_segue(current_input))
          break;
        continue;
      }
    }
    balance_input(obuf, olen, files[current_input < input_count ? current_input : input_count - 1]);
    break;
  } else {
    sox_sample_t *p = obuf;
    for (i = 0; i < input_count; ++i) {
      z->ilen[i] = sox_read_wide(files[i]->ft, z->ibuf[i], *osamp);
      balance_input(z->ibuf[i], z->ilen[i], files[i]);
      olen = max(olen, z->ilen[i]);
    }
    for (ws = 0; ws < olen; ++ws) {
      if (combine_method == sox_mix || combine_method == sox_mix_power) {
        for (s = 0; s < effp->out_signal.channels; ++s, ++p) {
          *p = 0;
          for (i = 0; i < input_count; ++i)
            if (ws < z->ilen[i] && s < files[i]->ft->signal.channels) {
              double sample = *p + (double)z->ibuf[i][ws * files[i]->ft->signal.channels + s];
              *p = SOX_ROUND_CLIP_COUNT(sample, mixing_clips);
            }
        }
      } else if (combine_method == sox_multiply) {
        for (s = 0; s < effp->out_signal.channels; ++s, ++p) {
          i = 0;
          *p = ws < z->ilen[i] && s < files[i]->ft->signal.channels ?
            z->ibuf[i][ws * files[i]->ft->signal.channels + s] : 0;
          for (++i; i < input_count; ++i) {
            double sample = *p * (-1. / SOX_SAMPLE_MIN) * (ws < z->ilen[i] && s < files[i]->ft->signal.channels ?
              z->ibuf[i][ws * files[i]->ft->signal.channels + s] : 0);
            *p = SOX_ROUND_CLIP_COUNT(sample, mixing_clips);
          }
        }
      } else {
        for (i = 0; i < input_count; ++i)
          for (s = 0; s < files[i]->ft->signal.channels; ++s)
            *p++ = (ws < z->ilen[i]) * z->ibuf[i][ws * files[i]->ft->signal.channels + s];
      }
    }
  }
  read_wide_samples += olen;
  olen *= effp->out_signal.channels;
  *osamp = olen;
  return olen ? SOX_SUCCESS : SOX_EOF;
}

static int combiner_stop(sox_effect_t *effp)
{
  input_combiner_t *z = (input_combiner_t *)effp->priv;
  size_t i;

  if (combine_method >= sox_mix) {
    for (i = 0; i < input_count; i++)
      free(z->ibuf[i]);
    free(z->ibuf);
    free(z->ilen);
  }
  return SOX_SUCCESS;
}

static sox_effect_handler_t const *input_combiner_effect_fn(void)
{
  static sox_effect_handler_t handler = { "input", 0, SOX_EFF_MCHAN | SOX_EFF_MODIFY,
    0, combiner_start, 0, combiner_drain, combiner_stop, 0, sizeof(input_combiner_t)
  };
  return &handler;
}

static int ostart(sox_effect_t *effp)
{
  unsigned prec = effp->out_signal.precision;
  if (effp->in_signal.mult && effp->in_signal.precision > prec)
    *effp->in_signal.mult *= 1 - (1 << (31 - prec)) * (1. / SOX_SAMPLE_MAX);
  return SOX_SUCCESS;
}

static int output_flow(sox_effect_t *effp, sox_sample_t const *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  size_t len;
  (void)effp, (void)obuf;
  *osamp = 0;
  len = *isamp ? sox_write(ofile->ft, ibuf, *isamp) : 0;
  output_samples += len / ofile->ft->signal.channels;
  if (len != *isamp) {
    if (ofile->ft->sox_errno) {
      lsx_set_subsystem(NULL);
      lsx_fail("`%s' %s: %s", ofile->ft->filename, ofile->ft->sox_errstr, sox_strerror(ofile->ft->sox_errno));
    }
    return SOX_EOF;
  }
  return SOX_SUCCESS;
}

static sox_effect_handler_t const *output_effect_fn(void)
{
  static sox_effect_handler_t handler = { "output", 0, SOX_EFF_MCHAN | SOX_EFF_MODIFY | SOX_EFF_PREC,
    NULL, ostart, output_flow, NULL, NULL, NULL, 0
  };
  return &handler;
}

static void add_effects(sox_effects_chain_t *chain)
{
  sox_signalinfo_t signal = combiner_signal;
  int guard = is_guarded - 1;
  unsigned i;
  sox_effect_t *effp;
  char *rate_arg = sox_mode == sox_play ? (play_rate_arg ? play_rate_arg : "-l") : NULL;

  effp = sox_create_effect(input_combiner_effect_fn());
  sox_add_effect(chain, effp, &signal, &ofile->ft->signal);
  free(effp);

  for (i = 0; i < nuser_effects[current_eff_chain] && strcmp(user_efftab[i]->handler.name, "dither"); i++) {
    if (guard == 1 && (user_efftab[i]->handler.flags & SOX_EFF_GAIN)) {
      char *arg = "-r";
      auto_effect(chain, "gain", 1, &arg, &signal, &guard);
      guard = 0;
    }
    if (sox_add_effect(chain, user_efftab[i], &signal, &ofile->ft->signal) != SOX_SUCCESS)
      exit(2);
    if (guard == 0 && !(user_efftab[i]->handler.flags & SOX_EFF_GAIN) && strcmp(user_efftab[i]->handler.name, "rate")) {
    }
    free(user_efftab[i]);
    user_efftab[i] = NULL;
  }

  if ((signal.channels < ofile->ft->signal.channels && signal.rate != ofile->ft->signal.rate)) {
    auto_effect(chain, "rate", rate_arg != NULL, &rate_arg, &signal, &guard);
  }
  if (signal.channels != ofile->ft->signal.channels)
    auto_effect(chain, "channels", 0, NULL, &signal, &guard);
  if (signal.rate != ofile->ft->signal.rate)
    auto_effect(chain, "rate", rate_arg != NULL, &rate_arg, &signal, &guard);

  if (is_guarded && (do_guarded_norm || !(signal.mult && *signal.mult == 1))) {
    char *args[2];
    int no_guard = -1;
    args[0] = do_guarded_norm ? "-nh" : guard ? "-rh" : "-h";
    args[1] = norm_level;
    auto_effect(chain, "gain", norm_level ? 2 : 1, args, &signal, &no_guard);
    guard = 1;
  }

  if (i == nuser_effects[current_eff_chain] && !no_dither && signal.precision > ofile->ft->signal.precision && ofile->ft->signal.precision < 24)
    auto_effect(chain, "dither", 0, NULL, &signal, &guard);

  for (; i < nuser_effects[current_eff_chain]; i++) {
    if (sox_add_effect(chain, user_efftab[i], &signal, &ofile->ft->signal) != SOX_SUCCESS)
      exit(2);
    free(user_efftab[i]);
    user_efftab[i] = NULL;
  }

  if (signal.channels != ofile->ft->signal.channels)
    auto_effect(chain, "channels", 0, NULL, &signal, &guard);
  if (signal.rate != ofile->ft->signal.rate)
    auto_effect(chain, "rate", rate_arg != NULL, &rate_arg, &signal, &guard);

  effp = sox_create_effect(output_effect_fn());
  if (sox_add_effect(chain, effp, &signal, &ofile->ft->signal) != SOX_SUCCESS)
    exit(2);
  free(effp);

  for (i = 0; i < chain->length; ++i) {
    char const *format = sox_globals.verbosity > 3 ?
      "effects chain: %-10s %7gHz %2u channels %7s %2u bits %s" :
      "effects chain: %-10s %7gHz %2u channels";
    sox_effect_t const *effp2 = chain->effects[i];
    lsx_set_subsystem(NULL);
    lsx_report(format, effp2->handler.name, effp2->out_signal.rate, effp2->out_signal.channels,
        (effp2->handler.flags & SOX_EFF_MCHAN) ? "(multi)" : "",
        effp2->out_signal.precision,
        effp2->out_signal.length != SOX_UNKNOWN_LEN ?
          str_time(effp2->out_signal.length / effp2->out_signal.channels / effp2->out_signal.rate) : "unknown");
  }
}

/* ----- overwrite ----- */
static sox_bool overwrite_permitted(char const *filename)
{
  char c;
  if (!no_clobber) {
    lsx_set_subsystem(NULL);
    lsx_report("Overwriting `%s'", filename);
    return sox_true;
  }
  lsx_set_subsystem(NULL);
  lsx_warn("Output file `%s' already exists", filename);
  if (!isatty(fileno(stdin)))
    return sox_false;
  do fprintf(stderr, "%s sox: overwrite `%s' (y/n)? ", myname, filename);
  while (scanf(" %c%*[^\n]", &c) != 1 || !strchr("yYnN", c));
  return c == 'y' || c == 'Y';
}

/* ----- output open ----- */
static void open_output_file(void)
{
  double factor;
  int i;
  sox_comments_t comments = {NULL, 0};
  sox_comments_t *pc = &ofile->comments;

  /* Copy comments */
  {
    size_t k;
    sox_comments_t c = {NULL, 0};
    if (ofile->comments.n == 0 && !ofile->comments.list) {
      if (files[0]->ft->comments.n)
        sox_copy_comments(&c, &files[0]->ft->comments);
      else
        sox_append_comment(&c, "Processed by SoX");
    } else if (ofile->comments.n) {
      /* --add-comment adds to input comments; --comment replaces.
         Represent: list with leading NULL? We use a flag stored in filetype. */
    }
    if (ofile->comments.n || ofile->comments.list) {
      /* user-specified */
      sox_copy_comments(&c, &ofile->comments);
    }
    comments = c;
    (void)k;
  }
  (void)pc;

  factor = 0;
  (void)factor; (void)i;

  ofile->ft = sox_open_write(ofile->filename, &ofile->signal, &ofile->encoding, ofile->filetype, &comments, overwrite_permitted);
  sox_delete_comments(&comments);

  if (!ofile->ft)
    exit(2);

  /* If whether to enable the progress display (similar to that of ogg123) has
   * not been specified by the user, auto turn on when outputting to an audio
   * device: */
  if (!show_progress_set)
    show_progress = (ofile->ft->handler.flags & SOX_FILE_DEVICE) != 0 && (ofile->ft->handler.flags & SOX_FILE_PHONY) == 0;

  if (sox_globals.verbosity > 2)
    display_file_info(ofile->ft, ofile, sox_true);
}

static sox_bool add_comments_mode = sox_false;

static int update_status(sox_bool all_done, void *client_data)
{
  (void)all_done; (void)client_data;
  return user_abort ? SOX_EOF : SOX_SUCCESS;
}

static void sigint(int s)
{
  (void)s;
  user_abort = sox_true;
}

static void calculate_combiner_signal_parameters(void)
{
  size_t i;

  /* If user didn't specify # of channels then see if an effect
   * is specifying them.  */
  combiner_encoding = files[0]->ft->encoding;
  combiner_signal = files[0]->ft->signal;

  if (combine_method == sox_sequence) {
    if (!known_length) combiner_signal.length = SOX_UNKNOWN_LEN;
  } else {
    size_t total_channels = 0;
    size_t min_channels = SIZE_MAX;
    size_t max_channels = 0;
    size_t min_rate = SIZE_MAX;
    size_t max_rate = 0;
    uint64_t total_length = 0, max_length_ws = 0;

    for (i = 0; i < input_count; i++) {
      total_channels += files[i]->ft->signal.channels;
      min_channels = min(min_channels, files[i]->ft->signal.channels);
      max_channels = max(max_channels, files[i]->ft->signal.channels);
      min_rate = min(min_rate, (size_t)files[i]->ft->signal.rate);
      max_rate = max(max_rate, (size_t)files[i]->ft->signal.rate);
      known_length = known_length && files[i]->ft->signal.length != 0;
      if (combine_method == sox_concatenate)
        total_length += files[i]->ft->signal.length / files[i]->ft->signal.channels;
      else
        max_length_ws = max(max_length_ws, files[i]->ft->signal.length / files[i]->ft->signal.channels);
    }
    if (min_rate != max_rate) {
      lsx_set_subsystem(NULL);
      lsx_fail("Input files must have the same sample-rate");
    }
    if (min_channels != max_channels) {
      lsx_set_subsystem(NULL);
      if (combine_method == sox_concatenate) {
        lsx_fail("Input files must have the same # channels");
        exit(1);
      } else if (combine_method != sox_merge)
        lsx_warn("Input files don't have the same # channels");
    }
    if (min_rate != max_rate)
      exit(1);

    combiner_signal.channels = combine_method == sox_merge ? total_channels : max_channels;

    if (combine_method == sox_concatenate)
      combiner_signal.length = total_length * combiner_signal.channels;
    else
      combiner_signal.length = max_length_ws * combiner_signal.channels;
    if (!known_length)
      combiner_signal.length = SOX_UNKNOWN_LEN;
  }
}

static void set_combiner_and_output_encoding_and_signal(void)
{
  size_t i, j;

  for (i = 0, combiner_signal.precision = 0; i < input_count; i++)
    combiner_signal.precision = max(combiner_signal.precision, files[i]->ft->signal.precision);
  combiner_signal.rate = files[0]->ft->signal.rate;

  if (combine_method == sox_mix || combine_method == sox_mix_power || combine_method == sox_multiply)
    combiner_signal.precision = SOX_SAMPLE_PRECISION;

  ofile_signal_options = ofile->signal;
  ofile_encoding_options = ofile->encoding;

  if (!ofile->signal.rate)
    ofile->signal.rate = combiner_signal.rate;
  if (!ofile->signal.channels)
    ofile->signal.channels = combiner_signal.channels;
  if (!ofile->signal.precision)
    ofile->signal.precision = files[0]->ft->signal.precision;
  ofile->signal.precision = combiner_signal.precision < ofile->signal.precision ? ofile->signal.precision : ofile->signal.precision;
  /* The output precision follows the first input (as observed) */
  (void)j;
}

static int process(void)
{
  size_t i;
  int flow_status;

  set_combiner_and_output_encoding_and_signal();

  /* Output rate/channels from effects that set them at getopts time */
  {
    size_t e;
    double rate = 0;
    unsigned channels = 0;
    for (e = 0; e < nuser_effects[current_eff_chain]; ++e) {
      if (user_efftab[e]->out_signal.rate) rate = user_efftab[e]->out_signal.rate;
      if (user_efftab[e]->out_signal.channels) channels = user_efftab[e]->out_signal.channels;
    }
    if (!ofile_signal_options.rate && rate) ofile->signal.rate = rate;
    if (!ofile_signal_options.channels && channels) ofile->signal.channels = channels;
  }

  /* Output length */
  {
    sox_bool ok = known_length && combiner_signal.length != SOX_UNKNOWN_LEN;
    size_t e;
    for (e = 0; e < nuser_effects[current_eff_chain]; ++e)
      if (user_efftab[e]->handler.flags & SOX_EFF_LENGTH) ok = sox_false;
    if (ok && combiner_signal.channels && combiner_signal.rate) {
      double ws = (double)(combiner_signal.length / combiner_signal.channels);
      ofile->signal.length = (uint64_t)(ws * ofile->signal.rate / combiner_signal.rate + .5) * ofile->signal.channels;
    } else
      ofile->signal.length = 0;
  }

  /* Output encoding: use input's if supported and not specified */
  if (!ofile->encoding.encoding) {
    const sox_format_handler_t *h = NULL;
    if (ofile->filetype) h = sox_find_format(ofile->filetype, sox_false);
    else {
      const char *ext = lsx_find_file_extension(ofile->filename);
      if (ext && strcmp(ofile->filename, "-")) h = sox_find_format(ext, sox_true);
    }
    if (h && h->write_formats) {
      unsigned const *w = h->write_formats;
      size_t k = 0;
      sox_encoding_t e;
      sox_bool found = sox_false;
      while ((e = w[k++])) {
        unsigned s;
        while ((s = w[k++]))
          if (e == combiner_encoding.encoding && (!ofile->encoding.bits_per_sample || s == ofile->encoding.bits_per_sample))
            found = sox_true;
      }
      if (found) ofile->encoding.encoding = combiner_encoding.encoding;
    }
  }

  for (i = 0; i < input_count; i++) {
    if (sox_globals.verbosity > 2)
      display_file_info(files[i]->ft, files[i], sox_true);
  }

  open_output_file();

  if (!effects_chain)
    effects_chain = sox_create_effects_chain(&combiner_encoding, &ofile->ft->encoding);
  add_effects(effects_chain);

  if (sox_effects_globals.plot != sox_plot_off) {
    return 0;
  }

  signal(SIGTERM, sigint);
  signal(SIGINT, sigint);

  flow_status = sox_flow_effects(effects_chain, update_status, NULL);

  /* Close the effects chain */
  sox_delete_effects_chain(effects_chain);
  effects_chain = NULL;

  for (i = 0; i < file_count; ++i) {
    if (files[i]->ft && files[i]->ft->clips != 0) {
      lsx_set_subsystem(NULL);
      lsx_warn(i < input_count ? "`%s' input clipped %llu samples" : "`%s' output clipped %llu samples; decrease volume?",
          (files[i]->ft->handler.flags & SOX_FILE_DEVICE) ? files[i]->ft->handler.names[0] : files[i]->ft->filename,
          (unsigned long long)files[i]->ft->clips);
    }
  }

  if (mixing_clips > 0) {
    lsx_set_subsystem(NULL);
    lsx_warn("mix-combining clipped %llu samples; decrease volume?", (unsigned long long)mixing_clips);
  }

  for (i = 0; i < input_count; i++)
    if (files[i]->volume_clips > 0) {
      lsx_set_subsystem(NULL);
      lsx_warn("`%s' balancing clipped %llu samples; decrease volume?", files[i]->filename, (unsigned long long)files[i]->volume_clips);
    }

  return flow_status;
}

static void cleanup(void)
{
  size_t i;
  for (i = 0; i < file_count; ++i) {
    if (files[i]->ft) {
      sox_close(files[i]->ft);
      files[i]->ft = NULL;
    }
  }
}

int main(int argc, char **argv)
{
  size_t i;
  char mybase[256];
  file_t opts, *f;
  lsx_getopt_t optstate;

  myname = argv[0];
  {
    const char *b = strrchr(argv[0], '/');
    b = b ? b + 1 : argv[0];
    snprintf(mybase, sizeof(mybase), "%s", b);
    {
      char *dot = strrchr(mybase, '.');
      if (dot && !lsx_strcasecmp(dot, ".exe")) *dot = 0;
    }
  }
  sox_globals.subsystem = NULL;
  sox_globals.ranqd1 = 0;

  if (lsx_strends(mybase, "play")) sox_mode = sox_play;
  else if (lsx_strends(mybase, "rec")) sox_mode = sox_rec;
  else if (lsx_strends(mybase, "soxi")) sox_mode = sox_soxi;

  if (sox_mode == sox_sox && argc > 1 && (!strcmp(argv[1], "--i") || !strcmp(argv[1], "--info"))) {
    --argc, ++argv;
    sox_mode = sox_soxi;
  }

  if (sox_mode == sox_soxi)
    exit(soxi(argc, argv));

  init_file(&opts);
  init_eff_chains();

  if (argc <= 1 && sox_mode == sox_sox)
    usage("No input filenames specified");
  if (argc == 1) usage(NULL);

  lsx_getopt_init(argc, argv, getoptstr, long_options, lsx_getopt_flag_opterr, 1, &optstate);

  /* Parse global and file options and filenames */
  while (optstate.ind < argc && !sox_find_effect(argv[optstate.ind])) {
    int r;
    f = new_file();
    *f = opts;
    r = parse_gopts_and_fopts(f, &optstate);
    if (r) {
      int c = r - sox_true;
      if (c == 'd') {
        f->filetype = NULL;
        f->filename = (char *)set_default_device(f);
      } else if (c == 'n') {
        f->filetype = "null";
        add_file(f, "");
      } else if (c == 'p') {
        f->filetype = "sox";
        add_file(f, "-");
      }
      free(f);
      init_file(&opts);
      continue;
    }
    if (optstate.ind >= argc || sox_find_effect(argv[optstate.ind])) {
      /* options with no filename */
      if (f->filetype || f->signal.rate || f->signal.channels || f->encoding.encoding ||
          f->encoding.bits_per_sample || f->volume != HUGE_VAL || f->comments.n ||
          f->encoding.reverse_bytes != SOX_OPTION_DEFAULT || f->encoding.opposite_endian ||
          f->encoding.reverse_bits != SOX_OPTION_DEFAULT || f->encoding.reverse_nibbles != SOX_OPTION_DEFAULT ||
          f->signal.length || f->encoding.compression != HUGE_VAL || f->no_glob)
        usage("missing filename");
      free(f);
      break;
    }
    if (is_playlist(argv[optstate.ind]))
      parse_playlist(add_file_cb, f, argv[optstate.ind]);
    else
      add_glob_file(f, argv[optstate.ind]);
    optstate.ind++;
    free(f);
    init_file(&opts);
  }

  /* Effects */
  if (effects_filename)
    read_user_effects(effects_filename);
  else {
    parse_effects(argc, argv, optstate.ind);
    if (eff_chain_count == 0) eff_chain_count = 1;
  }

  /* Validate files */
  if (sox_mode == sox_rec) {
  }

  if (file_count == 0 || (sox_mode != sox_play && file_count < 2)) {
    if (file_count == 0 && sox_mode == sox_sox)
      usage("No input filenames specified");
    if (file_count < 2 && sox_mode == sox_sox)
      usage("No input filenames specified");
    usage("Not enough input filenames specified");
  }
  input_count = file_count - 1;
  output_count = 1;

  for (i = 0; i < input_count; i++) {
    if (files[i]->comments.n) usage("Comments can be given only for an output file");
  }
  if (ofile->volume != HUGE_VAL)
    usage("-v can be given only for an input file;\n\tuse the `gain' or `vol' effect to set the output file volume");
  if (ofile->signal.length != 0)
    usage("--ignore-length can be given only for an input file");

  if (combine_method == sox_default)
    combine_method = sox_mode == sox_play ? sox_sequence : sox_concatenate;
  else if (input_count < 1)
    usage("Not enough input filenames specified");

  if (combine_method == sox_sequence && 0)
    ;

  /* Open the input file(s). */
  if (sox_globals.verbosity > 2)
    display_SoX_version(stderr);

  if (!sox_globals.repeatable) {
    sox_globals.ranqd1 = (int32_t)time(NULL) ^ (int32_t)getpid();
  }

  known_length = combine_method != sox_sequence;
  for (i = 0; i < input_count; i++) {
    /* Null input: take channel count from first synth if not specified */
    if (files[i]->filetype && !strcmp(files[i]->filetype, "null") && !files[i]->signal.channels) {
      size_t e;
      for (e = 0; e < nuser_effects[0]; ++e) {
        if (!strcmp(user_effargs[0][e].name, "synth")) {
          extern unsigned lsx_synth_count_channels(int argc, char **argv);
          unsigned n = lsx_synth_count_channels(user_effargs[0][e].argc, user_effargs[0][e].argv);
          if (n) files[i]->signal.channels = n;
          break;
        }
      }
    }
    files[i]->ft = sox_open_read(files[i]->filename, &files[i]->signal, &files[i]->encoding, files[i]->filetype);
    if (!files[i]->ft)
      exit(2);
    files[i]->ft->file_size = lsx_filelength(files[i]->ft);
    if (files[i]->volume == HUGE_VAL) {
      /* default volume */
    }
  }

  /* Set the volume for mixing */
  if (combine_method == sox_mix || combine_method == sox_mix_power) {
    if (!uservolume)
      for (i = 0; i < input_count; i++) {
        files[i]->volume = combine_method == sox_mix ? 1.0 / input_count : 1.0 / sqrt((double)input_count);
      }
  }

  for (i = 0; i < input_count; i++)
    if (files[i]->volume == HUGE_VAL)
      ;

  /* Effects getopts */
  current_eff_chain = 0;
  calculate_combiner_signal_parameters();
  create_user_effects();

  for (i = 0; i < input_count; i++) {
    if (files[i]->volume == HUGE_VAL) files[i]->volume = 1;
  }
  {
    /* restore HUGE_VAL marker for display where volume was default */
  }

  success = process();
  cleanup();
  (void)add_comments_mode;
  (void)save_output_eff;
  (void)device_name;
  (void)replay_gain_mode;
  (void)input_wide_samples;
  return success == SOX_SUCCESS ? 0 : 2;
}
EOF
