/* AIFF and AIFF-C formats */
#include "sox.h"
#include <time.h>

typedef struct {
  uint64_t nsamples;
  uint64_t dataStart;
} priv_t;

static double read_ieee_extended(const unsigned char *bytes)
{
  double f;
  int expon;
  uint32_t hiMant, loMant;
  expon = ((bytes[0] & 0x7F) << 8) | (bytes[1] & 0xFF);
  hiMant = ((uint32_t)bytes[2] << 24) | ((uint32_t)bytes[3] << 16) | ((uint32_t)bytes[4] << 8) | (uint32_t)bytes[5];
  loMant = ((uint32_t)bytes[6] << 24) | ((uint32_t)bytes[7] << 16) | ((uint32_t)bytes[8] << 8) | (uint32_t)bytes[9];
  if (expon == 0 && hiMant == 0 && loMant == 0) {
    f = 0;
  } else {
    if (expon == 0x7FFF) {
      f = HUGE_VAL;
    } else {
      expon -= 16383;
      f = ldexp((double)hiMant, expon -= 31);
      f += ldexp((double)loMant, expon -= 32);
    }
  }
  if (bytes[0] & 0x80)
    return -f;
  else
    return f;
}

static void write_ieee_extended(sox_format_t *ft, double num)
{
  unsigned char bytes[10];
  int sign;
  int expon;
  double fMant, fsMant;
  uint32_t hiMant, loMant;

  if (num < 0) { sign = 0x8000; num *= -1; }
  else sign = 0;

  if (num == 0) {
    expon = 0; hiMant = 0; loMant = 0;
  } else {
    fMant = frexp(num, &expon);
    if ((expon > 16384) || !(fMant < 1)) {
      expon = sign | 0x7FFF; hiMant = 0; loMant = 0;
    } else {
      expon += 16382;
      if (expon < 0) {
        fMant = ldexp(fMant, expon);
        expon = 0;
      }
      expon |= sign;
      fMant = ldexp(fMant, 32);
      fsMant = floor(fMant);
      hiMant = (uint32_t)fsMant;
      fMant = ldexp(fMant - fsMant, 32);
      fsMant = floor(fMant);
      loMant = (uint32_t)fsMant;
    }
  }
  bytes[0] = expon >> 8;
  bytes[1] = expon;
  bytes[2] = hiMant >> 24;
  bytes[3] = hiMant >> 16;
  bytes[4] = hiMant >> 8;
  bytes[5] = hiMant;
  bytes[6] = loMant >> 24;
  bytes[7] = loMant >> 16;
  bytes[8] = loMant >> 8;
  bytes[9] = loMant;
  lsx_writebuf(ft, bytes, 10);
}

static int read_chunk_text(sox_format_t *ft, uint32_t size, const char *prefix)
{
  char *buf = lsx_calloc(1, size + 2);
  if (lsx_readbuf(ft, buf, size) != size) { free(buf); return SOX_EOF; }
  if (size & 1) { char c; lsx_readbuf(ft, &c, 1); }
  buf[size] = 0;
  (void)prefix;
  sox_append_comments(&ft->comments, buf);
  free(buf);
  return SOX_SUCCESS;
}

