  double rate = 0.0;
  uint32_t offset = 0;
  uint32_t blocksize = 0;
  int foundcomm = 0, foundmark = 0, foundinstr = 0, is_sowt = 0;
  uint64_t seekto = 0, ssndsize = 0;
  int is_aifc = 0;

