  if (lsx_readbuf(ft, buf, 4) != 4 || strncmp(buf, "FORM", 4) != 0) {
    lsx_fail_errno(ft, SOX_EHDR, "AIFF header does not begin with magic word `FORM'");
    return SOX_EOF;
  }
