    return SOX_EOF;
  }
  is_aifc = !strncmp(buf, "AIFC", 4);

  /* Skip everything but the COMM chunk and the SSND chunk */
  /* The SSND chunk must be the last in the file */
  while (1) {
    if (lsx_readbuf(ft, buf, 4) != 4) {
      if (ssndsize > 0)
        break;
      else {
        lsx_fail_errno(ft, SOX_EHDR, "Missing SSND chunk in AIFF file");
        return SOX_EOF;
      }
    }
    buf[4] = 0;
    if (strncmp(buf, "COMM", 4) == 0) {
      unsigned char ext[10];
      /* COMM chunk */
      lsx_readdw(ft, &chunksize);
      lsx_readw(ft, &channels);
      lsx_readdw(ft, &frames);
      lsx_readw(ft, &bits);
      lsx_readbuf(ft, ext, 10);
      rate = read_ieee_extended(ext);
      chunksize -= 18;
      if (chunksize > 0 && is_aifc) {
        char t[5];
        lsx_readbuf(ft, t, 4);
        t[4] = 0;
        chunksize -= 4;
        if (!strcmp(t, "sowt")) { is_sowt = 1; }
        else if (!strcmp(t, "fl32") || !strcmp(t, "FL32")) { enc = SOX_ENCODING_FLOAT; }
        else if (!strcmp(t, "fl64") || !strcmp(t, "FL64")) { enc = SOX_ENCODING_FLOAT; }
        else if (!strcmp(t, "ulaw") || !strcmp(t, "ULAW")) { enc = SOX_ENCODING_ULAW; bits = 8; }
        else if (!strcmp(t, "alaw") || !strcmp(t, "ALAW")) { enc = SOX_ENCODING_ALAW; bits = 8; }
        else if (strcmp(t, "NONE") && strcmp(t, "twos") && strcmp(t, "raw ")) {
          lsx_fail_errno(ft, SOX_EHDR, "AIFC files that contain compressed data are not supported: %s", t);
          return SOX_EOF;
        }
        if (!strcmp(t, "raw ")) enc = SOX_ENCODING_UNSIGNED;
      }
      while (chunksize-- > 0) {
        unsigned char c;
        lsx_readb(ft, &c);
      }
      foundcomm = 1;
    } else if (strncmp(buf, "SSND", 4) == 0) {
      /* SSND chunk */
      lsx_readdw(ft, &chunksize);
      lsx_readdw(ft, &offset);
      lsx_readdw(ft, &blocksize);
      chunksize -= 8;
      ssndsize = chunksize;
      /* word-align chunksize in case it wasn't
       * done by writing application already.
       */
      chunksize += (chunksize % 2);
      /* if can't seek, just do sound now */
      if (!ft->seekable)
        break;
      /* else, seek to end of sound and hunt for more */
      seekto = lsx_tell(ft);
      lsx_seeki(ft, (int64_t)chunksize, SEEK_CUR);
    } else if (strncmp(buf, "MARK", 4) == 0) {
      lsx_readdw(ft, &chunksize);
      foundmark = 1;
      lsx_seeki(ft, (int64_t)(chunksize + (chunksize & 1)), SEEK_CUR);
    } else if (strncmp(buf, "INST", 4) == 0) {
      lsx_readdw(ft, &chunksize);
      foundinstr = 1;
      lsx_seeki(ft, (int64_t)(chunksize + (chunksize & 1)), SEEK_CUR);
    } else if (strncmp(buf, "APPL", 4) == 0) {
      lsx_readdw(ft, &chunksize);
      lsx_seeki(ft, (int64_t)(chunksize + (chunksize & 1)), SEEK_CUR);
    } else if (strncmp(buf, "ALCH", 4) == 0) {
      /* skip ALCH chunk */
      lsx_readdw(ft, &chunksize);
      lsx_seeki(ft, (int64_t)(chunksize + (chunksize & 1)), SEEK_CUR);
    } else if (strncmp(buf, "ANNO", 4) == 0 || strncmp(buf, "AUTH", 4) == 0 ||
               strncmp(buf, "NAME", 4) == 0 || strncmp(buf, "(c) ", 4) == 0) {
      lsx_readdw(ft, &chunksize);
      if (read_chunk_text(ft, chunksize, buf) != SOX_SUCCESS)
        return SOX_EOF;
    } else if (strncmp(buf, "COMT", 4) == 0) {
      unsigned short nComments, i;
      lsx_readdw(ft, &chunksize);
      lsx_readw(ft, &nComments);
      for (i = 0; i < nComments; i++) {
        uint32_t timeStamp;
        unsigned short markerId, totalCommentLength;
        char *text;
        lsx_readdw(ft, &timeStamp);
        lsx_readw(ft, &markerId);
        lsx_readw(ft, &totalCommentLength);
        text = lsx_calloc(1, (size_t)totalCommentLength + 2);
        if (lsx_readbuf(ft, text, totalCommentLength) != totalCommentLength) {
          lsx_fail_errno(ft, SOX_EOF, "AIFF: Unexpected EOF in COMT chunk");
          free(text);
          return SOX_EOF;
        }
        if (totalCommentLength & 1) {
          char c; lsx_readbuf(ft, &c, 1);
        }
        sox_append_comments(&ft->comments, text);
        free(text);
      }
    } else if (strncmp(buf, "FVER", 4) == 0) {
      lsx_readdw(ft, &chunksize);
      lsx_seeki(ft, (int64_t)(chunksize + (chunksize & 1)), SEEK_CUR);
    } else {
      if (lsx_eof(ft))
        break;
      buf[4] = 0;
      lsx_debug("AIFFstartread: ignoring `%s' chunk", buf);
      lsx_readdw(ft, &chunksize);
      if (lsx_eof(ft))
        break;
      /* Skip the chunk using lsx_readb() so we may read from a pipe */
      while (chunksize-- > 0) {
        unsigned char c;
        if (lsx_readb(ft, &c) == SOX_EOF)
          break;
      }
    }
    if (lsx_eof(ft))
      break;
  }
  (void)foundmark; (void)foundinstr; (void)totalsize;

  if (!foundcomm) {
    lsx_fail_errno(ft, SOX_EHDR, "Missing COMM chunk in AIFF file");
    return SOX_EOF;
  }
  /* SSND chunk just read */
  if (blocksize != 0)
    lsx_warn("AIFF header has invalid blocksize.  Ignoring but expect a premature EOF");

  if (ft->seekable) {
    if (seekto > 0)
      lsx_seeki(ft, (int64_t)seekto, SEEK_SET);
    else {
      lsx_fail_errno(ft, SOX_EOF, "AIFF: no sound data on input file");
      return SOX_EOF;
    }
  }
  while (offset-- > 0) {
    unsigned char c;
    if (lsx_readb(ft, &c) == SOX_EOF) {
      lsx_fail_errno(ft, errno, "unexpected EOF while skipping AIFF offset");
      return SOX_EOF;
    }
  }

  if (is_sowt) ft->encoding.reverse_bytes = !ft->encoding.reverse_bytes;

  if (enc == SOX_ENCODING_SIGN2 && bits <= 8) bits = 8;
  else if (enc == SOX_ENCODING_SIGN2 && bits <= 16) bits = 16;
  else if (enc == SOX_ENCODING_SIGN2 && bits <= 24) bits = 24;
  else if (enc == SOX_ENCODING_SIGN2 && bits <= 32) bits = 32;
  else if (enc == SOX_ENCODING_SIGN2) {
    lsx_fail_errno(ft, SOX_EFMT, "unsupported sample size in AIFF header: %d", bits);
    return SOX_EOF;
  }

  aiff->nsamples = ssndsize / (bits >> 3);
  if (ft->signal.length != SOX_IGNORE_LENGTH && frames && (uint64_t)frames * channels < aiff->nsamples)
    aiff->nsamples = (uint64_t)frames * channels;
  ft->signal.length = 0;
  {
    int r = lsx_check_read_params(ft, channels, rate, enc, bits, aiff->nsamples, sox_false);
    return r;
  }
}

static int aiffstartread(sox_format_t *ft)
{
  return lsx_aiffstartread(ft);
}

static int textChunk(sox_format_t *ft, char const *chunkname, char const *text);

static int aiffwriteheader(sox_format_t *ft, uint64_t nframes, int is_aifc)
{
  int hsize = 8 /*COMM hdr*/ + 18 /*COMM chunk*/ + 8 /*SSND hdr*/ + 12 /*SSND chunk*/;
  unsigned bits = 0;
  size_t i;
  uint64_t size;
  size_t padded_comment_size = 0;
  size_t comment_size = 0;
  char *comment = NULL;
  uint32_t comment_ts = 0;

  if (ft->encoding.encoding == SOX_ENCODING_SIGN2 && ft->encoding.bits_per_sample == 8) bits = 8;
  else if (ft->encoding.encoding == SOX_ENCODING_SIGN2 && ft->encoding.bits_per_sample == 16) bits = 16;
  else if (ft->encoding.encoding == SOX_ENCODING_SIGN2 && ft->encoding.bits_per_sample == 24) bits = 24;
  else if (ft->encoding.encoding == SOX_ENCODING_SIGN2 && ft->encoding.bits_per_sample == 32) bits = 32;
  else if (is_aifc && ft->encoding.encoding == SOX_ENCODING_FLOAT && (ft->encoding.bits_per_sample == 32 || ft->encoding.bits_per_sample == 64))
    bits = ft->encoding.bits_per_sample;
  else {
    lsx_fail_errno(ft, SOX_EFMT, "unsupported output encoding/size for AIFF header");
    return SOX_EOF;
  }

  if (!is_aifc && ft->comments.n) {
    /* Join comments */
    size_t len = 0;
    for (i = 0; i < ft->comments.n; ++i) len += strlen(ft->comments.list[i]) + 1;
    comment = lsx_calloc(1, len + 2);
    for (i = 0; i < ft->comments.n; ++i) {
      if (i) strcat(comment, "\n");
      strcat(comment, ft->comments.list[i]);
    }
    comment_size = strlen(comment);
    padded_comment_size = (comment_size % 2 == 0) ? comment_size : comment_size + 1;
    hsize += 8 /* COMT hdr */ + 2 /* num. comments */ + 4 /* timestamp */ + 2 /* markerID */ + 2 /* size */ + padded_comment_size;
    comment_ts = sox_globals.repeatable ? 0 : (uint32_t)time(NULL);
    comment_ts += 2082844800u;
  }
  if (is_aifc)
    hsize += 12 /* FVER */ + 4 + 16; /* compressionType + name pstring "not compressed" padded */

  lsx_writes(ft, "FORM");
  size = (uint64_t)hsize + nframes * (ft->encoding.bits_per_sample >> 3) * ft->signal.channels;
  if (size > UINT32_MAX) size = UINT32_MAX;
  lsx_writedw(ft, (unsigned)(size + ((size) & 1 ? 0 : 0)));
  lsx_writes(ft, is_aifc ? "AIFC" : "AIFF");

  if (is_aifc) {
    lsx_writes(ft, "FVER");
    lsx_writedw(ft, 4);
    lsx_writedw(ft, 0xa2805140u);
  }

  if (!is_aifc && comment) {
    lsx_writes(ft, "COMT");
    lsx_writedw(ft, (unsigned)(2 + 4 + 2 + 2 + padded_comment_size));
    lsx_writew(ft, 1);
    lsx_writedw(ft, comment_ts);
    lsx_writew(ft, 0);
    lsx_writew(ft, (unsigned)padded_comment_size);
    lsx_writebuf(ft, comment, comment_size);
    if (comment_size != padded_comment_size)
      lsx_writes(ft, " ");
  }
  free(comment);

  lsx_writes(ft, "COMM");
  lsx_writedw(ft, is_aifc ? 18 + 4 + 16 : 18);
  lsx_writew(ft, ft->signal.channels);
  lsx_writedw(ft, (unsigned)nframes);
  lsx_writew(ft, bits);
  write_ieee_extended(ft, (double)ft->signal.rate);
  if (is_aifc) {
    lsx_writes(ft, ft->encoding.encoding == SOX_ENCODING_FLOAT ? (bits == 32 ? "fl32" : "fl64") : "NONE");
    lsx_writeb(ft, 14);
    lsx_writes(ft, "not compressed");
    lsx_writeb(ft, 0);
  }

  lsx_writes(ft, "SSND");
  lsx_writedw(ft, (unsigned)(8 + nframes * ft->signal.channels * (ft->encoding.bits_per_sample >> 3)));
  lsx_writedw(ft, 0);
  lsx_writedw(ft, 0);
  (void)textChunk;
  return SOX_SUCCESS;
}

static int textChunk(sox_format_t *ft, char const *chunkname, char const *text)
{
  (void)ft; (void)chunkname; (void)text;
  return SOX_SUCCESS;
}

static int aiff_startwrite_common(sox_format_t *ft, int is_aifc)
{
  priv_t *aiff = (priv_t *)ft->priv;
  aiff->nsamples = 0;
  /* Compute the "very large number" so that a maximum number
   * of samples can be transmitted through a pipe without the
   * risk of causing overflow when calculating the number of bytes.
   * At 48 kHz, 16 bits stereo, this gives ~3 hours of audio.
   * Sorry, the AIFF format does not provide for an indefinite
   * number of samples. */
  return aiffwriteheader(ft, (uint64_t)0x7f000000 / ((ft->encoding.bits_per_sample >> 3) * ft->signal.channels), is_aifc);
}

static int aiffstartwrite(sox_format_t *ft) { return aiff_startwrite_common(ft, 0); }
static int aifcstartwrite(sox_format_t *ft) { return aiff_startwrite_common(ft, 1); }

static size_t aiffwrite(sox_format_t *ft, const sox_sample_t *buf, size_t len)
{
  priv_t *aiff = (priv_t *)ft->priv;
  aiff->nsamples += len;
  lsx_rawwrite(ft, buf, len);
  return len;
}

static int stopwrite_common(sox_format_t *ft, int is_aifc)
{
  priv_t *aiff = (priv_t *)ft->priv;

  /* If we've written an odd number of bytes, write a padding
     NUL */
  if (aiff->nsamples % 2 == 1 && ft->encoding.bits_per_sample == 8 && ft->signal.channels == 1) {
    sox_sample_t buf = 0;
    lsx_rawwrite(ft, &buf, (size_t)1);
  }

  if (!ft->seekable) {
    lsx_fail_errno(ft, SOX_EOF, "Non-seekable file.");
    return SOX_EOF;
  }
  if (lsx_seeki(ft, (int64_t)0, SEEK_SET) != 0) {
    lsx_fail_errno(ft, errno, "can't rewind output file to rewrite AIFF header");
    return SOX_EOF;
  }
  return aiffwriteheader(ft, aiff->nsamples / ft->signal.channels, is_aifc);
}

static int aiffstopwrite(sox_format_t *ft) { return stopwrite_common(ft, 0); }
static int aifcstopwrite(sox_format_t *ft) { return stopwrite_common(ft, 1); }

const sox_format_handler_t *lsx_aiff_format_fn(void)
{
  static char const *const names[] = {"aiff", "aif", NULL};
  static unsigned const write_encodings[] = {
    SOX_ENCODING_SIGN2, 32, 24, 16, 8, 0, 0};
  static sox_format_handler_t const sox_aiff_format = {
    "AIFF files used on Apple IIc/IIgs and SGI", names, SOX_FILE_LOOP | SOX_FILE_BIG_END,
    aiffstartread, lsx_rawread, NULL,
    aiffstartwrite, aiffwrite, aiffstopwrite,
    lsx_rawseek, write_encodings, NULL, sizeof(priv_t)
  };
  return &sox_aiff_format;
}

const sox_format_handler_t *lsx_aifc_format_fn(void)
{
  static char const *const names[] = {"aifc", "aiffc", NULL};
  static unsigned const write_encodings[] = {
    SOX_ENCODING_SIGN2, 32, 24, 16, 8, 0,
    SOX_ENCODING_FLOAT, 32, 64, 0,
    0};
  static sox_format_handler_t const sox_aifc_format = {
    "AIFF-C (not compressed), defined in DAVIC 1.4 Part 9 Annex B", names, SOX_FILE_LOOP | SOX_FILE_BIG_END,
    aiffstartread, lsx_rawread, NULL,
    aifcstartwrite, aiffwrite, aifcstopwrite,
    lsx_rawseek, write_encodings, NULL, sizeof(priv_t)
  };
  return &sox_aifc_format;
}
