static int norm_getopts(sox_effect_t *effp, int argc, char **argv)
{
  char *argv2[3];
  int argc2 = 2;

  argv2[0] = argv[0], --argc, ++argv;
  argv2[1] = "-n";
  if (argc)
    argv2[argc2++] = *argv, --argc, ++argv;
  return argc ? lsx_usage(effp) : create(effp, argc2, argv2);
}

const sox_effect_handler_t *lsx_norm_effect_fn(void)
{
  static sox_effect_handler_t handler;
  handler = *lsx_gain_effect_fn();
  handler.name = "norm";
  handler.usage = USAGE_norm;
  handler.getopts = norm_getopts;
  return &handler;
}
