    if (sscanf(argv[1], "%d %c", (int *)&p->num_out_channels, &dummy) != 1 || (int)p->num_out_channels <= 0)
      return lsx_usage(effp);
    effp->out_signal.channels = p->num_out_channels;
  } else if (argc != 1)
    return lsx_usage(effp);
  return SOX_SUCCESS;
}

static int channels_start(sox_effect_t *effp)
{
  priv_t *p = (priv_t *)effp->priv;
  unsigned num_out_channels = p->num_out_channels != 0 ? p->num_out_channels : effp->out_signal.channels;
  unsigned i, j;

  p->out_specs = lsx_calloc(num_out_channels, sizeof(*p->out_specs));
  if (effp->in_signal.channels == num_out_channels)
    return SOX_EFF_NULL;

  if (effp->in_signal.channels > num_out_channels) {
    for (j = 0; j < num_out_channels; j++) {
      unsigned in_per_out = (effp->in_signal.channels + num_out_channels - 1 - j) / num_out_channels;
      p->out_specs[j].in_specs = lsx_malloc(in_per_out * sizeof(*p->out_specs[j].in_specs));
      p->out_specs[j].num_in_channels = in_per_out;
      for (i = 0; i < in_per_out; ++i) {
        p->out_specs[j].in_specs[i].channel_num = i * num_out_channels + j;
        p->out_specs[j].in_specs[i].multiplier = 1. / in_per_out;
      }
    }
  } else for (j = 0; j < num_out_channels; j++) {
    p->out_specs[j].in_specs = lsx_malloc(sizeof(*p->out_specs[j].in_specs));
    p->out_specs[j].num_in_channels = 1;
    p->out_specs[j].in_specs[0].channel_num = j % effp->in_signal.channels;
    p->out_specs[j].in_specs[0].multiplier = 1;
  }
  effp->out_signal.channels = p->num_out_channels = num_out_channels;
  {
    int non_integer = 0;
    for (j = 0; j < num_out_channels; j++)
      for (i = 0; i < p->out_specs[j].num_in_channels; i++) {
        double mult = p->out_specs[j].in_specs[i].multiplier;
        non_integer += floor(mult) != mult;
      }
    effp->out_signal.precision = non_integer ? SOX_SAMPLE_PRECISION : effp->in_signal.precision;
  }
  return SOX_SUCCESS;
}

static int channels_closedown(sox_effect_t *effp)
{
  priv_t *p = (priv_t *)effp->priv;
  unsigned i;
  if (p->out_specs) {
    for (i = 0; i < p->num_out_channels; ++i)
      free(p->out_specs[i].in_specs);
    free(p->out_specs);
  }
  p->out_specs = NULL;
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_channels_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "channels", USAGE_channels, SOX_EFF_MCHAN | SOX_EFF_CHAN | SOX_EFF_PREC,
    channels_create, channels_start, flow, NULL, NULL, channels_closedown, sizeof(priv_t)
  };
  return &handler;
}

