static int flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  size_t len, done;
  unsigned c = effp->in_signal.channels;

  *osamp = *isamp = len = min(*isamp, *osamp) / c * c;
  for (done = 0; done < len; done += c, ibuf += c, obuf += c) {
    unsigned i;
    for (i = 0; i + 1 < c; i += 2) {
      obuf[i] = ibuf[i + 1];
      obuf[i + 1] = ibuf[i];
    }
    if (c & 1) obuf[c - 1] = ibuf[c - 1];
  }
  return SOX_SUCCESS;
}

