/* trim, pad, reverse, repeat, fade, dcshift effects */
#include "sox.h"
#include "usage_strings.h"

FILE *lsx_tmpfile(void);

/* ===================== trim ===================== */
typedef struct {
  unsigned int num_pos;
  struct {
    uint64_t sample;
    char *argstr;
  } *pos;
  uint64_t samples_read;
  unsigned int current_pos;
  sox_bool copying;
} trim_priv_t;

static int trim_parse(sox_effect_t *effp, int argc, char **argv)
{
  trim_priv_t *p = (trim_priv_t *)effp->priv;
  unsigned int i;
  --argc, ++argv;
  p->num_pos = argc;
  p->pos = lsx_calloc(p->num_pos + 1, sizeof(*p->pos));
  for (i = 0; i < p->num_pos; i++) {
    const char *arg = argv[i];
    p->pos[i].argstr = lsx_strdup(arg);
    arg = lsx_parseposition(0., arg, NULL, (uint64_t)0, (uint64_t)0, '+');
    if (!arg || *arg) {
      lsx_fail("Error parsing position %u", i + 1);
      return lsx_usage(effp);
    }
  }
  return SOX_SUCCESS;
}

static int trim_start(sox_effect_t *effp)
{
  trim_priv_t *p = (trim_priv_t *)effp->priv;
  uint64_t in_length = effp->in_signal.length != SOX_UNKNOWN_LEN ?
    effp->in_signal.length / effp->in_signal.channels : SOX_UNKNOWN_LEN;
  uint64_t last_seen = 0;
  sox_bool open_end;
  unsigned int i;

  p->copying = sox_false;

  for (i = 0; i < p->num_pos; i++) {
    if (!lsx_parseposition(effp->in_signal.rate, p->pos[i].argstr, &p->pos[i].sample, last_seen, in_length, '+')) {
      lsx_fail("Position %u is relative to end of audio, but audio length is unknown", i + 1);
      return SOX_EOF;
    }
    last_seen = p->pos[i].sample;
    lsx_debug_more("position %u at %llu", i + 1, (unsigned long long)last_seen);
  }

  last_seen = 0;
  for (i = 0; i < p->num_pos; i++) {
    if (p->pos[i].sample < last_seen) {
      lsx_fail("Position %u is behind the following position.", i);
      return SOX_EOF;
    }
    last_seen = p->pos[i].sample;
  }
  if (p->num_pos && in_length != SOX_UNKNOWN_LEN)
    if (p->pos[0].sample > in_length || p->pos[p->num_pos - 1].sample > in_length)
      lsx_warn("%s position is after expected end of audio.",
          p->pos[0].sample > in_length ? "Start" : "End");

  if (in_length == SOX_UNKNOWN_LEN)
    while (p->num_pos && p->pos[p->num_pos - 1].sample == SOX_UNKNOWN_LEN) {
      lsx_debug_more("removing `-0' position");
      p->num_pos--;
      free(p->pos[p->num_pos].argstr);
      p->pos[p->num_pos].argstr = NULL;
    }
  if (p->num_pos == 1 && !p->pos[0].sample)
    return SOX_EFF_NULL;

  open_end = p->num_pos % 2;
  if (open_end && in_length == SOX_UNKNOWN_LEN)
    effp->out_signal.length = SOX_UNKNOWN_LEN;
  else {
    effp->out_signal.length = 0;
    for (i = 0; i + 1 < p->num_pos; i += 2)
      effp->out_signal.length += min(p->pos[i + 1].sample, in_length) - min(p->pos[i].sample, in_length);
    if (open_end)
      effp->out_signal.length += in_length - min(p->pos[p->num_pos - 1].sample, in_length);
    effp->out_signal.length *= effp->in_signal.channels;
  }
  return SOX_SUCCESS;
}

static int trim_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  trim_priv_t *p = (trim_priv_t *)effp->priv;
  size_t len = min(*isamp, *osamp);
  size_t channels = effp->in_signal.channels;
  len /= channels;
  *isamp = *osamp = 0;

  while (len) {
    size_t chunk;

    if (p->current_pos < p->num_pos && p->samples_read == p->pos[p->current_pos].sample) {
      p->copying = !p->copying;
      p->current_pos++;
    }

    if (p->current_pos >= p->num_pos && !p->copying)
      return SOX_EOF;

    chunk = p->current_pos < p->num_pos ?
      min(len, p->pos[p->current_pos].sample - p->samples_read) : len;
    if (p->copying) {
      memcpy(obuf, ibuf, chunk * channels * sizeof(*obuf));
      obuf += chunk * channels, *osamp += chunk * channels;
    }
    ibuf += chunk * channels; *isamp += chunk * channels;
    p->samples_read += chunk, len -= chunk;
  }
  return SOX_SUCCESS;
}

static int trim_drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{
  trim_priv_t *p = (trim_priv_t *)effp->priv;
  (void)obuf;
  *osamp = 0;
  if (p->current_pos + 1 == p->num_pos && p->pos[p->current_pos].sample == p->samples_read && p->copying)
    p->current_pos++;
  if (p->current_pos < p->num_pos)
    lsx_warn("Last %u position(s) not reached%s.", p->num_pos - p->current_pos,
        (effp->in_signal.length == SOX_UNKNOWN_LEN ||
         effp->in_signal.length / effp->in_signal.channels == p->samples_read) ?
        "" : " (audio shorter than expected)");
  return SOX_EOF;
}

static int trim_kill(sox_effect_t *effp)
{
  trim_priv_t *p = (trim_priv_t *)effp->priv;
  unsigned int i;
  for (i = 0; i < p->num_pos; i++)
    free(p->pos[i].argstr);
  free(p->pos);
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_trim_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "trim", USAGE_trim, SOX_EFF_MCHAN | SOX_EFF_LENGTH | SOX_EFF_MODIFY,
    trim_parse, trim_start, trim_flow, trim_drain, NULL, trim_kill, sizeof(trim_priv_t)
  };
  return &handler;
}

/* ===================== pad ===================== */
typedef struct {
  unsigned npads;
  struct {
    char *str;
    uint64_t start;
    uint64_t pad;
  } *pads;
  uint64_t in_pos;
  unsigned pads_pos;
  uint64_t pad_pos;
} pad_priv_t;

static int pad_parse(sox_effect_t *effp, char **argv, sox_rate_t rate)
{
  pad_priv_t *p = (pad_priv_t *)effp->priv;
  char const *next;
  unsigned i;
  uint64_t last_seen = 0;
  const uint64_t in_length = argv ? 0 :
    (effp->in_signal.length != SOX_UNKNOWN_LEN ? effp->in_signal.length / effp->in_signal.channels : SOX_UNKNOWN_LEN);

  for (i = 0; i < p->npads; ++i) {
    if (argv)
      p->pads[i].str = lsx_strdup(argv[i]);
    next = lsx_parsesamples(rate, p->pads[i].str, &p->pads[i].pad, 't');
    if (next == NULL) break;
    if (*next == '\0')
      p->pads[i].start = i ? UINT64_MAX : 0;
    else {
      if (*next != '@') break;
      next = lsx_parseposition(rate, next + 1, argv ? NULL : &p->pads[i].start, last_seen, in_length, '=');
      if (next == NULL || *next) break;
      if (!argv) last_seen = p->pads[i].start;
      if (!argv && p->pads[i].start == SOX_UNKNOWN_LEN)
        p->pads[i].start = UINT64_MAX;
    }
    if (!argv) {
      if (i > 0 && p->pads[i].start <= p->pads[i - 1].start) break;
    }
  }
  if (i < p->npads)
    return lsx_usage(effp);
  return SOX_SUCCESS;
}

static int pad_create(sox_effect_t *effp, int argc, char **argv)
{
  pad_priv_t *p = (pad_priv_t *)effp->priv;
  --argc, ++argv;
  p->npads = argc;
  p->pads = lsx_calloc(p->npads + 1, sizeof(*p->pads));
  return pad_parse(effp, argv, 1e5);
}

static int pad_start(sox_effect_t *effp)
{
  pad_priv_t *p = (pad_priv_t *)effp->priv;
  unsigned i;

  if (pad_parse(effp, 0, effp->in_signal.rate) != SOX_SUCCESS)
    return SOX_EOF;

  if ((effp->out_signal.length = effp->in_signal.length) != SOX_UNKNOWN_LEN) {
    for (i = 0; i < p->npads; ++i)
      effp->out_signal.length += p->pads[i].pad * effp->in_signal.channels;
    i = p->npads;
    if (i > 0 && p->pads[i - 1].start == UINT64_MAX)
      i--;
    if (i > 0 && p->pads[i - 1].start * effp->in_signal.channels > effp->in_signal.length) {
      lsx_fail("pad position after end of audio");
      return SOX_EOF;
    }
  }

  p->in_pos = p->pad_pos = p->pads_pos = 0;
  for (i = 0; i < p->npads; ++i)
    if (p->pads[i].pad)
      return SOX_SUCCESS;
  return SOX_EFF_NULL;
}

static int pad_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  pad_priv_t *p = (pad_priv_t *)effp->priv;
  size_t c, idone = 0, odone = 0;
  *isamp /= effp->in_signal.channels;
  *osamp /= effp->in_signal.channels;

  do {
    for (; idone < *isamp && odone < *osamp && !(p->pads_pos != p->npads && p->in_pos == p->pads[p->pads_pos].start); ++idone, ++odone, ++p->in_pos)
      for (c = 0; c < effp->in_signal.channels; ++c) *obuf++ = *ibuf++;

    if (p->pads_pos != p->npads && p->in_pos == p->pads[p->pads_pos].start) {
      for (; odone < *osamp && p->pad_pos < p->pads[p->pads_pos].pad; ++odone, ++p->pad_pos)
        for (c = 0; c < effp->in_signal.channels; ++c) *obuf++ = 0;
      if (p->pad_pos == p->pads[p->pads_pos].pad) {
        ++p->pads_pos;
        p->pad_pos = 0;
      }
    }
  } while (idone < *isamp && odone < *osamp);

  *isamp = idone * effp->in_signal.channels;
  *osamp = odone * effp->in_signal.channels;
  return SOX_SUCCESS;
}

static int pad_drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{
  pad_priv_t *p = (pad_priv_t *)effp->priv;
  size_t isamp = 0;
  if (p->pads_pos != p->npads && p->in_pos != p->pads[p->pads_pos].start)
    p->in_pos = UINT64_MAX;
  return pad_flow(effp, 0, obuf, &isamp, osamp);
}

static int pad_stop(sox_effect_t *effp)
{
  pad_priv_t *p = (pad_priv_t *)effp->priv;
  if (p->pads_pos != p->npads)
    lsx_warn("Input audio too short; pads not applied: %u", p->npads - p->pads_pos);
  return SOX_SUCCESS;
}

static int pad_kill(sox_effect_t *effp)
{
  pad_priv_t *p = (pad_priv_t *)effp->priv;
  unsigned i;
  for (i = 0; i < p->npads; ++i)
    free(p->pads[i].str);
  free(p->pads);
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_pad_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "pad", USAGE_pad, SOX_EFF_MCHAN | SOX_EFF_LENGTH | SOX_EFF_MODIFY,
    pad_create, pad_start, pad_flow, pad_drain, pad_stop, pad_kill, sizeof(pad_priv_t)
  };
  return &handler;
}

/* ===================== reverse ===================== */
typedef struct {
  off_t pos;
  FILE *tmp_file;
} reverse_priv_t;

static int reverse_start(sox_effect_t *effp)
{
  reverse_priv_t *p = (reverse_priv_t *)effp->priv;
  p->pos = 0;
  p->tmp_file = lsx_tmpfile();
  if (p->tmp_file == NULL) {
    lsx_fail("can't create temporary file: %s", strerror(errno));
    return SOX_EOF;
  }
  return SOX_SUCCESS;
}

static int reverse_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  reverse_priv_t *p = (reverse_priv_t *)effp->priv;
  (void)obuf;
  if (fwrite(ibuf, sizeof(*ibuf), *isamp, p->tmp_file) != *isamp) {
    lsx_fail("error writing temporary file: %s", strerror(errno));
    return SOX_EOF;
  }
  *osamp = 0;
  return SOX_SUCCESS;
}

static int reverse_drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{
  reverse_priv_t *p = (reverse_priv_t *)effp->priv;
  size_t i, j;

  if (p->pos == 0) {
    fflush(p->tmp_file);
    p->pos = ftello(p->tmp_file);
    if (p->pos % sizeof(sox_sample_t) != 0) {
      lsx_fail("temporary file has incorrect size");
      return SOX_EOF;
    }
    p->pos /= sizeof(sox_sample_t);
  }
  p->pos -= *osamp = min((off_t)*osamp, p->pos);
  fseeko(p->tmp_file, (off_t)(p->pos * sizeof(sox_sample_t)), SEEK_SET);
  if (fread(obuf, sizeof(sox_sample_t), *osamp, p->tmp_file) != *osamp) {
    lsx_fail("error reading temporary file: %s", strerror(errno));
    return SOX_EOF;
  }
  if (*osamp)
    for (i = 0, j = *osamp - 1; i < j; ++i, --j) {
      sox_sample_t temp = obuf[i];
      obuf[i] = obuf[j];
      obuf[j] = temp;
    }
  return p->pos ? SOX_SUCCESS : SOX_EOF;
}

static int reverse_stop(sox_effect_t *effp)
{
  reverse_priv_t *p = (reverse_priv_t *)effp->priv;
  if (p->tmp_file) fclose(p->tmp_file);
  p->tmp_file = NULL;
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_reverse_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "reverse", NULL, SOX_EFF_MODIFY,
    NULL, reverse_start, reverse_flow, reverse_drain, reverse_stop, NULL, sizeof(reverse_priv_t)
  };
  return &handler;
}

/* ===================== repeat ===================== */
typedef struct {
  unsigned num_repeats, remaining_repeats;
  uint64_t num_samples, remaining_samples;
  FILE *tmp_file;
} repeat_priv_t;

static int repeat_create(sox_effect_t *effp, int argc, char **argv)
{
  repeat_priv_t *p = (repeat_priv_t *)effp->priv;
  p->num_repeats = 1;
  --argc, ++argv;
  if (argc == 1 && !strcmp(*argv, "-")) {
    p->num_repeats = UINT_MAX;
    ++argv, --argc;
  } else do { NUMERIC_PARAMETER(num_repeats, 0, UINT_MAX - 1) } while (0);
  return argc ? lsx_usage(effp) : SOX_SUCCESS;
}

static int repeat_start(sox_effect_t *effp)
{
  repeat_priv_t *p = (repeat_priv_t *)effp->priv;
  if (!p->num_repeats)
    return SOX_EFF_NULL;
  if (!(p->tmp_file = lsx_tmpfile())) {
    lsx_fail("can't create temporary file: %s", strerror(errno));
    return SOX_EOF;
  }
  p->num_samples = p->remaining_samples = 0;
  p->remaining_repeats = p->num_repeats;
  if (effp->in_signal.length != SOX_UNKNOWN_LEN && p->num_repeats != UINT_MAX)
    effp->out_signal.length = effp->in_signal.length * (p->num_repeats + 1);
  else
    effp->out_signal.length = SOX_UNKNOWN_LEN;
  return SOX_SUCCESS;
}

static int repeat_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  repeat_priv_t *p = (repeat_priv_t *)effp->priv;
  size_t len = min(*isamp, *osamp);
  memcpy(obuf, ibuf, len * sizeof(*obuf));
  if (fwrite(ibuf, sizeof(*ibuf), len, p->tmp_file) != len) {
    lsx_fail("error writing temporary file: %s", strerror(errno));
    return SOX_EOF;
  }
  p->num_samples += len;
  *isamp = *osamp = len;
  return SOX_SUCCESS;
}

static int repeat_drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{
  repeat_priv_t *p = (repeat_priv_t *)effp->priv;
  size_t odone = 0, n;

  *osamp -= *osamp % effp->in_signal.channels;

  while ((p->remaining_samples || p->remaining_repeats) && odone < *osamp) {
    if (!p->remaining_samples) {
      p->remaining_samples = p->num_samples;
      --p->remaining_repeats;
      rewind(p->tmp_file);
    }
    n = min(p->remaining_samples, *osamp - odone);
    if ((fread(obuf + odone, sizeof(*obuf), n, p->tmp_file)) != n) {
      lsx_fail("error reading temporary file: %s", strerror(errno));
      return SOX_EOF;
    }
    p->remaining_samples -= n;
    odone += n;
  }
  *osamp = odone;
  return p->remaining_samples || p->remaining_repeats ? SOX_SUCCESS : SOX_EOF;
}

static int repeat_stop(sox_effect_t *effp)
{
  repeat_priv_t *p = (repeat_priv_t *)effp->priv;
  if (p->tmp_file) fclose(p->tmp_file);
  p->tmp_file = NULL;
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_repeat_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "repeat", USAGE_repeat, SOX_EFF_MCHAN | SOX_EFF_LENGTH | SOX_EFF_MODIFY,
    repeat_create, repeat_start, repeat_flow, repeat_drain, repeat_stop, NULL, sizeof(repeat_priv_t)
  };
  return &handler;
}

/* ===================== fade ===================== */
typedef struct {
  uint64_t in_start, in_stop, out_start, out_stop, samplesdone;
  char *in_stop_str, *out_start_str, *out_stop_str;
  char in_fadetype, out_fadetype;
  char do_out;
  int endpadwarned;
} fade_priv_t;

#define FADE_QUARTER 'q'
#define FADE_HALF 'h'
#define FADE_LOG 'l'
#define FADE_TRI 't'
#define FADE_PAR 'p'

static double fade_gain(uint64_t index, uint64_t range, int type)
{
  double retval = 0.0, findex = 0.0;
  findex = max(0.0, min(1.0, 1.0 * index / range));
  switch (type) {
    case FADE_TRI: retval = findex; break;
    case FADE_QUARTER: retval = sin(findex * M_PI / 2); break;
    case FADE_HALF: retval = (1 - cos(findex * M_PI)) / 2; break;
    case FADE_LOG: retval = pow(0.1, (1 - findex) * 5); break;
    case FADE_PAR: retval = (1 - (1 - findex) * (1 - findex)); break;
    default: retval = -1.0; break;
  }
  return retval;
}

static int fade_getopts(sox_effect_t *effp, int argc, char **argv)
{
  fade_priv_t *fade = (fade_priv_t *)effp->priv;
  char t_char[2];
  int t_argno;
  uint64_t samples;
  const char *n;
  --argc, ++argv;

  if (argc < 1 || argc > 4)
    return lsx_usage(effp);

  if (sscanf(argv[0], "%1[qhltp]", t_char)) {
    fade->in_fadetype = *t_char;
    fade->out_fadetype = *t_char;
    argv++;
    argc--;
  } else {
    fade->in_fadetype = 'l';
    fade->out_fadetype = 'l';
  }
  if (argc < 1)
    return lsx_usage(effp);

  fade->in_stop_str = lsx_strdup(argv[0]);
  n = lsx_parsesamples(0., fade->in_stop_str, &samples, 't');
  if (!n || *n)
    return lsx_usage(effp);

  fade->in_stop = samples;
  fade->out_start_str = fade->out_stop_str = 0;

  for (t_argno = 1; t_argno < argc && t_argno < 3; t_argno++) {
    if (t_argno == 1) {
      fade->out_stop_str = lsx_strdup(argv[t_argno]);
      n = lsx_parseposition(0., fade->out_stop_str, NULL, (uint64_t)0, (uint64_t)0, '=');
      if (!n || *n)
        return lsx_usage(effp);
      fade->out_stop = samples;
    } else {
      fade->out_start_str = lsx_strdup(argv[t_argno]);
      n = lsx_parsesamples(0., fade->out_start_str, &samples, 't');
      if (!n || *n)
        return lsx_usage(effp);
      fade->out_start = samples;
    }
  }
  return SOX_SUCCESS;
}

static int fade_start(sox_effect_t *effp)
{
  fade_priv_t *fade = (fade_priv_t *)effp->priv;
  sox_bool truncate = sox_false;
  uint64_t samples;
  uint64_t in_length = effp->in_signal.length != SOX_UNKNOWN_LEN ?
    effp->in_signal.length / effp->in_signal.channels : SOX_UNKNOWN_LEN;

  fade->in_start = 0;
  if (lsx_parsesamples(effp->in_signal.rate, fade->in_stop_str, &samples, 't') == NULL)
    return lsx_usage(effp);

  fade->in_stop = samples;
  fade->do_out = 0;
  if (fade->out_stop_str) {
    fade->do_out = 1;
    if (!lsx_parseposition(effp->in_signal.rate, fade->out_stop_str, &samples, (uint64_t)0, in_length, '=') ||
        samples == SOX_UNKNOWN_LEN) {
      lsx_fail("audio length is unknown");
      return SOX_EOF;
    }
    fade->out_stop = samples;

    if (!(truncate = !!fade->out_stop)) {
      fade->out_stop = effp->in_signal.length != SOX_UNKNOWN_LEN ?
        effp->in_signal.length / effp->in_signal.channels : 0;
      if (!fade->out_stop) {
        lsx_fail("cannot fade out: audio length is neither known nor given");
        return SOX_EOF;
      }
    }

    if (fade->out_start_str) {
      if (lsx_parsesamples(effp->in_signal.rate, fade->out_start_str, &samples, 't') == NULL)
        return lsx_usage(effp);
      fade->out_start = fade->out_stop - samples;
    } else
      fade->out_start = fade->out_stop - fade->in_stop;
  } else
    fade->out_stop = 0;

  if (fade->out_start) {
    if (fade->in_stop > fade->out_start)
      --fade->in_stop;
    if (fade->in_stop > fade->out_start) {
      lsx_fail("fade-out overlaps fade-in");
      return SOX_EOF;
    }
  }

  fade->samplesdone = fade->in_start;
  fade->endpadwarned = 0;

  lsx_debug("in_start = %llu in_stop = %llu out_start = %llu out_stop = %llu",
      (unsigned long long)fade->in_start, (unsigned long long)fade->in_stop,
      (unsigned long long)fade->out_start, (unsigned long long)fade->out_stop);

  if (fade->in_start == fade->in_stop && !truncate && fade->out_start == fade->out_stop)
    return SOX_EFF_NULL;

  effp->out_signal.length = truncate ? fade->out_stop * effp->in_signal.channels : effp->in_signal.length;
  return SOX_SUCCESS;
}

static int fade_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  fade_priv_t *fade = (fade_priv_t *)effp->priv;
  int len = 0, t_output = 1, more_output = 1;
  sox_sample_t t_ibuf;
  size_t chcnt = 0;

  len = ((*isamp > *osamp) ? *osamp : *isamp);
  *osamp = 0;
  *isamp = 0;

  for (; len && more_output; len--) {
    t_ibuf = *ibuf;

    if ((fade->samplesdone >= fade->in_start) && (!fade->do_out || fade->samplesdone < fade->out_stop)) {
      if (fade->samplesdone < fade->in_stop) {
        *obuf = t_ibuf * fade_gain(fade->samplesdone - fade->in_start, fade->in_stop - fade->in_start, fade->in_fadetype);
      } else if (!fade->do_out || fade->samplesdone < fade->out_start) {
        *obuf = t_ibuf;
      } else {
        *obuf = t_ibuf * fade_gain(fade->out_stop - fade->samplesdone, fade->out_stop - fade->out_start, fade->out_fadetype);
      }
      if (!(!fade->do_out || fade->samplesdone < fade->out_stop))
        more_output = 0;
      t_output = 1;
    } else {
      t_output = 0;
    }

    *isamp += 1;
    ibuf++;
    if (t_output) {
      obuf++;
      *osamp += 1;
    }

    if (++chcnt >= effp->in_signal.channels) {
      fade->samplesdone += 1;
      chcnt = 0;
    }
  }

  if (fade->do_out && fade->samplesdone >= fade->out_stop)
    return SOX_EOF;
  else
    return SOX_SUCCESS;
}

static int fade_drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{
  fade_priv_t *fade = (fade_priv_t *)effp->priv;
  int len;
  size_t t_chan = 0;

  len = *osamp;
  len -= len % effp->in_signal.channels;
  *osamp = 0;

  if (fade->do_out && fade->samplesdone < fade->out_stop && !(fade->endpadwarned)) {
    lsx_warn("Fade: warning: End time passed end-of-file. Padding with silence");
    fade->endpadwarned = 1;
  }

  for (; fade->do_out && fade->samplesdone < fade->out_stop && len; len--) {
    *obuf = 0;
    obuf++;
    *osamp += 1;
    t_chan++;
    if (t_chan >= effp->in_signal.channels) {
      fade->samplesdone += 1;
      t_chan = 0;
    }
  }

  if (fade->do_out && fade->samplesdone >= fade->out_stop)
    return SOX_EOF;
  else
    return SOX_SUCCESS;
}

static int fade_kill(sox_effect_t *effp)
{
  fade_priv_t *fade = (fade_priv_t *)effp->priv;
  free(fade->in_stop_str);
  free(fade->out_start_str);
  free(fade->out_stop_str);
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_fade_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "fade", USAGE_fade, SOX_EFF_MCHAN | SOX_EFF_LENGTH,
    fade_getopts, fade_start, fade_flow, fade_drain, NULL, fade_kill, sizeof(fade_priv_t)
  };
  return &handler;
}

/* ===================== dcshift ===================== */
typedef struct {
  double dcshift;
  int uselimiter;
  double limiterthreshhold;
  double limitergain;
  uint64_t limited;
  uint64_t totalprocessed;
} dcshift_priv_t;

static int dcshift_getopts(sox_effect_t *effp, int argc, char **argv)
{
  dcshift_priv_t *dcs = (dcshift_priv_t *)effp->priv;
  dcs->dcshift = 1.0;
  dcs->uselimiter = 0;

  --argc, ++argv;
  if (argc < 1)
    return lsx_usage(effp);

  if (argc && (!sscanf(argv[0], "%lf", &dcs->dcshift)))
    return lsx_usage(effp);

  if (argc > 1) {
    if (!sscanf(argv[1], "%lf", &dcs->limitergain))
      return lsx_usage(effp);
    dcs->uselimiter = 1;
    dcs->limiterthreshhold = SOX_SAMPLE_MAX * (1.0 - (fabs(dcs->dcshift) - dcs->limitergain));
  }
  return SOX_SUCCESS;
}

static int dcshift_start(sox_effect_t *effp)
{
  dcshift_priv_t *dcs = (dcshift_priv_t *)effp->priv;
  if (dcs->dcshift == 0)
    return SOX_EFF_NULL;
  dcs->limited = 0;
  dcs->totalprocessed = 0;
  return SOX_SUCCESS;
}

static int dcshift_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  dcshift_priv_t *dcs = (dcshift_priv_t *)effp->priv;
  double dcshift = dcs->dcshift;
  double limitergain = dcs->limitergain;
  double limiterthreshhold = dcs->limiterthreshhold;
  double sample;
  size_t len;

  len = min(*osamp, *isamp);
  *isamp = len; *osamp = len;

  if (dcs->uselimiter) {
    dcs->totalprocessed += len;
    for (; len > 0; len--) {
      sample = *ibuf++;
      if (sample > limiterthreshhold && dcshift > 0) {
        sample = (sample - limiterthreshhold) * limitergain / (SOX_SAMPLE_MAX - limiterthreshhold) + limiterthreshhold + dcshift;
        dcs->limited++;
      } else if (sample < -limiterthreshhold && dcshift < 0) {
        sample = (sample + limiterthreshhold) * limitergain / (SOX_SAMPLE_MAX - limiterthreshhold) - limiterthreshhold + dcshift;
        dcs->limited++;
      } else {
        sample = dcshift * SOX_SAMPLE_MAX + sample;
      }
      SOX_SAMPLE_CLIP_COUNT(sample, effp->clips);
      *obuf++ = sample;
    }
  } else for (; len > 0; --len) {
    double d = dcshift * (SOX_SAMPLE_MAX + 1.) + *ibuf++;
    *obuf++ = SOX_ROUND_CLIP_COUNT(d, effp->clips);
  }
  return SOX_SUCCESS;
}

static int dcshift_stop(sox_effect_t *effp)
{
  dcshift_priv_t *dcs = (dcshift_priv_t *)effp->priv;
  if (dcs->limited) {
    lsx_warn("DCSHIFT limited %llu values (%d percent).",
        (unsigned long long)dcs->limited, (int)(dcs->limited * 100.0 / dcs->totalprocessed));
  }
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_dcshift_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "dcshift", USAGE_dcshift, SOX_EFF_MCHAN,
    dcshift_getopts, dcshift_start, dcshift_flow, NULL, dcshift_stop, NULL, sizeof(dcshift_priv_t)
  };
  return &handler;
}
