/* ===================== reverse ===================== */
typedef struct {
  off_t pos;
  FILE *tmp_file;
} reverse_priv_t;

static int reverse_start(sox_effect_t *effp)
{
  reverse_priv_t *p = (reverse_priv_t *)effp->priv;
  p->pos = 0;
  p->tmp_file = lsx_tmpfile();
  if (p->tmp_file == NULL) {
    lsx_fail("can't create temporary file: %s", strerror(errno));
    return SOX_EOF;
  }
  return SOX_SUCCESS;
}

static int reverse_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  reverse_priv_t *p = (reverse_priv_t *)effp->priv;
  (void)obuf;
  if (fwrite(ibuf, sizeof(*ibuf), *isamp, p->tmp_file) != *isamp) {
    lsx_fail("error writing temporary file: %s", strerror(errno));
    return SOX_EOF;
  }
  *osamp = 0;
  return SOX_SUCCESS;
}

static int reverse_drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{
  reverse_priv_t *p = (reverse_priv_t *)effp->priv;
  size_t i, j;

  if (p->pos == 0) {
    fflush(p->tmp_file);
    p->pos = ftello(p->tmp_file);
    if (p->pos % sizeof(sox_sample_t) != 0) {
      lsx_fail("temporary file has incorrect size");
      return SOX_EOF;
    }
    p->pos /= sizeof(sox_sample_t);
  }
  p->pos -= *osamp = min((off_t)*osamp, p->pos);
  fseeko(p->tmp_file, (off_t)(p->pos * sizeof(sox_sample_t)), SEEK_SET);
  if (fread(obuf, sizeof(sox_sample_t), *osamp, p->tmp_file) != *osamp) {
    lsx_fail("error reading temporary file: %s", strerror(errno));
    return SOX_EOF;
  }
  if (*osamp)
    for (i = 0, j = *osamp - 1; i < j; ++i, --j) {
      sox_sample_t temp = obuf[i];
      obuf[i] = obuf[j];
      obuf[j] = temp;
    }
  return p->pos ? SOX_SUCCESS : SOX_EOF;
}

static int reverse_stop(sox_effect_t *effp)
{
  reverse_priv_t *p = (reverse_priv_t *)effp->priv;
  if (p->tmp_file) fclose(p->tmp_file);
  p->tmp_file = NULL;
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_reverse_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "reverse", NULL, SOX_EFF_MODIFY,
    NULL, reverse_start, reverse_flow, reverse_drain, reverse_stop, NULL, sizeof(reverse_priv_t)
  };
  return &handler;
}

/* ===================== repeat ===================== */
typedef struct {
  unsigned num_repeats, remaining_repeats;
  uint64_t num_samples, remaining_samples;
  FILE *tmp_file;
} repeat_priv_t;

static int repeat_create(sox_effect_t *effp, int argc, char **argv)
{
  repeat_priv_t *p = (repeat_priv_t *)effp->priv;
  p->num_repeats = 1;
  --argc, ++argv;
  if (argc == 1 && !strcmp(*argv, "-")) {
    p->num_repeats = UINT_MAX;
    ++argv, --argc;
  } else do { NUMERIC_PARAMETER(num_repeats, 0, UINT_MAX - 1) } while (0);
  return argc ? lsx_usage(effp) : SOX_SUCCESS;
}

static int repeat_start(sox_effect_t *effp)
{
  repeat_priv_t *p = (repeat_priv_t *)effp->priv;
  if (!p->num_repeats)
    return SOX_EFF_NULL;
  if (!(p->tmp_file = lsx_tmpfile())) {
    lsx_fail("can't create temporary file: %s", strerror(errno));
    return SOX_EOF;
  }
  p->num_samples = p->remaining_samples = 0;
  p->remaining_repeats = p->num_repeats;
  if (effp->in_signal.length != SOX_UNKNOWN_LEN && p->num_repeats != UINT_MAX)
    effp->out_signal.length = effp->in_signal.length * (p->num_repeats + 1);
  else
    effp->out_signal.length = SOX_UNKNOWN_LEN;
  return SOX_SUCCESS;
}

static int repeat_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  repeat_priv_t *p = (repeat_priv_t *)effp->priv;
  size_t len = min(*isamp, *osamp);
  memcpy(obuf, ibuf, len * sizeof(*obuf));
  if (fwrite(ibuf, sizeof(*ibuf), len, p->tmp_file) != len) {
    lsx_fail("error writing temporary file: %s", strerror(errno));
    return SOX_EOF;
  }
  p->num_samples += len;
  *isamp = *osamp = len;
  return SOX_SUCCESS;
}

static int repeat_drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{
  repeat_priv_t *p = (repeat_priv_t *)effp->priv;
  size_t odone = 0, n;

  *osamp -= *osamp % effp->in_signal.channels;

  while ((p->remaining_samples || p->remaining_repeats) && odone < *osamp) {
    if (!p->remaining_samples) {
      p->remaining_samples = p->num_samples;
      --p->remaining_repeats;
      rewind(p->tmp_file);
    }
    n = min(p->remaining_samples, *osamp - odone);
    if ((fread(obuf + odone, sizeof(*obuf), n, p->tmp_file)) != n) {
      lsx_fail("error reading temporary file: %s", strerror(errno));
      return SOX_EOF;
    }
    p->remaining_samples -= n;
    odone += n;
  }
  *osamp = odone;
  return p->remaining_samples || p->remaining_repeats ? SOX_SUCCESS : SOX_EOF;
}

static int repeat_stop(sox_effect_t *effp)
{
  repeat_priv_t *p = (repeat_priv_t *)effp->priv;
  if (p->tmp_file) fclose(p->tmp_file);
  p->tmp_file = NULL;
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_repeat_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "repeat", USAGE_repeat, SOX_EFF_MCHAN | SOX_EFF_LENGTH | SOX_EFF_MODIFY,
    repeat_create, repeat_start, repeat_flow, repeat_drain, repeat_stop, NULL, sizeof(repeat_priv_t)
  };
  return &handler;
}

/* ===================== fade ===================== */
typedef struct {
  uint64_t in_start, in_stop, out_start, out_stop, samplesdone;
  char *in_stop_str, *out_start_str, *out_stop_str;
  char in_fadetype, out_fadetype;
  char do_out;
  int endpadwarned;
} fade_priv_t;

#define FADE_QUARTER 'q'
#define FADE_HALF 'h'
#define FADE_LOG 'l'
#define FADE_TRI 't'
#define FADE_PAR 'p'

static double fade_gain(uint64_t index, uint64_t range, int type)
{
  double retval = 0.0, findex = 0.0;
  findex = max(0.0, min(1.0, 1.0 * index / range));
  switch (type) {
    case FADE_TRI: retval = findex; break;
    case FADE_QUARTER: retval = sin(findex * M_PI / 2); break;
    case FADE_HALF: retval = (1 - cos(findex * M_PI)) / 2; break;
    case FADE_LOG: retval = pow(0.1, (1 - findex) * 5); break;
    case FADE_PAR: retval = (1 - (1 - findex) * (1 - findex)); break;
    default: retval = -1.0; break;
  }
  return retval;
}

static int fade_getopts(sox_effect_t *effp, int argc, char **argv)
{
  fade_priv_t *fade = (fade_priv_t *)effp->priv;
  char t_char[2];
  int t_argno;
  uint64_t samples;
  const char *n;
  --argc, ++argv;

  if (argc < 1 || argc > 4)
    return lsx_usage(effp);

  if (sscanf(argv[0], "%1[qhltp]", t_char)) {
    fade->in_fadetype = *t_char;
    fade->out_fadetype = *t_char;
    argv++;
    argc--;
  } else {
    fade->in_fadetype = 'l';
    fade->out_fadetype = 'l';
  }
  if (argc < 1)
    return lsx_usage(effp);

  fade->in_stop_str = lsx_strdup(argv[0]);
  n = lsx_parsesamples(0., fade->in_stop_str, &samples, 't');
  if (!n || *n)
    return lsx_usage(effp);

  fade->in_stop = samples;
  fade->out_start_str = fade->out_stop_str = 0;

  for (t_argno = 1; t_argno < argc && t_argno < 3; t_argno++) {
    if (t_argno == 1) {
      fade->out_stop_str = lsx_strdup(argv[t_argno]);
      n = lsx_parseposition(0., fade->out_stop_str, NULL, (uint64_t)0, (uint64_t)0, '=');
      if (!n || *n)
        return lsx_usage(effp);
      fade->out_stop = samples;
    } else {
      fade->out_start_str = lsx_strdup(argv[t_argno]);
      n = lsx_parsesamples(0., fade->out_start_str, &samples, 't');
      if (!n || *n)
        return lsx_usage(effp);
      fade->out_start = samples;
    }
  }
  return SOX_SUCCESS;
}

static int fade_start(sox_effect_t *effp)
{
  fade_priv_t *fade = (fade_priv_t *)effp->priv;
  sox_bool truncate = sox_false;
  uint64_t samples;
  uint64_t in_length = effp->in_signal.length != SOX_UNKNOWN_LEN ?
    effp->in_signal.length / effp->in_signal.channels : SOX_UNKNOWN_LEN;

  fade->in_start = 0;
  if (lsx_parsesamples(effp->in_signal.rate, fade->in_stop_str, &samples, 't') == NULL)
    return lsx_usage(effp);

  fade->in_stop = samples;
  fade->do_out = 0;
  if (fade->out_stop_str) {
    fade->do_out = 1;
    if (!lsx_parseposition(effp->in_signal.rate, fade->out_stop_str, &samples, (uint64_t)0, in_length, '=') ||
        samples == SOX_UNKNOWN_LEN) {
      lsx_fail("audio length is unknown");
      return SOX_EOF;
    }
    fade->out_stop = samples;

    if (!(truncate = !!fade->out_stop)) {
      fade->out_stop = effp->in_signal.length != SOX_UNKNOWN_LEN ?
        effp->in_signal.length / effp->in_signal.channels : 0;
      if (!fade->out_stop) {
        lsx_fail("cannot fade out: audio length is neither known nor given");
        return SOX_EOF;
      }
    }

    if (fade->out_start_str) {
      if (lsx_parsesamples(effp->in_signal.rate, fade->out_start_str, &samples, 't') == NULL)
        return lsx_usage(effp);
      fade->out_start = fade->out_stop - samples;
    } else
      fade->out_start = fade->out_stop - fade->in_stop;
  } else
    fade->out_stop = 0;

  if (fade->out_start) {
    if (fade->in_stop > fade->out_start)
      --fade->in_stop;
    if (fade->in_stop > fade->out_start) {
      lsx_fail("fade-out overlaps fade-in");
      return SOX_EOF;
    }
  }

  fade->samplesdone = fade->in_start;
  fade->endpadwarned = 0;

  lsx_debug("in_start = %llu in_stop = %llu out_start = %llu out_stop = %llu",
      (unsigned long long)fade->in_start, (unsigned long long)fade->in_stop,
      (unsigned long long)fade->out_start, (unsigned long long)fade->out_stop);

  if (fade->in_start == fade->in_stop && !truncate && fade->out_start == fade->out_stop)
    return SOX_EFF_NULL;

  effp->out_signal.length = truncate ? fade->out_stop * effp->in_signal.channels : effp->in_signal.length;
  return SOX_SUCCESS;
}

static int fade_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  fade_priv_t *fade = (fade_priv_t *)effp->priv;
  int len = 0, t_output = 1, more_output = 1;
  sox_sample_t t_ibuf;
  size_t chcnt = 0;

  len = ((*isamp > *osamp) ? *osamp : *isamp);
  *osamp = 0;
  *isamp = 0;

  for (; len && more_output; len--) {
    t_ibuf = *ibuf;

    if ((fade->samplesdone >= fade->in_start) && (!fade->do_out || fade->samplesdone < fade->out_stop)) {
      if (fade->samplesdone < fade->in_stop) {
        *obuf = t_ibuf * fade_gain(fade->samplesdone - fade->in_start, fade->in_stop - fade->in_start, fade->in_fadetype);
      } else if (!fade->do_out || fade->samplesdone < fade->out_start) {
        *obuf = t_ibuf;
      } else {
        *obuf = t_ibuf * fade_gain(fade->out_stop - fade->samplesdone, fade->out_stop - fade->out_start, fade->out_fadetype);
      }
      if (!(!fade->do_out || fade->samplesdone < fade->out_stop))
        more_output = 0;
      t_output = 1;
    } else {
      t_output = 0;
    }

    *isamp += 1;
    ibuf++;
    if (t_output) {
      obuf++;
      *osamp += 1;
    }

    if (++chcnt >= effp->in_signal.channels) {
      fade->samplesdone += 1;
      chcnt = 0;
    }
  }

  if (fade->do_out && fade->samplesdone >= fade->out_stop)
    return SOX_EOF;
  else
    return SOX_SUCCESS;
}

static int fade_drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{
  fade_priv_t *fade = (fade_priv_t *)effp->priv;
  int len;
  size_t t_chan = 0;

  len = *osamp;
  len -= len % effp->in_signal.channels;
  *osamp = 0;

  if (fade->do_out && fade->samplesdone < fade->out_stop && !(fade->endpadwarned)) {
    lsx_warn("Fade: warning: End time passed end-of-file. Padding with silence");
    fade->endpadwarned = 1;
  }

  for (; fade->do_out && fade->samplesdone < fade->out_stop && len; len--) {
    *obuf = 0;
    obuf++;
    *osamp += 1;
    t_chan++;
    if (t_chan >= effp->in_signal.channels) {
      fade->samplesdone += 1;
      t_chan = 0;
    }
  }

  if (fade->do_out && fade->samplesdone >= fade->out_stop)
    return SOX_EOF;
  else
    return SOX_SUCCESS;
}

static int fade_kill(sox_effect_t *effp)
{
  fade_priv_t *fade = (fade_priv_t *)effp->priv;
  free(fade->in_stop_str);
  free(fade->out_start_str);
  free(fade->out_stop_str);
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_fade_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "fade", USAGE_fade, SOX_EFF_MCHAN | SOX_EFF_LENGTH,
    fade_getopts, fade_start, fade_flow, fade_drain, NULL, fade_kill, sizeof(fade_priv_t)
  };
  return &handler;
}

/* ===================== dcshift ===================== */
typedef struct {
  double dcshift;
  int uselimiter;
  double limiterthreshhold;
  double limitergain;
  uint64_t limited;
  uint64_t totalprocessed;
} dcshift_priv_t;

static int dcshift_getopts(sox_effect_t *effp, int argc, char **argv)
{
  dcshift_priv_t *dcs = (dcshift_priv_t *)effp->priv;
  dcs->dcshift = 1.0;
  dcs->uselimiter = 0;

  --argc, ++argv;
  if (argc < 1)
    return lsx_usage(effp);

  if (argc && (!sscanf(argv[0], "%lf", &dcs->dcshift)))
    return lsx_usage(effp);

  if (argc > 1) {
    if (!sscanf(argv[1], "%lf", &dcs->limitergain))
      return lsx_usage(effp);
    dcs->uselimiter = 1;
    dcs->limiterthreshhold = SOX_SAMPLE_MAX * (1.0 - (fabs(dcs->dcshift) - dcs->limitergain));
  }
  return SOX_SUCCESS;
}

static int dcshift_start(sox_effect_t *effp)
{
  dcshift_priv_t *dcs = (dcshift_priv_t *)effp->priv;
  if (dcs->dcshift == 0)
    return SOX_EFF_NULL;
  dcs->limited = 0;
  dcs->totalprocessed = 0;
  return SOX_SUCCESS;
}

static int dcshift_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  dcshift_priv_t *dcs = (dcshift_priv_t *)effp->priv;
  double dcshift = dcs->dcshift;
  double limitergain = dcs->limitergain;
  double limiterthreshhold = dcs->limiterthreshhold;
  double sample;
  size_t len;

  len = min(*osamp, *isamp);
  *isamp = len; *osamp = len;

  if (dcs->uselimiter) {
    dcs->totalprocessed += len;
    for (; len > 0; len--) {
      sample = *ibuf++;
      if (sample > limiterthreshhold && dcshift > 0) {
        sample = (sample - limiterthreshhold) * limitergain / (SOX_SAMPLE_MAX - limiterthreshhold) + limiterthreshhold + dcshift;
        dcs->limited++;
      } else if (sample < -limiterthreshhold && dcshift < 0) {
        sample = (sample + limiterthreshhold) * limitergain / (SOX_SAMPLE_MAX - limiterthreshhold) - limiterthreshhold + dcshift;
        dcs->limited++;
      } else {
        sample = dcshift * SOX_SAMPLE_MAX + sample;
      }
      SOX_SAMPLE_CLIP_COUNT(sample, effp->clips);
      *obuf++ = sample;
    }
  } else for (; len > 0; --len) {
    double d = dcshift * (SOX_SAMPLE_MAX + 1.) + *ibuf++;
    *obuf++ = SOX_ROUND_CLIP_COUNT(d, effp->clips);
  }
  return SOX_SUCCESS;
}

static int dcshift_stop(sox_effect_t *effp)
{
  dcshift_priv_t *dcs = (dcshift_priv_t *)effp->priv;
  if (dcs->limited) {
    lsx_warn("DCSHIFT limited %llu values (%d percent).",
        (unsigned long long)dcs->limited, (int)(dcs->limited * 100.0 / dcs->totalprocessed));
  }
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_dcshift_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "dcshift", USAGE_dcshift, SOX_EFF_MCHAN,
    dcshift_getopts, dcshift_start, dcshift_flow, NULL, dcshift_stop, NULL, sizeof(dcshift_priv_t)
  };
  return &handler;
}
