/* stat and stats effects */
#include "sox.h"
#include "usage_strings.h"

/* ================= stat ================= */
typedef struct {
  double min, max, mid;
  double asum;
  double sum1, sum2;
  double dmin, dmax;
  double dsum1, dsum2;
