static void rftfsub(int n, double *a, int nc, double *c)
{
  int j, k, kk, ks, m;
  double wkr, wki, xr, xi, yr, yi;

  m = n >> 1;
  ks = 2 * nc / m;
  kk = 0;
  for (j = 2; j < m; j += 2) {
    k = n - j;
    kk += ks;
    wkr = 0.5 - c[nc - kk];
    wki = c[kk];
    xr = a[j] - a[k];
    xi = a[j + 1] + a[k + 1];
    yr = wkr * xr - wki * xi;
    yi = wkr * xi + wki * xr;
    a[j] -= yr;
    a[j + 1] -= yi;
    a[k] += yr;
    a[k + 1] -= yi;
  }
}

static void rftbsub(int n, double *a, int nc, double *c)
{
  int j, k, kk, ks, m;
  double wkr, wki, xr, xi, yr, yi;

  a[1] = -a[1];
  m = n >> 1;
  ks = 2 * nc / m;
  kk = 0;
  for (j = 2; j < m; j += 2) {
    k = n - j;
    kk += ks;
    wkr = 0.5 - c[nc - kk];
    wki = c[kk];
    xr = a[j] - a[k];
    xi = a[j + 1] + a[k + 1];
    yr = wkr * xr + wki * xi;
    yi = wkr * xi - wki * xr;
    a[j] -= yr;
    a[j + 1] = yi - a[j + 1];
    a[k] += yr;
    a[k + 1] = yi - a[k + 1];
  }
  a[m + 1] = -a[m + 1];
}

/* cached work areas */
static int *fft_br;
static double *fft_sc;
static int fft_len = -1;

static void update_fft_cache(int len)
{
  if (len > fft_len) {
    int old_n = fft_len;
    fft_len = len;
    fft_br = lsx_realloc(fft_br, (size_t)(2 + (1 << (int)(log(max(len / 2, 1) + .5) / log(2.) / 2))) * sizeof(*fft_br) + 64 * sizeof(int));
    fft_sc = lsx_realloc(fft_sc, (size_t)(len / 2 + 2) * sizeof(*fft_sc));
    if (old_n <= 0)
      fft_br[0] = fft_br[1] = 0;
  }
}

void lsx_safe_rdft(int len, int type, double *d)
{
  update_fft_cache(len);
  lsx_rdft(len, type, d, fft_br, fft_sc);
}

void lsx_safe_cdft(int len, int type, double *d)
{
  update_fft_cache(len);
  lsx_cdft(len, type, d, fft_br, fft_sc);
}
