/* biquad filter effects */
#include "sox.h"
#include "usage_strings.h"

typedef enum {
  filter_LPF, filter_HPF, filter_BPF_CSG, filter_BPF, filter_notch, filter_APF,
  filter_peakingEQ, filter_lowShelf, filter_highShelf, filter_LPF_1, filter_HPF_1,
  filter_BPF_SPK, filter_BPF_SPK_N, filter_AP1, filter_AP2, filter_deemph, filter_riaa
} filter_t;

typedef enum { width_bw_Hz, width_bw_kHz, width_bw_old, width_bw_oct, width_Q, width_slope } width_t;
static char const all_width_types[] = "hkboqs";

typedef struct {
  double gain;
  double fc;
  double width;
  width_t width_type;
  filter_t filter_type;
  double b0, b1, b2;
  double a0, a1, a2;
  sox_sample_t i1, i2;
  double o1, o2;
} priv_t;

static int lsx_biquad_getopts(sox_effect_t *effp, int argc, char **argv,
    int min_args, int max_args, int fc_pos, int width_pos, int gain_pos,
    char const *allowed_width_types, filter_t filter_type)
{
  priv_t *p = (priv_t *)effp->priv;
  char width_type = *allowed_width_types;
  char dummy, *dummy_p;
  --argc, ++argv;

  p->filter_type = filter_type;
  if (argc < min_args || argc > max_args ||
      (argc > fc_pos && ((p->fc = lsx_parse_frequency(argv[fc_pos], &dummy_p)) <= 0 || *dummy_p)) ||
      (argc > width_pos && ((unsigned)(sscanf(argv[width_pos], "%lf%c %c", &p->width, &width_type, &dummy) - 1) > 1 || p->width <= 0)) ||
      (argc > gain_pos && sscanf(argv[gain_pos], "%lf %c", &p->gain, &dummy) != 1) ||
      !strchr(allowed_width_types, width_type) || (width_type == 's' && p->width > 1))
    return lsx_usage(effp);
  p->width_type = strchr(all_width_types, width_type) - all_width_types;
  if ((size_t)p->width_type >= strlen(all_width_types))
    p->width_type = 0;
  if (p->width_type == width_bw_kHz) {
    p->width *= 1000;
    p->width_type = width_bw_Hz;
  }
  return SOX_SUCCESS;
}

static int biquad_start_common(sox_effect_t *effp)
{
  priv_t *p = (priv_t *)effp->priv;
  p->b2 /= p->a0;
  p->b1 /= p->a0;
  p->b0 /= p->a0;
  p->a2 /= p->a0;
  p->a1 /= p->a0;
  p->o2 = p->o1 = p->i2 = p->i1 = 0;
  return SOX_SUCCESS;
}

static int lsx_biquad_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  priv_t *p = (priv_t *)effp->priv;
  size_t len = *isamp = *osamp = min(*isamp, *osamp);
  while (len--) {
    double o0 = *ibuf * p->b0 + p->i1 * p->b1 + p->i2 * p->b2 - p->o1 * p->a1 - p->o2 * p->a2;
    p->i2 = p->i1, p->i1 = *ibuf++;
    p->o2 = p->o1, p->o1 = o0;
    *obuf++ = SOX_ROUND_CLIP_COUNT(o0, effp->clips);
  }
  return SOX_SUCCESS;
}

static void make_poly_from_roots(double const *roots, size_t num_roots, double *poly)
{
  size_t i, j;
  poly[0] = 1;
  poly[1] = -roots[0];
  memset(poly + 2, 0, (num_roots + 1 - 2) * sizeof(*poly));
  for (i = 1; i < num_roots; ++i)
    for (j = num_roots; j > 0; --j)
      poly[j] -= poly[j - 1] * roots[i];
}

static int start(sox_effect_t *effp)
{
  priv_t *p = (priv_t *)effp->priv;
  double w0, A, alpha = 0, mult;

  if (p->filter_type == filter_deemph) {
    if (effp->in_signal.rate == 44100) {
      p->fc = 5283;
      p->width = 0.4845;
      p->gain = -9.477;
    } else if (effp->in_signal.rate == 48000) {
      p->fc = 5356;
      p->width = 0.479;
      p->gain = -9.62;
    } else {
      lsx_fail("sample rate must be 44100 (audio-CD) or 48000 (DAT)");
      return SOX_EOF;
    }
    p->width_type = width_slope;
  }

  w0 = 2 * M_PI * p->fc / effp->in_signal.rate;
  A = exp(p->gain / 40 * log(10.));
  mult = dB_to_linear(max(p->gain, 0));

  if (w0 > M_PI) {
    lsx_fail("frequency must be less than half the sample-rate (Nyquist rate)");
    return SOX_EOF;
  }

  p->b0 = p->b1 = p->b2 = p->a1 = p->a2 = 0;
  p->a0 = 1;

  if (p->width) switch (p->width_type) {
    case width_slope:
      alpha = sin(w0) / 2 * sqrt((A + 1 / A) * (1 / p->width - 1) + 2);
      break;
    case width_Q:
      alpha = sin(w0) / (2 * p->width);
      break;
    case width_bw_oct:
      alpha = sin(w0) * sinh(log(2.) / 2 * p->width * w0 / sin(w0));
      break;
    case width_bw_Hz:
      alpha = sin(w0) / (2 * p->fc / p->width);
      break;
    case width_bw_kHz:
      break;
    case width_bw_old:
      alpha = tan(M_PI * p->width / effp->in_signal.rate);
      break;
  }
  switch (p->filter_type) {
    case filter_LPF:
      p->b0 = (1 - cos(w0)) / 2;
      p->b1 = 1 - cos(w0);
      p->b2 = (1 - cos(w0)) / 2;
      p->a0 = 1 + alpha;
      p->a1 = -2 * cos(w0);
      p->a2 = 1 - alpha;
      break;
    case filter_HPF:
      p->b0 = (1 + cos(w0)) / 2;
      p->b1 = -(1 + cos(w0));
      p->b2 = (1 + cos(w0)) / 2;
      p->a0 = 1 + alpha;
      p->a1 = -2 * cos(w0);
      p->a2 = 1 - alpha;
      break;
    case filter_BPF_CSG:
      p->b0 = sin(w0) / 2;
      p->b1 = 0;
      p->b2 = -sin(w0) / 2;
      p->a0 = 1 + alpha;
      p->a1 = -2 * cos(w0);
      p->a2 = 1 - alpha;
      break;
    case filter_BPF:
      p->b0 = alpha;
      p->b1 = 0;
      p->b2 = -alpha;
      p->a0 = 1 + alpha;
      p->a1 = -2 * cos(w0);
      p->a2 = 1 - alpha;
      break;
    case filter_notch:
      p->b0 = 1;
      p->b1 = -2 * cos(w0);
      p->b2 = 1;
      p->a0 = 1 + alpha;
      p->a1 = -2 * cos(w0);
      p->a2 = 1 - alpha;
      break;
    case filter_APF:
      p->b0 = 1 - alpha;
      p->b1 = -2 * cos(w0);
      p->b2 = 1 + alpha;
      p->a0 = 1 + alpha;
      p->a1 = -2 * cos(w0);
      p->a2 = 1 - alpha;
      break;
    case filter_peakingEQ:
      if (A == 1)
        return SOX_EFF_NULL;
      p->b0 = 1 + alpha * A;
      p->b1 = -2 * cos(w0);
      p->b2 = 1 - alpha * A;
      p->a0 = 1 + alpha / A;
      p->a1 = -2 * cos(w0);
      p->a2 = 1 - alpha / A;
      break;
    case filter_lowShelf:
      if (A == 1)
        return SOX_EFF_NULL;
      p->b0 = A * ((A + 1) - (A - 1) * cos(w0) + 2 * sqrt(A) * alpha);
      p->b1 = 2 * A * ((A - 1) - (A + 1) * cos(w0));
      p->b2 = A * ((A + 1) - (A - 1) * cos(w0) - 2 * sqrt(A) * alpha);
      p->a0 = (A + 1) + (A - 1) * cos(w0) + 2 * sqrt(A) * alpha;
      p->a1 = -2 * ((A - 1) + (A + 1) * cos(w0));
      p->a2 = (A + 1) + (A - 1) * cos(w0) - 2 * sqrt(A) * alpha;
      break;
    case filter_deemph:
    case filter_highShelf:
      if (!A)
        return SOX_EFF_NULL;
      p->b0 = A * ((A + 1) + (A - 1) * cos(w0) + 2 * sqrt(A) * alpha);
      p->b1 = -2 * A * ((A - 1) + (A + 1) * cos(w0));
      p->b2 = A * ((A + 1) + (A - 1) * cos(w0) - 2 * sqrt(A) * alpha);
      p->a0 = (A + 1) - (A - 1) * cos(w0) + 2 * sqrt(A) * alpha;
      p->a1 = 2 * ((A - 1) - (A + 1) * cos(w0));
      p->a2 = (A + 1) - (A - 1) * cos(w0) - 2 * sqrt(A) * alpha;
      break;
    case filter_LPF_1:
      p->a1 = -exp(-w0);
      p->b0 = 1 + p->a1;
      break;
    case filter_HPF_1:
      p->a1 = -exp(-w0);
      p->b0 = (1 - p->a1) / 2;
      p->b1 = -p->b0;
      break;
    case filter_BPF_SPK: case filter_BPF_SPK_N: {
      double bw_Hz;
      if (!p->width)
        p->width = p->fc / 2;
      bw_Hz = p->width_type == width_Q ? p->fc / p->width :
        p->width_type == width_bw_Hz ? p->width :
        p->fc * (pow(2., p->width) - 1) * pow(2., -0.5 * p->width);
      p->a2 = exp(-2 * M_PI * bw_Hz / effp->in_signal.rate);
      p->a1 = -4 * p->a2 / (1 + p->a2) * cos(w0);
      if (p->filter_type == filter_BPF_SPK_N)
