/* echo, echos, delay, tremolo, overdrive, contrast, earwax, downsample, upsample */
#include "sox.h"
#include "usage_strings.h"

#define SOX_24BIT_CLIP_COUNT(l, clips) \
  ((l) >= ((sox_sample_t)1 << 23) ? ++(clips), ((sox_sample_t)1 << 23) - 1 : \
   (l) <= -((sox_sample_t)1 << 23) ? ++(clips), -((sox_sample_t)1 << 23) + 1 : (l))

#define DELAY_BUFSIZ (50 * 50U * 1024)
#define MAX_ECHOS 7

/* ================= echo ================= */
typedef struct {
  int counter;
  int num_delays;
  double *delay_buf;
  float in_gain, out_gain;
  float delay[MAX_ECHOS], decay[MAX_ECHOS];
  ptrdiff_t samples[MAX_ECHOS], maxsamples;
  size_t fade_out;
} echo_priv_t;

static int echo_getopts(sox_effect_t *effp, int argc, char **argv)
{
  echo_priv_t *echo = (echo_priv_t *)effp->priv;
  int i;

  --argc, ++argv;
  echo->num_delays = 0;

  if ((argc < 4) || (argc % 2))
    return lsx_usage(effp);

  i = 0;
  sscanf(argv[i++], "%f", &echo->in_gain);
  sscanf(argv[i++], "%f", &echo->out_gain);
  while (i < argc) {
    if (echo->num_delays >= MAX_ECHOS) {
      lsx_fail("echo: to many delays, use less than %i delays", MAX_ECHOS);
      return SOX_EOF;
    }
    sscanf(argv[i++], "%f", &echo->delay[echo->num_delays]);
    sscanf(argv[i++], "%f", &echo->decay[echo->num_delays]);
    echo->num_delays++;
  }
  return SOX_SUCCESS;
}

static int echo_start(sox_effect_t *effp)
{
  echo_priv_t *echo = (echo_priv_t *)effp->priv;
  int i;
  float sum_in_volume;
  long j;

  echo->maxsamples = 0;
  if (echo->in_gain < 0.0) {
    lsx_fail("echo: gain-in must be positive!");
    return SOX_EOF;
  }
  if (echo->in_gain > 1.0) {
    lsx_fail("echo: gain-in must be less than 1.0!");
    return SOX_EOF;
  }
  if (echo->out_gain < 0.0) {
    lsx_fail("echo: gain-in must be positive!");
    return SOX_EOF;
  }
  for (i = 0; i < echo->num_delays; i++) {
    echo->samples[i] = echo->delay[i] * effp->in_signal.rate / 1000.0;
    if (echo->samples[i] < 1) {
      lsx_fail("echo: delay must be positive!");
      return SOX_EOF;
    }
    if (echo->samples[i] > (ptrdiff_t)DELAY_BUFSIZ) {
      lsx_fail("echo: delay must be less than %g seconds!", DELAY_BUFSIZ / effp->in_signal.rate);
      return SOX_EOF;
    }
    if (echo->decay[i] < 0.0) {
      lsx_fail("echo: decay must be positive!");
      return SOX_EOF;
    }
    if (echo->decay[i] > 1.0) {
      lsx_fail("echo: decay must be less than 1.0!");
      return SOX_EOF;
    }
    if (echo->samples[i] > echo->maxsamples)
      echo->maxsamples = echo->samples[i];
  }
  echo->delay_buf = lsx_malloc(sizeof(double) * echo->maxsamples);
  for (j = 0; j < echo->maxsamples; ++j)
    echo->delay_buf[j] = 0.0;
  sum_in_volume = 1.0;
  for (i = 0; i < echo->num_delays; i++)
    sum_in_volume += echo->decay[i];
  if (sum_in_volume * echo->in_gain > 1.0 / echo->out_gain)
    lsx_warn("echo: warning >>> gain-out can cause saturation of output <<<");
  echo->counter = 0;
  echo->fade_out = echo->maxsamples;
  effp->out_signal.length = SOX_UNKNOWN_LEN;
  return SOX_SUCCESS;
}

static int echo_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  echo_priv_t *echo = (echo_priv_t *)effp->priv;
  int j;
  double d_in, d_out;
  sox_sample_t out;
  size_t len = min(*isamp, *osamp);
  *isamp = *osamp = len;

  while (len--) {
    d_in = (double)*ibuf++ / 256;
    d_out = d_in * echo->in_gain;
    for (j = 0; j < echo->num_delays; j++) {
      d_out += echo->delay_buf[(echo->counter + echo->maxsamples - echo->samples[j]) % echo->maxsamples] * echo->decay[j];
    }
    d_out = d_out * echo->out_gain;
    out = SOX_24BIT_CLIP_COUNT((sox_sample_t)d_out, effp->clips);
    *obuf++ = out * 256;
    echo->delay_buf[echo->counter] = d_in;
    echo->counter = (echo->counter + 1) % echo->maxsamples;
  }
  return SOX_SUCCESS;
}

static int echo_drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{
  echo_priv_t *echo = (echo_priv_t *)effp->priv;
  double d_in, d_out;
  sox_sample_t out;
  int j;
  size_t done;

  done = 0;
  while ((done < *osamp) && (done < echo->fade_out)) {
    d_in = 0;
    d_out = 0;
    for (j = 0; j < echo->num_delays; j++) {
      d_out += echo->delay_buf[(echo->counter + echo->maxsamples - echo->samples[j]) % echo->maxsamples] * echo->decay[j];
    }
    d_out = d_out * echo->out_gain;
    out = SOX_24BIT_CLIP_COUNT((sox_sample_t)d_out, effp->clips);
    *obuf++ = out * 256;
    echo->delay_buf[echo->counter] = d_in;
    echo->counter = (echo->counter + 1) % echo->maxsamples;
    done++;
    echo->fade_out--;
  }
  *osamp = done;
  if (echo->fade_out == 0)
    return SOX_EOF;
  else
    return SOX_SUCCESS;
}

static int echo_stop(sox_effect_t *effp)
{
  echo_priv_t *echo = (echo_priv_t *)effp->priv;
  free(echo->delay_buf);
  echo->delay_buf = NULL;
  return SOX_SUCCESS;
}

