actions.command:
cat > /workspace/src/echo_etc.c <<'EOF'
/* echo, echos, delay, tremolo, overdrive, contrast, earwax, downsample, upsample */
#include "sox.h"
#include "usage_strings.h"

#define SOX_24BIT_CLIP_COUNT(l, clips) \
  ((l) >= ((sox_sample_t)1 << 23) ? ++(clips), ((sox_sample_t)1 << 23) - 1 : \
   (l) <= -((sox_sample_t)1 << 23) ? ++(clips), -((sox_sample_t)1 << 23) + 1 : (l))

#define DELAY_BUFSIZ (50 * 50U * 1024)
#define MAX_ECHOS 7

/* ================= echo ================= */
typedef struct {
  int counter;
  int num_delays;
  double *delay_buf;
  float in_gain, out_gain;
  float delay[MAX_ECHOS], decay[MAX_ECHOS];
  ptrdiff_t samples[MAX_ECHOS], maxsamples;
  size_t fade_out;
} echo_priv_t;

static int echo_getopts(sox_effect_t *effp, int argc, char **argv)
{
  echo_priv_t *echo = (echo_priv_t *)effp->priv;
  int i;

  --argc, ++argv;
  echo->num_delays = 0;

  if ((argc < 4) || (argc % 2))
    return lsx_usage(effp);

  i = 0;
  sscanf(argv[i++], "%f", &echo->in_gain);
  sscanf(argv[i++], "%f", &echo->out_gain);
  while (i < argc) {
    if (echo->num_delays >= MAX_ECHOS) {
      lsx_fail("echo: to many delays, use less than %i delays", MAX_ECHOS);
      return SOX_EOF;
    }
    sscanf(argv[i++], "%f", &echo->delay[echo->num_delays]);
    sscanf(argv[i++], "%f", &echo->decay[echo->num_delays]);
    echo->num_delays++;
  }
  return SOX_SUCCESS;
}

static int echo_start(sox_effect_t *effp)
{
  echo_priv_t *echo = (echo_priv_t *)effp->priv;
  int i;
  float sum_in_volume;
  long j;

  echo->maxsamples = 0;
  if (echo->in_gain < 0.0) {
    lsx_fail("echo: gain-in must be positive!");
    return SOX_EOF;
  }
  if (echo->in_gain > 1.0) {
    lsx_fail("echo: gain-in must be less than 1.0!");
    return SOX_EOF;
  }
  if (echo->out_gain < 0.0) {
    lsx_fail("echo: gain-in must be positive!");
    return SOX_EOF;
  }
  for (i = 0; i < echo->num_delays; i++) {
    echo->samples[i] = echo->delay[i] * effp->in_signal.rate / 1000.0;
    if (echo->samples[i] < 1) {
      lsx_fail("echo: delay must be positive!");
      return SOX_EOF;
    }
    if (echo->samples[i] > (ptrdiff_t)DELAY_BUFSIZ) {
      lsx_fail("echo: delay must be less than %g seconds!", DELAY_BUFSIZ / effp->in_signal.rate);
      return SOX_EOF;
    }
    if (echo->decay[i] < 0.0) {
      lsx_fail("echo: decay must be positive!");
      return SOX_EOF;
    }
    if (echo->decay[i] > 1.0) {
      lsx_fail("echo: decay must be less than 1.0!");
      return SOX_EOF;
    }
    if (echo->samples[i] > echo->maxsamples)
      echo->maxsamples = echo->samples[i];
  }
  echo->delay_buf = lsx_malloc(sizeof(double) * echo->maxsamples);
  for (j = 0; j < echo->maxsamples; ++j)
    echo->delay_buf[j] = 0.0;
  sum_in_volume = 1.0;
  for (i = 0; i < echo->num_delays; i++)
    sum_in_volume += echo->decay[i];
  if (sum_in_volume * echo->in_gain > 1.0 / echo->out_gain)
    lsx_warn("echo: warning >>> gain-out can cause saturation of output <<<");
  echo->counter = 0;
  echo->fade_out = echo->maxsamples;
  effp->out_signal.length = SOX_UNKNOWN_LEN;
  return SOX_SUCCESS;
}

static int echo_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  echo_priv_t *echo = (echo_priv_t *)effp->priv;
  int j;
  double d_in, d_out;
  sox_sample_t out;
  size_t len = min(*isamp, *osamp);
  *isamp = *osamp = len;

  while (len--) {
    d_in = (double)*ibuf++ / 256;
    d_out = d_in * echo->in_gain;
    for (j = 0; j < echo->num_delays; j++) {
      d_out += echo->delay_buf[(echo->counter + echo->maxsamples - echo->samples[j]) % echo->maxsamples] * echo->decay[j];
    }
    d_out = d_out * echo->out_gain;
    out = SOX_24BIT_CLIP_COUNT((sox_sample_t)d_out, effp->clips);
    *obuf++ = out * 256;
    echo->delay_buf[echo->counter] = d_in;
    echo->counter = (echo->counter + 1) % echo->maxsamples;
  }
  return SOX_SUCCESS;
}

static int echo_drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{
  echo_priv_t *echo = (echo_priv_t *)effp->priv;
  double d_in, d_out;
  sox_sample_t out;
  int j;
  size_t done;

  done = 0;
  while ((done < *osamp) && (done < echo->fade_out)) {
    d_in = 0;
    d_out = 0;
    for (j = 0; j < echo->num_delays; j++) {
      d_out += echo->delay_buf[(echo->counter + echo->maxsamples - echo->samples[j]) % echo->maxsamples] * echo->decay[j];
    }
    d_out = d_out * echo->out_gain;
    out = SOX_24BIT_CLIP_COUNT((sox_sample_t)d_out, effp->clips);
    *obuf++ = out * 256;
    echo->delay_buf[echo->counter] = d_in;
    echo->counter = (echo->counter + 1) % echo->maxsamples;
    done++;
    echo->fade_out--;
  }
  *osamp = done;
  if (echo->fade_out == 0)
    return SOX_EOF;
  else
    return SOX_SUCCESS;
}

static int echo_stop(sox_effect_t *effp)
{
  echo_priv_t *echo = (echo_priv_t *)effp->priv;
  free(echo->delay_buf);
  echo->delay_buf = NULL;
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_echo_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "echo", USAGE_echo, SOX_EFF_LENGTH | SOX_EFF_GAIN,
    echo_getopts, echo_start, echo_flow, echo_drain, echo_stop, NULL, sizeof(echo_priv_t)
  };
  return &handler;
}

/* ================= echos ================= */
typedef struct {
  int counter[MAX_ECHOS];
  int num_delays;
  double *delay_buf;
  float in_gain, out_gain;
  float delay[MAX_ECHOS], decay[MAX_ECHOS];
  ptrdiff_t samples[MAX_ECHOS], pointer[MAX_ECHOS];
  size_t sumsamples;
} echos_priv_t;

static int echos_getopts(sox_effect_t *effp, int argc, char **argv)
{
  echos_priv_t *echo = (echos_priv_t *)effp->priv;
  int i;

  echo->num_delays = 0;
  --argc, ++argv;

  if ((argc < 4) || (argc % 2))
    return lsx_usage(effp);

  i = 0;
  sscanf(argv[i++], "%f", &echo->in_gain);
  sscanf(argv[i++], "%f", &echo->out_gain);
  while (i < argc) {
    if (echo->num_delays >= MAX_ECHOS) {
      lsx_fail("echos: to many delays, use less than %i delays", MAX_ECHOS);
      return SOX_EOF;
    }
    sscanf(argv[i++], "%f", &echo->delay[echo->num_delays]);
    sscanf(argv[i++], "%f", &echo->decay[echo->num_delays]);
    echo->num_delays++;
  }
  return SOX_SUCCESS;
}

static int echos_start(sox_effect_t *effp)
{
  echos_priv_t *echo = (echos_priv_t *)effp->priv;
  int i;
  float sum_in_volume;
  unsigned long j;

  if (echo->in_gain < 0.0) {
    lsx_fail("echos: gain-in must be positive!");
    return SOX_EOF;
  }
  if (echo->in_gain > 1.0) {
    lsx_fail("echos: gain-in must be less than 1.0!");
    return SOX_EOF;
  }
  if (echo->out_gain < 0.0) {
    lsx_fail("echos: gain-in must be positive!");
    return SOX_EOF;
  }
  echo->sumsamples = 0;
  for (i = 0; i < echo->num_delays; i++) {
    echo->samples[i] = echo->delay[i] * effp->in_signal.rate / 1000.0;
    if (echo->samples[i] < 1) {
      lsx_fail("echos: delay must be positive!");
      return SOX_EOF;
    }
    if (echo->samples[i] > (ptrdiff_t)DELAY_BUFSIZ) {
      lsx_fail("echos: delay must be less than %g seconds!", DELAY_BUFSIZ / effp->in_signal.rate);
      return SOX_EOF;
    }
    if (echo->decay[i] < 0.0) {
      lsx_fail("echos: decay must be positive!");
      return SOX_EOF;
    }
    if (echo->decay[i] > 1.0) {
      lsx_fail("echos: decay must be less than 1.0!");
      return SOX_EOF;
    }
    echo->counter[i] = 0;
    echo->pointer[i] = echo->sumsamples;
    echo->sumsamples += echo->samples[i];
  }
  echo->delay_buf = lsx_malloc(sizeof(double) * echo->sumsamples);
  for (j = 0; j < echo->sumsamples; ++j)
    echo->delay_buf[j] = 0.0;
  sum_in_volume = 1.0;
  for (i = 0; i < echo->num_delays; i++)
    sum_in_volume += echo->decay[i];
  if (sum_in_volume * echo->in_gain > 1.0 / echo->out_gain)
    lsx_warn("echos: warning >>> gain-out can cause saturation of output <<<");
  effp->out_signal.length = SOX_UNKNOWN_LEN;
  return SOX_SUCCESS;
}

static int echos_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  echos_priv_t *echo = (echos_priv_t *)effp->priv;
  int j;
  double d_in, d_out;
  sox_sample_t out;
  size_t len = min(*isamp, *osamp);
  *isamp = *osamp = len;

  while (len--) {
    d_in = (double)*ibuf++ / 256;
    d_out = d_in * echo->in_gain;
    for (j = 0; j < echo->num_delays; j++) {
      d_out += echo->delay_buf[echo->counter[j] + echo->pointer[j]] * echo->decay[j];
    }
    d_out = d_out * echo->out_gain;
    out = SOX_24BIT_CLIP_COUNT((sox_sample_t)d_out, effp->clips);
    *obuf++ = out * 256;
    for (j = 0; j < echo->num_delays; j++) {
      if (j == 0)
        echo->delay_buf[echo->counter[j] + echo->pointer[j]] = d_in;
      else
        echo->delay_buf[echo->counter[j] + echo->pointer[j]] =
          echo->delay_buf[echo->counter[j - 1] + echo->pointer[j - 1]] + d_in;
    }
    for (j = 0; j < echo->num_delays; j++)
      echo->counter[j] = (echo->counter[j] + 1) % echo->samples[j];
  }
  return SOX_SUCCESS;
}

static int echos_drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{
  echos_priv_t *echo = (echos_priv_t *)effp->priv;
  double d_in, d_out;
  sox_sample_t out;
  int j;
  size_t done;

  done = 0;
  while ((done < *osamp) && (done < echo->sumsamples)) {
    d_in = 0;
    d_out = 0;
    for (j = 0; j < echo->num_delays; j++) {
      d_out += echo->delay_buf[echo->counter[j] + echo->pointer[j]] * echo->decay[j];
    }
    d_out = d_out * echo->out_gain;
    out = SOX_24BIT_CLIP_COUNT((sox_sample_t)d_out, effp->clips);
    *obuf++ = out * 256;
    for (j = 0; j < echo->num_delays; j++) {
      if (j == 0)
        echo->delay_buf[echo->counter[j] + echo->pointer[j]] = d_in;
      else
        echo->delay_buf[echo->counter[j] + echo->pointer[j]] =
          echo->delay_buf[echo->counter[j - 1] + echo->pointer[j - 1]];
    }
    for (j = 0; j < echo->num_delays; j++)
      echo->counter[j] = (echo->counter[j] + 1) % echo->samples[j];
    done++;
    echo->sumsamples--;
  }
  *osamp = done;
  if (echo->sumsamples == 0)
    return SOX_EOF;
  else
    return SOX_SUCCESS;
}

static int echos_stop(sox_effect_t *effp)
{
  echos_priv_t *echo = (echos_priv_t *)effp->priv;
  free(echo->delay_buf);
  echo->delay_buf = NULL;
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_echos_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "echos", USAGE_echos, SOX_EFF_LENGTH | SOX_EFF_GAIN,
    echos_getopts, echos_start, echos_flow, echos_drain, echos_stop, NULL, sizeof(echos_priv_t)
  };
  return &handler;
}

/* ================= delay ================= */
typedef struct {
  size_t argc;
  struct { char *str; uint64_t delay; } *args;
  uint64_t *max_delay;
  uint64_t delay, pre_pad, pad;
  size_t buffer_size, buffer_index;
  sox_sample_t *buffer;
  sox_bool drain_started;
} delay_priv_t;

static int delay_kill(sox_effect_t *effp)
{
  delay_priv_t *p = (delay_priv_t *)effp->priv;
  unsigned i;
  for (i = 0; i < p->argc; ++i)
    free(p->args[i].str);
  free(p->args);
  free(p->max_delay);
  p->args = NULL; p->max_delay = NULL; p->argc = 0;
  return SOX_SUCCESS;
}

static int delay_create(sox_effect_t *effp, int argc, char **argv)
{
  delay_priv_t *p = (delay_priv_t *)effp->priv;
  unsigned i;

  --argc, ++argv;
  p->argc = argc;
  p->args = lsx_calloc(p->argc + 1, sizeof(*p->args));
  p->max_delay = lsx_malloc(sizeof(*p->max_delay));
  for (i = 0; i < p->argc; ++i) {
    char const *next = lsx_parseposition(1e5, p->args[i].str = lsx_strdup(argv[i]), NULL, (uint64_t)0, (uint64_t)0, '=');
    if (!next || *next) {
      delay_kill(effp);
      return lsx_usage(effp);
    }
  }
  return SOX_SUCCESS;
}

static int delay_stop(sox_effect_t *effp)
{
  delay_priv_t *p = (delay_priv_t *)effp->priv;
  free(p->buffer);
  p->buffer = NULL;
  return SOX_SUCCESS;
}

static int delay_start(sox_effect_t *effp)
{
  delay_priv_t *p = (delay_priv_t *)effp->priv;
  uint64_t max_delay = 0, last_seen = 0, delay;
  uint64_t in_length = effp->in_signal.length != SOX_UNKNOWN_LEN ?
    effp->in_signal.length / effp->in_signal.channels : SOX_UNKNOWN_LEN;

  if (effp->flow == 0) {
    unsigned i;
    if (p->argc > effp->in_signal.channels) {
      lsx_fail("too few input channels");
      return SOX_EOF;
    }
    for (i = 0; i < p->argc; ++i) {
      if (!lsx_parseposition(effp->in_signal.rate, p->args[i].str, &delay, last_seen, in_length, '=') || delay == SOX_UNKNOWN_LEN) {
        lsx_fail("Position relative to end of audio specified, but audio length is unknown");
        return SOX_EOF;
      }
      p->args[i].delay = last_seen = delay;
      if (delay > max_delay)
        max_delay = delay;
    }
    *p->max_delay = max_delay;
    if (max_delay == 0)
      return SOX_EFF_NULL;
    effp->out_signal.length = effp->in_signal.length != SOX_UNKNOWN_LEN ?
      effp->in_signal.length + max_delay * effp->in_signal.channels : SOX_UNKNOWN_LEN;
    lsx_debug("extending audio by %llu samples", (unsigned long long)max_delay);
  }

  max_delay = *p->max_delay;
  p->buffer_size = 0;
  if (effp->flow < p->argc)
    p->buffer_size = p->args[effp->flow].delay;
  p->buffer_index = p->delay = p->pre_pad = 0;
  p->pad = max_delay - p->buffer_size;
  p->buffer = lsx_malloc(p->buffer_size * sizeof(*p->buffer) + 1);
  p->drain_started = sox_false;
  return SOX_SUCCESS;
}

static int delay_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  delay_priv_t *p = (delay_priv_t *)effp->priv;
  size_t len = *isamp = *osamp = min(*isamp, *osamp);

  if (!p->buffer_size)
    memcpy(obuf, ibuf, len * sizeof(*obuf));
  else for (; len; --len) {
    if (p->delay < p->buffer_size) {
      p->buffer[p->delay++] = *ibuf++;
      *obuf++ = 0;
    } else {
      *obuf++ = p->buffer[p->buffer_index];
      p->buffer[p->buffer_index++] = *ibuf++;
      p->buffer_index %= p->buffer_size;
    }
  }
  return SOX_SUCCESS;
}

static int delay_drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{
  delay_priv_t *p = (delay_priv_t *)effp->priv;
  size_t len;
  if (!p->drain_started) {
    p->drain_started = sox_true;
    p->pre_pad = p->buffer_size - p->delay;
  }
  len = *osamp = min(p->pre_pad + p->delay + p->pad, *osamp);

  for (; p->pre_pad && len; --p->pre_pad, --len)
    *obuf++ = 0;
  for (; p->delay && len; --p->delay, --len) {
    *obuf++ = p->buffer[p->buffer_index++];
    p->buffer_index %= p->buffer_size;
  }
  for (; p->pad && len; --p->pad, --len)
    *obuf++ = 0;
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_delay_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "delay", USAGE_delay, SOX_EFF_LENGTH | SOX_EFF_MODIFY,
    delay_create, delay_start, delay_flow, delay_drain, delay_stop, delay_kill, sizeof(delay_priv_t)
  };
  return &handler;
}

/* ================= tremolo ================= */
static int tremolo_getopts(sox_effect_t *effp, int argc, char **argv)
{
  double speed, depth = 40;
  char dummy;
  char offset[100];
  char *args[] = {0, "sine", "fmod", 0, 0, "25"};

  if (argc < 2 || argc > 3 ||
      sscanf(argv[1], "%lf %c", &speed, &dummy) != 1 || speed < 0 ||
      (argc > 2 && sscanf(argv[2], "%lf %c", &depth, &dummy) != 1) ||
      depth <= 0 || depth > 100)
    return lsx_usage(effp);
  args[0] = argv[0];
  args[3] = argv[1];
  sprintf(offset, "%g", 100 - depth / 2);
  args[4] = offset;
  {
    extern const sox_effect_handler_t *lsx_synth_effect_fn(void);
    return lsx_synth_effect_fn()->getopts(effp, (int)array_length(args), args);
  }
}

const sox_effect_handler_t *lsx_tremolo_effect_fn(void)
{
  extern const sox_effect_handler_t *lsx_synth_effect_fn(void);
  static sox_effect_handler_t handler;
  handler = *lsx_synth_effect_fn();
  handler.name = "tremolo";
  handler.usage = USAGE_tremolo;
  handler.getopts = tremolo_getopts;
  return &handler;
}

/* ================= overdrive ================= */
typedef struct {
  double gain, colour, last_in, last_out, b0, b1, a1;
} overdrive_priv_t;

static int overdrive_create(sox_effect_t *effp, int argc, char **argv)
{
  overdrive_priv_t *p = (overdrive_priv_t *)effp->priv;
  p->gain = p->colour = 20;
  --argc, ++argv;
  do {
    NUMERIC_PARAMETER(gain, 0, 100)
    NUMERIC_PARAMETER(colour, 0, 100)
  } while (0);
  p->gain = dB_to_linear(p->gain);
  p->colour /= 200;
  return argc ? lsx_usage(effp) : SOX_SUCCESS;
}

static int overdrive_start(sox_effect_t *effp)
{
  overdrive_priv_t *p = (overdrive_priv_t *)effp->priv;
  if (p->gain == 1)
    return SOX_EFF_NULL;
  return SOX_SUCCESS;
}

static int overdrive_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  overdrive_priv_t *p = (overdrive_priv_t *)effp->priv;
  size_t dummy = 0, len = *isamp = *osamp = min(*isamp, *osamp);
  while (len--) {
    double d = SOX_SAMPLE_TO_FLOAT_64BIT(*ibuf++, dummy), d0 = d;
    d *= p->gain;
    d += p->colour;
    d = d < -1 ? -2. / 3 : d > 1 ? 2. / 3 : d - d * d * d * (1. / 3);
    p->last_out = d - p->last_in + .995 * p->last_out;
    p->last_in = d;
    *obuf++ = SOX_FLOAT_64BIT_TO_SAMPLE(d0 * .5 + p->last_out * .75, dummy);
  }
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_overdrive_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "overdrive", USAGE_overdrive, SOX_EFF_GAIN,
    overdrive_create, overdrive_start, overdrive_flow, NULL, NULL, NULL, sizeof(overdrive_priv_t)
  };
  return &handler;
}

/* ================= contrast ================= */
typedef struct { double contrast; } contrast_priv_t;

static int contrast_create(sox_effect_t *effp, int argc, char **argv)
{
  contrast_priv_t *p = (contrast_priv_t *)effp->priv;
  p->contrast = 75;
  --argc, ++argv;
  do { NUMERIC_PARAMETER(contrast, 0, 100) } while (0);
  p->contrast /= 750;
  return argc ? lsx_usage(effp) : SOX_SUCCESS;
}

static int contrast_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  contrast_priv_t *p = (contrast_priv_t *)effp->priv;
  size_t len = *isamp = *osamp = min(*isamp, *osamp);
  while (len--) {
    double d = *ibuf++ * (-M_PI_2 / SOX_SAMPLE_MIN);
    *obuf++ = sin(d + p->contrast * sin(d * 4)) * SOX_SAMPLE_MAX;
  }
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_contrast_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "contrast", USAGE_contrast, 0,
    contrast_create, NULL, contrast_flow, NULL, NULL, NULL, sizeof(contrast_priv_t)
  };
  return &handler;
}

/* ================= earwax ================= */
static const sox_sample_t earwax_filt[32 * 2] = {
  4, -6, 4, -11, -1, -5, 3, 3, -2, 5, -5, 0, 9, 1, 6, 3, -4, -1, -5, -3,
  -2, -5, -7, 1, 6, -7, 30, -29, 12, -3, -11, 4, -3, 7, -20, 23, 2, 0, 1, -6,
  -14, -5, 15, -18, 6, 7, 15, -10, -14, 22, -7, -2, -4, 9, 6, -12, 6, -6, 0, -11,
  0, -5, 4, 0};
#define EARWAX_NUMTAPS array_length(earwax_filt)
typedef struct { sox_sample_t tap[EARWAX_NUMTAPS]; } earwax_priv_t;

static int earwax_start(sox_effect_t *effp)
{
  earwax_priv_t *p = (earwax_priv_t *)effp->priv;
  if (effp->in_signal.rate != 44100 || effp->in_signal.channels != 2) {
    lsx_fail("works only with stereo audio sampled at 44100Hz (i.e. CDDA)");
    return SOX_EOF;
  }
  memset(p->tap, 0, EARWAX_NUMTAPS * sizeof(*p->tap));
  if (effp->in_signal.mult)
    *effp->in_signal.mult *= dB_to_linear(-4.4);
  return SOX_SUCCESS;
}

static int earwax_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  earwax_priv_t *p = (earwax_priv_t *)effp->priv;
  size_t i, len = *isamp = *osamp = min(*isamp, *osamp);

  while (len--) {
    double output = 0;
    for (i = EARWAX_NUMTAPS - 1; i; --i) {
      p->tap[i] = p->tap[i - 1];
      output += p->tap[i] * earwax_filt[i];
    }
    p->tap[0] = *ibuf++ / 64;
    output += p->tap[0] * earwax_filt[0];
    *obuf++ = SOX_ROUND_CLIP_COUNT(output, effp->clips);
  }
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_earwax_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "earwax", NULL, SOX_EFF_MCHAN,
    NULL, earwax_start, earwax_flow, NULL, NULL, NULL, sizeof(earwax_priv_t)
  };
  return &handler;
}

/* ================= downsample / upsample ================= */
typedef struct {
  unsigned int factor;
  unsigned int carry;
} updown_priv_t;

static int updown_create(sox_effect_t *effp, int argc, char **argv)
{
  updown_priv_t *p = (updown_priv_t *)effp->priv;
  p->factor = 2;
  --argc, ++argv;
  do { NUMERIC_PARAMETER(factor, 1, 16384) } while (0);
  return argc ? lsx_usage(effp) : SOX_SUCCESS;
}

static int downsample_start(sox_effect_t *effp)
{
  updown_priv_t *p = (updown_priv_t *)effp->priv;
  effp->out_signal.rate = effp->in_signal.rate / p->factor;
  return p->factor == 1 ? SOX_EFF_NULL : SOX_SUCCESS;
}

static int downsample_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  updown_priv_t *p = (updown_priv_t *)effp->priv;
  size_t ilen = *isamp, olen = *osamp;
  size_t t;

  t = min(p->carry, ilen);
  p->carry -= t;
  ibuf += t; ilen -= t;

  /* NB: either p->carry (usually) or ilen is now zero; if ilen is zero, we're done */
  for (; ilen && olen; ilen -= t, ibuf += t) {
    *obuf++ = *ibuf;
    olen--;
    t = min(p->factor, ilen);
    p->carry = p->factor - t;
  }
  *isamp -= ilen, *osamp -= olen;
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_downsample_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "downsample", USAGE_downsample, SOX_EFF_RATE | SOX_EFF_MODIFY,
    updown_create, downsample_start, downsample_flow, NULL, NULL, NULL, sizeof(updown_priv_t)
  };
  return &handler;
}

static int upsample_start(sox_effect_t *effp)
{
  updown_priv_t *p = (updown_priv_t *)effp->priv;
  effp->out_signal.rate = effp->in_signal.rate * p->factor;
  return p->factor == 1 ? SOX_EFF_NULL : SOX_SUCCESS;
}

static int upsample_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  updown_priv_t *p = (updown_priv_t *)effp->priv;
  size_t ibuf_size = *isamp, obuf_size = *osamp;
  size_t done = 0;

  while (done < ibuf_size && obuf_size - (obuf - (obuf)) >= 0) {
    break;
  }
  {
    size_t i = 0, o = 0;
    while (i < ibuf_size && o + p->factor <= obuf_size) {
      unsigned j;
      obuf[o++] = ibuf[i++];
      for (j = 1; j < p->factor; ++j) obuf[o++] = 0;
    }
    *isamp = i;
    *osamp = o;
  }
  (void)done;
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_upsample_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "upsample", USAGE_upsample, SOX_EFF_RATE | SOX_EFF_MODIFY,
    updown_create, upsample_start, upsample_flow, NULL, NULL, NULL, sizeof(updown_priv_t)
  };
  return &handler;
}
