} flanger_priv_t;

static lsx_enum_item const interp_enum[] = {
  {"linear", INTERP_LINEAR},
  {"quadratic", INTERP_QUADRATIC},
  {0, 0}};

static int flanger_getopts(sox_effect_t *effp, int argc, char *argv[])
{
  flanger_priv_t *p = (flanger_priv_t *)effp->priv;
  --argc, ++argv;

  p->delay_depth = 2;
  p->delay_gain = 71;
  p->speed = 0.5;
  p->channel_phase = 25;

  do {
    NUMERIC_PARAMETER(delay_min, 0, 30)
    NUMERIC_PARAMETER(delay_depth, 0, 10)
    NUMERIC_PARAMETER(feedback_gain, -95, 95)
    NUMERIC_PARAMETER(delay_gain, 0, 100)
    NUMERIC_PARAMETER(speed, 0.1, 10)
    TEXTUAL_PARAMETER(wave_shape, wave_enum)
    NUMERIC_PARAMETER(channel_phase, 0, 100)
    TEXTUAL_PARAMETER(interpolation, interp_enum)
  } while (0);

  if (argc != 0)
    return lsx_usage(effp);

  lsx_report("parameters:\n"
      "delay = %gms\n"
      "depth = %gms\n"
      "regen = %g%%\n"
      "width = %g%%\n"
      "speed = %gHz\n"
      "shape = %s\n"
      "phase = %g%%\n"
      "interp= %s",
      p->delay_min,
      p->delay_depth,
      p->feedback_gain,
      p->delay_gain,
      p->speed,
      wave_enum[p->wave_shape].name,
      p->channel_phase,
      interp_enum[p->interpolation].name);

  p->feedback_gain /= 100;
  p->delay_gain /= 100;
  p->channel_phase /= 100;
  p->delay_min /= 1000;
  p->delay_depth /= 1000;
  return SOX_SUCCESS;
}

static int flanger_start(sox_effect_t *effp)
{
  flanger_priv_t *f = (flanger_priv_t *)effp->priv;
  int c, channels = effp->in_signal.channels;

  if (channels > MAX_CHANNELS) {
    lsx_fail("Can not operate with more than %i channels", MAX_CHANNELS);
    return SOX_EOF;
  }

  f->in_gain = 1 / (1 + f->delay_gain);
  f->delay_gain /= 1 + f->delay_gain;
  f->delay_gain *= 1 - fabs(f->feedback_gain);

  lsx_debug("in_gain=%g feedback_gain=%g delay_gain=%g\n", f->in_gain, f->feedback_gain, f->delay_gain);

  f->delay_buf_length = (f->delay_min + f->delay_depth) * effp->in_signal.rate + 0.5;
  ++f->delay_buf_length;
  ++f->delay_buf_length;
  for (c = 0; c < channels; ++c)
    f->delay_bufs[c] = lsx_calloc(f->delay_buf_length, sizeof(*f->delay_bufs[0]));

  f->lfo_length = effp->in_signal.rate / f->speed;
  f->lfo = lsx_calloc(f->lfo_length, sizeof(*f->lfo));
  lsx_generate_wave_table(f->wave_shape, SOX_FLOAT, f->lfo, f->lfo_length,
      floor(f->delay_min * effp->in_signal.rate + .5), f->delay_buf_length - 2., 3 * M_PI_2);

  lsx_debug("delay_buf_length=%lu lfo_length=%lu\n", (unsigned long)f->delay_buf_length, (unsigned long)f->lfo_length);
  return SOX_SUCCESS;
}

static int flanger_flow(sox_effect_t *effp, sox_sample_t const *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  flanger_priv_t *f = (flanger_priv_t *)effp->priv;
  int c, channels = effp->in_signal.channels;
  size_t len = (*isamp > *osamp ? *osamp : *isamp) / channels;

  *isamp = *osamp = len * channels;

  while (len--) {
    f->delay_buf_pos = (f->delay_buf_pos + f->delay_buf_length - 1) % f->delay_buf_length;
    for (c = 0; c < channels; ++c) {
      double delayed_0, delayed_1;
      double delayed;
      double in, out;
      size_t channel_phase = c * f->lfo_length * f->channel_phase + .5;
      double delay = f->lfo[(f->lfo_pos + channel_phase) % f->lfo_length];
      double frac_delay = modf(delay, &delay);
      size_t int_delay = (size_t)delay;

      in = *ibuf++;
      f->delay_bufs[c][f->delay_buf_pos] = in + f->delay_last[c] * f->feedback_gain;

      delayed_0 = f->delay_bufs[c][(f->delay_buf_pos + int_delay++) % f->delay_buf_length];
      delayed_1 = f->delay_bufs[c][(f->delay_buf_pos + int_delay++) % f->delay_buf_length];

      if (f->interpolation == INTERP_LINEAR)
        delayed = delayed_0 + (delayed_1 - delayed_0) * frac_delay;
      else {
        double a, b;
        double delayed_2 = f->delay_bufs[c][(f->delay_buf_pos + int_delay++) % f->delay_buf_length];
        delayed_2 -= delayed_0;
        delayed_1 -= delayed_0;
        a = delayed_2 * .5 - delayed_1;
        b = delayed_1 * 2 - delayed_2 * .5;
        delayed = delayed_0 + (a * frac_delay + b) * frac_delay;
      }

      f->delay_last[c] = delayed;
      out = in * f->in_gain + delayed * f->delay_gain;
      *obuf++ = SOX_ROUND_CLIP_COUNT(out, effp->clips);
    }
    f->lfo_pos = (f->lfo_pos + 1) % f->lfo_length;
  }
  return SOX_SUCCESS;
}

static int flanger_stop(sox_effect_t *effp)
{
  flanger_priv_t *f = (flanger_priv_t *)effp->priv;
  int c, channels = effp->in_signal.channels;
  for (c = 0; c < channels && c < MAX_CHANNELS; ++c) {
    free(f->delay_bufs[c]);
    f->delay_bufs[c] = NULL;
  }
  free(f->lfo);
  f->lfo = NULL;
  memset(f, 0, sizeof(*f));
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_flanger_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "flanger", USAGE_flanger, SOX_EFF_MCHAN,
    flanger_getopts, flanger_start, flanger_flow, NULL, flanger_stop, NULL, sizeof(flanger_priv_t)
  };
  return &handler;
}

/* ================= phaser ================= */
typedef struct {
  double in_gain, out_gain, delay_ms, decay, mod_speed;
  lsx_wave_t mod_type;
  int *mod_buf;
  size_t mod_buf_len;
  int mod_pos;
  double *delay_buf;
  size_t delay_buf_len;
  int delay_pos;
} phaser_priv_t;

static int phaser_getopts(sox_effect_t *effp, int argc, char **argv)
{
  phaser_priv_t *p = (phaser_priv_t *)effp->priv;
  char chars[2];

  p->in_gain = .4;
  p->out_gain = .74;
  p->delay_ms = 3.;
  p->decay = .4;
  p->mod_speed = .5;

  --argc, ++argv;
  do {
    NUMERIC_PARAMETER(in_gain, .0, 1)
    NUMERIC_PARAMETER(out_gain, .0, 1e9)
    NUMERIC_PARAMETER(delay_ms, .0, 5)
    NUMERIC_PARAMETER(decay, .0, .99)
    NUMERIC_PARAMETER(mod_speed, .1, 2)
  } while (0);

  if (argc && sscanf(*argv, "-%1[st]%c", chars, chars + 1) == 1) {
    p->mod_type = *chars == 's' ? SOX_WAVE_SINE : SOX_WAVE_TRIANGLE;
    --argc, ++argv;
  }

  if (p->in_gain > (1 - p->decay * p->decay))
    lsx_warn("warning: gain-in might cause clipping");
  if (p->in_gain / (1 - p->decay) > 1 / p->out_gain)
    lsx_warn("warning: gain-out might cause clipping");

  return argc ? lsx_usage(effp) : SOX_SUCCESS;
}

static int phaser_start(sox_effect_t *effp)
{
  phaser_priv_t *p = (phaser_priv_t *)effp->priv;

  p->delay_buf_len = p->delay_ms * .001 * effp->in_signal.rate + .5;
  p->delay_buf = lsx_calloc(p->delay_buf_len, sizeof(*p->delay_buf));

  p->mod_buf_len = effp->in_signal.rate / p->mod_speed + .5;
  p->mod_buf = lsx_malloc(p->mod_buf_len * sizeof(*p->mod_buf));
  lsx_generate_wave_table(p->mod_type, SOX_INT, p->mod_buf, p->mod_buf_len, 1., (double)p->delay_buf_len, M_PI_2);

  p->delay_pos = p->mod_pos = 0;
  effp->out_signal.length = SOX_UNKNOWN_LEN;
  return SOX_SUCCESS;
}

static int phaser_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  phaser_priv_t *p = (phaser_priv_t *)effp->priv;
  size_t len = *isamp = *osamp = min(*isamp, *osamp);

  while (len--) {
    double d = *ibuf++ * p->in_gain + p->delay_buf[(p->delay_pos + p->mod_buf[p->mod_pos]) % p->delay_buf_len] * p->decay;
    p->mod_pos = (p->mod_pos + 1) % p->mod_buf_len;
    p->delay_pos = (p->delay_pos + 1) % p->delay_buf_len;
    p->delay_buf[p->delay_pos] = d;
    *obuf++ = SOX_ROUND_CLIP_COUNT(d * p->out_gain, effp->clips);
  }
  return SOX_SUCCESS;
}

static int phaser_stop(sox_effect_t *effp)
{
  phaser_priv_t *p = (phaser_priv_t *)effp->priv;
  free(p->delay_buf);
  free(p->mod_buf);
  p->delay_buf = NULL; p->mod_buf = NULL;
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_phaser_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "phaser", USAGE_phaser, SOX_EFF_LENGTH | SOX_EFF_GAIN,
    phaser_getopts, phaser_start, phaser_flow, NULL, phaser_stop, NULL, sizeof(phaser_priv_t)
  };
  return &handler;
}
