cat > /workspace/src/modulation.c <<'EOF'
/* chorus, flanger, phaser effects + wave table generator */
#include "sox.h"
#include "usage_strings.h"

typedef enum { SOX_WAVE_SINE, SOX_WAVE_TRIANGLE } lsx_wave_t;
typedef enum { SOX_SHORT, SOX_INT, SOX_FLOAT, SOX_DOUBLE } sox_data_t;

static lsx_enum_item const wave_enum[] = {
  {"sine", SOX_WAVE_SINE},
  {"triangle", SOX_WAVE_TRIANGLE},
  {0, 0}};

void lsx_generate_wave_table(lsx_wave_t wave_type, sox_data_t data_type, void *table, size_t table_size, double mn, double mx, double phase)
{
  uint32_t t;
  uint32_t phase_offset = phase / M_PI / 2 * table_size + 0.5;

  for (t = 0; t < table_size; t++) {
    uint32_t point = (t + phase_offset) % table_size;
    double d;
    switch (wave_type) {
      case SOX_WAVE_SINE:
        d = (sin((double)point / table_size * 2 * M_PI) + 1) / 2;
        break;
      case SOX_WAVE_TRIANGLE:
        d = (double)point * 2 / table_size;
        switch (4 * point / table_size) {
          case 0: d = d + 0.5; break;
          case 1: case 2: d = 1.5 - d; break;
          case 3: d = d - 1.5; break;
        }
        break;
      default:
        d = 0.0;
        break;
    }
    d = d * (mx - mn) + mn;
    switch (data_type) {
      case SOX_FLOAT: {
        float *fp = (float *)table;
        *fp++ = (float)d;
        table = fp;
        continue;
      }
      case SOX_DOUBLE: {
        double *dp = (double *)table;
        *dp++ = d;
        table = dp;
        continue;
      }
      default: break;
    }
    d += d < 0 ? -0.5 : +0.5;
    switch (data_type) {
      case SOX_SHORT: {
        short *sp = table;
        *sp++ = (short)d;
        table = sp;
        continue;
      }
      case SOX_INT: {
        int *ip = table;
        *ip++ = (int)d;
        table = ip;
        continue;
      }
      default: break;
    }
  }
}

#define SOX_24BIT_CLIP_COUNT(l, clips) \
  ((l) > ((sox_sample_t)1 << 23) - 1 ? ++(clips), ((sox_sample_t)1 << 23) - 1 : \
   (l) < -((sox_sample_t)1 << 23) ? ++(clips), -((sox_sample_t)1 << 23) : (l))

/* ================= chorus ================= */
#define MOD_SINE 0
#define MOD_TRIANGLE 1
#define MAX_CHORUS 7

typedef struct {
  int num_chorus;
  int modulation[MAX_CHORUS];
  int counter;
  long phase[MAX_CHORUS];
  float *chorusbuf;
  float in_gain, out_gain;
  float delay[MAX_CHORUS], decay[MAX_CHORUS];
  float speed[MAX_CHORUS], depth[MAX_CHORUS];
  long length[MAX_CHORUS];
  int *lookup_tab[MAX_CHORUS];
  int depth_samples[MAX_CHORUS], samples[MAX_CHORUS];
  int maxsamples;
  unsigned int fade_out;
} chorus_priv_t;

static int chorus_getopts(sox_effect_t *effp, int argc, char **argv)
{
  chorus_priv_t *chorus = (chorus_priv_t *)effp->priv;
  int i;
  --argc, ++argv;

  chorus->num_chorus = 0;
  i = 0;

  if ((argc < 7) || ((argc - 2) % 5))
    return lsx_usage(effp);

  sscanf(argv[i++], "%f", &chorus->in_gain);
  sscanf(argv[i++], "%f", &chorus->out_gain);
  while (i < argc) {
    if (chorus->num_chorus > MAX_CHORUS) {
      lsx_fail("chorus: to many delays, use less than %i delays", MAX_CHORUS);
      return SOX_EOF;
    }
    sscanf(argv[i++], "%f", &chorus->delay[chorus->num_chorus]);
    sscanf(argv[i++], "%f", &chorus->decay[chorus->num_chorus]);
    sscanf(argv[i++], "%f", &chorus->speed[chorus->num_chorus]);
    sscanf(argv[i++], "%f", &chorus->depth[chorus->num_chorus]);
    if (!strcmp(argv[i], "-s"))
      chorus->modulation[chorus->num_chorus] = MOD_SINE;
    else if (!strcmp(argv[i], "-t"))
      chorus->modulation[chorus->num_chorus] = MOD_TRIANGLE;
    else
      return lsx_usage(effp);
    i++;
    chorus->num_chorus++;
  }
  return SOX_SUCCESS;
}

static int chorus_start(sox_effect_t *effp)
{
  chorus_priv_t *chorus = (chorus_priv_t *)effp->priv;
  int i;
  float sum_in_volume;

  chorus->maxsamples = 0;

  if (chorus->in_gain < 0.0) {
    lsx_fail("chorus: gain-in must be positive!");
    return SOX_EOF;
  }
  if (chorus->in_gain > 1.0) {
    lsx_fail("chorus: gain-in must be less than 1.0!");
    return SOX_EOF;
  }
  if (chorus->out_gain < 0.0) {
    lsx_fail("chorus: gain-out must be positive!");
    return SOX_EOF;
  }
  for (i = 0; i < chorus->num_chorus; i++) {
    chorus->samples[i] = (int)((chorus->delay[i] + chorus->depth[i]) * effp->in_signal.rate / 1000.0);
    chorus->depth_samples[i] = (int)(chorus->depth[i] * effp->in_signal.rate / 1000.0);

    if (chorus->delay[i] < 20.0) {
      lsx_fail("chorus: delay must be more than 20.0 msec!");
      return SOX_EOF;
    }
    if (chorus->delay[i] > 100.0) {
      lsx_fail("chorus: delay must be less than 100.0 msec!");
      return SOX_EOF;
    }
    if (chorus->speed[i] < 0.1) {
      lsx_fail("chorus: speed must be more than 0.1 Hz!");
      return SOX_EOF;
    }
    if (chorus->speed[i] > 5.0) {
      lsx_fail("chorus: speed must be less than 5.0 Hz!");
      return SOX_EOF;
    }
    if (chorus->depth[i] < 0.0) {
      lsx_fail("chorus: delay must be more positive!");
      return SOX_EOF;
    }
    if (chorus->depth[i] > 10.0) {
      lsx_fail("chorus: delay must be less than 10.0 msec!");
      return SOX_EOF;
    }
    if (chorus->decay[i] < 0.0) {
      lsx_fail("chorus: decay must be positive!");
      return SOX_EOF;
    }
    if (chorus->decay[i] > 1.0) {
      lsx_fail("chorus: decay must be less that 1.0!");
      return SOX_EOF;
    }
    chorus->length[i] = effp->in_signal.rate / chorus->speed[i];
    chorus->lookup_tab[i] = lsx_malloc(sizeof(int) * chorus->length[i]);

    if (chorus->modulation[i] == MOD_SINE)
      lsx_generate_wave_table(SOX_WAVE_SINE, SOX_INT, chorus->lookup_tab[i],
          (size_t)chorus->length[i], 0., (double)chorus->depth_samples[i], 0.);
    else
      lsx_generate_wave_table(SOX_WAVE_TRIANGLE, SOX_INT, chorus->lookup_tab[i],
          (size_t)chorus->length[i],
          (double)(chorus->samples[i] - 1 - 2 * chorus->depth_samples[i]),
          (double)(chorus->samples[i] - 1), 3 * M_PI_2);
    chorus->phase[i] = 0;

    if (chorus->samples[i] > chorus->maxsamples)
      chorus->maxsamples = chorus->samples[i];
  }

  sum_in_volume = 1.0;
  for (i = 0; i < chorus->num_chorus; i++)
    sum_in_volume += chorus->decay[i];
  if (chorus->in_gain * (sum_in_volume) > 1.0 / chorus->out_gain)
    lsx_warn("chorus: warning >>> gain-out can cause saturation or clipping of output <<<");

  chorus->chorusbuf = lsx_malloc(sizeof(float) * chorus->maxsamples);
  for (i = 0; i < chorus->maxsamples; i++)
    chorus->chorusbuf[i] = 0.0;

  chorus->counter = 0;
  chorus->fade_out = chorus->maxsamples;
  effp->out_signal.length = SOX_UNKNOWN_LEN;
  return SOX_SUCCESS;
}

static int chorus_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  chorus_priv_t *chorus = (chorus_priv_t *)effp->priv;
  int i;
  float d_in, d_out;
  sox_sample_t out;
  size_t len = min(*isamp, *osamp);
  *isamp = *osamp = len;

  while (len--) {
    d_in = (float)*ibuf++ / 256;
    d_out = d_in * chorus->in_gain;
    for (i = 0; i < chorus->num_chorus; i++)
      d_out += chorus->chorusbuf[(chorus->maxsamples + chorus->counter - chorus->lookup_tab[i][chorus->phase[i]]) % chorus->maxsamples] * chorus->decay[i];
    d_out = d_out * chorus->out_gain;
    out = SOX_24BIT_CLIP_COUNT((sox_sample_t)d_out, effp->clips);
    *obuf++ = out * 256;
    chorus->chorusbuf[chorus->counter] = d_in;
    chorus->counter = (chorus->counter + 1) % chorus->maxsamples;
    for (i = 0; i < chorus->num_chorus; i++)
      chorus->phase[i] = (chorus->phase[i] + 1) % chorus->length[i];
  }
  return SOX_SUCCESS;
}

static int chorus_drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{
  chorus_priv_t *chorus = (chorus_priv_t *)effp->priv;
  size_t done;
  int i;
  float d_in, d_out;
  sox_sample_t out;

  done = 0;
  while ((done < *osamp) && (done < chorus->fade_out)) {
    d_in = 0;
    d_out = 0;
    for (i = 0; i < chorus->num_chorus; i++)
      d_out += chorus->chorusbuf[(chorus->maxsamples + chorus->counter - chorus->lookup_tab[i][chorus->phase[i]]) % chorus->maxsamples] * chorus->decay[i];
    d_out = d_out * chorus->out_gain;
    out = SOX_24BIT_CLIP_COUNT((sox_sample_t)d_out, effp->clips);
    *obuf++ = out * 256;
    chorus->chorusbuf[chorus->counter] = d_in;
    chorus->counter = (chorus->counter + 1) % chorus->maxsamples;
    for (i = 0; i < chorus->num_chorus; i++)
      chorus->phase[i] = (chorus->phase[i] + 1) % chorus->length[i];
    done++;
    chorus->fade_out--;
  }
  *osamp = done;
  if (chorus->fade_out == 0)
    return SOX_EOF;
  else
    return SOX_SUCCESS;
}

static int chorus_stop(sox_effect_t *effp)
{
  chorus_priv_t *chorus = (chorus_priv_t *)effp->priv;
  int i;
  free(chorus->chorusbuf);
  chorus->chorusbuf = NULL;
  for (i = 0; i < chorus->num_chorus; i++) {
    free(chorus->lookup_tab[i]);
    chorus->lookup_tab[i] = NULL;
  }
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_chorus_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "chorus", USAGE_chorus, SOX_EFF_LENGTH | SOX_EFF_GAIN,
    chorus_getopts, chorus_start, chorus_flow, chorus_drain, chorus_stop, NULL, sizeof(chorus_priv_t)
  };
  return &handler;
}

/* ================= flanger ================= */
typedef enum { INTERP_LINEAR, INTERP_QUADRATIC } interp_t;
#define MAX_CHANNELS 4

typedef struct {
  double delay_min;
  double delay_depth;
  double feedback_gain;
  double delay_gain;
  double speed;
  lsx_wave_t wave_shape;
  double channel_phase;
  interp_t interpolation;
  double *delay_bufs[MAX_CHANNELS];
  size_t delay_buf_length;
  size_t delay_buf_pos;
  double delay_last[MAX_CHANNELS];
  float *lfo;
  size_t lfo_length;
  size_t lfo_pos;
  double in_gain;
} flanger_priv_t;

static lsx_enum_item const interp_enum[] = {
  {"linear", INTERP_LINEAR},
  {"quadratic", INTERP_QUADRATIC},
  {0, 0}};

static int flanger_getopts(sox_effect_t *effp, int argc, char *argv[])
{
  flanger_priv_t *p = (flanger_priv_t *)effp->priv;
  --argc, ++argv;

  p->delay_depth = 2;
  p->delay_gain = 71;
  p->speed = 0.5;
  p->channel_phase = 25;

  do {
    NUMERIC_PARAMETER(delay_min, 0, 30)
    NUMERIC_PARAMETER(delay_depth, 0, 10)
    NUMERIC_PARAMETER(feedback_gain, -95, 95)
    NUMERIC_PARAMETER(delay_gain, 0, 100)
    NUMERIC_PARAMETER(speed, 0.1, 10)
    TEXTUAL_PARAMETER(wave_shape, wave_enum)
    NUMERIC_PARAMETER(channel_phase, 0, 100)
    TEXTUAL_PARAMETER(interpolation, interp_enum)
  } while (0);

  if (argc != 0)
    return lsx_usage(effp);

  lsx_report("parameters:\n"
      "delay = %gms\n"
      "depth = %gms\n"
      "regen = %g%%\n"
      "width = %g%%\n"
      "speed = %gHz\n"
      "shape = %s\n"
      "phase = %g%%\n"
      "interp= %s",
      p->delay_min,
      p->delay_depth,
      p->feedback_gain,
      p->delay_gain,
      p->speed,
      wave_enum[p->wave_shape].name,
      p->channel_phase,
      interp_enum[p->interpolation].name);

  p->feedback_gain /= 100;
  p->delay_gain /= 100;
  p->channel_phase /= 100;
  p->delay_min /= 1000;
  p->delay_depth /= 1000;
  return SOX_SUCCESS;
}

static int flanger_start(sox_effect_t *effp)
{
  flanger_priv_t *f = (flanger_priv_t *)effp->priv;
  int c, channels = effp->in_signal.channels;

  if (channels > MAX_CHANNELS) {
    lsx_fail("Can not operate with more than %i channels", MAX_CHANNELS);
    return SOX_EOF;
  }

  f->in_gain = 1 / (1 + f->delay_gain);
  f->delay_gain /= 1 + f->delay_gain;
  f->delay_gain *= 1 - fabs(f->feedback_gain);

  lsx_debug("in_gain=%g feedback_gain=%g delay_gain=%g\n", f->in_gain, f->feedback_gain, f->delay_gain);

  f->delay_buf_length = (f->delay_min + f->delay_depth) * effp->in_signal.rate + 0.5;
  ++f->delay_buf_length;
  ++f->delay_buf_length;
  for (c = 0; c < channels; ++c)
    f->delay_bufs[c] = lsx_calloc(f->delay_buf_length, sizeof(*f->delay_bufs[0]));

  f->lfo_length = effp->in_signal.rate / f->speed;
  f->lfo = lsx_calloc(f->lfo_length, sizeof(*f->lfo));
  lsx_generate_wave_table(f->wave_shape, SOX_FLOAT, f->lfo, f->lfo_length,
      floor(f->delay_min * effp->in_signal.rate + .5), f->delay_buf_length - 2., 3 * M_PI_2);

  lsx_debug("delay_buf_length=%lu lfo_length=%lu\n", (unsigned long)f->delay_buf_length, (unsigned long)f->lfo_length);
  return SOX_SUCCESS;
}

static int flanger_flow(sox_effect_t *effp, sox_sample_t const *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  flanger_priv_t *f = (flanger_priv_t *)effp->priv;
  int c, channels = effp->in_signal.channels;
  size_t len = (*isamp > *osamp ? *osamp : *isamp) / channels;

  *isamp = *osamp = len * channels;

  while (len--) {
    f->delay_buf_pos = (f->delay_buf_pos + f->delay_buf_length - 1) % f->delay_buf_length;
    for (c = 0; c < channels; ++c) {
      double delayed_0, delayed_1;
      double delayed;
      double in, out;
      size_t channel_phase = c * f->lfo_length * f->channel_phase + .5;
      double delay = f->lfo[(f->lfo_pos + channel_phase) % f->lfo_length];
      double frac_delay = modf(delay, &delay);
      size_t int_delay = (size_t)delay;

      in = *ibuf++;
      f->delay_bufs[c][f->delay_buf_pos] = in + f->delay_last[c] * f->feedback_gain;

      delayed_0 = f->delay_bufs[c][(f->delay_buf_pos + int_delay++) % f->delay_buf_length];
      delayed_1 = f->delay_bufs[c][(f->delay_buf_pos + int_delay++) % f->delay_buf_length];

      if (f->interpolation == INTERP_LINEAR)
        delayed = delayed_0 + (delayed_1 - delayed_0) * frac_delay;
      else {
        double a, b;
        double delayed_2 = f->delay_bufs[c][(f->delay_buf_pos + int_delay++) % f->delay_buf_length];
        delayed_2 -= delayed_0;
        delayed_1 -= delayed_0;
        a = delayed_2 * .5 - delayed_1;
        b = delayed_1 * 2 - delayed_2 * .5;
        delayed = delayed_0 + (a * frac_delay + b) * frac_delay;
      }

      f->delay_last[c] = delayed;
      out = in * f->in_gain + delayed * f->delay_gain;
      *obuf++ = SOX_ROUND_CLIP_COUNT(out, effp->clips);
    }
    f->lfo_pos = (f->lfo_pos + 1) % f->lfo_length;
  }
  return SOX_SUCCESS;
}

static int flanger_stop(sox_effect_t *effp)
{
  flanger_priv_t *f = (flanger_priv_t *)effp->priv;
  int c, channels = effp->in_signal.channels;
  for (c = 0; c < channels && c < MAX_CHANNELS; ++c) {
    free(f->delay_bufs[c]);
    f->delay_bufs[c] = NULL;
  }
  free(f->lfo);
  f->lfo = NULL;
  memset(f, 0, sizeof(*f));
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_flanger_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "flanger", USAGE_flanger, SOX_EFF_MCHAN,
    flanger_getopts, flanger_start, flanger_flow, NULL, flanger_stop, NULL, sizeof(flanger_priv_t)
  };
  return &handler;
}

/* ================= phaser ================= */
typedef struct {
  double in_gain, out_gain, delay_ms, decay, mod_speed;
  lsx_wave_t mod_type;
  int *mod_buf;
  size_t mod_buf_len;
  int mod_pos;
  double *delay_buf;
  size_t delay_buf_len;
  int delay_pos;
} phaser_priv_t;

static int phaser_getopts(sox_effect_t *effp, int argc, char **argv)
{
  phaser_priv_t *p = (phaser_priv_t *)effp->priv;
  char chars[2];

  p->in_gain = .4;
  p->out_gain = .74;
  p->delay_ms = 3.;
  p->decay = .4;
  p->mod_speed = .5;

  --argc, ++argv;
  do {
    NUMERIC_PARAMETER(in_gain, .0, 1)
    NUMERIC_PARAMETER(out_gain, .0, 1e9)
    NUMERIC_PARAMETER(delay_ms, .0, 5)
    NUMERIC_PARAMETER(decay, .0, .99)
    NUMERIC_PARAMETER(mod_speed, .1, 2)
  } while (0);

  if (argc && sscanf(*argv, "-%1[st]%c", chars, chars + 1) == 1) {
    p->mod_type = *chars == 's' ? SOX_WAVE_SINE : SOX_WAVE_TRIANGLE;
    --argc, ++argv;
  }

  if (p->in_gain > (1 - p->decay * p->decay))
    lsx_warn("warning: gain-in might cause clipping");
  if (p->in_gain / (1 - p->decay) > 1 / p->out_gain)
    lsx_warn("warning: gain-out might cause clipping");

  return argc ? lsx_usage(effp) : SOX_SUCCESS;
}

static int phaser_start(sox_effect_t *effp)
{
  phaser_priv_t *p = (phaser_priv_t *)effp->priv;

  p->delay_buf_len = p->delay_ms * .001 * effp->in_signal.rate + .5;
  p->delay_buf = lsx_calloc(p->delay_buf_len, sizeof(*p->delay_buf));

  p->mod_buf_len = effp->in_signal.rate / p->mod_speed + .5;
  p->mod_buf = lsx_malloc(p->mod_buf_len * sizeof(*p->mod_buf));
  lsx_generate_wave_table(p->mod_type, SOX_INT, p->mod_buf, p->mod_buf_len, 1., (double)p->delay_buf_len, M_PI_2);

  p->delay_pos = p->mod_pos = 0;
  effp->out_signal.length = SOX_UNKNOWN_LEN;
  return SOX_SUCCESS;
}

static int phaser_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  phaser_priv_t *p = (phaser_priv_t *)effp->priv;
  size_t len = *isamp = *osamp = min(*isamp, *osamp);

  while (len--) {
    double d = *ibuf++ * p->in_gain + p->delay_buf[(p->delay_pos + p->mod_buf[p->mod_pos]) % p->delay_buf_len] * p->decay;
    p->mod_pos = (p->mod_pos + 1) % p->mod_buf_len;
    p->delay_pos = (p->delay_pos + 1) % p->delay_buf_len;
    p->delay_buf[p->delay_pos] = d;
    *obuf++ = SOX_ROUND_CLIP_COUNT(d * p->out_gain, effp->clips);
  }
  return SOX_SUCCESS;
}

static int phaser_stop(sox_effect_t *effp)
{
  phaser_priv_t *p = (phaser_priv_t *)effp->priv;
  free(p->delay_buf);
  free(p->mod_buf);
  p->delay_buf = NULL; p->mod_buf = NULL;
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_phaser_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "phaser", USAGE_phaser, SOX_EFF_LENGTH | SOX_EFF_GAIN,
    phaser_getopts, phaser_start, phaser_flow, NULL, phaser_stop, NULL, sizeof(phaser_priv_t)
  };
  return &handler;
}
