#ifndef FIFO_H
#define FIFO_H
#include "sox.h"
typedef struct {
  char *data;
  size_t allocation;
  size_t item_size;
  size_t begin;
  size_t end;
} fifo_t;

#define FIFO_MIN 0x4000

static inline void fifo_clear(fifo_t *f) { f->end = f->begin = 0; }

static inline void *fifo_reserve(fifo_t *f, size_t n)
{
  n *= f->item_size;
  if (f->begin == f->end)
    fifo_clear(f);
  while (1) {
    if (f->end + n <= f->allocation) {
      void *p = f->data + f->end;
      f->end += n;
      return p;
    }
    if (f->begin > FIFO_MIN) {
      memmove(f->data, f->data + f->begin, f->end - f->begin);
      f->end -= f->begin;
      f->begin = 0;
      continue;
    }
    f->allocation += n;
    f->data = lsx_realloc(f->data, f->allocation);
  }
}

static inline void *fifo_write(fifo_t *f, size_t n, void const *data)
{
  void *s = fifo_reserve(f, n);
  if (data)
    memcpy(s, data, n * f->item_size);
  return s;
}

static inline void fifo_trim_to(fifo_t *f, size_t n)
{
  n *= f->item_size;
  f->end = f->begin + n;
}

static inline void fifo_trim_by(fifo_t *f, size_t n)
{
  n *= f->item_size;
  f->end -= n;
}

static inline size_t fifo_occupancy(fifo_t *f)
{
  return (f->end - f->begin) / f->item_size;
}

static inline void *fifo_read(fifo_t *f, size_t n, void *data)
{
  char *ret = f->data + f->begin;
  n *= f->item_size;
  if (n > (size_t)(f->end - f->begin))
    return NULL;
  if (data)
    memcpy(data, ret, (size_t)n);
  f->begin += n;
  return ret;
}

#define fifo_read_ptr(f) fifo_read(f, (size_t)0, NULL)

static inline void fifo_delete(fifo_t *f)
{
  free(f->data);
  f->data = NULL;
}

static inline void fifo_create(fifo_t *f, size_t item_size)
{
  f->item_size = item_size;
  f->allocation = FIFO_MIN;
  f->data = lsx_malloc(f->allocation);
  fifo_clear(f);
}
#endif
