static int start(sox_effect_t *effp)
{
  priv_t *silence = (priv_t *)effp->priv;
  uint64_t temp;

  silence->window_size = (effp->in_signal.rate / 50) * effp->in_signal.channels;
  silence->window = lsx_malloc(silence->window_size * sizeof(double));

  clear_rms(effp);

  if (silence->start) {
    if (lsx_parsesamples(effp->in_signal.rate, silence->start_duration_str, &temp, 's') == NULL)
      return lsx_usage(effp);
    silence->start_duration = temp * effp->in_signal.channels;
  }
  if (silence->stop) {
    if (lsx_parsesamples(effp->in_signal.rate, silence->stop_duration_str, &temp, 's') == NULL)
      return lsx_usage(effp);
    silence->stop_duration = temp * effp->in_signal.channels;
  }

  if (silence->start)
    silence->mode = SILENCE_TRIM;
  else
    silence->mode = SILENCE_COPY;

  silence->start_holdoff = lsx_malloc(sizeof(sox_sample_t) * silence->start_duration + 1);
  silence->start_holdoff_offset = 0;
  silence->start_holdoff_end = 0;
  silence->start_found_periods = 0;

  silence->stop_holdoff = lsx_malloc(sizeof(sox_sample_t) * silence->stop_duration + 1);
  silence->stop_holdoff_offset = 0;
  silence->stop_holdoff_end = 0;
  silence->stop_found_periods = 0;

  effp->out_signal.length = SOX_UNKNOWN_LEN;
  return SOX_SUCCESS;
}

static sox_bool aboveThreshold(sox_effect_t const *effp, sox_sample_t value, double threshold, int unit)
{
  sox_sample_t masked_value = value & (-1 << (32 - effp->in_signal.precision));
  double scaled_value = (double)masked_value / SOX_SAMPLE_MAX;

  if (unit == '%')
    scaled_value *= 100;
  else if (unit == 'd')
    scaled_value = linear_to_dB(scaled_value);

  return scaled_value > threshold;
}

static sox_sample_t compute_rms(sox_effect_t *effp, sox_sample_t sample)
{
  priv_t *silence = (priv_t *)effp->priv;
  double new_sum;
  sox_sample_t rms;

  new_sum = silence->rms_sum;
  new_sum -= *silence->window_current;
  new_sum += ((double)sample * (double)sample);

  rms = sqrt(new_sum / silence->window_size);
  return rms;
}

static void update_rms(sox_effect_t *effp, sox_sample_t sample)
{
  priv_t *silence = (priv_t *)effp->priv;

  silence->rms_sum -= *silence->window_current;
  *silence->window_current = ((double)sample * (double)sample);
  silence->rms_sum += *silence->window_current;

  silence->window_current++;
  if (silence->window_current >= silence->window_end)
    silence->window_current = silence->window;
}

static int flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  priv_t *silence = (priv_t *)effp->priv;
  int threshold;
  size_t i, j;
  size_t nrOfTicks, nrOfInSamplesRead, nrOfOutSamplesWritten;

  nrOfInSamplesRead = 0;
  nrOfOutSamplesWritten = 0;

  switch (silence->mode) {
    case SILENCE_TRIM:
silence_trim:
      nrOfTicks = min((*isamp - nrOfInSamplesRead), (*osamp - nrOfOutSamplesWritten)) / effp->in_signal.channels;
      for (i = 0; i < nrOfTicks; i++) {
        threshold = 0;
        for (j = 0; j < effp->in_signal.channels; j++) {
          threshold |= aboveThreshold(effp, compute_rms(effp, ibuf[j]), silence->start_threshold, silence->start_unit);
        }

        if (threshold) {
          for (j = 0; j < effp->in_signal.channels; j++) {
            update_rms(effp, *ibuf);
            silence->start_holdoff[silence->start_holdoff_end++] = *ibuf++;
            nrOfInSamplesRead++;
          }

          if (silence->start_holdoff_end >= silence->start_duration) {
            if (++silence->start_found_periods >= silence->start_periods) {
              silence->mode = SILENCE_TRIM_FLUSH;
              goto silence_trim_flush;
            }
            silence->start_holdoff_offset = 0;
            silence->start_holdoff_end = 0;
          }
        } else {
          silence->start_holdoff_end = 0;
          for (j = 0; j < effp->in_signal.channels; j++) {
            update_rms(effp, ibuf[j]);
          }
          ibuf += effp->in_signal.channels;
          nrOfInSamplesRead += effp->in_signal.channels;
        }
      }
      break;

    case SILENCE_TRIM_FLUSH:
silence_trim_flush:
      nrOfTicks = min((silence->start_holdoff_end - silence->start_holdoff_offset), (*osamp - nrOfOutSamplesWritten));
      nrOfTicks -= nrOfTicks % effp->in_signal.channels;
      for (i = 0; i < nrOfTicks; i++) {
        *obuf++ = silence->start_holdoff[silence->start_holdoff_offset++];
        nrOfOutSamplesWritten++;
      }

      if (silence->start_holdoff_offset == silence->start_holdoff_end) {
        silence->start_holdoff_offset = 0;
        silence->start_holdoff_end = 0;
        silence->mode = SILENCE_COPY;
        goto silence_copy;
      }
      break;

    case SILENCE_COPY:
silence_copy:
      nrOfTicks = min((*isamp - nrOfInSamplesRead), (*osamp - nrOfOutSamplesWritten)) / effp->in_signal.channels;
      if (silence->stop) {
        for (i = 0; i < nrOfTicks; i++) {
          threshold = 1;
          for (j = 0; j < effp->in_signal.channels; j++) {
            threshold &= aboveThreshold(effp, compute_rms(effp, ibuf[j]), silence->stop_threshold, silence->stop_unit);
          }

          if (threshold) {
            for (j = 0; j < effp->in_signal.channels; j++) {
              update_rms(effp, *ibuf);
              *obuf++ = *ibuf++;
              nrOfInSamplesRead++;
              nrOfOutSamplesWritten++;
            }
          } else if (!threshold) {
            for (j = 0; j < effp->in_signal.channels; j++) {
              update_rms(effp, *ibuf);
              silence->stop_holdoff[silence->stop_holdoff_end++] = *ibuf++;
              nrOfInSamplesRead++;
            }

            if (silence->stop_holdoff_end >= silence->stop_duration) {
              if (++silence->stop_found_periods >= silence->stop_periods) {
                silence->stop_holdoff_offset = 0;
                silence->stop_holdoff_end = 0;
                if (!silence->restart) {
                  *isamp = nrOfInSamplesRead;
                  *osamp = nrOfOutSamplesWritten;
                  silence->mode = SILENCE_STOP;
                  return SOX_EOF;
                } else {
                  silence->stop_found_periods = 0;
                  silence->start_found_periods = 0;
                  silence->start_holdoff_offset = 0;
                  silence->start_holdoff_end = 0;
                  clear_rms(effp);
                  silence->mode = SILENCE_TRIM;
                  goto silence_trim;
                }
              } else {
                silence->mode = SILENCE_COPY_FLUSH;
                goto silence_copy_flush;
              }
              break;
            }
          }
        }
      } else {
        memcpy(obuf, ibuf, sizeof(sox_sample_t) * nrOfTicks * effp->in_signal.channels);
        nrOfInSamplesRead += (nrOfTicks * effp->in_signal.channels);
        nrOfOutSamplesWritten += (nrOfTicks * effp->in_signal.channels);
      }
      break;

    case SILENCE_COPY_FLUSH:
silence_copy_flush:
      nrOfTicks = min((silence->stop_holdoff_end - silence->stop_holdoff_offset), (*osamp - nrOfOutSamplesWritten));
      nrOfTicks -= nrOfTicks % effp->in_signal.channels;

      for (i = 0; i < nrOfTicks; i++) {
        *obuf++ = silence->stop_holdoff[silence->stop_holdoff_offset++];
        nrOfOutSamplesWritten++;
      }

      if (silence->stop_holdoff_offset == silence->stop_holdoff_end) {
        silence->stop_holdoff_offset = 0;
        silence->stop_holdoff_end = 0;
        silence->mode = SILENCE_COPY;
        goto silence_copy;
      }
      break;

    case SILENCE_STOP:
      nrOfInSamplesRead = *isamp;
      break;
  }

  *isamp = nrOfInSamplesRead;
  *osamp = nrOfOutSamplesWritten;
  return SOX_SUCCESS;
}

static int drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{
  priv_t *silence = (priv_t *)effp->priv;
  size_t i;
  size_t nrOfTicks, nrOfOutSamplesWritten = 0;

  if (silence->mode == SILENCE_COPY_FLUSH || silence->mode == SILENCE_COPY) {
    nrOfTicks = min((silence->stop_holdoff_end - silence->stop_holdoff_offset), *osamp);
    nrOfTicks -= nrOfTicks % effp->in_signal.channels;
    for (i = 0; i < nrOfTicks; i++) {
      *obuf++ = silence->stop_holdoff[silence->stop_holdoff_offset++];
      nrOfOutSamplesWritten++;
    }
    if (silence->stop_holdoff_offset == silence->stop_holdoff_end) {
      silence->stop_holdoff_offset = 0;
      silence->stop_holdoff_end = 0;
      silence->mode = SILENCE_STOP;
    }
  }

  *osamp = nrOfOutSamplesWritten;
  if (silence->mode == SILENCE_STOP || *osamp == 0)
    return SOX_EOF;
  else
    return SOX_SUCCESS;
}

static int stop(sox_effect_t *effp)
{
  priv_t *silence = (priv_t *)effp->priv;
  free(silence->window);
  free(silence->start_holdoff);
  free(silence->stop_holdoff);
  silence->window = NULL; silence->start_holdoff = silence->stop_holdoff = NULL;
  return SOX_SUCCESS;
}

static int lsx_kill(sox_effect_t *effp)
{
  priv_t *silence = (priv_t *)effp->priv;
  free(silence->start_duration_str);
  free(silence->stop_duration_str);
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_silence_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "silence", USAGE_silence, SOX_EFF_MCHAN | SOX_EFF_MODIFY | SOX_EFF_LENGTH,
    getopts, start, flow, drain, stop, lsx_kill, sizeof(priv_t)
  };
  return &handler;
}
