/* rate effect: band-limited resampling (windowed-sinc, Kaiser window).
 * Also: speed effect. */
#include "sox.h"
#include "usage_strings.h"

typedef struct {
  double out_rate;
  int quality;
  double phase;
  double bandwidth;
  sox_bool allow_aliasing;
  /* runtime */
  double factor;        /* in_rate / out_rate */
  double fc;            /* cutoff, cycles per input sample */
  double half_len;      /* half filter length in input samples */
  double beta;
  int table_res;        /* table points per input sample */
  double *table;        /* h(t) for t in [0, half_len], step 1/table_res */
  size_t table_len;
  double *buf;          /* input history */
  size_t buf_len, buf_alloc;
  uint64_t buf_start;   /* absolute index of buf[0] */
  uint64_t samples_in, samples_out;
  sox_bool flushing;
  uint64_t target_out;
} priv_t;

static int create(sox_effect_t *effp, int argc, char **argv)
{
  priv_t *p = (priv_t *)effp->priv;
  int c;
  char *dummy_p, *found_at;
  char const *opts = "+i:c:b:B:A:p:Q:R:d:MILafnost" "qlmhv";
  char const *qopts = strchr(opts, 'q');
  lsx_getopt_t optstate;
  lsx_getopt_init(argc, argv, opts, NULL, lsx_getopt_flag_none, 1, &optstate);

  p->quality = -1;
  p->phase = 50;

  while ((c = lsx_getopt(&optstate)) != -1) switch (c) {
    case 'i': case 'c': case 'B': case 'A': case 'd': case 'R': case 'Q': break;
    case 'p': {
      char *e; double d = strtod(optstate.arg, &e);
      if (e == optstate.arg || d < 0 || d > 100 || *e) {
        lsx_fail("parameter `%s' must be between %g and %g", "p->phase", 0., 100.);
        return lsx_usage(effp);
      }
      p->phase = d; break;
    }
    case 'b': {
      char *e; double d = strtod(optstate.arg, &e);
      if (e == optstate.arg || d < 74 || d > 99.7 || *e) {
        lsx_fail("parameter `%s' must be between %g and %g", "bw_3dB_pc", 74., 99.7);
        return lsx_usage(effp);
      }
      p->bandwidth = d; break;
    }
    case 'M': p->phase = 0; break;
    case 'I': p->phase = 25; break;
    case 'L': p->phase = 50; break;
    case 'a': p->allow_aliasing = sox_true; break;
    case 'f': case 'n': case 't': break;
    case 's': p->bandwidth = 99; break;
    default:
      if ((found_at = strchr(qopts, c))) p->quality = found_at - qopts;
      else { lsx_fail("unknown option `-%c'", optstate.opt); return lsx_usage(effp); }
  }
  argc -= optstate.ind, argv += optstate.ind;

  if ((unsigned)p->quality < 2 && (p->bandwidth || p->phase != 50 || p->allow_aliasing)) {
    lsx_fail("override options not allowed with this quality level");
    return SOX_EOF;
  }

  if (argc) {
    if ((p->out_rate = lsx_parse_frequency(*argv, &dummy_p)) <= 0 || *dummy_p)
      return lsx_usage(effp);
    argc--; argv++;
    effp->out_signal.rate = p->out_rate;
  }
  return argc ? lsx_usage(effp) : SOX_SUCCESS;
}

static double kaiser_beta(double att)
{
  if (att > 50) return .1102 * (att - 8.7);
  if (att > 20.96) return .58417 * pow(att - 20.96, .4) + .07886 * (att - 20.96);
  return 0;
}

static int start(sox_effect_t *effp)
{
  priv_t *p = (priv_t *)effp->priv;
  double out_rate = p->out_rate != 0 ? p->out_rate : effp->out_signal.rate;
  double att, bw, tr, lower;
  size_t i;

  if (effp->in_signal.rate == out_rate)
    return SOX_EFF_NULL;

  if (effp->in_signal.mult)
    *effp->in_signal.mult *= .705;

  effp->out_signal.channels = effp->in_signal.channels;
  effp->out_signal.rate = out_rate;

  p->factor = effp->in_signal.rate / out_rate;
  switch (p->quality) {
    case 0: att = 40; bw = .80; break;
    case 1: att = 100; bw = .80; break;
    case 2: att = 100; bw = .913628; break;
    case 4: att = 175; bw = .91151; break;
    default: att = 126.433; bw = .913628; break;
  }
  if (p->bandwidth) bw = 1 - (1 - p->bandwidth / 100) * 2 * .5;
  if (bw > .995) bw = .995;
  lower = min(1., 1. / p->factor);       /* lower Nyquist relative to input Nyquist */
  tr = (1 - bw) * lower * .5;            /* transition width, cycles per input sample */
  p->fc = (1 + bw) * .5 * lower * .5;    /* 6dB cutoff, cycles per input sample */
  p->beta = kaiser_beta(att);
  {
    double n = (att - 7.95) / (2.285 * 2 * M_PI * tr);
    p->half_len = ceil(n / 2) + 1;
  }
  p->table_res = 1024;
  p->table_len = (size_t)(p->half_len * p->table_res) + 2;
  p->table = lsx_malloc(p->table_len * sizeof(double));
  {
    double i0b = lsx_bessel_I_0(p->beta);
    for (i = 0; i < p->table_len; ++i) {
      double t = (double)i / p->table_res;
      double x = t / p->half_len, w, s;
      if (x >= 1) { p->table[i] = 0; continue; }
      w = lsx_bessel_I_0(p->beta * sqrt(1 - x * x)) / i0b;
      s = t == 0 ? 2 * p->fc : sin(2 * M_PI * p->fc * t) / (M_PI * t);
      p->table[i] = s * w;
    }
  }
  p->buf_alloc = 1024;
  p->buf = lsx_calloc(p->buf_alloc, sizeof(double));
  p->buf_len = 0;
  p->buf_start = 0;
  p->samples_in = p->samples_out = 0;
  p->flushing = sox_false;
  return SOX_SUCCESS;
}

static double h_at(priv_t *p, double t)
{
  double a = fabs(t) * p->table_res;
  size_t i = (size_t)a;
  double f = a - i;
  if (i + 1 >= p->table_len) return 0;
  return p->table[i] + (p->table[i + 1] - p->table[i]) * f;
}

/* value of the input at absolute index n (0 outside known data) */
static inline double in_at(priv_t *p, int64_t n)
{
  if (n < (int64_t)p->buf_start || n >= (int64_t)(p->buf_start + p->buf_len)) return 0;
  return p->buf[n - p->buf_start];
}

static size_t produce(priv_t *p, sox_sample_t *obuf, size_t max_out, sox_bool final, size_t *clips)
{
  size_t done = 0;
  while (done < max_out) {
    double t = (double)p->samples_out * p->factor;
    int64_t lo = (int64_t)ceil(t - p->half_len), hi = (int64_t)floor(t + p->half_len);
    int64_t n;
    double sum = 0;
    if (final) {
      if (p->samples_out >= p->target_out) break;
    } else if (hi >= (int64_t)(p->buf_start + p->buf_len))
      break;
    for (n = lo; n <= hi; ++n) {
      double x = in_at(p, n);
      if (x != 0) sum += x * h_at(p, t - n);
    }
    *obuf++ = SOX_ROUND_CLIP_COUNT(sum, *clips);
    ++done;
    ++p->samples_out;
  }
  /* discard history no longer needed */
  {
    double t = (double)p->samples_out * p->factor;
    int64_t keep_from = (int64_t)floor(t - p->half_len) - 1;
    if (keep_from > (int64_t)p->buf_start) {
      size_t drop = (size_t)min((uint64_t)(keep_from - (int64_t)p->buf_start), (uint64_t)p->buf_len);
      memmove(p->buf, p->buf + drop, (p->buf_len - drop) * sizeof(double));
      p->buf_len -= drop;
      p->buf_start += drop;
    }
  }
  return done;
}

static int flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  priv_t *p = (priv_t *)effp->priv;
  size_t i, n = *isamp;
  size_t odone;
  /* only accept input if we can produce output into the buffer */
  if (p->buf_len + n > p->buf_alloc) {
    p->buf_alloc = (p->buf_len + n) * 2;
    p->buf = lsx_realloc(p->buf, p->buf_alloc * sizeof(double));
  }
  for (i = 0; i < n; ++i)
    p->buf[p->buf_len + i] = ibuf[i];
  p->buf_len += n;
  p->samples_in += n;
  odone = produce(p, obuf, *osamp, sox_false, &effp->clips);
  *osamp = odone;
  *isamp = n;
  return SOX_SUCCESS;
}

static int drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{
  priv_t *p = (priv_t *)effp->priv;
  if (!p->flushing) {
    p->flushing = sox_true;
    p->target_out = (uint64_t)(p->samples_in / p->factor + .5);
  }
  *osamp = produce(p, obuf, *osamp, sox_true, &effp->clips);
  return p->samples_out >= p->target_out ? SOX_EOF : SOX_SUCCESS;
}

static int stop(sox_effect_t *effp)
{
  priv_t *p = (priv_t *)effp->priv;
  free(p->table);
  free(p->buf);
  p->table = NULL; p->buf = NULL;
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_rate_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "rate", USAGE_rate, SOX_EFF_RATE | SOX_EFF_GAIN,
    create, start, flow, drain, stop, NULL, sizeof(priv_t)
  };
  return &handler;
}

/* ================= speed ================= */
typedef struct { double factor; } speed_priv_t;

static int speed_getopts(sox_effect_t *effp, int argc, char **argv)
{
  speed_priv_t *p = (speed_priv_t *)effp->priv;
  sox_bool is_cents = sox_false;
  char c, dummy;

  --argc, ++argv;
  if (argc == 1) {
    if (sscanf(*argv, "%lf %c %c", &p->factor, &c, &dummy) == 2 && c == 'c')
      is_cents = sox_true;
    else if (sscanf(*argv, "%lf %c", &p->factor, &dummy) != 1)
      return lsx_usage(effp);
    if (is_cents)
      p->factor = pow(2., p->factor / 1200);
    if (p->factor <= 0)
      return lsx_usage(effp);
    return SOX_SUCCESS;
  }
  return lsx_usage(effp);
}

static int speed_start(sox_effect_t *effp)
{
  speed_priv_t *p = (speed_priv_t *)effp->priv;
  if (p->factor == 1)
    return SOX_EFF_NULL;
  effp->out_signal.rate = effp->in_signal.rate * p->factor;
  effp->out_signal.length = effp->in_signal.length;
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_speed_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "speed", USAGE_speed, SOX_EFF_MCHAN | SOX_EFF_RATE | SOX_EFF_LENGTH | SOX_EFF_MODIFY,
    speed_getopts, speed_start, lsx_flow_copy, 0, 0, 0, sizeof(speed_priv_t)
  };
  return &handler;
}
