/* ===================================================================== */
/* IRCAM sf */
static struct { char str[4]; sox_bool reverse_bytes; char const *desc; } sf_id[] = {
  {"\144\243\001\0", 0, "little-endian VAX (native)"},
  {"\0\001\243\144", 1, "big-endian VAX"},
  {"\144\243\002\0", 1, "big-endian Sun (native)"},
  {"\0\002\243\144", 0, "little-endian Sun"},
  {"\144\243\003\0", 0, "little-endian MIPS (DEC)"},
  {"\0\003\243\144", 1, "big-endian MIPS (SGI)"},
  {"\144\243\004\0", 1, "big-endian NeXT"},
  {"    ", 0, NULL}
};
#define SF_FIXED_HDR 1024
#define SF_COMMENT 2
typedef enum { sf_Unspecified, sf_Linear_8 = 0x00001, sf_Alaw_8 = 0x10001, sf_Mulaw_8 = 0x20001, sf_Linear_16 = 0x00002,
  sf_Linear_24 = 0x00003, sf_Linear_32 = 0x40004, sf_Float = 0x00004, sf_Double = 0x00008 } sf_enc_t;

static sf_enc_t sf_ft_enc(unsigned size, sox_encoding_t encoding)
{
  if (encoding == SOX_ENCODING_ULAW && size == 8) return sf_Mulaw_8;
  if (encoding == SOX_ENCODING_ALAW && size == 8) return sf_Alaw_8;
  if (encoding == SOX_ENCODING_SIGN2 && size == 8) return sf_Linear_8;
  if (encoding == SOX_ENCODING_SIGN2 && size == 16) return sf_Linear_16;
  if (encoding == SOX_ENCODING_SIGN2 && size == 24) return sf_Linear_24;
  if (encoding == SOX_ENCODING_SIGN2 && size == 32) return sf_Linear_32;
  if (encoding == SOX_ENCODING_FLOAT && size == 32) return sf_Float;
  if (encoding == SOX_ENCODING_FLOAT && size == 64) return sf_Double;
  return sf_Unspecified;
}

static sox_encoding_t sf_sox_enc(uint32_t e, unsigned *size)
{
  switch (e) {
    case sf_Mulaw_8: *size = 8; return SOX_ENCODING_ULAW;
    case sf_Alaw_8: *size = 8; return SOX_ENCODING_ALAW;
    case sf_Linear_8: *size = 8; return SOX_ENCODING_SIGN2;
    case sf_Linear_16: *size = 16; return SOX_ENCODING_SIGN2;
    case sf_Linear_24: *size = 24; return SOX_ENCODING_SIGN2;
    case sf_Linear_32: *size = 32; return SOX_ENCODING_SIGN2;
    case sf_Float: *size = 32; return SOX_ENCODING_FLOAT;
    case sf_Double: *size = 64; return SOX_ENCODING_FLOAT;
    default: return SOX_ENCODING_UNKNOWN;
  }
}

static int sf_startread(sox_format_t *ft)
{
  char magic[4];
  float rate;
  uint32_t channels, ft_encoding;
  unsigned i, bits_per_sample = 0;
  sox_encoding_t encoding;
  uint16_t code, size;

  if (lsx_readchars(ft, magic, sizeof(magic)))
    return SOX_EOF;

  for (i = 0; sf_id[i].desc && memcmp(magic, sf_id[i].str, sizeof(magic)); ++i);
  if (!sf_id[i].desc) {
    lsx_fail_errno(ft, SOX_EHDR, "sf: can't find IRCAM identifier");
    return SOX_EOF;
  }
  lsx_report("found %s identifier", sf_id[i].desc);
  ft->encoding.reverse_bytes = sf_id[i].reverse_bytes;

  if (lsx_readf(ft, &rate) || lsx_readdw(ft, &channels) || lsx_readdw(ft, &ft_encoding))
    return SOX_EOF;

  if (!(encoding = sf_sox_enc(ft_encoding, &bits_per_sample))) {
    lsx_fail_errno(ft, SOX_EFMT, "sf: unsupported encoding %#x)", ft_encoding);
    return SOX_EOF;
  }
  do {
    if (lsx_readw(ft, &code) || lsx_readw(ft, &size))
      return SOX_EOF;
    if (code == SF_COMMENT) {
      char *buf = lsx_calloc(1, (size_t)size + 1);
      if (lsx_readchars(ft, buf, (size_t)size) != SOX_SUCCESS) {
        free(buf);
        return SOX_EOF;
      }
      sox_append_comments(&ft->comments, buf);
      free(buf);
    } else if (lsx_skipbytes(ft, (size_t)size))
      return SOX_EOF;
  } while (code);
  if (lsx_skipbytes(ft, SF_FIXED_HDR - (size_t)lsx_tell(ft)))
    return SOX_EOF;

  return lsx_check_read_params(ft, channels, rate, encoding, bits_per_sample, (uint64_t)0, sox_true);
}

static int sf_write_header(sox_format_t *ft)
{
  char *comment = cat_comments(&ft->comments);
  size_t len = min(SF_FIXED_HDR - 4 - 3 * 4 - 4 * 2, strlen(comment) + 1);
  size_t info_len = max(4, (len + 3) & ~3u);
  int i = ft->encoding.reverse_bytes == 0 ? 0 : 2;
  sox_bool error = sox_false
    || writechars(ft, sf_id[i].str, sizeof(sf_id[i].str))
    || lsx_writef(ft, ft->signal.rate)
    || lsx_writedw(ft, ft->signal.channels)
    || lsx_writedw(ft, sf_ft_enc(ft->encoding.bits_per_sample, ft->encoding.encoding))
    || lsx_writew(ft, SF_COMMENT)
    || lsx_writew(ft, (unsigned)info_len)
    || writechars(ft, comment, len)
    || lsx_padbytes(ft, SF_FIXED_HDR - (size_t)lsx_tell(ft));
  free(comment);
  return error ? SOX_EOF : SOX_SUCCESS;
}

const sox_format_handler_t *lsx_sf_format_fn(void)
{
  static char const *const names[] = {"sf", "ircam", NULL};
  static unsigned const write_encodings[] = {
    SOX_ENCODING_ULAW, 8, 0,
    SOX_ENCODING_ALAW, 8, 0,
    SOX_ENCODING_SIGN2, 8, 16, 24, 32, 0,
    SOX_ENCODING_FLOAT, 32, 64, 0,
    0};
  static sox_format_handler_t const handler = {
    "Institut de Recherche et Coordination Acoustique/Musique", names, SOX_FILE_LIT_END,
    sf_startread, lsx_rawread, NULL,
    sf_write_header, lsx_rawwrite, NULL,
    lsx_rawseek, write_encodings, NULL, 0
  };
  return &handler;
}

/* ===================================================================== */
/* 8SVX */
typedef struct {
  uint64_t nsamples;
  uint64_t left;
  off_t ch0_pos;
  sox_uint8_t_dummy;
} svx_dummy_t;

typedef struct {
  uint64_t nsamples;
  uint64_t left;
  off_t ch0_pos;
  FILE *ch[4];
} svx_priv_t;

static void svx_writeheader(sox_format_t *ft, size_t nsamples)
{
  size_t formsize = nsamples + 8 + 4 + 8 + 20 + 8 + 32 + 8 + 4;

  lsx_writes(ft, "FORM");
  lsx_writedw(ft, (unsigned)formsize);
  lsx_writes(ft, "8SVX");

  lsx_writes(ft, "VHDR");
  lsx_writedw(ft, 20);
  lsx_writedw(ft, (unsigned)nsamples / ft->signal.channels);
  lsx_writedw(ft, 0);
  lsx_writedw(ft, 0);
  lsx_writew(ft, min(65535, (unsigned)(ft->signal.rate + .5)));
  lsx_writeb(ft, 1);
  lsx_writeb(ft, 0);
  lsx_writew(ft, 1); lsx_writew(ft, 0);

  lsx_writes(ft, "ANNO");
  lsx_writedw(ft, 32);
  lsx_writes(ft, "File created by Sound Exchange  ");

  lsx_writes(ft, "CHAN");
  lsx_writedw(ft, 4);
  lsx_writedw(ft, (ft->signal.channels == 2) ? 6u : (ft->signal.channels == 4) ? 15u : 2u);

  lsx_writes(ft, "BODY");
  lsx_writedw(ft, (unsigned)nsamples);
}

static int svx_startread(sox_format_t *ft)
{
  svx_priv_t *p = (svx_priv_t *)ft->priv;
  char buf[12];
  char *chunk_buf;
  uint32_t totalsize;
  uint32_t chunksize;
  uint32_t channels;
  unsigned short rate;
  int i;
  off_t chan1_pos;

  if (!ft->seekable) {
    lsx_fail_errno(ft, SOX_EINVAL, "8svx input file must be a file, not a pipe");
    return SOX_EOF;
  }
  rate = 0;
  channels = 1;

  if (lsx_readbuf(ft, buf, 4) != 4 || strncmp(buf, "FORM", 4) != 0) {
    lsx_fail_errno(ft, SOX_EHDR, "Header did not begin with magic word `FORM'");
    return SOX_EOF;
  }
  lsx_readdw(ft, &totalsize);
  if (lsx_readbuf(ft, buf, 4) != 4 || strncmp(buf, "8SVX", 4) != 0) {
    lsx_fail_errno(ft, SOX_EHDR, "'FORM' chunk does not specify `8SVX' as type");
    return SOX_EOF;
  }

  while (1) {
    if (lsx_readbuf(ft, buf, 4) != 4) {
      lsx_fail_errno(ft, SOX_EHDR, "Missing BODY chunk in 8SVX file");
      return SOX_EOF;
    }
    if (strncmp(buf, "VHDR", 4) == 0) {
      uint32_t oneshot;
      uint8_t oct, comp;
      lsx_readdw(ft, &chunksize);
      if (chunksize != 20) {
        lsx_fail_errno(ft, SOX_EHDR, "VHDR chunk has bad size");
        return SOX_EOF;
      }
      lsx_readdw(ft, &oneshot);
      lsx_skipbytes(ft, (size_t)8);
      lsx_readw(ft, &rate);
      lsx_readb(ft, &oct);
      lsx_readb(ft, &comp);
      if (comp) {
        lsx_fail_errno(ft, SOX_EHDR, "Unsupported data compression");
        return SOX_EOF;
      }
      lsx_skipbytes(ft, (size_t)4);
      continue;
    }
    if (strncmp(buf, "ANNO", 4) == 0 || strncmp(buf, "NAME", 4) == 0 || strncmp(buf, "AUTH", 4) == 0 || strncmp(buf, "(c) ", 4) == 0) {
      lsx_readdw(ft, &chunksize);
      if (chunksize & 1) chunksize++;
      chunk_buf = lsx_calloc(1, chunksize + 1);
      if (lsx_readbuf(ft, chunk_buf, chunksize) != chunksize) {
        free(chunk_buf);
        lsx_fail_errno(ft, SOX_EHDR, "Couldn't read all of header");
        return SOX_EOF;
      }
      lsx_debug("%.4s: %s", buf, chunk_buf);
      free(chunk_buf);
      continue;
    }
    if (strncmp(buf, "CHAN", 4) == 0) {
      lsx_readdw(ft, &chunksize);
      if (chunksize != 4) {
        lsx_fail_errno(ft, SOX_EHDR, "Couldn't read all of header");
        return SOX_EOF;
      }
      lsx_readdw(ft, &channels);
      channels = (channels & 0x01) + ((channels & 0x02) >> 1) + ((channels & 0x04) >> 2) + ((channels & 0x08) >> 3);
      continue;
    }
    if (strncmp(buf, "BODY", 4) == 0) break;
    lsx_readdw(ft, &chunksize);
    if (chunksize & 1) chunksize++;
    lsx_seeki(ft, (int64_t)chunksize, SEEK_CUR);
  }

  if (rate == 0) {
    lsx_fail_errno(ft, SOX_EHDR, "Invalid sample rate");
    return SOX_EOF;
  }
  if (channels == 0) channels = 1;

  lsx_readdw(ft, &(chunksize));
  p->nsamples = chunksize;
  p->left = p->nsamples / channels;

  ft->signal.rate = rate;
  ft->signal.channels = channels;
  ft->encoding.encoding = SOX_ENCODING_SIGN2;
  ft->encoding.bits_per_sample = 8;
  ft->signal.length = p->nsamples;

  p->ch[0] = ft->fp;
  p->ch0_pos = ftello(ft->fp);
  chan1_pos = lsx_tell(ft);

  for (i = 1; i < (int)channels; i++) {
    if ((p->ch[i] = fopen(ft->filename, "rb")) == NULL) {
      lsx_fail_errno(ft, errno, "Can't open channel file '%s'", ft->filename);
      return SOX_EOF;
    }
    if (fseeko(p->ch[i], chan1_pos, SEEK_SET)) {
      lsx_fail_errno(ft, errno, "Can't position channel %d", i);
      return SOX_EOF;
    }
    if (fseeko(p->ch[i], (off_t)(p->nsamples / channels * i), SEEK_CUR)) {
      lsx_fail_errno(ft, errno, "Can't seek channel %d", i);
      return SOX_EOF;
    }
  }
  return SOX_SUCCESS;
}

static size_t svx_read(sox_format_t *ft, sox_sample_t *buf, size_t nsamp)
{
  unsigned char datum;
  size_t done = 0, i;
  svx_priv_t *p = (svx_priv_t *)ft->priv;

  while (done < nsamp) {
    if (p->left == 0) break;
    for (i = 0; i < ft->signal.channels; i++) {
      if (fread(&datum, (size_t)1, (size_t)1, p->ch[i]) != 1)
        return done;
      *buf++ = SOX_SIGNED_8BIT_TO_SAMPLE(datum);
    }
    p->left--;
    done += ft->signal.channels;
  }
  return done;
}

static int svx_stopread(sox_format_t *ft)
{
  size_t i;
  svx_priv_t *p = (svx_priv_t *)ft->priv;
  for (i = 1; i < ft->signal.channels; i++)
    if (p->ch[i]) fclose(p->ch[i]);
  return SOX_SUCCESS;
}

static int svx_startwrite(sox_format_t *ft)
{
  svx_priv_t *p = (svx_priv_t *)ft->priv;
  size_t i;

  if (!ft->seekable) {
    lsx_fail_errno(ft, SOX_EINVAL, "Output .8svx file must be a file, not a pipe");
    return SOX_EOF;
  }
  p->ch[0] = ft->fp;
  for (i = 1; i < ft->signal.channels; i++) {
    if ((p->ch[i] = lsx_tmpfile()) == NULL) {
      lsx_fail_errno(ft, errno, "Can't open channel output file");
      return SOX_EOF;
    }
  }
  p->nsamples = 0;
  svx_writeheader(ft, (size_t)p->nsamples);
  return SOX_SUCCESS;
}

static size_t svx_write(sox_format_t *ft, const sox_sample_t *buf, size_t len)
{
  svx_priv_t *p = (svx_priv_t *)ft->priv;
  unsigned char datum;
  size_t done = 0, i;

  p->nsamples += len;
  while (done < len) {
    for (i = 0; i < ft->signal.channels; i++) {
      datum = SOX_SAMPLE_TO_SIGNED_8BIT(*buf++, ft->clips);
      if (i == 0) lsx_writeb(ft, datum);
      else fputc(datum, p->ch[i]);
    }
    done += ft->signal.channels;
  }
  return done;
}

static int svx_stopwrite(sox_format_t *ft)
{
  svx_priv_t *p = (svx_priv_t *)ft->priv;
  size_t i, len;
  char svxbuf[512];

  for (i = 1; i < ft->signal.channels; i++) {
    if (fseeko(p->ch[i], (off_t)0, 0)) {
      lsx_fail_errno(ft, errno, "Can't rewind channel output file %lu", (unsigned long)i);
      return SOX_EOF;
    }
    while (!feof(p->ch[i])) {
      len = fread(svxbuf, (size_t)1, (size_t)512, p->ch[i]);
      if (lsx_writebuf(ft, svxbuf, len) != len) {
        lsx_fail_errno(ft, errno, "Can't write channel output file %lu", (unsigned long)i);
        return SOX_EOF;
      }
    }
    fclose(p->ch[i]);
  }

  if (p->nsamples % 2 != 0)
    lsx_writeb(ft, '\0');

  if (lsx_seeki(ft, (int64_t)0, 0) != 0) {
    lsx_fail_errno(ft, errno, "can't rewind output file to rewrite 8SVX header");
    return SOX_EOF;
  }
  svx_writeheader(ft, (size_t)p->nsamples);
  return SOX_SUCCESS;
}

const sox_format_handler_t *lsx_svx_format_fn(void)
{
  static char const *const names[] = {"8svx", NULL};
  static unsigned const write_encodings[] = {SOX_ENCODING_SIGN2, 8, 0, 0};
  static sox_format_handler_t const handler = {
    "Amiga audio format (a subformat of the Interchange File Format)", names,
    SOX_FILE_BIG_END | SOX_FILE_MONO | SOX_FILE_STEREO | SOX_FILE_QUAD,
    svx_startread, svx_read, svx_stopread,
    svx_startwrite, svx_write, svx_stopwrite,
    NULL, write_encodings, NULL, sizeof(svx_priv_t)
  };
  return &handler;
}

/* ===================================================================== */
/* AVR */
#define AVR_MAGIC "2BIT"
typedef struct {
  char magic[5];
  char name[8];
  unsigned short mono;
  unsigned short rez;
  unsigned short sign;
  unsigned short loop;
  unsigned short midi;
  uint32_t rate;
  uint32_t size;
  uint32_t lbeg;
  uint32_t lend;
  unsigned short res1;
  unsigned short res2;
  unsigned short res3;
  char ext[20];
  char user[64];
} avr_priv_t;

static int avr_startread(sox_format_t *ft)
{
  avr_priv_t *avr = (avr_priv_t *)ft->priv;
  int rc;

  lsx_reads(ft, avr->magic, (size_t)4);
  if (strncmp(avr->magic, AVR_MAGIC, (size_t)4)) {
    lsx_fail_errno(ft, SOX_EHDR, "AVR: unknown header");
    return SOX_EOF;
  }

  lsx_readbuf(ft, avr->name, sizeof(avr->name));
  lsx_readw(ft, &(avr->mono));
  if (avr->mono) ft->signal.channels = 2;
  else ft->signal.channels = 1;

  lsx_readw(ft, &(avr->rez));
  if (avr->rez == 8) {
    ft->encoding.bits_per_sample = 8;
  } else if (avr->rez == 16) {
    ft->encoding.bits_per_sample = 16;
  } else {
    lsx_fail_errno(ft, SOX_EFMT, "AVR: unsupported sample resolution");
    return SOX_EOF;
  }

  lsx_readw(ft, &(avr->sign));
  if (avr->sign) ft->encoding.encoding = SOX_ENCODING_SIGN2;
  else ft->encoding.encoding = SOX_ENCODING_UNSIGNED;

  lsx_readw(ft, &(avr->loop));
  lsx_readw(ft, &(avr->midi));
  lsx_readdw(ft, &(avr->rate));
  ft->signal.rate = (avr->rate & 0x00ffffff);
  lsx_readdw(ft, &(avr->size));
  lsx_readdw(ft, &(avr->lbeg));
  lsx_readdw(ft, &(avr->lend));
  lsx_readw(ft, &(avr->res1));
  lsx_readw(ft, &(avr->res2));
  lsx_readw(ft, &(avr->res3));
  lsx_readbuf(ft, avr->ext, sizeof(avr->ext));
  lsx_readbuf(ft, avr->user, sizeof(avr->user));

  rc = lsx_rawstartread(ft);
  if (rc)
    return rc;
  ft->signal.length = (uint64_t)avr->size * ft->signal.channels;
  return SOX_SUCCESS;
}

static int avr_startwrite(sox_format_t *ft)
{
  int rc;

  if (!ft->seekable) {
    lsx_fail_errno(ft, SOX_EOF, "AVR: file is not seekable");
    return SOX_EOF;
  }
  rc = lsx_rawstartwrite(ft);
  if (rc)
    return rc;

  lsx_writes(ft, AVR_MAGIC);
  lsx_writeb(ft, 0); lsx_writeb(ft, 0); lsx_writeb(ft, 0); lsx_writeb(ft, 0);
  lsx_writeb(ft, 0); lsx_writeb(ft, 0); lsx_writeb(ft, 0); lsx_writeb(ft, 0);
  if (ft->signal.channels == 1) lsx_writew(ft, 0);
  else if (ft->signal.channels == 2) lsx_writew(ft, 0xffff);
  else {
    lsx_fail_errno(ft, SOX_EFMT, "AVR: number of channels not supported");
    return 0;
  }
  if (ft->encoding.bits_per_sample == 8) lsx_writew(ft, 8);
  else if (ft->encoding.bits_per_sample == 16) lsx_writew(ft, 16);
  else {
    lsx_fail_errno(ft, SOX_EFMT, "AVR: unsupported sample resolution");
    return SOX_EOF;
  }
  if (ft->encoding.encoding == SOX_ENCODING_SIGN2) lsx_writew(ft, 0xffff);
  else if (ft->encoding.encoding == SOX_ENCODING_UNSIGNED) lsx_writew(ft, 0);
  else {
    lsx_fail_errno(ft, SOX_EFMT, "AVR: unsupported encoding");
    return SOX_EOF;
  }
  lsx_writew(ft, 0xffff);
  lsx_writew(ft, 0xffff);
  lsx_writedw(ft, (unsigned)(ft->signal.rate + .5));
  lsx_writedw(ft, 0);
  lsx_writedw(ft, 0);
  lsx_writedw(ft, 0);
  lsx_writew(ft, 0);
  lsx_writew(ft, 0);
  lsx_writew(ft, 0);
  lsx_padbytes(ft, 20);
  lsx_padbytes(ft, 64);
  return SOX_SUCCESS;
}

static size_t avr_write(sox_format_t *ft, const sox_sample_t *buf, size_t nsamp)
{
  avr_priv_t *avr = (avr_priv_t *)ft->priv;
  avr->size += nsamp;
  return lsx_rawwrite(ft, buf, nsamp);
}

static int avr_stopwrite(sox_format_t *ft)
{
  avr_priv_t *avr = (avr_priv_t *)ft->priv;
  unsigned size = avr->size / ft->signal.channels;

  lsx_seeki(ft, (int64_t)26, SEEK_SET);
  lsx_writedw(ft, size);
  lsx_seeki(ft, (int64_t)34, SEEK_SET);
  lsx_writedw(ft, size);
  return SOX_SUCCESS;
}

const sox_format_handler_t *lsx_avr_format_fn(void)
{
  static char const *const names[] = {"avr", NULL};
  static unsigned const write_encodings[] = {
    SOX_ENCODING_SIGN2, 16, 8, 0,
    SOX_ENCODING_UNSIGNED, 16, 8, 0,
    0};
  static sox_format_handler_t const handler = {
    "Audio Visual Research format; used on the Mac", names, SOX_FILE_BIG_END | SOX_FILE_MONO | SOX_FILE_STEREO,
    avr_startread, lsx_rawread, NULL,
    avr_startwrite, avr_write, avr_stopwrite,
    NULL, write_encodings, NULL, sizeof(avr_priv_t)
  };
  return &handler;
}

/* ===================================================================== */
/* MAUD */
typedef struct { uint32_t nsamples; } maud_priv_t;

static void maud_writeheader(sox_format_t *ft)
{
  maud_priv_t *p = (maud_priv_t *)ft->priv;
  uint32_t samples = p->nsamples;

  lsx_writes(ft, "FORM");
  lsx_writedw(ft, (samples * (ft->encoding.bits_per_sample >> 3)) + 40 + 8 + 20 + 8 + 4);
  lsx_writes(ft, "MAUD");

  lsx_writes(ft, "MHDR");
  lsx_writedw(ft, 8 * 4);
  lsx_writedw(ft, samples);
  lsx_writew(ft, ft->encoding.bits_per_sample);
  lsx_writew(ft, ft->encoding.encoding == SOX_ENCODING_ULAW || ft->encoding.encoding == SOX_ENCODING_ALAW ? 16 : ft->encoding.bits_per_sample);
  lsx_writedw(ft, (unsigned)(ft->signal.rate + .5));
  lsx_writew(ft, 1);
  lsx_writew(ft, ft->signal.channels == 2 ? 1 : 0);
  lsx_writew(ft, ft->signal.channels);
  if (ft->encoding.encoding == SOX_ENCODING_ULAW) lsx_writew(ft, 3);
  else if (ft->encoding.encoding == SOX_ENCODING_ALAW) lsx_writew(ft, 2);
  else lsx_writew(ft, 0);
  lsx_writedw(ft, 0);
  lsx_writedw(ft, 0);
  lsx_writedw(ft, 0);

  lsx_writes(ft, "ANNO");
  lsx_writedw(ft, 19);
  lsx_writes(ft, "file created by SoX");
  lsx_writeb(ft, 0);

  lsx_writes(ft, "MDAT");
  lsx_writedw(ft, p->nsamples * (ft->encoding.bits_per_sample >> 3));
}

static int maud_startread(sox_format_t *ft)
{
  maud_priv_t *p = (maud_priv_t *)ft->priv;
  char buf[12];
  char *chunk_buf;
  unsigned short bitpersam;
  uint32_t nom;
  unsigned short denom;
  unsigned short chaninf;
  uint32_t chunksize;
  uint32_t trash32;
  uint16_t trash16;
  int rc;

  if (lsx_readbuf(ft, buf, 4) != 4 || strncmp(buf, "FORM", 4) != 0) {
    lsx_fail_errno(ft, SOX_EHDR, "MAUD: header does not begin with magic word `FORM'");
    return SOX_EOF;
  }
  lsx_readdw(ft, &trash32);
  if (lsx_readbuf(ft, buf, 4) != 4 || strncmp(buf, "MAUD", 4) != 0) {
    lsx_fail_errno(ft, SOX_EHDR, "MAUD: `FORM' chunk does not specify `MAUD' as type");
    return SOX_EOF;
  }

  while (1) {
    if (lsx_readbuf(ft, buf, 4) != 4) {
      lsx_fail_errno(ft, SOX_EHDR, "MAUD: unexpected EOF in header");
      return SOX_EOF;
    }
    if (strncmp(buf, "MHDR", 4) == 0) {
      lsx_readdw(ft, &chunksize);
      if (chunksize != 8 * 4) {
        lsx_fail_errno(ft, SOX_EHDR, "MAUD: MHDR chunk has bad size");
        return SOX_EOF;
      }
      lsx_readdw(ft, &(p->nsamples));
      lsx_readw(ft, &bitpersam);
      lsx_readw(ft, &trash16);
      lsx_readdw(ft, &nom);
      lsx_readw(ft, &denom);
      if (denom == 0) {
        lsx_fail_errno(ft, SOX_EHDR, "MAUD: frequency denominator == 0, failed");
        return SOX_EOF;
      }
      ft->signal.rate = nom / denom;
      lsx_readw(ft, &chaninf);
      switch (chaninf) {
        case 0: ft->signal.channels = 1; break;
        case 1: ft->signal.channels = 2; break;
        default:
          lsx_fail_errno(ft, SOX_EFMT, "MAUD: unsupported number of channels in file");
          return SOX_EOF;
      }
      lsx_readw(ft, &chaninf);
      if (chaninf != ft->signal.channels) {
        lsx_fail_errno(ft, SOX_EFMT, "MAUD: unsupported number of channels in file");
        return SOX_EOF;
      }
      lsx_readw(ft, &chaninf);
      lsx_readdw(ft, &trash32);
      lsx_readdw(ft, &trash32);
      lsx_readdw(ft, &trash32);
      if (bitpersam == 8 && chaninf == 0) {
        ft->encoding.bits_per_sample = 8;
        ft->encoding.encoding = SOX_ENCODING_UNSIGNED;
      } else if (bitpersam == 8 && chaninf == 2) {
        ft->encoding.bits_per_sample = 8;
        ft->encoding.encoding = SOX_ENCODING_ALAW;
      } else if (bitpersam == 8 && chaninf == 3) {
        ft->encoding.bits_per_sample = 8;
        ft->encoding.encoding = SOX_ENCODING_ULAW;
      } else if (bitpersam == 16 && chaninf == 0) {
        ft->encoding.bits_per_sample = 16;
        ft->encoding.encoding = SOX_ENCODING_SIGN2;
      } else {
        lsx_fail_errno(ft, SOX_EFMT, "MAUD: unsupported compression type detected");
        return SOX_EOF;
      }
      continue;
    }
    if (strncmp(buf, "ANNO", 4) == 0) {
      lsx_readdw(ft, &chunksize);
      if (chunksize & 1) chunksize++;
      chunk_buf = lsx_calloc(1, chunksize + 1);
      if (lsx_readbuf(ft, chunk_buf, (size_t)chunksize) != chunksize) {
        lsx_fail_errno(ft, SOX_EOF, "MAUD: Unexpected EOF in ANNO header");
        free(chunk_buf);
        return SOX_EOF;
      }
      lsx_debug("%s", chunk_buf);
      free(chunk_buf);
      continue;
    }
    if (strncmp(buf, "MDAT", 4) == 0) break;
    lsx_readdw(ft, &chunksize);
    if (chunksize & 1) chunksize++;
    lsx_seeki(ft, (int64_t)chunksize, SEEK_CUR);
  }
  lsx_readdw(ft, &chunksize);
  rc = lsx_rawstartread(ft);
  if (rc) return rc;
  ft->signal.length = chunksize / (ft->encoding.bits_per_sample / 8);
  return SOX_SUCCESS;
}

static int maud_startwrite(sox_format_t *ft)
{
  maud_priv_t *p = (maud_priv_t *)ft->priv;
  int rc;

  if (!ft->seekable) {
    lsx_fail_errno(ft, SOX_EOF, "Output .maud file must be a file, not a pipe");
    return SOX_EOF;
  }
  rc = lsx_rawstartwrite(ft);
  if (rc) return rc;
  p->nsamples = 0x7f000000;
  maud_writeheader(ft);
  p->nsamples = 0;
  return SOX_SUCCESS;
}

static size_t maud_write(sox_format_t *ft, const sox_sample_t *buf, size_t len)
{
  maud_priv_t *p = (maud_priv_t *)ft->priv;
  p->nsamples += len;
  return lsx_rawwrite(ft, buf, len);
}

static int maud_stopwrite(sox_format_t *ft)
{
  if (lsx_seeki(ft, (int64_t)0, 0) != 0) {
    lsx_fail_errno(ft, errno, "can't rewind output file to rewrite MAUD header");
    return SOX_EOF;
  }
  maud_writeheader(ft);
  return SOX_SUCCESS;
}

const sox_format_handler_t *lsx_maud_format_fn(void)
{
  static char const *const names[] = {"maud", NULL};
  static unsigned const write_encodings[] = {
    SOX_ENCODING_SIGN2, 16, 0,
    SOX_ENCODING_UNSIGNED, 8, 0,
    SOX_ENCODING_ULAW, 8, 0,
    SOX_ENCODING_ALAW, 8, 0,
    0};
  static sox_format_handler_t const handler = {
    "Used with the \xe2\x80\x98Toccata\xe2\x80\x99 sound-card on the Amiga", names, SOX_FILE_BIG_END | SOX_FILE_MONO | SOX_FILE_STEREO,
    maud_startread, lsx_rawread, NULL,
    maud_startwrite, maud_write, maud_stopwrite,
    NULL, write_encodings, NULL, sizeof(maud_priv_t)
  };
  return &handler;
}

/* ===================================================================== */
/* SMP (Turtle Beach SampleVision) */
#define SMP_NAMELEN 30
#define SMP_COMMENTLEN 60
#define SMP_MIDI_UNITY 60
#define SMP_MARKERLEN (size_t)10
static char const *SVmagic = "SOUND SAMPLE DATA ", *SVvers = "2.1 ";

typedef struct {
  uint64_t NoOfSamps;
  uint64_t dataStart;
} smp_priv_t;

static int smp_startread(sox_format_t *ft)
{
  smp_priv_t *smp = (smp_priv_t *)ft->priv;
  char header[112];
  uint32_t samplestart;
  int i;
  char comment[64];
  uint8_t trash;
  (void)comment;

  if (lsx_readbuf(ft, header, 112) != 112) {
    lsx_fail_errno(ft, SOX_EHDR, "unexpected EOF in SMP header");
    return SOX_EOF;
  }
  if (strncmp(header, SVmagic, (size_t)17) != 0) {
    lsx_fail_errno(ft, SOX_EHDR, "SMP header does not begin with magic word %s", SVmagic);
    return SOX_EOF;
  }
  if (strncmp(header + 18, SVvers, (size_t)4) != 0) {
    lsx_fail_errno(ft, SOX_EHDR, "SMP header is not version %s", SVvers);
    return SOX_EOF;
  }
  {
    char name[SMP_NAMELEN + 1];
    memcpy(name, header + 82, SMP_NAMELEN);
    name[SMP_NAMELEN] = 0;
    for (i = SMP_NAMELEN - 1; i >= 0 && name[i] == ' '; --i) name[i] = 0;
    {
      char c2[SMP_COMMENTLEN + 1];
      memcpy(c2, header + 22, SMP_COMMENTLEN);
      c2[SMP_COMMENTLEN] = 0;
      for (i = SMP_COMMENTLEN - 1; i >= 0 && (c2[i] == ' ' || c2[i] == 0); --i) c2[i] = 0;
      if (name[0]) {
        char buf[SMP_NAMELEN + SMP_COMMENTLEN + 4];
        sprintf(buf, "%s", name);
        sox_append_comments(&ft->comments, buf);
      }
    }
  }

  lsx_readdw(ft, &samplestart);
  smp->NoOfSamps = samplestart;
  smp->dataStart = lsx_tell(ft);
  ft->signal.rate = 8000;
  {
    /* read trailer for rate */
    off_t here = ftello(ft->fp);
    if (ft->seekable && fseeko(ft->fp, (off_t)(here + smp->NoOfSamps * 2 + 2 + 8 * 11 + 8 * 14 + 1), SEEK_SET) == 0) {
      uint32_t rate;
      if (lsx_readdw(ft, &rate) == SOX_SUCCESS) ft->signal.rate = rate;
      fseeko(ft->fp, here, SEEK_SET);
    }
  }
  (void)trash;
  ft->encoding.encoding = SOX_ENCODING_SIGN2;
  ft->encoding.bits_per_sample = 16;
  ft->signal.channels = 1;
  ft->signal.length = smp->NoOfSamps;
  return SOX_SUCCESS;
}

static size_t smp_read(sox_format_t *ft, sox_sample_t *buf, size_t len)
{
  smp_priv_t *smp = (smp_priv_t *)ft->priv;
  size_t done;
  if (len > smp->NoOfSamps) len = smp->NoOfSamps;
  done = lsx_rawread(ft, buf, len);
  smp->NoOfSamps -= done;
  return done;
}

static int smp_startwrite(sox_format_t *ft)
{
  smp_priv_t *smp = (smp_priv_t *)ft->priv;
  char header[113 + 64];
  char *comment = cat_comments(&ft->comments);

  if (!ft->seekable) {
    lsx_fail_errno(ft, SOX_EOF, "Output .smp file must be a file, not a pipe");
    free(comment);
    return SOX_EOF;
  }
  memcpy(header, SVmagic, 18);
  memcpy(header + 18, SVvers, 4);
  sprintf(header + 22, "%-*s", SMP_COMMENTLEN - 1, "Converted using Sox.");
  sprintf(header + 82, "%-*.*s", SMP_NAMELEN, SMP_NAMELEN, comment);
  free(comment);
  if (lsx_writebuf(ft, header, 112) != 112) {
    lsx_fail_errno(ft, errno, "SMP: Can't write header completely");
    return SOX_EOF;
  }
  lsx_writedw(ft, 0);
  smp->NoOfSamps = 0;
  return SOX_SUCCESS;
}

static size_t smp_write(sox_format_t *ft, const sox_sample_t *buf, size_t len)
{
  smp_priv_t *smp = (smp_priv_t *)ft->priv;
  size_t done = lsx_rawwrite(ft, buf, len);
  smp->NoOfSamps += done;
  return done;
}

static int smp_stopwrite(sox_format_t *ft)
{
  smp_priv_t *smp = (smp_priv_t *)ft->priv;
  int i;

  lsx_writew(ft, 0);
  for (i = 0; i < 8; i++) {
    lsx_writedw(ft, ~0u);
    lsx_writedw(ft, 0);
    lsx_writeb(ft, 0);
    lsx_writew(ft, 0);
  }
  for (i = 0; i < 8; i++) {
    lsx_writes(ft, "          ");
    lsx_writedw(ft, ~0u);
  }
  lsx_writeb(ft, SMP_MIDI_UNITY);
  lsx_writedw(ft, (unsigned)ft->signal.rate);
  lsx_writedw(ft, 0);
  lsx_writedw(ft, ~0u);
  if (lsx_seeki(ft, (int64_t)112, 0) == -1) {
    lsx_fail_errno(ft, errno, "SMP unable to seek back to save size");
    return SOX_EOF;
  }
  lsx_writedw(ft, (unsigned)smp->NoOfSamps);
  return SOX_SUCCESS;
}

const sox_format_handler_t *lsx_smp_format_fn(void)
{
  static char const *const names[] = {"smp", NULL};
  static unsigned const write_encodings[] = {SOX_ENCODING_SIGN2, 16, 0, 0};
  static sox_format_handler_t const handler = {
    "Turtle Beach SampleVision", names, SOX_FILE_LIT_END | SOX_FILE_MONO,
    smp_startread, smp_read, NULL,
    smp_startwrite, smp_write, smp_stopwrite,
    NULL, write_encodings, NULL, sizeof(smp_priv_t)
  };
  return &handler;
}

/* ===================================================================== */
/* Sounder (sndr) */
static int sndr_startread(sox_format_t *ft)
{
  uint16_t type, rate, vol, shift;
  if (lsx_readw(ft, &type) || lsx_readw(ft, &rate) || lsx_readw(ft, &vol) || lsx_readw(ft, &shift))
    return SOX_EOF;
  if (type != 0) {
    lsx_fail_errno(ft, SOX_EHDR, "Sounder: invalid header");
    return SOX_EOF;
  }
  return lsx_check_read_params(ft, 1, (sox_rate_t)rate, SOX_ENCODING_UNSIGNED, 8, (uint64_t)0, sox_true);
}

static int sndr_startwrite(sox_format_t *ft)
{
  lsx_writew(ft, 0);
  lsx_writew(ft, (unsigned)(ft->signal.rate + .5));
  lsx_writew(ft, 10);
  lsx_writew(ft, 4);
  return SOX_SUCCESS;
}

const sox_format_handler_t *lsx_sounder_format_fn(void)
{
  static char const *const names[] = {"sndr", NULL};
  static unsigned const write_encodings[] = {SOX_ENCODING_UNSIGNED, 8, 0, 0};
  static sox_format_handler_t const handler = {
    "8-bit linear audio as used by Aaron Wallace's `Sounder' of 1991", names, SOX_FILE_LIT_END | SOX_FILE_MONO,
    sndr_startread, lsx_rawread, NULL,
    sndr_startwrite, lsx_rawwrite, NULL,
    lsx_rawseek, write_encodings, NULL, 0
  };
  return &handler;
}

/* ===================================================================== */
/* SoundTool (sndt) */
static int sndt_startread(sox_format_t *ft)
{
  char id[6];
  uint16_t gsound, rate, type, vol, shift;
  uint32_t nsamples, start, end;
  char text[97];

  if (lsx_readbuf(ft, id, 6) != 6 || memcmp(id, "SOUND\x1a", 6)) {
    lsx_fail_errno(ft, SOX_EHDR, "soundtool: invalid header");
    return SOX_EOF;
  }
  lsx_readw(ft, &gsound);
  lsx_readdw(ft, &nsamples);
  lsx_readdw(ft, &start);
  lsx_readdw(ft, &end);
  lsx_readw(ft, &rate);
  lsx_readw(ft, &type);
  lsx_readw(ft, &vol);
  lsx_readw(ft, &shift);
  memset(text, 0, sizeof(text));
  lsx_readbuf(ft, text, 96);
  if (text[0]) sox_append_comments(&ft->comments, text);
  return lsx_check_read_params(ft, 1, (sox_rate_t)rate, SOX_ENCODING_UNSIGNED, 8, (uint64_t)nsamples, sox_true);
}

static int sndt_write_header(sox_format_t *ft)
{
  char *comment = cat_comments(&ft->comments);
  char text_buf[97];

  memset(text_buf, 0, sizeof(text_buf));
  strncpy(text_buf, comment, (size_t)96);
  free(comment);
  lsx_writes(ft, "SOUND\x1a");
  lsx_writew(ft, 0);
  lsx_writedw(ft, (unsigned)ft->olength);
  lsx_writedw(ft, 0);
  lsx_writedw(ft, (unsigned)ft->olength);
  lsx_writew(ft, min(65535, (unsigned)(ft->signal.rate + .5)));
  lsx_writew(ft, 0);
  lsx_writew(ft, 10);
  lsx_writew(ft, 4);
  lsx_writebuf(ft, text_buf, (size_t)96);
  return SOX_SUCCESS;
}

const sox_format_handler_t *lsx_soundtool_format_fn(void)
{
  static char const *const names[] = {"sndt", NULL};
  static unsigned const write_encodings[] = {SOX_ENCODING_UNSIGNED, 8, 0, 0};
  static sox_format_handler_t const handler = {
    "8-bit linear audio as used by Martin Hepperle's `SoundTool' of 1991/2", names, SOX_FILE_LIT_END | SOX_FILE_MONO | SOX_FILE_REWIND,
    sndt_startread, lsx_rawread, NULL,
    sndt_write_header, lsx_rawwrite, NULL,
    lsx_rawseek, write_encodings, NULL, 0
  };
  return &handler;
}

/* ===================================================================== */
/* HTK */
typedef enum {
  Waveform, Lpc, Lprefc, Lpcepstra, Lpdelcep, Irefc,
  Mfcc, Fbank, Melspec, User, Discrete, Unknown
} htk_kind_t;

static int htk_startread(sox_format_t *ft)
{
  uint32_t period_100ns, num_samples;
  uint16_t bytes_per_sample, parmKind;

  if (lsx_readdw(ft, &num_samples) ||
      lsx_readdw(ft, &period_100ns) ||
      lsx_readw(ft, &bytes_per_sample) ||
      lsx_readw(ft, &parmKind)) return SOX_EOF;
  if (parmKind != Waveform) {
    int n = min(parmKind & 077, Unknown);
    static char const *const str[] = {"Waveform", "Lpc", "Lprefc", "Lpcepstra", "Lpdelcep", "Irefc", "Mfcc", "Fbank", "Melspec", "User", "Discrete", "Unknown"};
    lsx_fail_errno(ft, SOX_EFMT, "unsupported HTK type `%s' (0%o)", str[n], parmKind);
    return SOX_EOF;
  }
  return lsx_check_read_params(ft, 1, 1e7 / period_100ns, SOX_ENCODING_SIGN2,
      (unsigned)bytes_per_sample << 3, (uint64_t)num_samples, sox_true);
}

static int htk_write_header(sox_format_t *ft)
{
  double period_100ns = 1e7 / ft->signal.rate;
  uint64_t len = ft->olength ? ft->olength : ft->signal.length;

  if (len > UINT_MAX) {
    lsx_warn("length greater than 32 bits - cannot fit actual length in header");
    len = UINT_MAX;
  }
  if (!ft->olength && floor(period_100ns) != period_100ns)
    lsx_warn("rounding sample period %f (x 100ns) to nearest integer", period_100ns);
  return lsx_writedw(ft, (unsigned)len)
      || lsx_writedw(ft, (unsigned)(period_100ns + .5))
      || lsx_writew(ft, ft->encoding.bits_per_sample >> 3)
      || lsx_writew(ft, Waveform) ? SOX_EOF : SOX_SUCCESS;
}

const sox_format_handler_t *lsx_htk_format_fn(void)
{
  static char const *const names[] = {"htk", NULL};
  static unsigned const write_encodings[] = {SOX_ENCODING_SIGN2, 16, 0, 0};
  static sox_format_handler_t const handler = {
    "PCM format used for Hidden Markov Model speech processing", names, SOX_FILE_BIG_END | SOX_FILE_MONO | SOX_FILE_REWIND,
    htk_startread, lsx_rawread, NULL,
    htk_write_header, lsx_rawwrite, NULL,
    lsx_rawseek, write_encodings, NULL, 0
  };
  return &handler;
}

/* ===================================================================== */
/* WVE (Psion 3) */
#define PSION_MAGIC "ALawSoundFile**"
#define PSION_VERSION ((short)3856)
#define PSION_HDRSIZE 32

typedef struct { char magic[16]; short version; } wve_dummy_t;

static int wve_startread(sox_format_t *ft)
{
  char magic[16];
  short version;
  int rc;
  uint16_t trash16;
  uint32_t num_samples;

  rc = lsx_rawstartread(ft);
  if (rc) return rc;

  lsx_readbuf(ft, magic, (size_t)16);
  if (strncmp(magic, PSION_MAGIC, (size_t)15) != 0) {
    lsx_fail_errno(ft, SOX_EHDR, "Did not detect a Psion header");
    return SOX_EOF;
  }
  lsx_readsw(ft, &version);
  if (version != PSION_VERSION) {
    lsx_fail_errno(ft, SOX_EHDR, "Wrong version in Psion header");
    return SOX_EOF;
  }
  lsx_readdw(ft, &num_samples);
  lsx_readw(ft, &trash16);
  lsx_readw(ft, &trash16);
  lsx_readw(ft, &trash16);
  lsx_skipbytes(ft, (size_t)(PSION_HDRSIZE - 28));

  ft->encoding.encoding = SOX_ENCODING_ALAW;
  ft->encoding.bits_per_sample = 8;
  if (!ft->signal.rate) ft->signal.rate = 8000;
  if (!ft->signal.channels) ft->signal.channels = 1;
  ft->signal.length = num_samples;
  return SOX_SUCCESS;
}

static int wve_write_header(sox_format_t *ft)
{
  uint64_t size64 = ft->olength ? ft->olength : ft->signal.length;
  unsigned size = size64 > UINT_MAX ? UINT_MAX : (unsigned)size64;

  lsx_writes(ft, PSION_MAGIC);
  lsx_writeb(ft, 0);
  lsx_writesw(ft, PSION_VERSION);
  lsx_writedw(ft, size);
  lsx_writew(ft, 0);
  lsx_writew(ft, 1);
  lsx_writew(ft, 0);
  lsx_padbytes(ft, (size_t)(PSION_HDRSIZE - 28));
  return SOX_SUCCESS;
}

const sox_format_handler_t *lsx_wve_format_fn(void)
{
  static char const *const names[] = {"wve", NULL};
  static sox_rate_t const write_rates[] = {8000, 0};
  static unsigned const write_encodings[] = {SOX_ENCODING_ALAW, 8, 0, 0};
  static sox_format_handler_t const handler = {
    "Psion 3 audio format", names, SOX_FILE_BIG_END | SOX_FILE_MONO | SOX_FILE_REWIND,
    wve_startread, lsx_rawread, NULL,
    wve_write_header, lsx_rawwrite, NULL,
    lsx_rawseek, write_encodings, write_rates, 0
  };
  return &handler;
}
