/* Assorted simple formats: voc, sph, sf, 8svx, avr, maud, smp, sndr, sndt, htk, wve */
#include "sox.h"
#include "adpcm.h"

FILE *lsx_tmpfile(void);

static char *cat_comments(sox_comments_t *c)
{
