/* ===================================================================== */
/* VOC */
#define VOC_TERM 0
#define VOC_DATA 1
#define VOC_CONT 2
#define VOC_SILENCE 3
#define VOC_MARKER 4
#define VOC_TEXT 5
#define VOC_LOOP 6
#define VOC_LOOPEND 7
#define VOC_EXTENDED 8
#define VOC_DATA_16 9

typedef struct {
  long block_remaining;
  long rate;
  int silent;
  long srate;
  size_t blockseek;
  long samples;
  uint16_t format;
  int size;
  unsigned char channels;
  long total_size;
  int extended;
  adpcm_t adpcm;
  int nibble_toggle;
  int nibble;
} voc_priv_t;

static int voc_getblock(sox_format_t *ft);

static int voc_startread(sox_format_t *ft)
{
  char header[20];
  voc_priv_t *v = (voc_priv_t *)ft->priv;
  unsigned short sbseek;
  int rc;
  int ii;

  if (lsx_readbuf(ft, header, (size_t)20) != 20) {
    lsx_fail_errno(ft, SOX_EHDR, "unexpected EOF in VOC header");
    return SOX_EOF;
  }
  if (strncmp(header, "Creative Voice File\032", (size_t)19)) {
    lsx_fail_errno(ft, SOX_EHDR, "VOC file header incorrect");
    return SOX_EOF;
  }

  lsx_readw(ft, &sbseek);
  for (ii = 22; ii < sbseek; ii++) {
    uint8_t c;
    lsx_readb(ft, &c);
  }

  v->rate = -1;
  v->format = 0xffff;
  v->block_remaining = 0;
  v->total_size = 0;
  v->extended = 0;

  rc = voc_getblock(ft);
  if (rc)
    return rc;

  if (v->rate == -1) {
    lsx_fail_errno(ft, SOX_EOF, "Input .voc file had no sound!");
    return SOX_EOF;
  }

  switch (v->format) {
    case 0x00: ft->encoding.encoding = SOX_ENCODING_UNSIGNED; v->size = 8; break;
    case 0x01: ft->encoding.encoding = SOX_ENCODING_OKI_ADPCM; v->size = 4; break;
    case 0x04: ft->encoding.encoding = SOX_ENCODING_SIGN2; v->size = 16; break;
    case 0x06: ft->encoding.encoding = SOX_ENCODING_ALAW; v->size = 8; break;
    case 0x07: ft->encoding.encoding = SOX_ENCODING_ULAW; v->size = 8; break;
    default:
      lsx_fail_errno(ft, SOX_EFMT, "Unsupported VOC format %d", v->format);
      return SOX_EOF;
  }
  ft->encoding.bits_per_sample = v->size;

  if (ft->signal.channels == 0)
    ft->signal.channels = v->channels;
  return SOX_SUCCESS;
}

static size_t voc_read(sox_format_t *ft, sox_sample_t *buf, size_t len)
{
  voc_priv_t *v = (voc_priv_t *)ft->priv;
  size_t done = 0;
  int rc = 0;
  int16_t sw;
  unsigned char uc;

  if (v->block_remaining == 0) {
    rc = voc_getblock(ft);
    if (rc)
      return 0;
  }
  if (v->block_remaining == 0)
    return 0;

  if (v->silent) {
    for (; v->block_remaining && (done < len); v->block_remaining--, done++)
      *buf++ = 0;
  } else {
    for (; v->block_remaining && done < len; done++) {
      switch (v->size) {
        case 8:
          if (lsx_readb(ft, &uc) == SOX_EOF) {
            lsx_warn("VOC input: short file");
            v->block_remaining = 0;
            return done;
          }
          if (ft->encoding.encoding == SOX_ENCODING_ULAW) {
            extern int16_t lsx_ulaw2linear16[256];
            *buf++ = SOX_SIGNED_16BIT_TO_SAMPLE(lsx_ulaw2linear16[uc]);
          } else if (ft->encoding.encoding == SOX_ENCODING_ALAW) {
            extern int16_t lsx_alaw2linear16[256];
            *buf++ = SOX_SIGNED_16BIT_TO_SAMPLE(lsx_alaw2linear16[uc]);
          } else
            *buf++ = SOX_UNSIGNED_8BIT_TO_SAMPLE(uc);
          v->block_remaining--;
          break;
        case 16:
          lsx_readsw(ft, &sw);
          if (lsx_eof(ft)) {
            lsx_warn("VOC input: short file");
            v->block_remaining = 0;
            return done;
          }
          *buf++ = SOX_SIGNED_16BIT_TO_SAMPLE(sw);
          v->block_remaining -= 2;
          break;
        default:
          return done;
      }
      if (v->block_remaining == 0) {
        rc = voc_getblock(ft);
        if (rc) break;
      }
    }
  }
  return done;
}

static int voc_getblock(sox_format_t *ft)
{
  voc_priv_t *v = (voc_priv_t *)ft->priv;
  unsigned char uc, block;
  uint32_t sblen;
  uint16_t new_rate_16;
  uint32_t new_rate_32;

  v->silent = 0;
  while (v->block_remaining == 0) {
    if (lsx_eof(ft))
      return SOX_EOF;

    if (lsx_readb(ft, &block) == SOX_EOF)
      return SOX_EOF;

    if (block == VOC_TERM)
      return SOX_EOF;

    if (lsx_eof(ft))
      return SOX_EOF;

    lsx_read3(ft, &sblen);

    switch (block) {
      case VOC_DATA:
        lsx_readb(ft, &uc);
        if (uc == 0) {
          lsx_fail_errno(ft, SOX_EFMT, "sample rate codes differ: %ld != %d", v->rate, uc);
          return SOX_EOF;
        }
        if ((v->rate != -1) && (uc != v->rate)) {
          lsx_fail_errno(ft, SOX_EFMT, "sample rate codes differ: %ld != %d", v->rate, uc);
          return SOX_EOF;
        }
        v->rate = uc;
        ft->signal.rate = 1000000.0 / (256 - v->rate);
        if (v->channels > 1) ft->signal.rate /= v->channels;
        lsx_readb(ft, &uc);
        v->format = uc;
        v->extended = 0;
        v->block_remaining = sblen - 2;
        if (v->channels == 0) v->channels = 1;
        return SOX_SUCCESS;
      case VOC_DATA_16:
        lsx_readdw(ft, &new_rate_32);
        if (new_rate_32 == 0) {
          lsx_fail_errno(ft, SOX_EFMT, "invalid rate value %u", new_rate_32);
          return SOX_EOF;
        }
        if ((v->rate != -1) && ((long)new_rate_32 != v->rate)) {
          lsx_fail_errno(ft, SOX_EFMT, "sample rate codes differ: %ld != %u", v->rate, new_rate_32);
          return SOX_EOF;
        }
        v->rate = new_rate_32;
        ft->signal.rate = new_rate_32;
        lsx_readb(ft, &uc);
        v->size = uc;
        lsx_readb(ft, &(v->channels));
        lsx_readw(ft, &(v->format));
        lsx_skipbytes(ft, (size_t)4);
        v->block_remaining = sblen - 12;
        return SOX_SUCCESS;
      case VOC_CONT:
        v->block_remaining = sblen;
        return SOX_SUCCESS;
      case VOC_SILENCE: {
        unsigned short period;
        lsx_readw(ft, &period);
        lsx_readb(ft, &uc);
        if (uc == 0) {
          lsx_fail_errno(ft, SOX_EFMT, "Silence sample rate is zero");
          return SOX_EOF;
        }
        if ((v->rate != -1) && (uc != v->rate))
          period = (period * (256. - uc)) / (256 - v->rate) + .5;
        v->block_remaining = period;
        v->silent = 1;
        return SOX_SUCCESS;
      }
      case VOC_MARKER:
        lsx_readb(ft, &uc);
        lsx_readb(ft, &uc);
        /* fall through */
      case VOC_TEXT: {
        uint32_t i = sblen;
        char *text = lsx_calloc(1, sblen + 1);
        lsx_readbuf(ft, text, sblen);
        (void)i;
        free(text);
        continue;
      }
      case VOC_LOOP:
      case VOC_LOOPEND:
        lsx_skipbytes(ft, (size_t)sblen);
        break;
      case VOC_EXTENDED:
        lsx_readw(ft, &new_rate_16);
        if (new_rate_16 == 0) {
          lsx_fail_errno(ft, SOX_EFMT, "invalid rate value %d", new_rate_16);
          return SOX_EOF;
        }
        if ((v->rate != -1) && (new_rate_16 != v->rate)) {
          lsx_fail_errno(ft, SOX_EFMT, "sample rate codes differ: %ld != %d", v->rate, new_rate_16);
          return SOX_EOF;
        }
        v->rate = new_rate_16;
        lsx_readb(ft, &uc);
        lsx_readb(ft, &uc);
        v->channels = uc ? 2 : 1;
        ft->signal.rate = (256e6 / (65536 - v->rate)) / v->channels;
        v->extended = 1;
        continue;
      default:
        lsx_debug("skipping unknown block code %d", block);
        lsx_skipbytes(ft, (size_t)sblen);
    }
  }
  return SOX_SUCCESS;
}

static void voc_blockstart(sox_format_t *ft)
{
  voc_priv_t *v = (voc_priv_t *)ft->priv;

  v->blockseek = lsx_tell(ft);
  if (v->silent) {
    lsx_writeb(ft, VOC_SILENCE);
    lsx_writeb(ft, 0);
    lsx_writeb(ft, 0);
    lsx_writesb(ft, v->rate);
  } else {
    if (ft->encoding.bits_per_sample == 8 && ft->signal.channels == 1) {
      lsx_writeb(ft, VOC_DATA);
      lsx_writeb(ft, 0);
      lsx_writeb(ft, 0);
      lsx_writeb(ft, 0);
      v->rate = 256 - (1000000.0 / ft->signal.rate);
      lsx_writesb(ft, (int)v->rate);
      lsx_writeb(ft, 0);
    } else if (ft->encoding.bits_per_sample == 8 && ft->signal.channels > 1) {
      lsx_writeb(ft, VOC_EXTENDED);
      lsx_writeb(ft, 4);
      lsx_writeb(ft, 0);
      lsx_writeb(ft, 0);
      v->rate = 65536 - (256000000.0 / (2 * ft->signal.rate));
      lsx_writesw(ft, (signed)v->rate);
      lsx_writeb(ft, 0);
      lsx_writeb(ft, 1);
      lsx_writeb(ft, VOC_DATA);
      lsx_writeb(ft, 0);
      lsx_writeb(ft, 0);
      lsx_writeb(ft, 0);
      v->rate = 256 - (1000000.0 / ft->signal.rate);
      lsx_writesb(ft, (int)v->rate);
      lsx_writeb(ft, 0);
    } else {
      lsx_writeb(ft, VOC_DATA_16);
      lsx_writeb(ft, 0);
      lsx_writeb(ft, 0);
      lsx_writeb(ft, 0);
      v->rate = ft->signal.rate + .5;
      lsx_writedw(ft, (unsigned)v->rate);
      lsx_writeb(ft, 16);
      lsx_writeb(ft, ft->signal.channels);
      lsx_writew(ft, 0x0004);
      lsx_writeb(ft, 0);
      lsx_writeb(ft, 0);
      lsx_writeb(ft, 0);
      lsx_writeb(ft, 0);
    }
  }
}

static int voc_startwrite(sox_format_t *ft)
{
  voc_priv_t *v = (voc_priv_t *)ft->priv;
  if (!ft->seekable) {
    lsx_fail_errno(ft, SOX_EOF, "Output .voc file must be a file, not a pipe");
    return SOX_EOF;
  }
  v->samples = 0;
  lsx_writes(ft, "Creative Voice File\032");
  lsx_writew(ft, 26);
  lsx_writew(ft, 0x10a);
  lsx_writew(ft, 0x1129);
  return SOX_SUCCESS;
}

static size_t voc_write(sox_format_t *ft, const sox_sample_t *buf, size_t len)
{
  voc_priv_t *v = (voc_priv_t *)ft->priv;
  unsigned char uc;
  int16_t sw;
  size_t done = 0;

  if (len && v->samples == 0) {
    v->silent = 0;
    voc_blockstart(ft);
  }
  v->samples += len;
  while (done < len) {
    if (ft->encoding.bits_per_sample == 8) {
      uc = SOX_SAMPLE_TO_UNSIGNED_8BIT(*buf++, ft->clips);
      lsx_writeb(ft, uc);
    } else {
      sw = (int)SOX_SAMPLE_TO_SIGNED_16BIT(*buf++, ft->clips);
      lsx_writesw(ft, sw);
    }
    done++;
  }
  return done;
}

static int voc_stopwrite(sox_format_t *ft)
{
  voc_priv_t *v = (voc_priv_t *)ft->priv;
  sox_sample_t datum;

  lsx_writeb(ft, 0);
  lsx_seeki(ft, (int64_t)v->blockseek, 0);
  lsx_seeki(ft, (int64_t)1, 1);
  if (v->silent) {
    lsx_writesw(ft, (signed)v->samples);
  } else {
    if (ft->encoding.bits_per_sample == 8) {
      if (ft->signal.channels > 1) {
        lsx_seeki(ft, (int64_t)8, 1);
      }
    }
    v->samples += 2;
    datum = (v->samples * (ft->encoding.bits_per_sample >> 3)) & 0xff;
    lsx_writesb(ft, datum);
    datum = ((v->samples * (ft->encoding.bits_per_sample >> 3)) >> 8) & 0xff;
    lsx_writesb(ft, datum);
    datum = ((v->samples * (ft->encoding.bits_per_sample >> 3)) >> 16) & 0xff;
    lsx_writesb(ft, datum);
  }
  return SOX_SUCCESS;
}

const sox_format_handler_t *lsx_voc_format_fn(void)
{
  static char const *const names[] = {"voc", NULL};
  static unsigned const write_encodings[] = {
    SOX_ENCODING_SIGN2, 16, 0,
    SOX_ENCODING_UNSIGNED, 8, 0,
    0};
  static sox_format_handler_t const handler = {
    "Creative Technology Sound Blaster format", names, SOX_FILE_LIT_END | SOX_FILE_MONO | SOX_FILE_STEREO,
    voc_startread, voc_read, NULL,
    voc_startwrite, voc_write, voc_stopwrite,
    NULL, write_encodings, NULL, sizeof(voc_priv_t)
  };
  return &handler;
}

/* ===================================================================== */
/* NIST SPHERE */
static int sph_startread(sox_format_t *ft)
{
  unsigned header_size, bytes_per_sample;
  char *buf;
  uint64_t num_samples = 0;
  unsigned channels = 1;
  unsigned rate = 16000;
  sox_encoding_t encoding = SOX_ENCODING_SIGN2;
  char fldname[64], fldtype[16], fldsval[128];
  char line[256];

  if (lsx_reads(ft, line, 255) == SOX_EOF || strncmp(line, "NIST_1A", 7) != 0) {
    lsx_fail_errno(ft, SOX_EHDR, "Sphere header does not begin with magic word `NIST_1A'");
    return SOX_EOF;
  }
  if (lsx_reads(ft, line, 255) == SOX_EOF) {
    lsx_fail_errno(ft, SOX_EHDR, "Error reading Sphere header");
    return SOX_EOF;
  }
  sscanf(line, "%u", &header_size);
  if (header_size < 16) {
    lsx_fail_errno(ft, SOX_EHDR, "Error reading Sphere header");
    return SOX_EOF;
  }
  header_size -= 16;
  buf = lsx_malloc(header_size + 1);
  bytes_per_sample = 0;
  {
    size_t pos = 0;
    while (pos < header_size) {
      int c;
      size_t n = 0;
      char *p = buf;
      while (pos < header_size) {
        uint8_t b;
        if (lsx_readb(ft, &b) == SOX_EOF) { free(buf); lsx_fail_errno(ft, SOX_EHDR, "Error reading Sphere header"); return SOX_EOF; }
        pos++;
        if (b == '\n') break;
        if (n < 254) p[n++] = b;
      }
      p[n] = 0;
      c = 0;
      if (!strncmp(p, "end_head", 8)) {
        break;
      }
      if (sscanf(p, "%63s %15s %127s", fldname, fldtype, fldsval) == 3) {
        if (!strcmp(fldname, "sample_n_bytes")) bytes_per_sample = atoi(fldsval);
        else if (!strcmp(fldname, "channel_count")) channels = atoi(fldsval);
        else if (!strcmp(fldname, "sample_count")) num_samples = strtoull(fldsval, NULL, 10);
        else if (!strcmp(fldname, "sample_rate")) rate = atoi(fldsval);
        else if (!strcmp(fldname, "sample_coding")) {
          if (!strcasecmp(fldsval, "ulaw") || !strcasecmp(fldsval, "mu-law"))
            encoding = SOX_ENCODING_ULAW;
          else if (!strcasecmp(fldsval, "pcm"))
            encoding = SOX_ENCODING_SIGN2;
          else {
            lsx_fail_errno(ft, SOX_EFMT, "sph: unsupported coding `%s'", fldsval);
            free(buf);
            return SOX_EOF;
          }
        } else if (!strcmp(fldname, "sample_byte_format")) {
          if (!strcmp(fldsval, "01")) ft->encoding.reverse_bytes = 0;
          else if (!strcmp(fldsval, "10")) ft->encoding.reverse_bytes = 1;
          else if (!strcmp(fldsval, "1")) ft->encoding.reverse_bytes = 0;
        }
      }
      (void)c;
    }
    /* skip rest of header */
    while (pos < header_size) {
      uint8_t b;
      if (lsx_readb(ft, &b) == SOX_EOF) break;
      pos++;
    }
  }
  free(buf);
  if (!bytes_per_sample)
    bytes_per_sample = encoding == SOX_ENCODING_ULAW ? 1 : 2;
  if (encoding == SOX_ENCODING_SIGN2 && bytes_per_sample == 1)
    encoding = SOX_ENCODING_SIGN2;
  return lsx_check_read_params(ft, channels, (sox_rate_t)rate, encoding, bytes_per_sample << 3, num_samples * channels, sox_true);
}

static int sph_write_header(sox_format_t *ft)
{
  char buf[128];
  uint64_t samples = (ft->olength ? ft->olength : ft->signal.length) / ft->signal.channels;

  lsx_writes(ft, "NIST_1A\n");
  lsx_writes(ft, "   1024\n");

  if (samples) {
    sprintf(buf, "sample_count -i %llu\n", (unsigned long long)samples);
    lsx_writes(ft, buf);
  }
  sprintf(buf, "sample_n_bytes -i %d\n", ft->encoding.bits_per_sample >> 3);
  lsx_writes(ft, buf);
  sprintf(buf, "channel_count -i %d\n", ft->signal.channels);
  lsx_writes(ft, buf);
  if (ft->encoding.bits_per_sample == 8)
    sprintf(buf, "sample_byte_format -s1 1\n");
  else
    sprintf(buf, "sample_byte_format -s2 %s\n", ft->encoding.reverse_bytes ? "10" : "01");
  lsx_writes(ft, buf);
  sprintf(buf, "sample_rate -i %u\n", (unsigned)(ft->signal.rate + .5));
  lsx_writes(ft, buf);
  if (ft->encoding.encoding == SOX_ENCODING_ULAW)
    lsx_writes(ft, "sample_coding -s4 ulaw\n");
  else
    lsx_writes(ft, "sample_coding -s3 pcm\n");
  lsx_writes(ft, "end_head\n");
  lsx_padbytes(ft, 1024 - (size_t)lsx_tell(ft));
  return SOX_SUCCESS;
}

const sox_format_handler_t *lsx_sphere_format_fn(void)
{
  static char const *const names[] = {"sph", "nist", NULL};
  static unsigned const write_encodings[] = {
    SOX_ENCODING_SIGN2, 8, 16, 24, 32, 0,
    SOX_ENCODING_ULAW, 8, 0,
    0};
  static sox_format_handler_t const handler = {
    "SPeech HEader Resources; defined by NIST", names, SOX_FILE_REWIND,
    sph_startread, lsx_rawread, NULL,
    sph_write_header, lsx_rawwrite, NULL,
    lsx_rawseek, write_encodings, NULL, 0
  };
  return &handler;
}

/* ===================================================================== */
/* IRCAM sf */
static struct { char str[4]; sox_bool reverse_bytes; char const *desc; } sf_id[] = {
  {"\144\243\001\0", 0, "little-endian VAX (native)"},
  {"\0\001\243\144", 1, "big-endian VAX"},
  {"\144\243\002\0", 1, "big-endian Sun (native)"},
  {"\0\002\243\144", 0, "little-endian Sun"},
  {"\144\243\003\0", 0, "little-endian MIPS (DEC)"},
  {"\0\003\243\144", 1, "big-endian MIPS (SGI)"},
  {"\144\243\004\0", 1, "big-endian NeXT"},
  {"    ", 0, NULL}
};
#define SF_FIXED_HDR 1024
#define SF_COMMENT 2
typedef enum { sf_Unspecified, sf_Linear_8 = 0x00001, sf_Alaw_8 = 0x10001, sf_Mulaw_8 = 0x20001, sf_Linear_16 = 0x00002,
  sf_Linear_24 = 0x00003, sf_Linear_32 = 0x40004, sf_Float = 0x00004, sf_Double = 0x00008 } sf_enc_t;

static sf_enc_t sf_ft_enc(unsigned size, sox_encoding_t encoding)
{
  if (encoding == SOX_ENCODING_ULAW && size == 8) return sf_Mulaw_8;
  if (encoding == SOX_ENCODING_ALAW && size == 8) return sf_Alaw_8;
  if (encoding == SOX_ENCODING_SIGN2 && size == 8) return sf_Linear_8;
  if (encoding == SOX_ENCODING_SIGN2 && size == 16) return sf_Linear_16;
  if (encoding == SOX_ENCODING_SIGN2 && size == 24) return sf_Linear_24;
  if (encoding == SOX_ENCODING_SIGN2 && size == 32) return sf_Linear_32;
  if (encoding == SOX_ENCODING_FLOAT && size == 32) return sf_Float;
  if (encoding == SOX_ENCODING_FLOAT && size == 64) return sf_Double;
  return sf_Unspecified;
}

static sox_encoding_t sf_sox_enc(uint32_t e, unsigned *size)
{
  switch (e) {
    case sf_Mulaw_8: *size = 8; return SOX_ENCODING_ULAW;
    case sf_Alaw_8: *size = 8; return SOX_ENCODING_ALAW;
    case sf_Linear_8: *size = 8; return SOX_ENCODING_SIGN2;
    case sf_Linear_16: *size = 16; return SOX_ENCODING_SIGN2;
    case sf_Linear_24: *size = 24; return SOX_ENCODING_SIGN2;
    case sf_Linear_32: *size = 32; return SOX_ENCODING_SIGN2;
    case sf_Float: *size = 32; return SOX_ENCODING_FLOAT;
    case sf_Double: *size = 64; return SOX_ENCODING_FLOAT;
    default: return SOX_ENCODING_UNKNOWN;
  }
}

static int sf_startread(sox_format_t *ft)
{
  char magic[4];
  float rate;
  uint32_t channels, ft_encoding;
  unsigned i, bits_per_sample = 0;
  sox_encoding_t encoding;
  uint16_t code, size;

  if (lsx_readchars(ft, magic, sizeof(magic)))
    return SOX_EOF;

  for (i = 0; sf_id[i].desc && memcmp(magic, sf_id[i].str, sizeof(magic)); ++i);
  if (!sf_id[i].desc) {
    lsx_fail_errno(ft, SOX_EHDR, "sf: can't find IRCAM identifier");
    return SOX_EOF;
  }
  lsx_report("found %s identifier", sf_id[i].desc);
  ft->encoding.reverse_bytes = sf_id[i].reverse_bytes;

  if (lsx_readf(ft, &rate) || lsx_readdw(ft, &channels) || lsx_readdw(ft, &ft_encoding))
    return SOX_EOF;

  if (!(encoding = sf_sox_enc(ft_encoding, &bits_per_sample))) {
    lsx_fail_errno(ft, SOX_EFMT, "sf: unsupported encoding %#x)", ft_encoding);
    return SOX_EOF;
  }
  do {
    if (lsx_readw(ft, &code) || lsx_readw(ft, &size))
      return SOX_EOF;
    if (code == SF_COMMENT) {
      char *buf = lsx_calloc(1, (size_t)size + 1);
      if (lsx_readchars(ft, buf, (size_t)size) != SOX_SUCCESS) {
        free(buf);
        return SOX_EOF;
      }
      sox_append_comments(&ft->comments, buf);
      free(buf);
    } else if (lsx_skipbytes(ft, (size_t)size))
      return SOX_EOF;
  } while (code);
  if (lsx_skipbytes(ft, SF_FIXED_HDR - (size_t)lsx_tell(ft)))
    return SOX_EOF;

  return lsx_check_read_params(ft, channels, rate, encoding, bits_per_sample, (uint64_t)0, sox_true);
}

static int sf_write_header(sox_format_t *ft)
{
  char *comment = cat_comments(&ft->comments);
  size_t len = min(SF_FIXED_HDR - 4 - 3 * 4 - 4 * 2, strlen(comment) + 1);
  size_t info_len = max(4, (len + 3) & ~3u);
  int i = ft->encoding.reverse_bytes == 0 ? 0 : 2;
  sox_bool error = sox_false
    || writechars(ft, sf_id[i].str, sizeof(sf_id[i].str))
    || lsx_writef(ft, ft->signal.rate)
    || lsx_writedw(ft, ft->signal.channels)
    || lsx_writedw(ft, sf_ft_enc(ft->encoding.bits_per_sample, ft->encoding.encoding))
    || lsx_writew(ft, SF_COMMENT)
    || lsx_writew(ft, (unsigned)info_len)
    || writechars(ft, comment, len)
    || lsx_padbytes(ft, SF_FIXED_HDR - (size_t)lsx_tell(ft));
  free(comment);
  return error ? SOX_EOF : SOX_SUCCESS;
}

const sox_format_handler_t *lsx_sf_format_fn(void)
{
  static char const *const names[] = {"sf", "ircam", NULL};
  static unsigned const write_encodings[] = {
    SOX_ENCODING_ULAW, 8, 0,
    SOX_ENCODING_ALAW, 8, 0,
    SOX_ENCODING_SIGN2, 8, 16, 24, 32, 0,
    SOX_ENCODING_FLOAT, 32, 64, 0,
    0};
  static sox_format_handler_t const handler = {
    "Institut de Recherche et Coordination Acoustique/Musique", names, SOX_FILE_LIT_END,
    sf_startread, lsx_rawread, NULL,
    sf_write_header, lsx_rawwrite, NULL,
    lsx_rawseek, write_encodings, NULL, 0
  };
  return &handler;
}

/* ===================================================================== */
/* 8SVX */
typedef struct {
  uint64_t nsamples;
  uint64_t left;
  off_t ch0_pos;
  sox_uint8_t_dummy;
} svx_dummy_t;

typedef struct {
  uint64_t nsamples;
  uint64_t left;
  off_t ch0_pos;
  FILE *ch[4];
} svx_priv_t;

static void svx_writeheader(sox_format_t *ft, size_t nsamples)
{
  size_t formsize = nsamples + 8 + 4 + 8 + 20 + 8 + 32 + 8 + 4;

  lsx_writes(ft, "FORM");
  lsx_writedw(ft, (unsigned)formsize);
  lsx_writes(ft, "8SVX");

  lsx_writes(ft, "VHDR");
  lsx_writedw(ft, 20);
  lsx_writedw(ft, (unsigned)nsamples / ft->signal.channels);
  lsx_writedw(ft, 0);
  lsx_writedw(ft, 0);
  lsx_writew(ft, min(65535, (unsigned)(ft->signal.rate + .5)));
  lsx_writeb(ft, 1);
  lsx_writeb(ft, 0);
  lsx_writew(ft, 1); lsx_writew(ft, 0);

  lsx_writes(ft, "ANNO");
  lsx_writedw(ft, 32);
  lsx_writes(ft, "File created by Sound Exchange  ");

  lsx_writes(ft, "CHAN");
  lsx_writedw(ft, 4);
  lsx_writedw(ft, (ft->signal.channels == 2) ? 6u : (ft->signal.channels == 4) ? 15u : 2u);

  lsx_writes(ft, "BODY");
  lsx_writedw(ft, (unsigned)nsamples);
}

static int svx_startread(sox_format_t *ft)
{
  svx_priv_t *p = (svx_priv_t *)ft->priv;
  char buf[12];
  char *chunk_buf;
  uint32_t totalsize;
  uint32_t chunksize;
  uint32_t channels;
  unsigned short rate;
  int i;
  off_t chan1_pos;

  if (!ft->seekable) {
    lsx_fail_errno(ft, SOX_EINVAL, "8svx input file must be a file, not a pipe");
    return SOX_EOF;
  }
  rate = 0;
  channels = 1;

  if (lsx_readbuf(ft, buf, 4) != 4 || strncmp(buf, "FORM", 4) != 0) {
    lsx_fail_errno(ft, SOX_EHDR, "Header did not begin with magic word `FORM'");
    return SOX_EOF;
  }
  lsx_readdw(ft, &totalsize);
  if (lsx_readbuf(ft, buf, 4) != 4 || strncmp(buf, "8SVX", 4) != 0) {
    lsx_fail_errno(ft, SOX_EHDR, "'FORM' chunk does not specify `8SVX' as type");
    return SOX_EOF;
  }

  while (1) {
    if (lsx_readbuf(ft, buf, 4) != 4) {
      lsx_fail_errno(ft, SOX_EHDR, "Missing BODY chunk in 8SVX file");
      return SOX_EOF;
    }
    if (strncmp(buf, "VHDR", 4) == 0) {
      uint32_t oneshot;
      uint8_t oct, comp;
      lsx_readdw(ft, &chunksize);
      if (chunksize != 20) {
        lsx_fail_errno(ft, SOX_EHDR, "VHDR chunk has bad size");
        return SOX_EOF;
      }
      lsx_readdw(ft, &oneshot);
      lsx_skipbytes(ft, (size_t)8);
      lsx_readw(ft, &rate);
      lsx_readb(ft, &oct);
      lsx_readb(ft, &comp);
      if (comp) {
        lsx_fail_errno(ft, SOX_EHDR, "Unsupported data compression");
        return SOX_EOF;
      }
      lsx_skipbytes(ft, (size_t)4);
      continue;
    }
    if (strncmp(buf, "ANNO", 4) == 0 || strncmp(buf, "NAME", 4) == 0 || strncmp(buf, "AUTH", 4) == 0 || strncmp(buf, "(c) ", 4) == 0) {
      lsx_readdw(ft, &chunksize);
      if (chunksize & 1) chunksize++;
      chunk_buf = lsx_calloc(1, chunksize + 1);
      if (lsx_readbuf(ft, chunk_buf, chunksize) != chunksize) {
        free(chunk_buf);
        lsx_fail_errno(ft, SOX_EHDR, "Couldn't read all of header");
        return SOX_EOF;
      }
      lsx_debug("%.4s: %s", buf, chunk_buf);
      free(chunk_buf);
      continue;
    }
    if (strncmp(buf, "CHAN", 4) == 0) {
      lsx_readdw(ft, &chunksize);
      if (chunksize != 4) {
        lsx_fail_errno(ft, SOX_EHDR, "Couldn't read all of header");
        return SOX_EOF;
      }
      lsx_readdw(ft, &channels);
      channels = (channels & 0x01) + ((channels & 0x02) >> 1) + ((channels & 0x04) >> 2) + ((channels & 0x08) >> 3);
      continue;
    }
    if (strncmp(buf, "BODY", 4) == 0) break;
    lsx_readdw(ft, &chunksize);
    if (chunksize & 1) chunksize++;
    lsx_seeki(ft, (int64_t)chunksize, SEEK_CUR);
  }

  if (rate == 0) {
    lsx_fail_errno(ft, SOX_EHDR, "Invalid sample rate");
    return SOX_EOF;
  }
  if (channels == 0) channels = 1;

  lsx_readdw(ft, &(chunksize));
  p->nsamples = chunksize;
  p->left = p->nsamples / channels;

  ft->signal.rate = rate;
  ft->signal.channels = channels;
  ft->encoding.encoding = SOX_ENCODING_SIGN2;
  ft->encoding.bits_per_sample = 8;
  ft->signal.length = p->nsamples;

  p->ch[0] = ft->fp;
  p->ch0_pos = ftello(ft->fp);
  chan1_pos = lsx_tell(ft);

  for (i = 1; i < (int)channels; i++) {
    if ((p->ch[i] = fopen(ft->filename, "rb")) == NULL) {
      lsx_fail_errno(ft, errno, "Can't open channel file '%s'", ft->filename);
      return SOX_EOF;
    }
    if (fseeko(p->ch[i], chan1_pos, SEEK_SET)) {
      lsx_fail_errno(ft, errno, "Can't position channel %d", i);
      return SOX_EOF;
    }
    if (fseeko(p->ch[i], (off_t)(p->nsamples / channels * i), SEEK_CUR)) {
      lsx_fail_errno(ft, errno, "Can't seek channel %d", i);
      return SOX_EOF;
    }
  }
  return SOX_SUCCESS;
}

static size_t svx_read(sox_format_t *ft, sox_sample_t *buf, size_t nsamp)
{
  unsigned char datum;
  size_t done = 0, i;
  svx_priv_t *p = (svx_priv_t *)ft->priv;

  while (done < nsamp) {
    if (p->left == 0) break;
    for (i = 0; i < ft->signal.channels; i++) {
      if (fread(&datum, (size_t)1, (size_t)1, p->ch[i]) != 1)
        return done;
      *buf++ = SOX_SIGNED_8BIT_TO_SAMPLE(datum);
    }
    p->left--;
    done += ft->signal.channels;
  }
  return done;
}

static int svx_stopread(sox_format_t *ft)
{
  size_t i;
  svx_priv_t *p = (svx_priv_t *)ft->priv;
  for (i = 1; i < ft->signal.channels; i++)
    if (p->ch[i]) fclose(p->ch[i]);
  return SOX_SUCCESS;
}

static int svx_startwrite(sox_format_t *ft)
{
  svx_priv_t *p = (svx_priv_t *)ft->priv;
  size_t i;

  if (!ft->seekable) {
    lsx_fail_errno(ft, SOX_EINVAL, "Output .8svx file must be a file, not a pipe");
    return SOX_EOF;
  }
  p->ch[0] = ft->fp;
  for (i = 1; i < ft->signal.channels; i++) {
    if ((p->ch[i] = lsx_tmpfile()) == NULL) {
      lsx_fail_errno(ft, errno, "Can't open channel output file");
      return SOX_EOF;
    }
  }
  p->nsamples = 0;
  svx_writeheader(ft, (size_t)p->nsamples);
  return SOX_SUCCESS;
}

static size_t svx_write(sox_format_t *ft, const sox_sample_t *buf, size_t len)
{
  svx_priv_t *p = (svx_priv_t *)ft->priv;
  unsigned char datum;
  size_t done = 0, i;

  p->nsamples += len;
  while (done < len) {
    for (i = 0; i < ft->signal.channels; i++) {
      datum = SOX_SAMPLE_TO_SIGNED_8BIT(*buf++, ft->clips);
      if (i == 0) lsx_writeb(ft, datum);
      else fputc(datum, p->ch[i]);
    }
    done += ft->signal.channels;
  }
  return done;
}

static int svx_stopwrite(sox_format_t *ft)
{
  svx_priv_t *p = (svx_priv_t *)ft->priv;
  size_t i, len;
  char svxbuf[512];

  for (i = 1; i < ft->signal.channels; i++) {
    if (fseeko(p->ch[i], (off_t)0, 0)) {
      lsx_fail_errno(ft, errno, "Can't rewind channel output file %lu", (unsigned long)i);
      return SOX_EOF;
    }
    while (!feof(p->ch[i])) {
      len = fread(svxbuf, (size_t)1, (size_t)512, p->ch[i]);
      if (lsx_writebuf(ft, svxbuf, len) != len) {
        lsx_fail_errno(ft, errno, "Can't write channel output file %lu", (unsigned long)i);
        return SOX_EOF;
      }
    }
    fclose(p->ch[i]);
  }

  if (p->nsamples % 2 != 0)
    lsx_writeb(ft, '\0');

  if (lsx_seeki(ft, (int64_t)0, 0) != 0) {
    lsx_fail_errno(ft, errno, "can't rewind output file to rewrite 8SVX header");
    return SOX_EOF;
  }
  svx_writeheader(ft, (size_t)p->nsamples);
  return SOX_SUCCESS;
}

const sox_format_handler_t *lsx_svx_format_fn(void)
{
  static char const *const names[] = {"8svx", NULL};
  static unsigned const write_encodings[] = {SOX_ENCODING_SIGN2, 8, 0, 0};
  static sox_format_handler_t const handler = {
    "Amiga audio format (a subformat of the Interchange File Format)", names,
    SOX_FILE_BIG_END | SOX_FILE_MONO | SOX_FILE_STEREO | SOX_FILE_QUAD,
    svx_startread, svx_read, svx_stopread,
    svx_startwrite, svx_write, svx_stopwrite,
    NULL, write_encodings, NULL, sizeof(svx_priv_t)
  };
  return &handler;
}

/* ===================================================================== */
/* AVR */
#define AVR_MAGIC "2BIT"
typedef struct {
  char magic[5];
  char name[8];
  unsigned short mono;
  unsigned short rez;
  unsigned short sign;
  unsigned short loop;
  unsigned short midi;
  uint32_t rate;
  uint32_t size;
  uint32_t lbeg;
  uint32_t lend;
  unsigned short res1;
  unsigned short res2;
  unsigned short res3;
  char ext[20];
  char user[64];
} avr_priv_t;

static int avr_startread(sox_format_t *ft)
{
  avr_priv_t *avr = (avr_priv_t *)ft->priv;
  int rc;

  lsx_reads(ft, avr->magic, (size_t)4);
  if (strncmp(avr->magic, AVR_MAGIC, (size_t)4)) {
    lsx_fail_errno(ft, SOX_EHDR, "AVR: unknown header");
    return SOX_EOF;
  }

  lsx_readbuf(ft, avr->name, sizeof(avr->name));
  lsx_readw(ft, &(avr->mono));
  if (avr->mono) ft->signal.channels = 2;
  else ft->signal.channels = 1;

  lsx_readw(ft, &(avr->rez));
  if (avr->rez == 8) {
    ft->encoding.bits_per_sample = 8;
  } else if (avr->rez == 16) {
    ft->encoding.bits_per_sample = 16;
  } else {
    lsx_fail_errno(ft, SOX_EFMT, "AVR: unsupported sample resolution");
    return SOX_EOF;
  }

  lsx_readw(ft, &(avr->sign));
  if (avr->sign) ft->encoding.encoding = SOX_ENCODING_SIGN2;
  else ft->encoding.encoding = SOX_ENCODING_UNSIGNED;

  lsx_readw(ft, &(avr->loop));
  lsx_readw(ft, &(avr->midi));
  lsx_readdw(ft, &(avr->rate));
  ft->signal.rate = (avr->rate & 0x00ffffff);
  lsx_readdw(ft, &(avr->size));
  lsx_readdw(ft, &(avr->lbeg));
  lsx_readdw(ft, &(avr->lend));
  lsx_readw(ft, &(avr->res1));
  lsx_readw(ft, &(avr->res2));
  lsx_readw(ft, &(avr->res3));
  lsx_readbuf(ft, avr->ext, sizeof(avr->ext));
  lsx_readbuf(ft, avr->user, sizeof(avr->user));

  rc = lsx_rawstartread(ft);
  if (rc)
    return rc;
  ft->signal.length = (uint64_t)avr->size * ft->signal.channels;
  return SOX_SUCCESS;
}

static int avr_startwrite(sox_format_t *ft)
{
  int rc;

  if (!ft->seekable) {
    lsx_fail_errno(ft, SOX_EOF, "AVR: file is not seekable");
    return SOX_EOF;
  }
  rc = lsx_rawstartwrite(ft);
  if (rc)
    return rc;

  lsx_writes(ft, AVR_MAGIC);
  lsx_writeb(ft, 0); lsx_writeb(ft, 0); lsx_writeb(ft, 0); lsx_writeb(ft, 0);
  lsx_writeb(ft, 0); lsx_writeb(ft, 0); lsx_writeb(ft, 0); lsx_writeb(ft, 0);
  if (ft->signal.channels == 1) lsx_writew(ft, 0);
  else if (ft->signal.channels == 2) lsx_writew(ft, 0xffff);
  else {
    lsx_fail_errno(ft, SOX_EFMT, "AVR: number of channels not supported");
    return 0;
  }
  if (ft->encoding.bits_per_sample == 8) lsx_writew(ft, 8);
  else if (ft->encoding.bits_per_sample == 16) lsx_writew(ft, 16);
  else {
    lsx_fail_errno(ft, SOX_EFMT, "AVR: unsupported sample resolution");
    return SOX_EOF;
  }
  if (ft->encoding.encoding == SOX_ENCODING_SIGN2) lsx_writew(ft, 0xffff);
  else if (ft->encoding.encoding == SOX_ENCODING_UNSIGNED) lsx_writew(ft, 0);
  else {
    lsx_fail_errno(ft, SOX_EFMT, "AVR: unsupported encoding");
    return SOX_EOF;
  }
  lsx_writew(ft, 0xffff);
  lsx_writew(ft, 0xffff);
  lsx_writedw(ft, (unsigned)(ft->signal.rate + .5));
  lsx_writedw(ft, 0);
  lsx_writedw(ft, 0);
  lsx_writedw(ft, 0);
  lsx_writew(ft, 0);
  lsx_writew(ft, 0);
  lsx_writew(ft, 0);
  lsx_padbytes(ft, 20);
  lsx_padbytes(ft, 64);
  return SOX_SUCCESS;
}

static size_t avr_write(sox_format_t *ft, const sox_sample_t *buf, size_t nsamp)
{
  avr_priv_t *avr = (avr_priv_t *)ft->priv;
  avr->size += nsamp;
  return lsx_rawwrite(ft, buf, nsamp);
}

static int avr_stopwrite(sox_format_t *ft)
{
  avr_priv_t *avr = (avr_priv_t *)ft->priv;
  unsigned size = avr->size / ft->signal.channels;

  lsx_seeki(ft, (int64_t)26, SEEK_SET);
  lsx_writedw(ft, size);
  lsx_seeki(ft, (int64_t)34, SEEK_SET);
  lsx_writedw(ft, size);
  return SOX_SUCCESS;
}

const sox_format_handler_t *lsx_avr_format_fn(void)
{
  static char const *const names[] = {"avr", NULL};
  static unsigned const write_encodings[] = {
