/* ================= noisered ================= */
typedef struct {
  float *window;
  float *lastwindow;
  float *noisegate;
  float *smoothing;
} nr_chandata_t;

typedef struct {
  char *profile_filename;
  double threshold;
  nr_chandata_t *chandata;
  size_t bufdata;
} nr_priv_t;

static int nr_getopts(sox_effect_t *effp, int argc, char **argv)
{
  nr_priv_t *p = (nr_priv_t *)effp->priv;
  --argc, ++argv;

  if (argc > 0) {
    p->profile_filename = argv[0];
    ++argv;
    --argc;
  }

  p->threshold = 0.5;
  do {
    NUMERIC_PARAMETER(threshold, 0, 1);
  } while (0);

  return argc ? lsx_usage(effp) : SOX_SUCCESS;
}

static int nr_start(sox_effect_t *effp)
{
  nr_priv_t *data = (nr_priv_t *)effp->priv;
  size_t fchannels = 0;
  size_t channels = effp->in_signal.channels;
  size_t i;
  FILE *ifp;

  if (!data->profile_filename || !strcmp(data->profile_filename, "-")) {
    if (sox_globals.stdin_in_use_by) {
      lsx_fail("stdin already in use by `%s'", sox_globals.stdin_in_use_by);
      return SOX_EOF;
    }
    sox_globals.stdin_in_use_by = effp->handler.name;
    ifp = stdin;
  } else if ((ifp = fopen(data->profile_filename, "r")) == NULL) {
    lsx_fail("couldn't open input file `%s': %s", data->profile_filename, strerror(errno));
    return SOX_EOF;
  }

  data->chandata = lsx_calloc(channels, sizeof(*(data->chandata)));
  data->bufdata = 0;
  for (i = 0; i < channels; i++) {
    data->chandata[i].noisegate = lsx_calloc(FREQCOUNT, sizeof(float));
    data->chandata[i].smoothing = lsx_calloc(FREQCOUNT, sizeof(float));
    data->chandata[i].lastwindow = NULL;
  }
  while (1) {
    unsigned long i1_ul;
    size_t i1;
    float f1;
    if (2 != fscanf(ifp, " Channel %lu: %f", &i1_ul, &f1))
      break;
    i1 = i1_ul;
    if (i1 != fchannels) {
      lsx_fail("noisered: Got channel %lu, expected channel %lu.", (unsigned long)i1, (unsigned long)fchannels);
      return SOX_EOF;
    }
    if (fchannels >= channels) {
      fchannels++;
      break;
    }
    data->chandata[fchannels].noisegate[0] = f1;
    for (i = 1; i < FREQCOUNT; i++) {
      if (1 != fscanf(ifp, ", %f", &f1)) {
        lsx_fail("noisered: Not enough data for channel %lu (expected %d, got %lu)",
            (unsigned long)fchannels, FREQCOUNT, (unsigned long)i);
        return SOX_EOF;
      }
      data->chandata[fchannels].noisegate[i] = f1;
    }
    fchannels++;
  }
  if (fchannels != channels) {
    lsx_fail("noisered: channel mismatch: %lu in input, %lu in profile.", (unsigned long)channels, (unsigned long)fchannels);
    return SOX_EOF;
  }
  if (ifp != stdin)
    fclose(ifp);

  effp->out_signal.length = SOX_UNKNOWN_LEN;
  return SOX_SUCCESS;
}

static void reduce_noise(nr_chandata_t *chan, float *window, double level)
{
  float *inr, *ini, *outr, *outi, *power;
  float *smoothing = chan->smoothing;
  int i;
  double *work = lsx_malloc(WINDOWSIZE * sizeof(double));

  inr = lsx_calloc(WINDOWSIZE * 5, sizeof(float));
  ini = inr + WINDOWSIZE;
  outr = ini + WINDOWSIZE;
  outi = outr + WINDOWSIZE;
  power = outi + WINDOWSIZE;

  /* forward FFT of window */
  for (i = 0; i < WINDOWSIZE; i++) work[i] = window[i];
  lsx_safe_rdft(WINDOWSIZE, 1, work);
  outr[0] = work[0]; outi[0] = 0;
  outr[HALFWINDOW] = work[1]; outi[HALFWINDOW] = 0;
  for (i = 1; i < HALFWINDOW; i++) {
    outr[i] = work[2 * i];
    outi[i] = -work[2 * i + 1];
    outr[WINDOWSIZE - i] = work[2 * i];
    outi[WINDOWSIZE - i] = work[2 * i + 1];
  }

  memcpy(inr, window, WINDOWSIZE * sizeof(float));
  lsx_apply_hann_f(inr, WINDOWSIZE);
  lsx_power_spectrum_f(WINDOWSIZE, inr, power);

  for (i = 0; i < FREQCOUNT; i++) {
    float smooth;
    float plog;
    plog = log(power[i]);
    if (power[i] != 0 && plog < chan->noisegate[i] + level * 8.0)
      smooth = 0.0;
    else
      smooth = 1.0;
    smoothing[i] = smooth * 0.5 + smoothing[i] * 0.5;
  }

  for (i = 2; i < FREQCOUNT - 2; i++) {
    if (smoothing[i] >= 0.5 && smoothing[i] <= 0.55 &&
        smoothing[i - 1] < 0.1 && smoothing[i - 2] < 0.1 &&
        smoothing[i + 1] < 0.1 && smoothing[i + 2] < 0.1)
      smoothing[i] = 0.0;
  }

  outr[0] *= smoothing[0];
  outi[0] *= smoothing[0];
  outr[FREQCOUNT - 1] *= smoothing[FREQCOUNT - 1];
  outi[FREQCOUNT - 1] *= smoothing[FREQCOUNT - 1];

  for (i = 1; i < FREQCOUNT - 1; i++) {
    int j = WINDOWSIZE - i;
    float smooth = smoothing[i];
    outr[i] *= smooth;
    outi[i] *= smooth;
    outr[j] *= smooth;
    outi[j] *= smooth;
  }

  /* inverse */
  work[0] = outr[0];
  work[1] = outr[HALFWINDOW];
  for (i = 1; i < HALFWINDOW; i++) {
    work[2 * i] = outr[i];
    work[2 * i + 1] = -outi[i];
  }
  lsx_safe_rdft(WINDOWSIZE, -1, work);
  for (i = 0; i < WINDOWSIZE; i++) inr[i] = work[i] * (2.0 / WINDOWSIZE);
  lsx_apply_hann_f(inr, WINDOWSIZE);

  memcpy(window, inr, WINDOWSIZE * sizeof(float));
  free(inr);
  free(work);
}

static int process_window(sox_effect_t *effp, nr_priv_t *data, unsigned chan_num, unsigned num_chans,
    sox_sample_t *obuf, unsigned len)
{
  int j;
  float *nextwindow;
  int use = min(len, WINDOWSIZE) - min(len, (WINDOWSIZE / 2));
  nr_chandata_t *chan = &(data->chandata[chan_num]);
  int first = (chan->lastwindow == NULL);

  if ((nextwindow = lsx_calloc(WINDOWSIZE, sizeof(float))) == NULL)
    return SOX_EOF;

  memcpy(nextwindow, chan->window + WINDOWSIZE / 2, sizeof(float) * (WINDOWSIZE / 2));

  reduce_noise(chan, chan->window, data->threshold);
  if (!first) {
    for (j = 0; j < use; j++) {
      float s = chan->window[j] + chan->lastwindow[WINDOWSIZE / 2 + j];
      obuf[chan_num + num_chans * j] = SOX_FLOAT_32BIT_TO_SAMPLE(s, effp->clips);
    }
    free(chan->lastwindow);
  } else {
    for (j = 0; j < use; j++) {
      obuf[chan_num + num_chans * j] = SOX_FLOAT_32BIT_TO_SAMPLE(chan->window[j], effp->clips);
    }
  }
  chan->lastwindow = chan->window;
  chan->window = nextwindow;

  return use;
}

static int nr_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  nr_priv_t *data = (nr_priv_t *)effp->priv;
  size_t samp = min(*isamp, *osamp);
  size_t tracks = effp->in_signal.channels;
  size_t track_samples = samp / tracks;
  size_t ncopy = min(track_samples, WINDOWSIZE - data->bufdata);
  size_t whole_window = (ncopy + data->bufdata == WINDOWSIZE);
  int oldbuf = data->bufdata;
  size_t i;

  if (whole_window)
    data->bufdata = WINDOWSIZE / 2;
  else
    data->bufdata += ncopy;

  for (i = 0; i < tracks; i++) {
    nr_chandata_t *chan = &(data->chandata[i]);
    size_t j;

    if (chan->window == NULL)
      chan->window = lsx_calloc(WINDOWSIZE, sizeof(float));

    for (j = 0; j < ncopy; j++)
      chan->window[oldbuf + j] = SOX_SAMPLE_TO_FLOAT_32BIT(ibuf[i + tracks * j], effp->clips);

    if (!whole_window)
      continue;
    else
      process_window(effp, data, (unsigned)i, (unsigned)tracks, obuf, (unsigned)(oldbuf + ncopy));
  }

  *isamp = tracks * ncopy;
  if (whole_window)
    *osamp = tracks * (WINDOWSIZE / 2);
  else
    *osamp = 0;

  return SOX_SUCCESS;
}

static int nr_drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{
  nr_priv_t *data = (nr_priv_t *)effp->priv;
  unsigned i;
  unsigned tracks = effp->in_signal.channels;
  for (i = 0; i < tracks; i++)
    *osamp = process_window(effp, data, i, tracks, obuf, (unsigned)data->bufdata);
  return SOX_EOF;
}

static int nr_stop(sox_effect_t *effp)
{
  nr_priv_t *data = (nr_priv_t *)effp->priv;
  size_t i;
  for (i = 0; i < effp->in_signal.channels; i++) {
    nr_chandata_t *chan = &(data->chandata[i]);
    free(chan->lastwindow);
    free(chan->window);
    free(chan->smoothing);
    free(chan->noisegate);
  }
  free(data->chandata);
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_noisered_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "noisered", USAGE_noisered, SOX_EFF_MCHAN | SOX_EFF_LENGTH,
    nr_getopts, nr_start, nr_flow, nr_drain, nr_stop, NULL, sizeof(nr_priv_t)
  };
  return &handler;
}
