/* splice effect */
#include "sox.h"
#include "usage_strings.h"

static double difference(const sox_sample_t *a, const sox_sample_t *b, size_t length)
{
  double diff = 0;
  size_t i = 0;
#define _ diff += sqr((double)a[i] - b[i]), ++i;
  do { _ _ _ _ _ _ _ _ } while (i < length);
#undef _
  return diff;
}

static size_t best_overlap_position(sox_sample_t const *f1, sox_sample_t const *f2, uint64_t overlap, uint64_t search, size_t channels)
{
  size_t i, best_pos = 0;
  double diff, least_diff = difference(f2, f1, (size_t)(channels * overlap));

  for (i = 1; i < search; ++i) {
    diff = difference(f2 + channels * i, f1, (size_t)(channels * overlap));
    if (diff < least_diff)
      least_diff = diff, best_pos = i;
  }
  return best_pos;
}

typedef struct {
  enum { Cosine_2, Cosine_4, Triangular } fade_type;
  unsigned nsplices;
  struct {
    char *str;
    uint64_t overlap;
    uint64_t search;
    uint64_t start;
  } *splices;
  uint64_t in_pos;
  unsigned splices_pos;
  size_t buffer_pos;
  size_t max_buffer_size;
  sox_sample_t *buffer;
  unsigned state;
} priv_t;

static void splice(sox_effect_t *effp, const sox_sample_t *in1, const sox_sample_t *in2, sox_sample_t *output, uint64_t overlap, size_t channels)
{
  priv_t *p = (priv_t *)effp->priv;
  size_t i, j, k = 0;

  if (p->fade_type == Cosine_4) {
    double fade_step = M_PI_2 / overlap;
    for (i = 0; i < overlap; ++i) {
      double fade_in = sin(i * fade_step);
      double fade_out = cos(i * fade_step);
      for (j = 0; j < channels; ++j, ++k) {
        double d = in1[k] * fade_out + in2[k] * fade_in;
        output[k] = SOX_ROUND_CLIP_COUNT(d, effp->clips);
      }
    }
  } else if (p->fade_type == Cosine_2) {
    double fade_step = M_PI / overlap;
    for (i = 0; i < overlap; ++i) {
      double fade_in = .5 - .5 * cos(i * fade_step);
      double fade_out = 1 - fade_in;
      for (j = 0; j < channels; ++j, ++k) {
        double d = in1[k] * fade_out + in2[k] * fade_in;
        output[k] = SOX_ROUND_CLIP_COUNT(d, effp->clips);
      }
    }
  } else {
    double fade_step = 1. / overlap;
    for (i = 0; i < overlap; ++i) {
      double fade_in = fade_step * i;
      double fade_out = 1 - fade_in;
      for (j = 0; j < channels; ++j, ++k) {
        double d = in1[k] * fade_out + in2[k] * fade_in;
        output[k] = SOX_ROUND_CLIP_COUNT(d, effp->clips);
      }
    }
  }
}

static uint64_t do_splice(sox_effect_t *effp, sox_sample_t *f, uint64_t overlap, uint64_t search, size_t channels)
{
  uint64_t offset = search ? best_overlap_position(f, f + overlap * channels, overlap, search, channels) : 0;
  splice(effp, f, f + (overlap + offset) * channels, f + (overlap + offset) * channels, overlap, channels);
  return overlap + offset;
}

static int parse(sox_effect_t *effp, char **argv, sox_rate_t rate)
{
