/* FFT-based FIR filtering (overlap-save), and the fir effect */
#include "dft_filter.h"
#include "usage_strings.h"

void lsx_set_dft_filter(dft_filter_t *f, double *h, int n, int post_peak)
{
  int i;
  f->num_taps = n;
  f->post_peak = post_peak;
  f->dft_length = lsx_set_dft_length(f->num_taps);
  f->coefs = lsx_calloc(f->dft_length, sizeof(*f->coefs));
  for (i = 0; i < f->num_taps; ++i)
    f->coefs[(i + f->dft_length - f->num_taps + 1) & (f->dft_length - 1)] = h[i] / f->dft_length * 2;
  free(h);
  lsx_safe_rdft(f->dft_length, 1, f->coefs);
}

int lsx_dft_filter_start(sox_effect_t *effp)
{
  dft_filter_priv_t *p = (dft_filter_priv_t *)effp->priv;
  fifo_create(&p->input_fifo, sizeof(double));
  memset(fifo_reserve(&p->input_fifo, p->filter_ptr->post_peak), 0, sizeof(double) * p->filter_ptr->post_peak);
  fifo_create(&p->output_fifo, sizeof(double));
  p->samples_in = p->samples_out = 0;
  return SOX_SUCCESS;
}

static void filter(dft_filter_priv_t *p)
{
  int i, num_in = max(0, (int)fifo_occupancy(&p->input_fifo));
  dft_filter_t const *f = p->filter_ptr;
  int const overlap = f->num_taps - 1;
  double *output;

  while (num_in >= f->dft_length) {
    double const *input = fifo_read_ptr(&p->input_fifo);
    fifo_read(&p->input_fifo, f->dft_length - overlap, NULL);
    num_in -= f->dft_length - overlap;

    output = fifo_reserve(&p->output_fifo, f->dft_length);
    fifo_trim_by(&p->output_fifo, overlap);
    memcpy(output, input, f->dft_length * sizeof(*output));

    lsx_safe_rdft(f->dft_length, 1, output);
    output[0] *= f->coefs[0];
    output[1] *= f->coefs[1];
    for (i = 2; i < f->dft_length; i += 2) {
      double tmp = output[i];
      output[i] = f->coefs[i] * tmp - f->coefs[i + 1] * output[i + 1];
      output[i + 1] = f->coefs[i + 1] * tmp + f->coefs[i] * output[i + 1];
    }
    lsx_safe_rdft(f->dft_length, -1, output);
  }
}

int lsx_dft_filter_flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  dft_filter_priv_t *p = (dft_filter_priv_t *)effp->priv;
  size_t i, odone = min(*osamp, (size_t)fifo_occupancy(&p->output_fifo));
  double const *s = fifo_read(&p->output_fifo, odone, NULL);

  for (i = 0; i < odone; ++i)
    *obuf++ = SOX_ROUND_CLIP_COUNT(*s, effp->clips), ++s;
  p->samples_out += odone;

  if (*isamp && odone < *osamp) {
    double *t = fifo_write(&p->input_fifo, *isamp, NULL);
    p->samples_in += *isamp;
    for (i = *isamp; i; --i)
      *t++ = *ibuf++;
    filter(p);
  } else *isamp = 0;
  *osamp = odone;
  return SOX_SUCCESS;
}

int lsx_dft_filter_drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{
  dft_filter_priv_t *p = (dft_filter_priv_t *)effp->priv;
  size_t isamp = 0;
  size_t remaining = p->samples_in > p->samples_out ? (size_t)(p->samples_in - p->samples_out) : 0;
  double *buff = lsx_calloc(1024, sizeof(*buff));

  if (remaining > 0) {
    while ((size_t)fifo_occupancy(&p->output_fifo) < remaining) {
      fifo_write(&p->input_fifo, 1024, buff);
      p->samples_in += 1024;
      filter(p);
    }
    fifo_trim_to(&p->output_fifo, remaining);
    p->samples_in = 0;
  }
  free(buff);
  return lsx_dft_filter_flow(effp, 0, obuf, &isamp, osamp);
}

int lsx_dft_filter_stop(sox_effect_t *effp)
{
  dft_filter_priv_t *p = (dft_filter_priv_t *)effp->priv;
  fifo_delete(&p->input_fifo);
  fifo_delete(&p->output_fifo);
  if (effp->flow == effp->flows - 1 || effp->flows == 1) {
    free(p->filter_ptr->coefs);
    memset(p->filter_ptr, 0, sizeof(*p->filter_ptr));
  }
  return SOX_SUCCESS;
}

/* ================= fir ================= */
typedef struct {
  dft_filter_priv_t base;
  char const *filename;
  double *h;
  int n;
} fir_priv_t;

static int fir_create(sox_effect_t *effp, int argc, char **argv)
{
  fir_priv_t *p = (fir_priv_t *)effp->priv;
  dft_filter_priv_t *b = &p->base;
  double d;
  char c;

  b->filter_ptr = lsx_calloc(1, sizeof(*b->filter_ptr));
  --argc, ++argv;
  if (!argc)
    p->filename = "-";
  else if (argc == 1)
    p->filename = argv[0], --argc;
  else for (; argc && sscanf(*argv, "%lf%c", &d, &c) == 1; --argc, ++argv) {
    p->n++;
    p->h = lsx_realloc(p->h, p->n * sizeof(*p->h));
    p->h[p->n - 1] = d;
  }
  return argc ? lsx_usage(effp) : SOX_SUCCESS;
}

static int fir_start(sox_effect_t *effp)
{
  fir_priv_t *p = (fir_priv_t *)effp->priv;
  dft_filter_t *f = p->base.filter_ptr;
  double d;
  char c;
  int i;

  if (!f->num_taps) {
    if (!p->n && p->filename) {
      FILE *file;
      if (!strcmp(p->filename, "-")) {
        if (sox_globals.stdin_in_use_by) {
          lsx_fail("stdin already in use by `%s'", sox_globals.stdin_in_use_by);
          return SOX_EOF;
        }
        sox_globals.stdin_in_use_by = effp->handler.name;
        file = stdin;
      } else if (!(file = fopen(p->filename, "r"))) {
        lsx_fail("couldn't open input file `%s': %s", p->filename, strerror(errno));
        return SOX_EOF;
      }
      while ((i = fscanf(file, " #%*[^\n]%c", &c)) >= 0) {
        if (i >= 1) continue;
        if ((i = fscanf(file, "%lf", &d)) > 0) {
          p->n++;
          p->h = lsx_realloc(p->h, p->n * sizeof(*p->h));
          p->h[p->n - 1] = d;
        } else break;
      }
      if (!feof(file)) {
        lsx_fail("error reading coefficient file");
        if (file != stdin) fclose(file);
        return SOX_EOF;
      }
      if (file != stdin) fclose(file);
    }
    lsx_report("%i coefficients", p->n);
    if (!p->n)
      return SOX_EFF_NULL;
    lsx_set_dft_filter(f, p->h, p->n, p->n >> 1);
    p->h = NULL;
  }
  return lsx_dft_filter_start(effp);
}

const sox_effect_handler_t *lsx_fir_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "fir", USAGE_fir, 0,
    fir_create, fir_start, lsx_dft_filter_flow, lsx_dft_filter_drain, lsx_dft_filter_stop, NULL, sizeof(fir_priv_t)
  };
  return &handler;
}
