  int c;
  hilbert_priv_t *p = (hilbert_priv_t *)effp->priv;
  dft_filter_priv_t *b = &p->base;

  b->filter_ptr = lsx_calloc(1, sizeof(*b->filter_ptr));
  lsx_getopt_init(argc, argv, "+n:", NULL, lsx_getopt_flag_none, 1, &optstate);

  while ((c = lsx_getopt(&optstate)) != -1) switch (c) {
    GETOPT_NUMERIC(optstate, 'n', taps, 3, 32767)
    default: lsx_fail("invalid option `-%c'", optstate.opt); return lsx_usage(effp);
  }
  if (p->taps && p->taps % 2 == 0) {
    lsx_fail("only filters with an odd number of taps are supported");
    return SOX_EOF;
  }
  return optstate.ind != argc ? lsx_usage(effp) : SOX_SUCCESS;
}

static int hilbert_start(sox_effect_t *effp)
{
  hilbert_priv_t *p = (hilbert_priv_t *)effp->priv;
  dft_filter_t *f = p->base.filter_ptr;

  if (!f->num_taps) {
    int i;
    if (!p->taps) {
      p->taps = effp->in_signal.rate / 76.5 + 2;
      p->taps += 1 - (p->taps % 2);
      lsx_debug("choosing number of taps = %d (override with -n)", p->taps);
    }
    p->h = lsx_malloc(p->taps * sizeof(*p->h));
    for (i = 0; i < p->taps; i++) {
      int k = -(p->taps / 2) + i;
      if (k % 2 == 0) {
        p->h[i] = 0.0;
      } else {
        double pk = M_PI * k;
        p->h[i] = (1 - cos(pk)) / pk;
      }
    }
    lsx_apply_blackman(p->h, p->taps, .16);
    lsx_set_dft_filter(f, p->h, p->taps, p->taps / 2);
    p->h = NULL;
  }
  return lsx_dft_filter_start(effp);
}

const sox_effect_handler_t *lsx_hilbert_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "hilbert", USAGE_hilbert, 0,
    hilbert_getopts, hilbert_start, lsx_dft_filter_flow, lsx_dft_filter_drain, lsx_dft_filter_stop, NULL, sizeof(hilbert_priv_t)
  };
  return &handler;
}
