{"command":"cat > /workspace/src/mcompand.c <<'EOF'
/* mcompand: multi-band compander with Linkwitz-Riley crossovers */
#include "sox.h"
#include "usage_strings.h"
#include "compandt.h"
#include <ctype.h>

#define N 4
typedef struct {
  double in[2 * N], out_low[2 * N], out_high[2 * N];
} previous_t;

typedef struct {
  previous_t *previous;
  size_t pos;
  double coefs[3 * (N + 1)];
} crossover_t;

static void square_quadratic(double const *x, double *y)
{
  y[0] = x[0] * x[0];
  y[1] = 2 * x[0] * x[1];
  y[2] = 2 * x[0] * x[2] + x[1] * x[1];
  y[3] = 2 * x[1] * x[2];
  y[4] = x[2] * x[2];
}

static int crossover_setup(sox_effect_t *effp, crossover_t *p, double frequency)
{
  double w0 = 2 * M_PI * frequency / effp->in_signal.rate;
  double Q = sqrt(.5), alpha = sin(w0) / (2 * Q);
  double x[9], norm;
  int i;

  if (w0 > M_PI) {
    lsx_fail("frequency must not exceed half the sample-rate (Nyquist rate)");
    return SOX_EOF;
  }
  x[0] = (1 - cos(w0)) / 2;
  x[1] = 1 - cos(w0);
  x[2] = (1 - cos(w0)) / 2;
  x[3] = (1 + cos(w0)) / 2;
  x[4] = -(1 + cos(w0));
  x[5] = (1 + cos(w0)) / 2;
  x[6] = 1 + alpha;
  x[7] = -2 * cos(w0);
  x[8] = 1 - alpha;
  for (norm = x[6], i = 0; i < 9; ++i) x[i] /= norm;
  square_quadratic(x, p->coefs);
  square_quadratic(x + 3, p->coefs + 5);
  square_quadratic(x + 6, p->coefs + 10);

  p->previous = lsx_calloc(effp->in_signal.channels, sizeof(*p->previous));
  p->pos = 0;
  return SOX_SUCCESS;
}

static int crossover_flow(sox_effect_t *effp, crossover_t *p, sox_sample_t *ibuf, sox_sample_t *obuf_low, sox_sample_t *obuf_high, size_t len0)
{
  double out_low, out_high;
  size_t c, len = len0 / effp->in_signal.channels;

  while (len--) {
    p->pos = p->pos ? p->pos - 1 : N - 1;
    for (c = 0; c < effp->in_signal.channels; ++c) {
      previous_t *pr = p->previous + c;
      double *in = pr->in + p->pos;
      double *out_lo = pr->out_low + p->pos;
      double *out_hi = pr->out_high + p->pos;
      int j = 1;
      in[0] = in[N] = *ibuf++;
      out_low = p->coefs[0] * in[0];
      out_high = p->coefs[N + 1] * in[0];
      for (; j <= N; ++j) {
        out_low += p->coefs[j] * in[j] - p->coefs[2 * N + 2 + j] * out_lo[j];
        out_high += p->coefs[N + 1 + j] * in[j] - p->coefs[2 * N + 2 + j] * out_hi[j];
      }
      out_lo[0] = out_lo[N] = out_low;
      out_hi[0] = out_hi[N] = out_high;
      *obuf_low++ = SOX_ROUND_CLIP_COUNT(out_low, effp->clips);
      *obuf_high++ = SOX_ROUND_CLIP_COUNT(out_high, effp->clips);
    }
  }
  return SOX_SUCCESS;
}

typedef struct {
  sox_compandt_t transfer_fn;
  size_t expectedChannels;
  double *attackRate;
  double *decayRate;
  double *volume;
  double delay;
  double topfreq;
  crossover_t filter;
  sox_sample_t *delay_buf;
  size_t delay_size;
  ptrdiff_t delay_buf_ptr;
  size_t delay_buf_cnt;
} comp_band_t;

typedef struct {
  size_t nBands;
  sox_sample_t *band_buf1, *band_buf2, *band_buf3;
  size_t band_buf_len;
  size_t delay_buf_size;
  comp_band_t *bands;
  char *arg;
} priv_t;

static int getopts_1(comp_band_t *l, size_t n, char **argv)
{
  char *s;
  size_t rates, i, commas;

  for (s = argv[0], commas = 0; *s; ++s)
    if (*s == ',') ++commas;

  if (commas % 2 == 0) {
    lsx_fail("compander: Odd number of attack & decay rate parameters");
    return SOX_EOF;
  }

  rates = 1 + commas / 2;
  l->attackRate = lsx_malloc(sizeof(double) * rates);
  l->decayRate = lsx_malloc(sizeof(double) * rates);
  l->volume = lsx_malloc(sizeof(double) * rates);
  l->expectedChannels = rates;
  l->delay_buf = NULL;

  s = strtok(argv[0], ","); i = 0;
  do {
    l->attackRate[i] = atof(s); s = strtok(NULL, ",");
    l->decayRate[i] = atof(s); s = strtok(NULL, ",");
    ++i;
  } while (s != NULL);

  if (!lsx_compandt_parse(&l->transfer_fn, argv[1], n > 2 ? argv[2] : 0))
    return SOX_EOF;

  for (i = 0; i < l->expectedChannels; ++i) {
    double v = n >= 4 ? pow(10.0, atof(argv[3]) / 20) : 1.0;
    l->volume[i] = v;
    if (n >= 5) l->delay = atof(argv[4]);
    else l->delay = 0.0;
  }
  return SOX_SUCCESS;
}

static int parse_subarg(char *s, char **subargs, size_t *nsubargs)
{
  char *p;
  size_t i;

  p = s;
  *nsubargs = 0;
  while (*p) {
    while (*p && isspace((unsigned char)*p)) ++p;
    if (!*p) break;
    if (*nsubargs < 6) subargs[*nsubargs] = p;
    ++*nsubargs;
    while (*p && !isspace((unsigned char)*p)) ++p;
    if (*p) *p++ = '\0';
  }
  if (*nsubargs < 2 || *nsubargs > 5) {
    lsx_fail("Wrong number of parameters for the compander effect within mcompand; usage:\n"
        "\tattack1,decay1{,attack2,decay2} [soft-knee-dB:]in-dB1[,out-dB1]{,in-dB2,out-dB2} [gain [initial-volume-dB [delay]]]\n"
        "\twhere {} means optional and repeatable and [] means optional.\n"
        "\tdB values are floating point or -inf'; times are in seconds.");
    return SOX_EOF;
  }
  for (i = *nsubargs; i < 6; ++i) subargs[i] = NULL;
  return SOX_SUCCESS;
}

static int getopts(sox_effect_t *effp, int argc, char **argv)
{
  char *subargs[6];
  size_t nsubargs, i;
  priv_t *c = (priv_t *)effp->priv;
  --argc, ++argv;

  c->band_buf1 = c->band_buf2 = c->band_buf3 = 0;
  c->band_buf_len = 0;

  if (!(argc & 1)) {
    lsx_fail("mcompand accepts only an odd number of arguments:\argc"
        "  mcompand quoted_compand_args [crossover_freq quoted_compand_args [...]]");
    return SOX_EOF;
  }
  c->nBands = (argc + 1) / 2;
  c->bands = lsx_calloc(c->nBands, sizeof(comp_band_t));

  for (i = 0; i < c->nBands; ++i) {
    c->arg = lsx_strdup(argv[i << 1]);
    if (parse_subarg(c->arg, subargs, &nsubargs) != SOX_SUCCESS) {
      free(c->arg);
      return SOX_EOF;
    }
    if (getopts_1(&c->bands[i], nsubargs, &subargs[0]) != SOX_SUCCESS) {
      free(c->arg);
      return SOX_EOF;
    }
    free(c->arg);
    c->arg = NULL;
    if (i == (c->nBands - 1))
      c->bands[i].topfreq = 0;
    else {
      char *dummy_p;
      c->bands[i].topfreq = lsx_parse_frequency(argv[(i << 1) + 1], &dummy_p);
      if (*dummy_p || c->bands[i].topfreq < 0) {
        lsx_fail("bad frequency in args to mcompand");
        return SOX_EOF;
      }
      if ((i > 0) && (c->bands[i].topfreq < c->bands[i - 1].topfreq)) {
        lsx_fail("mcompand crossover frequencies must be in ascending order.");
        return SOX_EOF;
      }
    }
  }
  return SOX_SUCCESS;
}

static int start(sox_effect_t *effp)
{
  priv_t *c = (priv_t *)effp->priv;
  comp_band_t *l;
  size_t i;
  size_t band;

  for (band = 0; band < c->nBands; ++band) {
    l = &c->bands[band];
    l->delay_size = c->bands[band].delay * effp->out_signal.rate * effp->out_signal.channels;
    if (l->delay_size > c->delay_buf_size)
      c->delay_buf_size = l->delay_size;
  }

  for (band = 0; band < c->nBands; ++band) {
    l = &c->bands[band];
    for (i = 0; i < l->expectedChannels; ++i) {
      if (l->attackRate[i] > 1.0 / effp->out_signal.rate)
        l->attackRate[i] = 1.0 - exp(-1.0 / (effp->out_signal.rate * l->attackRate[i]));
      else
        l->attackRate[i] = 1.0;
      if (l->decayRate[i] > 1.0 / effp->out_signal.rate)
        l->decayRate[i] = 1.0 - exp(-1.0 / (effp->out_signal.rate * l->decayRate[i]));
      else
        l->decayRate[i] = 1.0;
    }
    if (c->delay_buf_size > 0)
      l->delay_buf = lsx_calloc(sizeof(long), c->delay_buf_size);
    l->delay_buf_ptr = 0;
    l->delay_buf_cnt = 0;

    if (l->topfreq != 0)
      if (crossover_setup(effp, &l->filter, l->topfreq) != SOX_SUCCESS)
        return SOX_EOF;
  }
  return SOX_SUCCESS;
}

static void doVolume(double *v, double samp, comp_band_t *l, size_t chan)
{
  double s = samp / (~((sox_sample_t)1 << 31));
  double delta = s - *v;
  if (delta > 0.0)
    *v += delta * l->attackRate[chan];
  else
    *v += delta * l->decayRate[chan];
}

static int flow_1(sox_effect_t *effp, priv_t *c, comp_band_t *l, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t len, size_t filechans)
{
  size_t idone, odone;

  for (idone = 0, odone = 0; idone < len; ibuf += filechans) {
    size_t chan;

    if (l->expectedChannels == 1 && filechans > 1) {
      double maxsamp = 0.0;
      for (chan = 0; chan < filechans; ++chan) {
        double rect = fabs((double)ibuf[chan]);
        if (rect > maxsamp)
          maxsamp = rect;
      }
      doVolume(&l->volume[0], maxsamp, l, (size_t)0);
    } else {
      for (chan = 0; chan < filechans; ++chan)
        doVolume(&l->volume[chan], fabs((double)ibuf[chan]), l, chan);
    }

    for (chan = 0; chan < filechans; ++chan) {
      int ch = l->expectedChannels > 1 ? chan : 0;
      double level_in_lin = l->volume[ch];
      double level_out_lin = lsx_compandt(&l->transfer_fn, level_in_lin);
      double checkbuf;

      if (c->delay_buf_size <= 0) {
        checkbuf = ibuf[chan] * level_out_lin;
        SOX_SAMPLE_CLIP_COUNT(checkbuf, effp->clips);
        obuf[odone++] = checkbuf;
        idone++;
      } else {
        if (l->delay_buf_cnt >= l->delay_size) {
          checkbuf = l->delay_buf[(l->delay_buf_ptr + c->delay_buf_size - l->delay_size) % c->delay_buf_size] * level_out_lin;
          SOX_SAMPLE_CLIP_COUNT(checkbuf, effp->clips);
          l->delay_buf[(l->delay_buf_ptr + c->delay_buf_size - l->delay_size) % c->delay_buf_size] = checkbuf;
        }
        if (l->delay_buf_cnt >= c->delay_buf_size) {
          obuf[odone] = l->delay_buf[l->delay_buf_ptr];
          odone++;
          idone++;
        } else {
          l->delay_buf_cnt++;
          idone++;
        }
        l->delay_buf[l->delay_buf_ptr++] = ibuf[chan];
        l->delay_buf_ptr %= c->delay_buf_size;
      }
    }
  }
  if (idone != odone) {
    lsx_fail("Internal error: idone != odone.");
    return SOX_EOF;
  }
  return SOX_SUCCESS;
}

static int flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  priv_t *c = (priv_t *)effp->priv;
  comp_band_t *l;
  size_t len = min(*isamp, *osamp);
  size_t band, i;
  sox_sample_t *abuf, *bbuf, *cbuf, *oldabuf, *ibuf_copy;

  if (c->band_buf_len < len) {
    c->band_buf1 = lsx_realloc(c->band_buf1, len * sizeof(sox_sample_t));
    c->band_buf2 = lsx_realloc(c->band_buf2, len * sizeof(sox_sample_t));
    c->band_buf3 = lsx_realloc(c->band_buf3, len * sizeof(sox_sample_t));
    c->band_buf_len = len;
  }

  len -= len % effp->out_signal.channels;

  ibuf_copy = lsx_malloc(*isamp * sizeof(sox_sample_t) + 1);
  memcpy(ibuf_copy, ibuf, *isamp * sizeof(sox_sample_t));

  memset(obuf, 0, len * sizeof *obuf);
  for (band = 0, abuf = ibuf_copy, bbuf = c->band_buf2, cbuf = c->band_buf1; band < c->nBands; ++band) {
    l = &c->bands[band];

    if (l->topfreq)
      crossover_flow(effp, &l->filter, abuf, bbuf, cbuf, len);
    else {
      bbuf = abuf;
      abuf = cbuf;
    }
    if (abuf == ibuf_copy)
      abuf = c->band_buf3;
    (void)flow_1(effp, c, l, bbuf, abuf, len, (size_t)effp->out_signal.channels);
    for (i = 0; i < len; ++i) {
      double out = (double)obuf[i] + (double)abuf[i];
      obuf[i] = SOX_ROUND_CLIP_COUNT(out, effp->clips);
    }
    oldabuf = abuf;
    abuf = cbuf;
    cbuf = oldabuf;
  }

  *isamp = *osamp = len;
  free(ibuf_copy);
  return SOX_SUCCESS;
}

static int drain_1(sox_effect_t *effp, priv_t *c, comp_band_t *l, sox_sample_t *obuf, int maxdrain)
{
  size_t done;
  double v;
  (void)c;
  for (done = 0; done < (size_t)maxdrain && l->delay_buf_cnt > 0; done++) {
    v = obuf[done] + l->delay_buf[l->delay_buf_ptr++];
    obuf[done] = SOX_ROUND_CLIP_COUNT(v, effp->clips);
    l->delay_buf_ptr %= c->delay_buf_size;
    l->delay_buf_cnt--;
  }
  return done;
}

static int drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{
  size_t band, drained, mostdrained = 0;
  priv_t *c = (priv_t *)effp->priv;
  comp_band_t *l;

  *osamp -= *osamp % effp->out_signal.channels;

  memset(obuf, 0, *osamp * sizeof *obuf);
  for (band = 0; band < c->nBands; ++band) {
    l = &c->bands[band];
    drained = drain_1(effp, c, l, obuf, (int)*osamp);
    if (drained > mostdrained)
      mostdrained = drained;
  }

  *osamp = mostdrained;
  if (mostdrained)
    return SOX_SUCCESS;
  else
    return SOX_EOF;
}

static int stop(sox_effect_t *effp)
{
  priv_t *c = (priv_t *)effp->priv;
  size_t band;

  free(c->band_buf1);
  c->band_buf1 = NULL;
  free(c->band_buf2);
  c->band_buf2 = NULL;
  free(c->band_buf3);
  c->band_buf3 = NULL;

  for (band = 0; band < c->nBands; band++) {
    comp_band_t *l = &c->bands[band];
    free(l->delay_buf);
    l->delay_buf = NULL;
    if (l->topfreq != 0)
      free(l->filter.previous);
    l->filter.previous = NULL;
  }
  return SOX_SUCCESS;
}

static int lsx_kill(sox_effect_t *effp)
{
  priv_t *c = (priv_t *)effp->priv;
  size_t band;
  for (band = 0; band < c->nBands; band++) {
    comp_band_t *l = &c->bands[band];
    lsx_compandt_kill(&l->transfer_fn);
    free(l->decayRate);
    free(l->attackRate);
    free(l->volume);
  }
  free(c->arg);
  free(c->bands);
  c->bands = NULL;
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_mcompand_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "mcompand", USAGE_mcompand, SOX_EFF_MCHAN | SOX_EFF_GAIN,
    getopts, start, flow, drain, stop, lsx_kill, sizeof(priv_t)
  };
  return &handler;
}
