    lsx_fail("error with fading ratio value");
    return lsx_usage(effp);
  }
  return SOX_SUCCESS;
}

static int start(sox_effect_t *effp)
{
  priv_t *p = (priv_t *)effp->priv;
  size_t i;

  if (p->factor == 1)
    return SOX_EFF_NULL;

  p->state = input_state;
  p->segment = (int)(effp->out_signal.rate * 0.001 * p->window);
  p->index = p->segment / 2;
  p->ibuf = lsx_malloc(p->segment * sizeof(sox_sample_t) + 1);

  if (p->factor < 1.0) {
    p->ishift = p->shift * p->segment;
    p->oshift = p->factor * p->ishift;
  } else {
    p->oshift = p->shift * p->segment;
    p->ishift = p->oshift / p->factor;
  }

  p->oindex = p->index;
  p->obuf = lsx_malloc(p->segment * sizeof(double) + 1);
  p->overlap = (int)(p->fading * p->segment);
  p->fade_coefs = lsx_malloc(p->overlap * sizeof(double) + 1);

  for (i = 0; i < p->segment; i++)
    p->ibuf[i] = 0;
  for (i = 0; i < p->segment; i++)
    p->obuf[i] = 0.0;

  if (p->overlap > 1) {
    double slope = 1.0 / (p->overlap - 1);
    p->fade_coefs[0] = 1.0;
    for (i = 1; i < p->overlap - 1; i++)
      p->fade_coefs[i] = slope * (p->overlap - i - 1);
    p->fade_coefs[p->overlap - 1] = 0.0;
  } else if (p->overlap == 1)
    p->fade_coefs[0] = 1.0;

  lsx_debug("start: (factor=%g segment=%g shift=%g overlap=%g)\nstate=%d\n"
      "segment=%lu\nindex=%lu\nishift=%lu\noindex=%lu\noshift=%lu\noverlap=%lu",
      p->factor, p->window, p->shift, p->fading, p->state,
      (unsigned long)p->segment, (unsigned long)p->index, (unsigned long)p->ishift,
      (unsigned long)p->oindex, (unsigned long)p->oshift, (unsigned long)p->overlap);

  effp->out_signal.length = SOX_UNKNOWN_LEN;
  return SOX_SUCCESS;
}

static void combine(priv_t *p)
{
  size_t i;
  for (i = 0; i < p->overlap; i++)
    p->obuf[i] += p->fade_coefs[p->overlap - 1 - i] * p->ibuf[i];
  for (; i < p->segment - p->overlap; i++)
    p->obuf[i] += p->ibuf[i];
  for (; i < p->segment; i++)
    p->obuf[i] += p->fade_coefs[i - p->segment + p->overlap] * p->ibuf[i];
}

static int flow(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf, size_t *isamp, size_t *osamp)
{
  priv_t *p = (priv_t *)effp->priv;
  size_t iindex = 0, oindex = 0;
  size_t i;

  while (iindex < *isamp && oindex < *osamp) {
    if (p->state == input_state) {
      size_t tocopy = min(*isamp - iindex, p->segment - p->index);
      memcpy(p->ibuf + p->index, ibuf + iindex, tocopy * sizeof(sox_sample_t));
      iindex += tocopy;
      p->index += tocopy;
      if (p->index == p->segment) {
        combine(p);
        for (i = 0; i + p->ishift < p->segment; i++)
          p->ibuf[i] = p->ibuf[i + p->ishift];
        p->index -= p->ishift;
        p->state = output_state;
      }
    }

    if (p->state == output_state) {
      while (p->oindex < p->oshift && oindex < *osamp) {
        float f;
        f = p->obuf[p->oindex++];
        SOX_SAMPLE_CLIP_COUNT(f, effp->clips);
        obuf[oindex++] = f;
      }
      if (p->oindex >= p->oshift && oindex < *osamp) {
        p->oindex -= p->oshift;
        for (i = 0; i + p->oshift < p->segment; i++)
          p->obuf[i] = p->obuf[i + p->oshift];
        for (; i < p->segment; i++)
          p->obuf[i] = 0.0;
        p->state = input_state;
      }
    }
  }
  *isamp = iindex;
  *osamp = oindex;
  return SOX_SUCCESS;
}

static int drain(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp)
{
  priv_t *p = (priv_t *)effp->priv;
  size_t i;
  size_t oindex = 0;

  if (p->state == input_state) {
    for (i = p->index; i < p->segment; i++)
      p->ibuf[i] = 0;
    combine(p);
    p->state = output_state;
  }
  while (oindex < *osamp && p->oindex < p->index) {
    float f = p->obuf[p->oindex++];
    SOX_SAMPLE_CLIP_COUNT(f, effp->clips);
    obuf[oindex++] = f;
  }
  *osamp = oindex;
  if (p->oindex == p->index)
    return SOX_EOF;
  else
    return SOX_SUCCESS;
}

static int stop(sox_effect_t *effp)
{
  priv_t *p = (priv_t *)effp->priv;
  free(p->ibuf);
  free(p->obuf);
  free(p->fade_coefs);
  p->ibuf = NULL; p->obuf = NULL; p->fade_coefs = NULL;
  return SOX_SUCCESS;
}

const sox_effect_handler_t *lsx_stretch_effect_fn(void)
{
  static sox_effect_handler_t handler = {
    "stretch", USAGE_stretch, SOX_EFF_LENGTH,
    getopts, start, flow, drain, stop, NULL, sizeof(priv_t)
  };
  return &handler;
}
