/* Raw IMA and OKI (vox) ADPCM formats */
#include "sox.h"
#include "adpcm.h"

typedef struct {
  adpcm_t encoder;
  struct { uint8_t byte; uint8_t flag; } store;
  struct { uint8_t *buf; size_t size, count; } file;
} adpcm_io_t;

static int adpcm_start(sox_format_t *ft, adpcm_io_t *state, sox_encoding_t type)
{
  state->file.buf = lsx_malloc(sox_globals.bufsiz);
  state->file.size = sox_globals.bufsiz;
  state->file.count = 0;
  ft->signal.channels = 1;
  state->store.byte = 0;
  state->store.flag = 0;
  lsx_adpcm_init(&state->encoder, (type == SOX_ENCODING_OKI_ADPCM) ? 1 : 0, 0);
  return lsx_rawstart(ft, sox_true, sox_false, sox_true, type, 4);
}

static size_t adpcm_read(sox_format_t *ft, sox_sample_t *buffer, size_t len)
{
  adpcm_io_t *state = (adpcm_io_t *)ft->priv;
  size_t n = 0;
  uint8_t byte;
  int16_t word;

  if (len && state->store.flag) {
    word = lsx_adpcm_decode(state->store.byte, &state->encoder);
    *buffer++ = SOX_SIGNED_16BIT_TO_SAMPLE(word);
    state->store.flag = 0;
    ++n;
  }
  while (n < len && lsx_readbuf(ft, &byte, (size_t)1) == 1) {
    word = lsx_adpcm_decode(byte >> 4, &state->encoder);
    *buffer++ = SOX_SIGNED_16BIT_TO_SAMPLE(word);
    if (++n < len) {
      word = lsx_adpcm_decode(byte, &state->encoder);
      *buffer++ = SOX_SIGNED_16BIT_TO_SAMPLE(word);
      ++n;
    } else {
      state->store.byte = byte;
      state->store.flag = 1;
    }
  }
  return n;
}

static int adpcm_stopread(sox_format_t *ft)
{
  adpcm_io_t *state = (adpcm_io_t *)ft->priv;
  if (state->encoder.errors)
    lsx_warn("%s: ADPCM state errors: %u", ft->filename, state->encoder.errors);
  free(state->file.buf);
  return SOX_SUCCESS;
}

static size_t adpcm_write(sox_format_t *ft, const sox_sample_t *buffer, size_t length)
{
  adpcm_io_t *state = (adpcm_io_t *)ft->priv;
  size_t count = 0;
  uint8_t byte = state->store.byte;
  uint8_t flag = state->store.flag;
  short word;

  while (count < length) {
    word = SOX_SAMPLE_TO_SIGNED_16BIT(*buffer++, ft->clips);
    byte <<= 4;
    byte |= lsx_adpcm_encode(word, &state->encoder) & 0x0F;
    flag = !flag;
    if (flag == 0) {
      state->file.buf[state->file.count++] = byte;
      if (state->file.count >= state->file.size) {
        lsx_writebuf(ft, state->file.buf, state->file.count);
        state->file.count = 0;
      }
    }
    count++;
  }
  state->store.byte = byte;
  state->store.flag = flag;
  return count;
}

static int adpcm_stopwrite(sox_format_t *ft)
{
  adpcm_io_t *state = (adpcm_io_t *)ft->priv;
  uint8_t byte = state->store.byte;
  uint8_t flag = state->store.flag;
  if (flag != 0) {
    byte <<= 4;
    state->file.buf[state->file.count++] = byte;
  }
  if (state->file.count > 0)
    lsx_writebuf(ft, state->file.buf, state->file.count);
  free(state->file.buf);
  return SOX_SUCCESS;
}

